class TestImportICS(unittest.TestCase):
    """ICS calendar reading: folded lines, time zones, no-number."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)

    @staticmethod
    def _ics(*evenements):
        corps = "".join(f"BEGIN:VEVENT\n{e}\nEND:VEVENT\n" for e in evenements)
        return f"BEGIN:VCALENDAR\nVERSION:2.0\n{corps}END:VCALENDAR\n"

    def test_ligne_pliee_recollee(self):
        # RFC 5545 unfolding removes the newline and ONE space: the
        # continuation therefore carries two spaces to preserve one.
        texte = self._ics("SUMMARY:Mme Pliure Exemple — Bilan complet avec\n"
                          "  compte rendu détaillé\nDTSTART:20270401T100000")
        evenements, erreurs = ics.analyser_ics(texte)
        self.assertEqual(erreurs, [])
        self.assertEqual(evenements[0]["motif"],
                         "Bilan complet avec compte rendu détaillé")

    def test_date_utc_convertie_en_heure_locale(self):
        texte = self._ics("SUMMARY:Mme Utc Exemple — Essai\nDTSTART:20270312T100000Z")
        evenements, _ = ics.analyser_ics(texte)
        attendu = (datetime.datetime(2027, 3, 12, 10, 0,
                                     tzinfo=datetime.timezone.utc)
                   .astimezone().replace(tzinfo=None).isoformat(timespec="minutes"))
        self.assertEqual(evenements[0]["horaire"], attendu)

    def test_date_sans_fuseau_prise_telle_quelle(self):
        texte = self._ics("SUMMARY:M. Local Exemple — Essai\nDTSTART:20260801T143000")
        evenements, _ = ics.analyser_ics(texte)
        self.assertEqual(evenements[0]["horaire"], "2026-08-01T14:30")

    def test_journee_entiere_rejetee_en_francais(self):
        texte = self._ics("SUMMARY:Atelier collectif\nDTSTART;VALUE=DATE:20270320")
        evenements, erreurs = ics.analyser_ics(texte)
        self.assertEqual(evenements, [])
        self.assertIn("journée entière", erreurs[0])
        self.assertIn("Atelier collectif", erreurs[0])

    def test_fichier_sans_evenement_refuse(self):
        with self.assertRaises(saisie.SaisieInvalide):
            ics.analyser_ics("BEGIN:VCALENDAR\nEND:VCALENDAR\n")

    def test_fichier_exemple_fourni_est_importable(self):
        chemin = os.path.join(RACINE, "exemple_agenda.ics")
        with open(chemin, encoding="utf-8") as fichier:
            importes, erreurs = ics.importer_ics(self.base, fichier.read())
        self.assertEqual(importes, 3)  # 3 timestamped events
        self.assertEqual(len(erreurs), 1)  # the `all day` one rejected
        self.assertIn("journée entière", erreurs[0])
        sans_numero = self.base.rendezvous_sans_numero()
        self.assertEqual(len(sans_numero), 3)  # all reported as `no number`
        self.assertEqual({rdv["telephone_masque"] for rdv in sans_numero}, {""})
        noms = [rdv["nom"] for rdv in sans_numero]
        self.assertIn("Mme Inès Fabre", noms)
        motifs = " / ".join(rdv["motif"] for rdv in sans_numero)
        self.assertIn("compte rendu détaillé", motifs)  # the folded line, end to end

    def test_sans_numero_complete_puis_rappelable(self):
        ics.importer_ics(self.base, self._ics(
            "SUMMARY:Mme Agenda Exemple — Séance\nDTSTART:20260101T100000"))
        self.base.marquer_manques_echus()  # past time slot -> missed
        planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=2, latence=0))
        self.assertEqual(planif.programmer_tous_les_manques(), [])  # no number:
        rdv = self.base.rendezvous_sans_numero()[0]  # not queued
        self.base.mettre_a_jour_telephone(rdv["client_id"], "+33 6 39 98 50 51")
        self.assertEqual(self.base.rendezvous_sans_numero(), [])  # completed
        crees = planif.programmer_tous_les_manques()                # maintenant oui
        self.assertEqual(len(crees), 1)
        self.assertEqual(planif.executer(), crees)  # and the call goes out


# --------------------------------------------------------------------------
# Local fake CALL-E API: an http.server that mimics call creation + follow-up.
# NO test contacts the real API.
# --------------------------------------------------------------------------
RESULTAT_CONFORME = {"appointment_status": "confirmed", "new_datetime": DEMAIN,
                     "notes": "Le client confirme le créneau proposé.",
                     "duration_seconds": 42}

# --------------------------------------------------------------------------
# THE REAL SHAPE OF A CALL-E RESPONSE — copied from the sponsor's documentation
# (github.com/CALLE-AI/call-e-integrations), not from what RingBack thinks it
# understands.  WHY THIS BLOCK EXISTS. Until 01/08/2026, the fake API answered
# {"status": "completed", "result": {...}, "transcript": "..."} — that is,
# EXACTLY what the product went looking for. All 451 tests therefore passed,
# while the real path had been wrong from the start: the real API stores ONE
# person's result in recipients[].structured_result and the conversation in
# recipients[].attempts[].transcript_turns[]. A test that mimics the product
# proves nothing; this one mimics the API.
TOURS_DOCUMENTES = [
    {"offset_seconds": 0, "speaker": "bot",
     "text": "Bonjour, ici l'assistant du cabinet. Je vous propose un "
             "nouveau créneau."},
    {"offset_seconds": 4, "speaker": "user",
     "text": "C'est parfait, je confirme."},
]


def reponse_calle_terminee(resultat_destinataire, tours=None, tentatives=None,
                           destinataires=None):
    """The TERMINAL response of GET /v1/calls/{id}, as documented.

    `destinataires` allows the `recipients` list to be imposed as is (to
    exercise a missing recipient); `tentatives` allows several of them, to
    exercise the choice of the LAST one.
    """
    if destinataires is None:
        if tentatives is None:
            tentatives = [{"transcript_turns":
                           TOURS_DOCUMENTES if tours is None else tours}]
        destinataires = [{"structured_result": resultat_destinataire,
                          "attempts": tentatives}]
    return {
        "status": "completed",
        "task_completed": True,
        "completion_confidence": {"score": 0.92, "label": "high"},
        "evidence": ["The recipient confirmed the proposed slot."],
        # GLOBAL summary of the campaign: this is NOT what RingBack reads.
        "structured_result": {"completed_count": 1},
        "recipients": destinataires,
    }


class _FauxApiCalle(BaseHTTPRequestHandler):
    """Mimics the CALL-E API: POST /v1/calls then GET /v1/calls/{id}.

    `etats` is the list of successive answers to the GETs; the last one
    `sticks` (it is served again indefinitely, useful for the timeout test).
    `creations` keeps every POST body received.

    It also knows how to be SLOW (`lenteur_post`, `lenteur_get`): it waits
    before answering, which really makes the client's read expire and raise the
    TimeoutError of 01/08/2026 — never an imitation of an exception, the real
    one, raised by the real network stack.
    """

    creations = None  # filled in by each test's subclass
    etats = None
    entetes = None  # headers of the last request received
    lectures = None  # the identifiers requested by GET, in order
    # Error codes to SERVE instead of a normal response. That is how a 401 (key
    # refused), a 402/429 (quota) or a 500 (service outage) are exercised
    # without ever touching the real API.
    code_erreur_post = None  # failure at CREATION: nothing went out
    code_erreur_get = None  # failure during FOLLOW-UP: the call had been placed
    # WHAT THE API ANSWERS IN THE BODY when it refuses. The real one names the
    # offending field — that is the sentence we must be able to read back, and
    # on 02/08/2026 it was read then thrown away along the way (see
    # test_la_reponse_de_l_api_est_citee_quand_elle_refuse).
    corps_erreur = {"error": "refus simulé"}
    # SIMULATED slowness, in seconds: the time the API takes to answer. Beyond
    # the client's delai_requete, the read expires for good.
    lenteur_post = 0
    lenteur_get = 0
    # Hanging up without answering: that is how we obtain the REAL
    # http.client.RemoteDisconnected / ConnectionResetError, the ones that also
    # went through the error translation.
    coupure_post = False
    coupure_get = False
    identifiant = "appel-essai-1"

    def do_POST(self):
        taille = int(self.headers.get("Content-Length", 0))
        type(self).entetes = dict(self.headers)
        type(self).creations.append(json.loads(self.rfile.read(taille)))
        if type(self).lenteur_post:
            time.sleep(type(self).lenteur_post)
        if type(self).coupure_post:
            return self._raccrocher()
        if type(self).code_erreur_post:
            return self._echec(type(self).code_erreur_post)
        self._json({"id": type(self).identifiant, "status": "queued"})

    def do_GET(self):
        if type(self).lectures is not None:
            type(self).lectures.append(self.path)
        if type(self).lenteur_get:
            time.sleep(type(self).lenteur_get)
        if type(self).coupure_get:
            return self._raccrocher()
        if type(self).code_erreur_get:
            return self._echec(type(self).code_erreur_get)
        etats = type(self).etats
        reponse = etats.pop(0) if len(etats) > 1 else etats[0]
        self._json(reponse)

    def _echec(self, code):
        """An ERROR response, as the real API would return."""
        octets = json.dumps(type(self).corps_erreur).encode("utf-8")
        self._ecrire(code, octets)

    def _raccrocher(self):
        """Cuts the connection without answering: the server that gives up
        mid-conversation. The client will see a http.client.RemoteDisconnected.
        """
        self.close_connection = True
        try:
            self.connection.close()
        except OSError:
            pass

    def _json(self, contenu):
        octets = json.dumps(contenu, ensure_ascii=False).encode("utf-8")
        self._ecrire(200, octets)

    def _ecrire(self, code, octets):
        """Writes the response; a client that has already given up makes no noise.

        When the client's read has expired, it closed the connection: writing
        into it raises a broken-pipe error. This is not a product defect, it is
        the scenario itself — we swallow it without polluting the output.
        """
        try:
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(octets)))
            self.end_headers()
            self.wfile.write(octets)
        except OSError:
            self.close_connection = True

    def handle_one_request(self):
        try:
            BaseHTTPRequestHandler.handle_one_request(self)
        except (OSError, ValueError):
            self.close_connection = True

    def log_message(self, *arguments):
        pass  # silence: no noise in the test output


class TestAppelReel(unittest.TestCase):
    """AppelReel exercised against the local fake API, never the real one."""

    def setUp(self):
        self.base, self.client_id, self.rdv_id = base_de_test()
        self.addCleanup(self.base.fermer)
        self._cle_sauvee = os.environ.pop("CALLE_API_KEY", None)
        if self._cle_sauvee is not None:
            self.addCleanup(os.environ.__setitem__, "CALLE_API_KEY", self._cle_sauvee)
        self.dossier = tempfile.mkdtemp(prefix="ringback-audit-")
        self.addCleanup(shutil.rmtree, self.dossier, ignore_errors=True)
        self.chemin_audit = os.path.join(self.dossier, "audit_appels_reels.jsonl")

        class Faux(_FauxApiCalle):
            creations = []
            etats = [{"status": "queued"}]
        self.faux = Faux
        self.serveur_api = HTTPServer(("127.0.0.1", 0), Faux)
        threading.Thread(target=self.serveur_api.serve_forever, daemon=True).start()
        self.url_api = f"http://127.0.0.1:{self.serveur_api.server_address[1]}"
        # It really is the CALLE_API_URL environment variable that steers the
        # client: proof that the base URL is configurable without code.
        os.environ["CALLE_API_URL"] = self.url_api
        self.addCleanup(os.environ.pop, "CALLE_API_URL", None)
        self.addCleanup(self.serveur_api.server_close)
        self.addCleanup(self.serveur_api.shutdown)

    def _client(self, **surcharge):
        options = dict(cle_api="cle-de-test-0123456789", delai_total=2.0, intervalle=0.01,
                       delai_requete=2.0, chemin_audit=self.chemin_audit)
        options.update(surcharge)
        return calle_client.AppelReel(**options)

    def test_le_POST_porte_la_langue_de_l_appel(self):
        """LOCK FOUND WITHOUT A GUARD BY THE COUNTER-TEST (01/09/2026).
        `_region_et_locale` was exercised on its own; nothing said it was
        ACTUALLY used when sending. So we look at what the fake API received.
        """
        for langue_code, attendu in (("fr", ("FR", "fr-FR")),
                                     ("en", ("GB", "en-GB"))):
            with self.subTest(langue=langue_code):
                self.faux.creations = []
                self.faux.etats = [{"status": "completed", "recipients": [
                    {"structured_result": {"appointment_status": "confirmed",
                                           "new_datetime": "", "notes": "",
                                           "do_not_call": "no"}}]}]
                client = self._client(langue_appel=langue_code)
                try:
                    client.appeler("Mme Essai", "+33 6 39 98 50 42",
                                   {"horaire": DEMAIN, "motif": "Bilan"},
                                   mission="Bonjour.")
                except Exception:                            # noqa: BLE001
                    pass
                self.assertTrue(self.faux.creations,
                                "aucune demande n'est arrivée à l'API")
                destinataire = self.faux.creations[-1]["recipients"][0]
                self.assertEqual(
                    (destinataire["region"], destinataire["locale"]), attendu)

    def _planificateur_deverrouille(self, client):
        planif = planificateur.Planificateur(self.base, client, dry_run=False)
        planif.confirmer_appels_reels()
        return planif

    def _lignes_audit(self):
        with open(self.chemin_audit, encoding="utf-8") as fichier:
            contenu = fichier.read()
        self.assertNotIn("+33 6 39 98 50 42", contenu)  # NEVER the number in clear
        return [json.loads(ligne) for ligne in contenu.splitlines() if ligne.strip()]

    def test_url_de_base_configurable_par_variable(self):
        self.assertEqual(self._client().url_base, self.url_api)
        del os.environ["CALLE_API_URL"]
        try:
            self.assertEqual(self._client().url_base, "https://api.heycall-e.com")
        finally:
            os.environ["CALLE_API_URL"] = self.url_api

    def test_verrous_bloquent_avant_toute_requete(self):
        # Lock 1: without a key, the real client does not even get built. THE
        # VARIABLE *AND* THE FILE (03/09/2026): see `sans_aucune_cle_calle`.
        with sans_aucune_cle_calle():
            with self.assertRaises(calle_client.CleApiAbsente):
                calle_client.AppelReel(chemin_audit=self.chemin_audit)
        reel = self._client()
        # Lock 2: dry_run (the default) blocks execution.
        planif = planificateur.Planificateur(self.base, reel)
        planif.programmer(self.rdv_id)
        with self.assertRaises(planificateur.GardeFou):
            planif.executer()
        # Verrou 3 : sans confirmation explicite, refus aussi.
        planif2 = planificateur.Planificateur(self.base, reel, dry_run=False)
        planif2.programmer(self.rdv_id)
        with self.assertRaises(planificateur.GardeFou):
            planif2.executer()
        self.assertEqual(self.faux.creations, [])  # NO request went out
        self.assertFalse(os.path.exists(self.chemin_audit))  # and nothing audited

    def test_appel_reel_complet_contre_fausse_api(self):
        self.faux.etats[:] = [
            {"status": "queued"}, {"status": "in_progress"},
            reponse_calle_terminee(dict(RESULTAT_CONFORME))]
        planif = self._planificateur_deverrouille(self._client())
        appel_id = planif.programmer(self.rdv_id)
        self.assertEqual(planif.executer(), [appel_id])
        appel = self.base.obtenir_appel(appel_id)
        self.assertEqual(appel["statut"], "terminé")
        self.assertEqual(appel["resultat"]["appointment_status"], "confirmed")
        self.assertIn("Bonjour", appel["transcription"])
        self.assertEqual(self.base.obtenir_rendezvous(self.rdv_id)["statut"], "confirmé")
        # The creation request follows the sponsor's documented API. This test
        # long locked in an ERROR: it expected `phone` (a text) and the spaced
        # number, because that is what the product was sending. The real API
        # answered 422 — observed on 01/08/2026 during the first real test
        # call. The documentation says `phones`, a LIST, in compact
        # international format (E.164). A test only checks what we thought we
        # understood: it never replaces a real call.
        self.assertEqual(len(self.faux.creations), 1)
        creation = self.faux.creations[0]
        self.assertEqual(creation["recipients"],
                         [{"phones": ["+33639985042"], "region": "FR",
                           "locale": "fr-FR"}])
        # `Mme` IS NO LONGER SENT AS IS: the owner noticed by ear that the
        # agent does not read abbreviations. They are expanded when the brief
        # is built — and only there: the client's card keeps its own spelling
        # (see the consigne module, and TestCivilitesDeveloppees).
        self.assertIn("madame Test Exemple", creation["task"])
        self.assertNotIn("Mme Test Exemple", creation["task"])
        self.assertNotIn("+33 6 39 98 50 42", creation["task"])  # no number in the mission
        # AND THE TASK IS NO LONGER A MONOLOGUE: three parts, only one of which
        # is imposed (the introduction). That is what was missing in the
        # owner's 5th real test call, where the agent recited then concluded.
        for titre in (consigne.TITRE_PRESENTATION, consigne.TITRE_CONTEXTE,
                      consigne.TITRE_ISSUES):
            self.assertIn(titre, creation["task"])
        for etiquette in ("- OUI — ", "- NON — ", "- AUTRE — "):
            self.assertIn(etiquette, creation["task"])
        # THE SCHEMA GOES OUT IN `recipient_result_schema`. It describes ONE
        # person's result; `result_schema` would describe the campaign's global
        # summary. It is the symmetrical mistake to the one on the return path,
        # observed on 01/08/2026 at 16:49.
        self.assertEqual(creation["recipient_result_schema"],
                         calle_client.SCHEMA_RESULTAT)
        # AND THE GLOBAL SUMMARY GOES WITH IT, as in the `Create call` example
        # of the API reference, which shows BOTH side by side. Removing it
        # `since it is optional` earned a 400 at creation on 02/08/2026: a
        # piece of reasoning against a documented example, and the example was
        # right.
        self.assertEqual(creation["result_schema"],
                         calle_client.SCHEMA_BILAN_GLOBAL)
        # No keyword outside the list the reference allows (type, properties,
        # required, enum, nested objects, array.items, description,
        # additionalProperties: false) — `minimum` is absent from it, and a
        # refused schema makes ALL calls fail.
        for schema in (calle_client.SCHEMA_RESULTAT,
                       calle_client.SCHEMA_RESULTAT_CASCADE,
                       calle_client.SCHEMA_BILAN_GLOBAL):
            for champ, regle in schema["properties"].items():
                interdits = set(regle) - {"type", "enum", "description",
                                          "properties", "required", "items",
                                          "additionalProperties"}
                self.assertEqual(interdits, set(),
                                 f"{champ} porte un mot-clé non admis")
        # AND NO RESERVED NAME: CALL-E fills in summary, status, transcript,
        # call_id and the time fields itself, and refuses the ENTIRE request if
        # we ask it for them. On 02/08/2026, `duration_seconds` made the 7th
        # real test call fail — a field RingBack demanded from the agent and
        # used nowhere.
        for schema in (calle_client.SCHEMA_RESULTAT,
                       calle_client.SCHEMA_RESULTAT_CASCADE,
                       calle_client.SCHEMA_BILAN_GLOBAL):
            self.assertEqual(calle_client.champs_reserves_dans(schema), [])
        self.assertEqual(self.faux.entetes.get("Authorization"), "Bearer cle-de-test-0123456789")
        # The transcript is rebuilt from transcript_turns, with the SAME labels
        # as the simulation: the screen stays consistent.
        self.assertEqual(
            appel["transcription"],
            "Agent : Bonjour, ici l'assistant du cabinet. Je vous propose un "
            "nouveau créneau.\nClient : C'est parfait, je confirme.")
        # Audit: one line, timestamped, number masked.
        lignes = self._lignes_audit()
        self.assertEqual(len(lignes), 1)
        self.assertEqual(lignes[0]["statut"], "terminé")
        self.assertEqual(lignes[0]["telephone"], "+33 6 •• •• •• 42")
        datetime.datetime.fromisoformat(lignes[0]["horodatage"])  # lisible

    # ------------------------------- the redirect to MY number (real test
    # calls)
    def test_le_renvoi_remplace_le_numero_compose_et_rien_d_autre(self):
        """THE POINT OF THE REQUEST, word for word: `on remplace les numeros de
        telephone transmise a l'agent par ce numero de telephone. L'identite
        reste inchange.` (owner, 10/08/2026)

        Both halves matter equally: if the identity changed, we would no longer
        hear the conversation the contact would have had — and the test call
        would be pointless.
        """
        self.faux.etats[:] = [reponse_calle_terminee(dict(RESULTAT_CONFORME))]
        planif = self._planificateur_deverrouille(
            self._client(numero_impose="06 39 98 00 24"))
        planif.programmer(self.rdv_id)
        planif.executer()
        creation = self.faux.creations[-1]
        # The dialled number is MINE, in the compact format the API expects...
        self.assertEqual(creation["recipients"][0]["phones"], ["+33639980024"])
        # ...and the contact's is nowhere in the request.
        self.assertNotIn("639985042", json.dumps(creation))
        # THE IDENTITY, FOR ITS PART, DOES NOT MOVE BY ONE WORD.
        self.assertIn("madame Test Exemple", creation["task"])
        self.assertIn(consigne.TITRE_PRESENTATION, creation["task"])

    def test_le_renvoi_est_relu_a_chaque_appel_jamais_figé(self):
        """WITHOUT THIS, A TICKED BOX WOULD HAVE NO EFFECT UNTIL RESTART. The real
        client is built ONCE, when the server starts: the imposed number is
        therefore a FUNCTION, re-read on every call — and the screen cannot
        announce anything other than what goes out.
        """
        impose = [""]
        client = self._client(numero_impose=lambda: impose[0])
        self.faux.etats[:] = [reponse_calle_terminee(dict(RESULTAT_CONFORME))]
        rdv = self.base.obtenir_rendezvous(self.rdv_id)
        client.appeler("Mme Test Exemple", "+33 6 39 98 50 42", rdv)
        self.assertEqual(self.faux.creations[-1]["recipients"][0]["phones"],
                         ["+33639985042"])
        impose[0] = "06 39 98 00 24"  # the box is ticked MID-COURSE
        client.appeler("Mme Test Exemple", "+33 6 39 98 50 42", rdv)
        self.assertEqual(self.faux.creations[-1]["recipients"][0]["phones"],
                         ["+33639980024"])

    def test_un_numero_impose_illisible_refuse_l_appel_et_ne_compose_rien(self):
        """IT NEVER FALLS BACK ON THE CONTACT'S NUMBER. Falling back would ring a
        real phone at the exact moment the screen promises none will ring: that
        is the only outcome we cannot undo. A refusal, by contrast, is read and
        corrected.
        """
        client = self._client(numero_impose="https://pas-un-numero")
        rdv = self.base.obtenir_rendezvous(self.rdv_id)
        with self.assertRaises(calle_client.DemandeRefusee) as refus:
            client.appeler("Mme Test Exemple", "+33 6 39 98 50 42", rdv)
        self.assertEqual(self.faux.creations, [])      # RIEN n'est parti
        self.assertIn("renvoi d'essai", str(refus.exception))
        lignes = self._lignes_audit()
        self.assertEqual(lignes[-1]["statut"], "aucun appel lancé")
        # The audit line does not show a meaningless row of dots: it says what
        # actually happened.
        self.assertEqual(lignes[-1]["numero_appele"],
                         "numéro d'essai illisible")

    def test_l_audit_dit_le_renvoi_et_garde_le_numero_du_contact_masque(self):
        """Reading the log back must say TWO things: who we meant to reach, and
        that it was not them who rang. Without the second, a whole campaign
        would read back as if real contacts had been called.
        """
        self.faux.etats[:] = [reponse_calle_terminee(dict(RESULTAT_CONFORME))]
        rdv = self.base.obtenir_rendezvous(self.rdv_id)
        self._client().appeler("Mme Test Exemple", "+33 6 39 98 50 42", rdv)
        ordinaire = self._lignes_audit()[-1]
        # WITHOUT a redirect, the line does not change shape: no extra key.
        self.assertNotIn("renvoi_essai", ordinaire)
        self.assertNotIn("numero_appele", ordinaire)
        self._client(numero_impose="06 39 98 00 24").appeler(
            "Mme Test Exemple", "+33 6 39 98 50 42", rdv)
        renvoye = self._lignes_audit()[-1]
        self.assertEqual(renvoye["telephone"], "+33 6 •• •• •• 42")  # THE CONTACT
        self.assertEqual(renvoye["numero_appele"], "06 39 •• •• 24")  # MOI
        self.assertIn("n'a PAS été appelé", renvoye["renvoi_essai"])

    def test_les_deux_portes_d_appel_passent_par_le_meme_entonnoir(self):
        """THE WHOLE REDIRECT HANGS ON THIS. If a third door ever posted without
        going through _appel_complet, it would dial the contact's number with
        nothing saying so — and nobody would notice before having called real
        clients.
        """
        source = inspect.getsource(calle_client.AppelReel)
        self.assertEqual(source.count("_numero_a_composer(telephone)"), 1)
        self.assertEqual(source.count("numero_e164(telephone)"), 1)
        for methode in ("appeler", "appeler_cascade"):
            with self.subTest(methode=methode):
                self.assertIn("self._appel_complet(", inspect.getsource(
                    getattr(calle_client.AppelReel, methode)))

    def test_resultat_non_conforme_rejete_sans_ecriture(self):
        """A result outside the schema is NEVER applied — and accuses nobody.

        This test expected `echec` and a read that silently carries on. Both
        were wrong: the POST had succeeded, the conversation had taken place.
        Since 01/08/2026 (16:49), a result RingBack cannot read is RingBack's
        fault — the call stops, its card keeps the RAW RESPONSE, and nothing is
        written against the client.
        """
        invalide = {"appointment_status": "maybe", "new_datetime": None,
                    "notes": "", "duration_seconds": 5}
        self.faux.etats[:] = [reponse_calle_terminee(invalide)]
        planif = self._planificateur_deverrouille(self._client())
        appel_id = planif.programmer(self.rdv_id)
        with self.assertRaises(calle_client.ResultatInvalide) as refus:
            planif.executer()
        appel = self.base.obtenir_appel(appel_id)
        self.assertEqual(appel["statut"], "réponse illisible")
        self.assertIsNone(appel["resultat"])  # NO writing of the result
        # The conversation, though, is KEPT: it took place.
        self.assertIn("C'est parfait, je confirme.", appel["transcription"])
        # NO LONGER BLIND: the raw response is on the card.
        self.assertIn("structured_result", appel["note"])
        self.assertIn("maybe", appel["note"])
        self.assertEqual(appel["appel_externe_id"], "appel-essai-1")
        self.assertEqual(self.base.obtenir_rendezvous(self.rdv_id)["statut"],
                         "manqué")                   # rendez-vous intact
        self.assertEqual(planif.file, [])  # never called back on its own
        # The message says what happened, and whose fault it is.
        self.assertIn("RingBack n'a pas su lire", str(refus.exception))
        self.assertIn("A BIEN EU LIEU", str(refus.exception))
        lignes = self._lignes_audit()
        self.assertEqual(lignes[0]["statut"], "réponse illisible")
        self.assertIn("appointment_status", lignes[0]["detail"])
        # and in the audit log too — that is what was missing.
        self.assertIn("maybe", lignes[0]["reponse_brute"])

    def test_delai_attente_declenche_proprement(self):
        """The wait expires: the call DID go out, it is NOT lost.

        This test expected `echec` and a call put back in the queue. Both were
        wrong: the creation POST had succeeded, so the phone had rung. Putting
        the call back in the queue would have made it ring a second time;
        writing it `echec` erased the conversation. Since 01/08/2026, the call
        keeps its CALL-E identifier and its status tells the truth — `en
        attente`.
        """
        self.faux.etats[:] = [{"status": "in_progress"}]  # never finishes
        planif = self._planificateur_deverrouille(
            self._client(delai_total=0.15, intervalle=0.02))
        appel_id = planif.programmer(self.rdv_id)
        with self.assertRaises(calle_client.DelaiDepasse):
            planif.executer()
        appel = self.base.obtenir_appel(appel_id)
        self.assertEqual(appel["statut"], "en attente")
        self.assertEqual(appel["appel_externe_id"], "appel-essai-1")
        self.assertIn("EST BIEN PARTI", appel["note"])
        # And it does NOT go back into the queue: nobody will be called back
        # for nothing.
        self.assertEqual(planif.file, [])
        self.assertEqual(self.base.obtenir_rendezvous(self.rdv_id)["statut"], "manqué")
        lignes = self._lignes_audit()
        self.assertEqual(lignes[0]["statut"], "délai dépassé")

    def test_statut_api_en_echec_refuse_proprement(self):
        self.faux.etats[:] = [{"status": "queued"}, {"status": "no_answer"}]
        planif = self._planificateur_deverrouille(self._client())
        appel_id = planif.programmer(self.rdv_id)
        self.assertEqual(planif.executer(), [])
        self.assertEqual(self.base.obtenir_appel(appel_id)["statut"], "échec")
        lignes = self._lignes_audit()
        # The log SAYS it was the contact who did not answer — as it already
        # did for the cascade. `echec` mixed that case with software outages,
        # which therefore read the same.
        self.assertEqual(lignes[0]["statut"], "pas de réponse")
        self.assertIn("no_answer", lignes[0]["detail"])

    def test_le_journal_distingue_le_contact_et_nous(self):
        """Two audit lines, two statuses that can no longer be confused."""
        self.faux.etats[:] = [{"status": "no_answer"}]
        planif = self._planificateur_deverrouille(self._client())
        planif.executer(seulement=planif.programmer(self.rdv_id))
        self.faux.code_erreur_post = 401
        with self.assertRaises(calle_client.EchecDeNotreCote):
            planif.executer(seulement=planif.programmer(self.rdv_id))
        lignes = self._lignes_audit()
        self.assertEqual([ligne["statut"] for ligne in lignes],
                         ["pas de réponse", "aucun appel lancé"])

    def test_la_reponse_de_l_api_est_citee_quand_elle_refuse(self):
        """The message PROMISES a quotation: it must be there.

        Observed on 02/08/2026 at the owner's: on a 400, the screen said `Lisez
        la reponse de l'API citee ci-dessus : elle nomme le champ en cause` —
        and nothing was quoted. The body was indeed read, then attached to
        args[0], which this family of errors never displays (it recomposes its
        text from constat + quoi_faire). Promising evidence we do not supply is
        worse than saying nothing: one then hunts for a quotation that does not
        exist instead of hunting for the fault.
        """
        self.faux.code_erreur_post = 400
        self.faux.corps_erreur = {
            "error": {"code": "recipient_result_schema_invalid",
                      "message": "unsupported schema feature at "
                                 "$.properties.duration_seconds.minimum"}}
        planif = self._planificateur_deverrouille(self._client())
        with self.assertRaises(calle_client.EchecDeNotreCote) as refus:
            planif.executer(seulement=planif.programmer(self.rdv_id))
        panne = refus.exception
        # (1) The response is KEPT, in its own slot — not in args[0].
        self.assertIn("duration_seconds.minimum", panne.reponse_brute)
        # (2) It is SAID in the displayed message, the one that promises the
        # quotation.
        self.assertIn("duration_seconds.minimum", panne.message())
        self.assertIn("mot pour mot", panne.message())
        # (3) And it is written to the audit log, in its column: reading one
        # line back must be enough to know which field the API refused.
        ligne = self._lignes_audit()[0]
        self.assertEqual(ligne["statut"], "aucun appel lancé")
        self.assertIn("duration_seconds.minimum", ligne["reponse_brute"])
        self.assertIn("duration_seconds.minimum", ligne["detail"])

    def test_une_autre_date_sans_date_est_lue_et_non_declaree_illisible(self):
        """The 8th real test call, replayed — and this time understood.

        What happened on 02/08/2026: the person asked to have the date
        repeated, the agent concluded `moved` without a date, and RingBack
        declared the answer UNREADABLE (`new_datetime doit etre une date ISO
        8601`). Yet `veut autre chose, rien n'est convenu` is not unreadable at
        all: it is to_reschedule, which the brief itself asks of the agent —
        except in a cascade, the only kind that lacked that fallback.
        """
        for vide in ("", None):
            with self.subTest(new_datetime=vide):
                lu = calle_client.valider_resultat_cascade(
                    {"outcome": "moved", "new_datetime": vide,
                     "notes": "La personne a demandé qu'on lui répète la date."})
                self.assertEqual(lu["outcome"], "to_reschedule")
                self.assertIsNone(lu["new_datetime"])
        # The same fallback on the classic callback side.
        lu = calle_client.valider_resultat(
            {"appointment_status": "rescheduled", "new_datetime": "",
             "notes": "Rien n'a été convenu."})
        self.assertEqual(lu["appointment_status"], "to_reschedule")
        # And a REAL agreed date remains a move: the fallback applies only to
        # the absence of a date, never to its presence.
        lu = calle_client.valider_resultat_cascade(
            {"outcome": "moved", "new_datetime": "2026-09-15T14:30",
             "notes": "Le 15 septembre lui va."})
        self.assertEqual(lu["outcome"], "moved")

    def test_la_citation_commence_par_le_resultat_qui_a_echoue(self):
        """A truncated quotation must keep the essentials, not the alphabet.

        On 02/08/2026, the quotation started from the whole response sorted by
        key name: `structured_result` came last and truncation at 2000
        characters carried away the only piece that said why the read had
        failed.
        """
        etat = {
            "completed_at": "2026-08-02T10:47:33Z",
            "evidence": ["blabla " * 400],  # enough to exceed the limit
            "recipients": [{"structured_result": {
                "outcome": "chose_inconnue", "new_datetime": "",
                "notes": "…"}}],
        }
        with self.assertRaises(calle_client.ResultatInvalide) as refus:
            calle_client.lire_appel_termine(
                etat, calle_client.valider_resultat_cascade)
        cite = refus.exception.reponse_brute
        self.assertIn("chose_inconnue", cite)
        self.assertLess(cite.index("chose_inconnue"),
                        calle_client.LIMITE_REPONSE_BRUTE)

    def test_le_detecteur_de_champs_reserves_les_reconnait(self):
        """The safety lock catches what made the 7th real test call fail.

        It is not enough for today's schemas to be clean: the day someone adds
        `call_duration` or `started_at`, a test must say so HERE — and not
        CALL-E, remotely, in the middle of a campaign, through a 400.
        """
        for nom in ("duration_seconds", "summary", "status", "transcript",
                    "call_id", "started_at", "completed_at", "call_duration"):
            with self.subTest(nom=nom):
                self.assertEqual(
                    calle_client.champs_reserves_dans(
                        {"properties": {nom: {"type": "string"}}}), [nom])
        # And it does NOT fire on the fields the API accepts: on 02/08/2026 it
        # validated appointment_status and new_datetime in the very request
        # where it refused duration_seconds.
        for nom in ("appointment_status", "new_datetime", "notes", "outcome"):
            with self.subTest(nom=nom):
                self.assertEqual(
                    calle_client.champs_reserves_dans(
                        {"properties": {nom: {"type": "string"}}}), [])

    def test_la_citation_masque_les_numeros_de_telephone(self):
        """A quotation stays a quotation — but never a number in clear."""
        self.faux.code_erreur_post = 400
        self.faux.corps_erreur = {"error": "invalid recipient +33639985042"}
        planif = self._planificateur_deverrouille(self._client())
        with self.assertRaises(calle_client.EchecDeNotreCote) as refus:
            planif.executer(seulement=planif.programmer(self.rdv_id))
        message = refus.exception.message()
        self.assertIn("invalid recipient", message)
        self.assertNotIn("+33639985042", message)
        self.assertNotIn("+33639985042", self._lignes_audit()[0]["reponse_brute"])


class _TestAvecServeurWeb(unittest.TestCase):
    """Shared setup: web server on a free port, in-memory database (no trace).

    The allowed calling window (politeness safety lock, 9am-7pm by default) is
    thrown WIDE open here so that the tests can place calls at any hour; the
    out-of-window refusal has its own dedicated tests (TestServeurPlageHoraire)
    which deliberately set a closed window.
    """

    appels_reels = False

    def setUp(self):
        self.serveur_http = serveur.creer_serveur(
            port=0, chemin_base=":memory:", appels_reels=self.appels_reels)
        fil = threading.Thread(target=self.serveur_http.serve_forever, daemon=True)
        fil.start()
        self.racine = f"http://127.0.0.1:{self.serveur_http.server_address[1]}"
        preferences = self.application.preferences
        preferences.definir(serveur.themes.CLE_PLAGE_DEBUT, "00:00")
        preferences.definir(serveur.themes.CLE_PLAGE_FIN, "23:59")

    def tearDown(self):
        self.serveur_http.shutdown()
        self.serveur_http.server_close()

    @property
    def application(self):
        return self.serveur_http.RequestHandlerClass.application

    # `fenetre` SAYS WHICH SIDE WE KNOCK ON. The product answers either a
    # WINDOW (a fragment, when the request comes from the modal machinery), or
    # a whole PAGE (ordinary form submission, browser without JavaScript, the
    # `Sans glisser` fallback). Tests that did not specify it therefore
    # exercised the page while believing they exercised the window — that is
    # how the dead end of 17/08/2026 slipped through.
    ENTETE_FENETRE = {"X-RingBack-Fragment": "1"}

    def _obtenir(self, chemin, fenetre=False):
        demande = urllib.request.Request(
            self.racine + chemin,
            headers=self.ENTETE_FENETRE if fenetre else {})
        with urllib.request.urlopen(demande, timeout=5) as reponse:
            return reponse.status, reponse.read().decode("utf-8")

    def _poster(self, chemin, donnees=None, fenetre=False):
        # doseq: a repeated field (several values with the same name, like the
        # custom fields the page carries) is sent line by line.
        octets = urllib.parse.urlencode(donnees or {},
                                        doseq=True).encode("utf-8")
        demande = urllib.request.Request(
            self.racine + chemin, data=octets,
            headers=self.ENTETE_FENETRE if fenetre else {})
        with urllib.request.urlopen(demande, timeout=15) as reponse:
            return reponse.status, reponse.read().decode("utf-8")

    def _brouillon(self, page):
        """The identifier of the wizard draft the page carries."""
        return re.search(r'name="b" value="(\d+)"', page).group(1)

    @staticmethod
    def _valeur_affichee(page, ident):
        """The value a field ALREADY CARRIES in the page (None if it is not
        there).

        WHAT THE BROWSER WOULD SEND BACK, and that is the whole point. A test
        that posts an invented value in place of the pre-filled one no longer
        exercises the computation: it overwrites it, then measures its own
        invention. Two slot tests lived like that since 17/08/2026 — they went
        green with a stock worth `mardi 9h00, mercredi 14h30`.
        """
        zone = re.search(r'<textarea[^>]*id="%s"[^>]*>(.*?)</textarea>'
                         % re.escape(ident), page, re.S)
        if zone:
            return html.unescape(zone.group(1))
        balise = re.search(r'<input[^>]*id="%s"[^>]*>' % re.escape(ident), page)
        if not balise:
            return None
        valeur = re.search(r'value="([^"]*)"', balise.group(0))
        return html.unescape(valeur.group(1)) if valeur else ""

    def _menu_relances(self, page):
        """The menu of callback types: {label: count}.

        The count is in its own <span> (it is coloured differently); we read it
        back rather than writing the markup into every test.
        """
        return {libelle.strip(): int(nombre) for libelle, nombre in re.findall(
            r'data-vue="panneau-[a-z_]+">(.*?)'
            r'<span class="famille-nombre">\((\d+)\)</span>', page)}

    def _panneau_relance(self, page, code):
        """The panel of a callback type: (visible, HTML content)."""
        ouverture = re.search(
            r'<section class="panneau-relance" id="panneau-%s"( hidden)?>'
            % code, page)
        self.assertIsNotNone(ouverture, f"panneau « {code} » absent de la page")
        fin = page.index("</section>", ouverture.end())
        return ouverture.group(1) is None, page[ouverture.end():fin]

    def _demarrer(self, campagne_id):
        """Start, including the gesture on the calendar.

        The cockpit requires a CONSCIOUS confirmation before launching: the
        slots announced over the phone come from RingBack's calendar, and an
        out-of-date calendar would make it offer slots already taken elsewhere.
        Clicking the panel's button sends `agenda_verifie=1` — that is what
        this shortcut reproduces. The REFUSAL when that gesture is missing has
        its own dedicated tests (TestVerificationAgendaAvantDemarrage).
        """
        return self._poster("/campagne/demarrer",
                            {"campagne": campagne_id, "agenda_verifie": "1"})

    def _attendre_statut(self, campagne_id, statut, delai=30):
        """Waits for a campaign launched in a background thread to reach THIS
        status.
        """
        fin = time.monotonic() + delai
        while time.monotonic() < fin:
            if (self.application.base.obtenir_campagne(campagne_id)["statut"]
                    == statut):
                return
            time.sleep(0.1)
        self.fail(f"La campagne n°{campagne_id} n'a pas atteint le statut "
                  f"« {statut} » (statut actuel : "
                  f"{self.application.base.obtenir_campagne(campagne_id)['statut']}).")


class TestServeur(_TestAvecServeurWeb):

    def test_demarrage_liste_et_rappel(self):
        statut, accueil = self._obtenir("/suivi")
        self.assertEqual(statut, 200)
        # THREE SECTIONS WERE REMOVED from this screen (10/08/2026): `A
        # rappeler (manques)`, `A contacter a la main` and `Rendez-vous a
        # venir`. All that remains is the schedule and the import gesture —
        # plus the link to `Tous les rendez-vous`, without which no list would
        # be reachable from here any more.
        for retiree in ("À rappeler (manqués)", "À contacter à la main",
                        "Rendez-vous à venir"):
            with self.subTest(retiree=retiree):
                self.assertNotIn(retiree, accueil)
        self.assertIn("＋ Importer votre agenda", accueil)
        self.assertIn('href="/tous"', accueil)
        self.assertNotIn("+33 6 39 98 50 41", accueil)  # jamais en clair
        _, tous = self._obtenir("/tous")
        self.assertIn("••", tous)  # masked numbers
        self.assertNotIn("+33 6 39 98 50 41", tous)
        donnees = urllib.parse.urlencode({"rdv": 1}).encode("ascii")
        with urllib.request.urlopen(self.racine + "/rappeler", data=donnees,
                                    timeout=10) as reponse:
            fiche = reponse.read().decode("utf-8")  # 303 suivi automatiquement
        self.assertIn("Transcription", fiche)
        self.assertIn("appointment_status", fiche)

    def test_ajout_par_formulaire_puis_detection_manque(self):
        donnees = urllib.parse.urlencode({
            "nom": "Mme Ajoutée EnLigne", "telephone": "+33 6 39 98 50 49",
            "date_heure": HIER, "motif": "Séance ajoutée"}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            confirmation = reponse.read().decode("utf-8")
        self.assertIn("Rendez-vous enregistré", confirmation)
        self.assertIn("+33 6 •• •• •• 49", confirmation)  # masked
        self.assertNotIn("+33 6 39 98 50 49", confirmation)  # jamais en clair
        # A past time slot becomes `manque`: it is read in `Tous les
        # rendez-vous` since `A rappeler` was removed (10/08/2026).
        _, tous = self._obtenir("/tous")
        self.assertIn("Mme Ajoutée EnLigne", tous)

    def test_ajout_futur_visible_immediatement(self):
        """The defect as lived: a future entry must be visible RIGHT AWAY.

        `Rendez-vous a venir` WAS REMOVED on 10/08/2026: what matters stays the
        same — the entry must not vanish into thin air. It is visible on the
        SCHEDULE (its tile) and in `Tous les rendez-vous`, and the confirmation
        leads to both.
        """
        donnees = urllib.parse.urlencode({
            "nom": "Mme Danse Exemple", "telephone": "+33 6 39 98 50 45",
            "date_heure": DEMAIN, "motif": "Séance de danse"}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            confirmation = reponse.read().decode("utf-8")
        # The confirmation says WHERE the appointment is visible, with its
        # links.
        self.assertIn("visible dès maintenant sur le planning", confirmation)
        self.assertIn('href="/suivi"', confirmation)
        self.assertIn('href="/tous"', confirmation)
        # The schedule carries its tile, immediately. ON THE APPOINTMENT'S
        # WEEK, NOT ON `the current week` (16/08/2026). The schedule opens on
        # today's week: on a SUNDAY, `tomorrow` falls in the NEXT week, and the
        # test failed — measuring the calendar, not the product. It is the same
        # family of trap as the bench's working days (see
        # banc_essai._jour_ouvre).
        demain = datetime.date.fromisoformat(DEMAIN[:10])
        annee, semaine, _ = demain.isocalendar()
        _, accueil = self._obtenir(f"/suivi?annee={annee}&semaine={semaine}")
        self.assertIn("Mme Danse Exemple", accueil)
        self.assertNotIn("+33 6 39 98 50 45", accueil)   # jamais en clair
        # And the full list shows it, number masked as everywhere else.
        _, tous = self._obtenir("/tous")
        self.assertIn("Mme Danse Exemple", tous)
        self.assertIn("Séance de danse", tous)
        self.assertIn("+33 6 •• •• •• 45", tous)
        self.assertNotIn("+33 6 39 98 50 45", tous)

    def test_ajout_passe_pointe_vers_a_rappeler(self):
        donnees = urllib.parse.urlencode({
            "nom": "M. Manqué Hier", "telephone": "+33 6 39 98 50 46",
            "date_heure": HIER, "motif": "Essai"}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            confirmation = reponse.read().decode("utf-8")
        self.assertIn("Statut : manqué", confirmation)
        # The link no longer points at an anchor that has disappeared.
        self.assertIn("Tous les rendez-vous", confirmation)
        self.assertNotIn("#a-rappeler", confirmation)

    def test_page_tous_les_rendezvous(self):
        # One future appointment on top of the demo's 4 missed ones: it must
        # come out first (reverse chronological order) with its status visible.
        donnees = urllib.parse.urlencode({
            "nom": "Mme Complète Liste", "telephone": "+33 6 39 98 50 47",
            "date_heure": DEMAIN, "motif": "Essai complet"}).encode("utf-8")
        urllib.request.urlopen(self.racine + "/ajouter", data=donnees, timeout=5).read()
        statut, page = self._obtenir("/tous")
        self.assertEqual(statut, 200)
        self.assertIn("Tous les rendez-vous (5)", page)
        self.assertIn("prévu", page)  # the statuses are visible
        self.assertIn("manqué", page)
        self.assertLess(page.index("Mme Complète Liste"),  # most recent first
                        page.index("Mme Nadia Lefèvre"))
        self.assertNotIn("+33 6 39 98 50 4", page)       # jamais en clair

    def test_doublon_signale_puis_ajout_explicite(self):
        base = self.application.base
        donnees = urllib.parse.urlencode({
            "nom": "Mme Double Saisie", "telephone": "+33 6 39 98 50 48",
            "date_heure": DEMAIN, "motif": "Séance unique"}).encode("utf-8")
        urllib.request.urlopen(self.racine + "/ajouter", data=donnees, timeout=5).read()
        avant = base.conn.execute("SELECT COUNT(*) FROM rendezvous").fetchone()[0]
        # Same client + same time slot: REPORTED, nothing created.
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn("Ce rendez-vous existe déjà", page)
        self.assertIn("rien n'a été ajouté", page)
        self.assertIn("Ajouter quand même", page)
        self.assertIn("+33 6 •• •• •• 48", page)  # masked
        self.assertNotIn("+33 6 39 98 50 48", page)          # jamais en clair
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM rendezvous").fetchone()[0], avant)  # no duplicate
        # `Add anyway`: the addition happens, EXPLICITLY.
        client_id = re.search(r'name="forcer" value="(\d+)"', page).group(1)
        confirmation_donnees = urllib.parse.urlencode({
            "forcer": client_id, "date_heure": DEMAIN,
            "motif": "Séance unique"}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter",
                                    data=confirmation_donnees, timeout=5) as reponse:
            confirmation = reponse.read().decode("utf-8")
        self.assertIn("Rendez-vous enregistré", confirmation)
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM rendezvous").fetchone()[0], avant + 1)
        self.assertEqual(base.compter_clients(), 5)  # 4 demo + 1, no duplicate client

    def test_ajout_invalide_affiche_les_erreurs_en_francais(self):
        donnees = urllib.parse.urlencode({
            "nom": "", "telephone": "12345",
            "date_heure": "bientôt", "motif": ""}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn("Saisie refusée", page)
        self.assertIn("Numéro de téléphone invalide", page)
        self.assertIn("Date illisible", page)

    def test_import_csv_par_le_serveur(self):
        contenu = ("nom;telephone;date_heure;motif\n"
                   f"Mme Import Réseau;+33 6 39 98 50 45;{HIER};Consultation\n"
                   "M. Numero Faux;12345;2026-08-01T10:00;Essai\n")
        frontiere = "----frontiereDeTest"
        corps = (f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="fichier"; filename="import.csv"\r\n'
                 "Content-Type: text/csv\r\n\r\n"
                 f"{contenu}\r\n--{frontiere}--\r\n").encode("utf-8")
        requete = urllib.request.Request(
            self.racine + "/importer", data=corps,
            headers={"Content-Type": f"multipart/form-data; boundary={frontiere}"})
        with urllib.request.urlopen(requete, timeout=5) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn("<strong>1</strong> rendez-vous importé", page)
        self.assertIn("Ligne 3", page)  # the offending row is reported
        _, tous = self._obtenir("/tous")
        self.assertIn("Mme Import Réseau", tous)
        self.assertNotIn("+33 6 39 98 50 45", tous)  # still masked


class TestServeurFileAppels(_TestAvecServeurWeb):
    """The `Call queue` page: call everyone back, cancel, run, summary."""

    def test_page_file_vide_au_depart(self):
        statut, page = self._obtenir("/file")
        self.assertEqual(statut, 200)
        self.assertIn("File d'appels", page)
        self.assertIn("La file est vide", page)
        self.assertIn("Tout rappeler", page)
        self.assertIn("Bilan des issues", page)
        self.assertIn("Mode simulation", page)

    def test_tout_rappeler_annuler_puis_executer(self):
        # 1. `Call everyone back`: the demo's 4 missed appointments enter the
        # queue.
        _, page = self._poster("/file/tout-rappeler")
        self.assertIn("4 appel(s) mis en file", page)
        self.assertIn("Mme Nadia Lefèvre", page)
        self.assertIn("Appels en attente (4)", page)
        self.assertIn("••", page)  # masked numbers
        self.assertNotIn("+33 6 39 98 50 41", page)     # jamais en clair
        # Clicking again duplicates no call.
        _, page = self._poster("/file/tout-rappeler")
        self.assertIn("Aucun nouvel appel", page)
        self.assertIn("Appels en attente (4)", page)
        # 2. Cancel the first call in the queue BEFORE running.
        premier = self.application.planif.file[0]["appel_id"]
        _, page = self._poster("/file/annuler", {"appel": premier})
        self.assertIn("Appel retiré de la file", page)
        self.assertIn("Appels en attente (3)", page)
        self.assertEqual(self.application.base.obtenir_appel(premier)["statut"],
                         "annulé")
        # Cancelling it again: not found, without breaking.
        _, page = self._poster("/file/annuler", {"appel": premier})
        self.assertIn("introuvable", page)
        # 3. Run the queue: the 3 remaining calls go out (simulated).
        _, page = self._poster("/file/executer")
        self.assertIn("Exécution terminée", page)
        self.assertIn("<strong>3</strong> appel(s) traité(s)", page)
        self.assertIn("Voir la fiche", page)
        self.assertIn("Bilan des issues", page)
        self.assertNotIn("+33 6 39 98 50 4", page)      # jamais en clair
        # 4. The summary counts exactly the 3 outcomes (the cancelled one does
        # not count).
        bilan = self.application.base.bilan_issues()
        self.assertEqual(sum(bilan.values()), 3)
        _, page_file = self._obtenir("/file")
        self.assertIn("La file est vide", page_file)  # everything went out


class TestServeurCascade(_TestAvecServeurWeb):
    """The `First yes cascade` page, exercised through real HTTP requests."""

    LISTE = ("Mme Refus Un;+33 6 39 98 50 52\n"
             "M. Silence Deux, 06 39 98 50 53\n"
             "Mme Accord Trois;+33 6 39 98 50 51\n"
             "M. Épargné Quatre;+33 6 39 98 50 49\n")

    def test_formulaire_pre_rempli(self):
        statut, page = self._obtenir("/cascade")
        self.assertEqual(statut, 200)
        self.assertIn("Cascade « premier oui »", page)
        self.assertIn("j&#x27;appelle de la part de [entreprise]", page)
        self.assertIn("Créneau proposé", page)

    def test_cascade_de_bout_en_bout_par_http(self):
        _, page = self._poster("/cascade/executer", {
            "liste": self.LISTE, "mission": "Un créneau s'est libéré [créneau]. "
            "Intéressé ?", "creneau": DEMAIN})    # 303 suivi automatiquement
        self.assertIn("créneau pourvu", page)
        self.assertIn("Créneau attribué à <strong>Mme Accord Trois</strong>", page)
        self.assertIn("Personnes appelées (3)", page)
        self.assertIn("Pas de réponse", page)                # M. Silence Deux
        # THE DISPLAYED WORD COMES FROM `mot_etat` (14/08/2026, cross audit):
        # this page still wrote `epargne` in clear, alone in the whole product,
        # whereas the owner said he did not understand that word.
        self.assertIn("Personnes non appelées (1)", page)
        self.assertIn("M. Épargné Quatre", page)
        self.assertIn("pas appelé (créneau pris)", page)
        self.assertNotIn("épargné (créneau pris)", page)
        self.assertIn("jamais appelé", page)
        self.assertIn("Transcriptions", page)
        self.assertIn("••", page)  # masked numbers
        self.assertNotIn("+33 6 39 98 50 5", page)           # jamais en clair
        self.assertNotIn("+33 6 39 98 50 49", page)
        self.assertNotIn("[créneau]", page)  # template substituted
        # The created appointment is indeed visible on the application side.
        cascade = self.application.base.obtenir_cascade(1)
        rdv = self.application.base.obtenir_rendezvous(cascade["rendezvous_id"])
        self.assertEqual((rdv["nom"], rdv["horaire"], rdv["statut"]),
                         ("Mme Accord Trois", DEMAIN, "confirmé"))

    def test_liste_epuisee_message_honnete(self):
        _, page = self._poster("/cascade/executer", {
            "liste": "Mme Refus Un;+33 6 39 98 50 52\n",
            "mission": "Un créneau s'est libéré.", "creneau": DEMAIN})
        self.assertIn("liste épuisée, créneau non pourvu", page)
        self.assertIn("personne n'a pris le créneau", page)

    def test_saisie_refusee_en_francais_sans_reafficher_les_numeros(self):
        # The 47 appears nowhere else in the page (unlike the template's static
        # examples): if it showed up, it would be the list.
        _, page = self._poster("/cascade/executer", {
            "liste": "pas de séparateur ici\nM. Bon;+33 6 39 98 50 47\n",
            "mission": "", "creneau": ""})
        self.assertIn("Saisie refusée", page)
        self.assertIn("séparateur introuvable", page)
        self.assertIn("La mission est obligatoire", page)
        self.assertIn("Créneau proposé", page)
        self.assertIn("la liste (qui contient des numéros", page)
        self.assertNotIn("+33 6 39 98 50 47", page)  # the list is not echoed back
        self.assertNotIn("M. Bon", page)


class TestServeurGenerationCascade(_TestAvecServeurWeb):
    """List generation from the database + CSV export, through real requests.
    """

    def _poster_brut(self, chemin, donnees):
        """POST returning (status, headers, bytes) — to inspect the CSV."""
        octets = urllib.parse.urlencode(donnees).encode("utf-8")
        with urllib.request.urlopen(self.racine + chemin, data=octets,
                                    timeout=15) as reponse:
            return reponse.status, dict(reponse.headers), reponse.read()

    def test_premiere_visite_aucun_ordre_preselectionne(self):
        _, page = self._obtenir("/cascade")
        self.assertIn("Remplir depuis les rendez-vous", page)
        self.assertIn("aucun ordre n'est imposé", page)
        for code in generation.ORDRES:
            self.assertNotIn(f'value="{code}" checked', page)  # NO order ticked
        self.assertIn('value="annules" checked', page)         # source, elle, l'est

    def test_generation_injecte_puis_memorise_l_ordre(self):
        _, page = self._poster("/cascade/generer", {
            "liste": "", "mission": "Mission.", "creneau": "",
            "source": "tous", "ordre": "alphabetique"})
        self.assertIn("4 personne(s) dans la liste", page)
        # The list is INJECTED into the paste area, in clear (that is its
        # purpose), in alphabetical order without regard for the honorific.
        zone = re.search(r"<textarea[^>]*>([^<]*)</textarea>", page).group(1)
        self.assertEqual(html.unescape(zone).splitlines(), [
            "Mme Élise Charpentier;+33 6 39 98 50 43",
            "M. Karim Osman;+33 6 39 98 50 42",
            "Mme Nadia Lefèvre;+33 6 39 98 50 41",
            "M. Paul Guillot;+33 6 39 98 50 44"])
        # The choice is remembered: the next page preselects that order.
        _, page = self._obtenir("/cascade")
        self.assertIn('value="alphabetique" checked', page)
        self.assertIn('value="tous" checked', page)

    def test_generation_sans_ordre_refusee_liste_conservee(self):
        _, page = self._poster("/cascade/generer", {
            "liste": "M. Garde Contenu;+33 6 39 98 50 47", "mission": "Mission.",
            "creneau": "", "source": "annules", "ordre": ""})
        self.assertIn("aucun ordre n&#x27;est imposé par défaut", page)
        self.assertIn("M. Garde Contenu;+33 6 39 98 50 47", page)  # area preserved

    def test_proximite_sans_creneau_refusee(self):
        _, page = self._poster("/cascade/generer", {
            "liste": "", "mission": "Mission.", "creneau": "",
            "source": "tous", "ordre": "proximite"})
        self.assertIn("créneau proposé", page)

    def test_generation_signale_les_sans_numero(self):
        base = self.application.base
        client_id = base.obtenir_ou_creer_client("Mme Sans Fil", "")
        base.ajouter_rendezvous(client_id, DEMAIN, "Essai")
        _, page = self._poster("/cascade/generer", {
            "liste": "", "mission": "Mission.", "creneau": "",
            "source": "tous", "ordre": "alphabetique"})
        self.assertIn("1 client(s) sans numéro exclu(s)", page)
        self.assertIn("/sans-numero", page)

    def test_csv_telecharge_avec_bom_et_en_clair(self):
        statut, entetes, octets = self._poster_brut("/cascade/csv", {
            "liste": "", "mission": "Mission.", "creneau": "",
            "source": "tous", "ordre": "anciennete"})
        self.assertEqual(statut, 200)
        self.assertIn("text/csv", entetes["Content-Type"])
        self.assertRegex(entetes["Content-Disposition"],
                         r'attachment; filename="liste_rappel_\d{8}\.csv"')
        self.assertTrue(octets.startswith(b"\xef\xbb\xbf"))  # BOM for Excel
        texte = octets.decode("utf-8-sig")
        self.assertTrue(texte.startswith("nom;telephone\r\n"))
        self.assertIn("+33 6 39 98 50 41", texte)  # IN CLEAR: that is the file's purpose
        # Seniority: the two appointments from the day before yesterday before
        # yesterday's.
        self.assertLess(texte.index("Mme Élise Charpentier"),
                        texte.index("Mme Nadia Lefèvre"))

    def test_csv_respecte_la_zone_de_collage_reordonnee(self):
        # The user reordered their list by hand: the CSV respects it.
        _, entetes, octets = self._poster_brut("/cascade/csv", {
            "liste": ("M. Zoulou Dernier;+33 6 39 98 50 49\n"
                      "Mme Alpha Premiere;+33 6 39 98 50 48\n"),
            "mission": "Mission.", "creneau": "", "source": "", "ordre": ""})
        texte = octets.decode("utf-8-sig")
        self.assertEqual(texte.splitlines(), [
            "nom;telephone",
            "M. Zoulou Dernier;+33 6 39 98 50 49",
            "Mme Alpha Premiere;+33 6 39 98 50 48"])

    def test_cascade_generee_puis_lancee(self):
        _, page = self._poster("/cascade/generer", {
            "liste": "", "mission": "Mission de test.", "creneau": DEMAIN,
            "source": "tous", "ordre": "anciennete"})
        zone = html.unescape(
            re.search(r"<textarea[^>]*>([^<]*)</textarea>", page).group(1))
        _, page = self._poster("/cascade/executer", {
            "liste": zone, "mission": "Un créneau s'est libéré [créneau].",
            "creneau": DEMAIN})
        self.assertIn("Cascade n°", page)  # the generated cascade ran
        cascade = self.application.base.lister_cascades()[0]
        appels = self.application.base.appels_de_cascade(cascade["id"])
        self.assertEqual(len(appels), 4)  # the demo's 4 clients
        self.assertNotIn("+33 6 39 98 50 4", page)  # and still nothing in clear


class TestServeurPreferencesDisque(unittest.TestCase):
    """The last chosen order survives a restart (donnees/preferences.json)."""

    def test_preference_ecrite_puis_relue_apres_redemarrage(self):
        dossier = tempfile.mkdtemp(prefix="ringback-prefsrv-")
        self.addCleanup(shutil.rmtree, dossier, ignore_errors=True)
        chemin_base = os.path.join(dossier, "ringback.db")

        def demarrer():
            serveur_http = serveur.creer_serveur(port=0, chemin_base=chemin_base)
            threading.Thread(target=serveur_http.serve_forever, daemon=True).start()
            return serveur_http, f"http://127.0.0.1:{serveur_http.server_address[1]}"

        premier, racine = demarrer()
        octets = urllib.parse.urlencode({
            "liste": "", "mission": "Mission.", "creneau": "",
            "source": "annules", "ordre": "alphabetique",
        }).encode("utf-8")
        urllib.request.urlopen(racine + "/cascade/generer", data=octets,
                               timeout=15).read()
        chemin_prefs = os.path.join(dossier, "preferences.json")
        self.assertTrue(os.path.exists(chemin_prefs))  # written NEXT TO the database
        with open(chemin_prefs, encoding="utf-8") as fichier:
            self.assertEqual(json.load(fichier)["cascade_ordre"], "alphabetique")
        premier.RequestHandlerClass.application.base.fermer()
        premier.shutdown()
        premier.server_close()
        second, racine = demarrer()  # restart: re-read from disk
        with urllib.request.urlopen(racine + "/cascade", timeout=15) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn('value="alphabetique" checked', page)
        second.RequestHandlerClass.application.base.fermer()
        second.shutdown()
        second.server_close()


class TestServeurImportICS(_TestAvecServeurWeb):
    """ICS calendar import + number completion, through real HTTP requests."""

    def _importer_ics(self, contenu):
        frontiere = "----frontiereDeTest"
        corps = (f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="fichier"; filename="agenda.ics"\r\n'
                 "Content-Type: text/calendar\r\n\r\n"
                 f"{contenu}\r\n--{frontiere}--\r\n").encode("utf-8")
        requete = urllib.request.Request(
            self.racine + "/importer-ics", data=corps,
            headers={"Content-Type": f"multipart/form-data; boundary={frontiere}"})
        with urllib.request.urlopen(requete, timeout=5) as reponse:
            return reponse.read().decode("utf-8")

    def test_import_exemple_puis_completion_du_numero(self):
        chemin = os.path.join(RACINE, "exemple_agenda.ics")
        with open(chemin, encoding="utf-8") as fichier:
            page = self._importer_ics(fichier.read())
        # WE LAND ON THE CALENDAR, report at the top (10/08/2026).
        self.assertIn('<section id="planning">', page)
        self.assertIn("📥 Import terminé", page)
        self.assertIn("<strong>3</strong> rendez-vous importé(s)", page)
        self.assertIn("journée entière", page)  # the event without a time, reported
        self.assertIn("rendez-vous sans numéro — à compléter", page)
        # The `no number` screen lists the three imported appointments.
        _, page_sans = self._obtenir("/sans-numero")
        self.assertIn("Rendez-vous sans numéro", page_sans)
        self.assertIn("Mme Léa Fontaine", page_sans)
        # An invalid number is refused in French...
        client_id = self.application.base.rendezvous_sans_numero()[0]["client_id"]
        _, page_refus = self._poster("/completer-numero",
                                     {"client": client_id, "telephone": "12345"})
        self.assertIn("Numéro refusé", page_refus)
        # ...and a valid number completes the client (masked everywhere
        # afterwards).
        _, page_ok = self._poster("/completer-numero",
                                  {"client": client_id, "telephone": "+33639985049"})
        self.assertEqual(len(self.application.base.rendezvous_sans_numero()), 2)
        self.assertEqual(self.application.base.telephone_de(client_id),
                         "+33 6 39 98 50 49")
        _, accueil = self._obtenir("/suivi")
        self.assertNotIn("+33 6 39 98 50 49", accueil)  # still masked on screen

    def test_fichier_non_ics_refuse(self):
        page_erreur = None
        try:
            self._importer_ics("Ceci n'est pas un agenda.")
        except urllib.error.HTTPError as erreur:
            page_erreur = erreur.read().decode("utf-8")
            self.assertEqual(erreur.code, 400)
        self.assertIn("Aucun événement (VEVENT) trouvé", page_erreur)


class TestServeurModeReel(_TestAvecServeurWeb):
    """On the day, zero code: environment variables + real mode, exercised here
    end to end against the local fake API (never the real one).
    """

    appels_reels = True

    def setUp(self):
        class Faux(_FauxApiCalle):
            creations = []
            etats = [reponse_calle_terminee(dict(RESULTAT_CONFORME))]
        self.faux = Faux
        self.serveur_api = HTTPServer(("127.0.0.1", 0), Faux)
        threading.Thread(target=self.serveur_api.serve_forever, daemon=True).start()
        self.addCleanup(self.serveur_api.server_close)
        self.addCleanup(self.serveur_api.shutdown)
        os.environ["CALLE_API_KEY"] = "cle-de-test-0123456789"  # lock 1 (dummy key)
        os.environ["CALLE_API_URL"] = \
            f"http://127.0.0.1:{self.serveur_api.server_address[1]}"
        self.addCleanup(os.environ.pop, "CALLE_API_KEY", None)
        self.addCleanup(os.environ.pop, "CALLE_API_URL", None)
        # The audit goes to a throwaway folder, not to donnees/.
        self.dossier = tempfile.mkdtemp(prefix="ringback-audit-")
        self.addCleanup(shutil.rmtree, self.dossier, ignore_errors=True)
        self.chemin_audit = os.path.join(self.dossier, "audit.jsonl")
        self._audit_sauve = calle_client.CHEMIN_AUDIT
        calle_client.CHEMIN_AUDIT = self.chemin_audit
        self.addCleanup(setattr, calle_client, "CHEMIN_AUDIT", self._audit_sauve)
        super().setUp()   # creer_serveur(appels_reels=True) lit ces variables

    def test_mode_reel_de_bout_en_bout_sur_fausse_api(self):
        _, accueil = self._obtenir("/")            # accueil = Campagnes
        self.assertIn("MODE RÉEL", accueil)
        # NO BUTTON LEADS HERE ANY MORE since 10/08/2026: the `Rappeler` link
        # lived in `A rappeler (manques)`, removed at the owner's request. The
        # page still exists and does say `REEL` — it remains to decide where to
        # rehouse it.
        _, prepare = self._obtenir("/rappel?rdv=1")
        self.assertIn("RÉEL", prepare)
        _, accueil = self._obtenir("/suivi")
        self.assertNotIn("+33 6 39 98 50 41", accueil)  # masking unchanged
        _, page = self._poster("/file/tout-rappeler")
        self.assertIn("4 appel(s) mis en file", page)
        _, page = self._poster("/file/executer")
        self.assertIn("Exécution terminée", page)
        self.assertIn("<strong>4</strong> appel(s) traité(s)", page)
        self.assertNotIn("+33 6 39 98 50 4", page)
        # The fake API did receive the 4 call creations.
        self.assertEqual(len(self.faux.creations), 4)
        self.assertEqual(self.faux.creations[0]["recipients"][0]["region"], "FR")
        # Each real call left its audit line, number masked.
        with open(self.chemin_audit, encoding="utf-8") as fichier:
            contenu = fichier.read()
        lignes = [json.loads(ligne) for ligne in contenu.splitlines() if ligne.strip()]
        self.assertEqual(len(lignes), 4)
        self.assertNotIn("+33 6 39 98 50 4", contenu)    # jamais en clair
        self.assertTrue(all(l["statut"] == "terminé" for l in lignes))
        self.assertTrue(all("••" in l["telephone"] for l in lignes))


# --------------------------------------------------------------------------
# Improvement batches: clients and lists, call themes, settings, interface
# (light/dark toggle). Everything is exercised for real: in-memory database or
# throwaway folder, never the real donnees/ringback.db database.
# --------------------------------------------------------------------------
class TestMigrationBase(unittest.TestCase):
    """A database on the OLD schema opens and receives the recent columns."""

    def test_ancienne_base_migree_sans_perte(self):
        dossier = tempfile.mkdtemp(prefix="ringback-migration-")
        self.addCleanup(shutil.rmtree, dossier, ignore_errors=True)
        chemin = os.path.join(dossier, "ringback.db")
        import sqlite3
        brute = sqlite3.connect(chemin)
        brute.executescript("""
            CREATE TABLE clients (id INTEGER PRIMARY KEY AUTOINCREMENT,
                                  nom TEXT NOT NULL, telephone TEXT NOT NULL);
            CREATE TABLE rendezvous (id INTEGER PRIMARY KEY AUTOINCREMENT,
                                     client_id INTEGER NOT NULL,
                                     horaire TEXT NOT NULL, motif TEXT NOT NULL,
                                     statut TEXT NOT NULL DEFAULT 'prévu');
            INSERT INTO clients (nom, telephone)
                VALUES ('Mme Ancienne Base', '+33 6 39 98 50 42');
            INSERT INTO rendezvous (client_id, horaire, motif, statut)
                VALUES (1, '2026-01-01T10:00', 'Essai', 'manqué');
        """)
        brute.commit()
        brute.close()
        base = db.Base(chemin)  # the gentle migration plays out here
        self.addCleanup(base.fermer)
        clients = base.lister_clients()
        self.assertEqual(len(clients), 1)
        self.assertEqual(clients[0]["nom"], "Mme Ancienne Base")
        self.assertFalse(clients[0]["ne_plus_appeler"])  # default: callable
        rdv = base.rendezvous_manques()[0]
        self.assertIsNone(rdv["rappel_souhaite"])  # column added, empty
        self.assertEqual(rdv["nom"], "Mme Ancienne Base")  # data intact


class TestNePlusAppeler(unittest.TestCase):
    """The `Do not call again` flag: excluded from the queue, from cascades and
    from generated lists — reversible, and visible in the data.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.marquee = self.base.ajouter_client("Mme Stop Exemple",
                                                "+33 6 39 98 50 51")
        self.rdv_marquee = self.base.ajouter_rendezvous(
            self.marquee, HIER, "Essai", statut="manqué")
        self.autre = self.base.ajouter_client("M. Libre Exemple",
                                              "+33 6 39 98 50 52")
        self.rdv_autre = self.base.ajouter_rendezvous(
            self.autre, HIER, "Essai", statut="manqué")
        self.base.definir_ne_plus_appeler(self.marquee, True)

    def test_drapeau_pose_visible_et_reversible(self):
        client = self.base.obtenir_client(self.marquee)
        self.assertTrue(client["ne_plus_appeler"])
        self.assertEqual(client["telephone_masque"], "+33 6 •• •• •• 51")
        rdv = self.base.obtenir_rendezvous(self.rdv_marquee)
        self.assertTrue(rdv["ne_plus_appeler"])  # carried by the lists
        self.base.definir_ne_plus_appeler(self.marquee, False)  # reversible
        self.assertFalse(self.base.obtenir_client(self.marquee)["ne_plus_appeler"])

    def test_exclu_de_la_mise_en_file_groupee(self):
        planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=1, latence=0))
        crees = planif.programmer_tous_les_manques()
        self.assertEqual(len(crees), 1)                   # seulement M. Libre
        rdv = self.base.obtenir_rendezvous(planif.file[0]["rendezvous_id"])
        self.assertEqual(rdv["nom"], "M. Libre Exemple")

    def test_rappel_individuel_refuse(self):
        planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=1, latence=0))
        with self.assertRaises(planificateur.ClientExclu) as contexte:
            planif.programmer(self.rdv_marquee)
        self.assertIn("Ne plus appeler", str(contexte.exception))
        self.assertEqual(planif.file, [])                 # rien en file

    def test_exclu_de_la_generation_de_liste(self):
        personnes, _ = generation.generer(self.base, "tous", "alphabetique")
        noms = [p["nom"] for p in personnes]
        self.assertEqual(noms, ["M. Libre Exemple"])  # the flagged one is set aside

    def test_cascade_ne_compose_jamais_son_numero(self):
        compteur = ClientCompteur(graine=6, latence=0)
        planif = planificateur.Planificateur(self.base, compteur)
        cascade_id = planif.executer_cascade(
            [{"nom": "Mme Stop Exemple", "telephone": "+33 6 39 98 50 51"},
             {"nom": "M. Libre Exemple", "telephone": "+33 6 39 98 50 52"}],
            "Un créneau s'est libéré.", DEMAIN)
        # PROOF by counter: the flagged number was NEVER dialled, even when
        # pasted into the list by hand.
        self.assertEqual(compteur.numeros_composes, ["+33 6 •• •• •• 52"])
        appels = self.base.appels_de_cascade(cascade_id)
        self.assertEqual([a["etat"] for a in appels], ["exclu", "appelé"])
        self.assertIsNone(appels[0]["issue"])  # excluded: no outcome


class TestViderLesListes(unittest.TestCase):
    """`Empty the list` (missed -> ignored, reversible) and `Empty the queue`.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        client_id = self.base.ajouter_client("Mme Vide Exemple", "+33 6 39 98 50 42")
        self.rdv_un = self.base.ajouter_rendezvous(client_id, HIER, "Un", statut="manqué")
        self.rdv_deux = self.base.ajouter_rendezvous(client_id, HIER, "Deux", statut="manqué")
        self.rdv_prevu = self.base.ajouter_rendezvous(client_id, DEMAIN, "Futur")

    def test_ignorer_tous_reversible_par_rendezvous(self):
        self.assertEqual(self.base.ignorer_tous_les_manques(), 2)
        self.assertEqual(self.base.rendezvous_manques(), [])  # list emptied
        self.assertEqual(self.base.obtenir_rendezvous(self.rdv_prevu)["statut"],
                         "prévu")                                  # intact
        # The missed-appointment rule does NOT swallow the ignored ones again.
        self.base.marquer_manques_echus()
        self.assertEqual(self.base.obtenir_rendezvous(self.rdv_un)["statut"],
                         "ignoré")
        # Reversible, one by one, from `Tous les rendez-vous`.
        self.assertTrue(self.base.retablir_manque(self.rdv_un))
        self.assertEqual(self.base.obtenir_rendezvous(self.rdv_un)["statut"],
                         "manqué")
        self.assertFalse(self.base.retablir_manque(self.rdv_prevu))  # not ignored
        self.assertEqual(self.base.ignorer_tous_les_manques(), 1)  # re-vidable

    def test_vider_la_file_avant_execution(self):
        planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=2, latence=0))
        premier = planif.programmer(self.rdv_un)
        second = planif.programmer(self.rdv_deux)
        self.assertEqual(planif.annuler_tout(), 2)
        self.assertEqual(planif.file, [])
        for appel_id in (premier, second):
            self.assertEqual(self.base.obtenir_appel(appel_id)["statut"], "annulé")
        self.assertEqual(planif.executer(), [])  # nothing left to run
        self.assertEqual(planif.annuler_tout(), 0)  # queue already empty


class TestSuppressionClient(unittest.TestCase):
    """Deleting a client takes their appointments AND their calls with it."""

    def test_suppression_en_cascade(self):
        base = db.Base(":memory:")
        self.addCleanup(base.fermer)
        vise = base.ajouter_client("Mme Partira Exemple", "+33 6 39 98 50 42")
        rdv_id = base.ajouter_rendezvous(vise, HIER, "Essai", statut="manqué")
        appel_id = base.creer_appel(rdv_id)
        temoin = base.ajouter_client("M. Restera Exemple", "+33 6 39 98 50 43")
        rdv_temoin = base.ajouter_rendezvous(temoin, DEMAIN, "Essai")
        self.assertEqual(base.supprimer_client(vise), 1)  # 1 appointment taken along
        self.assertIsNone(base.obtenir_client(vise))
        self.assertIsNone(base.obtenir_rendezvous(rdv_id))
        self.assertIsNone(base.obtenir_appel(appel_id))
        # The neighbour lost nothing.
        self.assertIsNotNone(base.obtenir_client(temoin))
        self.assertIsNotNone(base.obtenir_rendezvous(rdv_temoin))

    def test_purge_de_la_file_du_planificateur(self):
        base = db.Base(":memory:")
        self.addCleanup(base.fermer)
        client_id = base.ajouter_client("Mme File Exemple", "+33 6 39 98 50 42")
        rdv_id = base.ajouter_rendezvous(client_id, HIER, "Essai", statut="manqué")
        planif = planificateur.Planificateur(
            base, calle_client.AppelSimule(graine=3, latence=0))
        planif.programmer(rdv_id)
        self.assertEqual(planif.purger_rendezvous(base.rendezvous_du_client(client_id)), 1)
        self.assertEqual(planif.file, [])


class TestThemesAppel(unittest.TestCase):
    """The mission templates by theme and their substituted variables."""

    def setUp(self):
        self.prefs = generation.Preferences()  # in memory

    def test_quatre_themes_et_gabarits_francais(self):
        # Four since 03/08/2026: `Personnalise` left along with the kind of the
        # same name. Its template was empty — a theme that says nothing makes
        # you write the message twice.
        self.assertEqual(list(themes.THEMES),
                         ["manque", "confirmation", "deplacement",
                          "creneau_libere"])
        self.assertEqual(list(themes.GABARITS), list(themes.THEMES))
        for code in themes.THEMES:
            self.assertIn("Bonjour", themes.GABARITS[code])
            self.assertIn("[entreprise]", themes.GABARITS[code])
            # NEVER a phone number in a template (convention).
            self.assertNotRegex(themes.GABARITS[code], r"\d{4}")
        # The first theme's label no longer speaks of a missed CALL but of a
        # missed APPOINTMENT: that is what it does, and the old name was
        # confused with a removed kind which did speak of a call.
        self.assertEqual(themes.THEMES["manque"],
                         "① Rappel d'un rendez-vous manqué")

    def test_variables_laissees_telles_quelles_sans_reglage(self):
        texte = themes.preremplir("manque", self.prefs)
        self.assertIn("[entreprise]", texte)  # not set: visible
        self.assertIn("[créneaux_disponibles]", texte)
        self.assertIn("entre 9h00 et 19h00", texte)  # window: real default
        self.assertNotIn("[plage_rappel]", texte)

    def test_variables_substituees_depuis_les_reglages(self):
        self.prefs.definir(themes.CLE_ENTREPRISE, "Cabinet Essai Santé")
        self.prefs.definir(themes.CLE_CRENEAUX,
                           ["2026-08-01T14:00", "2026-08-02T09:30"])
        self.prefs.definir(themes.CLE_PLAGE_DEBUT, "08:30")
        self.prefs.definir(themes.CLE_PLAGE_FIN, "18:00")
        texte = themes.preremplir("deplacement", self.prefs,
                                  nom_client="Mme Cliente Exemple",
                                  date_rdv="2026-08-05T11:00")
        self.assertIn("Cabinet Essai Santé", texte)
        # THIS TEXT IS SPOKEN OVER THE PHONE: dates in it are spelled out in
        # full since 24/08/2026. `le 01/08/2026 a 14h00` cannot be pronounced —
        # a voice agent reads slashes in it.
        self.assertIn("le samedi 1 août 2026 à 14 heures, "
                      "le dimanche 2 août 2026 à 9 heures 30", texte)
        self.assertIn("entre 8h30 et 18h00", texte)
        self.assertIn("Mme Cliente Exemple", texte)
        self.assertIn("le mercredi 5 août 2026 à 11 heures", texte)
        for variable in ("[entreprise]", "[créneaux_disponibles]",
                         "[plage_rappel]", "[client]", "[date_rdv]"):
            self.assertNotIn(variable, texte)

    def test_finaliser_par_appel(self):
        texte = themes.finaliser("Bonjour [client], au sujet de [date_rdv].",
                                 "M. Untel Exemple", "2026-08-01T14:30")
        self.assertEqual(texte, "Bonjour M. Untel Exemple, au sujet de "
                                "le samedi 1 août 2026 à 14 heures 30.")

    def test_theme_inconnu_refuse(self):
        with self.assertRaises(ValueError):
            themes.preremplir("martien", self.prefs)

    def test_hors_plage_borne_et_message(self):
        jour = datetime.datetime(2026, 7, 27)
        dans = [jour.replace(hour=9, minute=0), jour.replace(hour=12),
                jour.replace(hour=19, minute=0)]
        for moment in dans:
            self.assertIsNone(themes.hors_plage(self.prefs, moment))
        message = themes.hors_plage(self.prefs, jour.replace(hour=20, minute=15))
        self.assertIn("20h15", message)
        self.assertIn("entre 9h00 et 19h00", message)
        self.assertIn("garde-fou de politesse", message)
        self.assertIsNotNone(themes.hors_plage(self.prefs,
                                               jour.replace(hour=8, minute=59)))

    def test_planificateur_substitue_client_et_date_par_appel(self):
        base = db.Base(":memory:")
        self.addCleanup(base.fermer)
        client_id = base.ajouter_client("Mme Mission Exemple", "+33 6 39 98 50 51")
        rdv_id = base.ajouter_rendezvous(client_id, HIER, "Essai", statut="manqué")
        planif = planificateur.Planificateur(
            base, calle_client.AppelSimule(graine=4, latence=0))
        appel_id = planif.programmer(rdv_id)
        planif.executer(mission="Bonjour [client], votre rendez-vous [date_rdv] "
                                "est à reprogrammer.")
        appel = base.obtenir_appel(appel_id)
        self.assertIn("Agent : Bonjour Mme Mission Exemple", appel["transcription"])
        self.assertNotIn("[client]", appel["transcription"])
        self.assertNotIn("[date_rdv]", appel["transcription"])
        self.assertNotIn("+33 6 39 98 50 51", appel["transcription"])  # jamais


class TestServeurClients(_TestAvecServeurWeb):
    """The `Clients` page: do-not-call flag everywhere, confirmed deletion."""

    def test_liste_masquee_et_bascule_ne_plus_appeler(self):
        statut, page = self._obtenir("/clients")
        self.assertEqual(statut, 200)
        self.assertIn("Contacts (4)", page)  # the demo
        self.assertIn("Mme Nadia Lefèvre", page)
        self.assertIn("••", page)
        self.assertNotIn("+33 6 39 98 50 41", page)         # jamais en clair
        self.assertIn("Ne plus appeler", page)
        self.assertIn("Supprimer…", page)
        # Flag Mme Nadia Lefevre (demo client no. 1).
        _, page = self._poster("/clients/ne-plus-appeler",
                               {"client": 1, "valeur": 1})
        self.assertIn("🚫 ne plus appeler", page)  # badge on the page
        self.assertIn("Appeler de nouveau", page)  # toggle flipped back
        # The badge is visible EVERYWHERE: the Appointments page included,
        # without a button. ON `TOUS LES RENDEZ-VOUS`: Mme Nadia's appointment
        # is PAST, hence absent from `a venir`, and the missed list on the
        # Appointments page was removed on 10/08/2026. The badge must be
        # visible everywhere the person appears — that is what this test
        # guards.
        _, tous = self._obtenir("/tous")
        ligne_nadia = tous.split("Mme Nadia Lefèvre")[1].split("</tr>")[0]
        self.assertIn("🚫 ne plus appeler", ligne_nadia)
        self.assertNotIn("/rappel?", ligne_nadia)  # no button
        # Excluded from bulk queueing: 3 calls instead of 4.
        _, page_file = self._poster("/file/tout-rappeler")
        self.assertIn("3 appel(s) mis en file", page_file)
        # Excluded from cascade list generation.
        _, page_cascade = self._poster("/cascade/generer", {
            "liste": "", "mission": "Mission.", "creneau": "",
            "source": "tous", "ordre": "alphabetique"})
        self.assertIn("3 personne(s) dans la liste", page_cascade)
        zone = re.search(r"<textarea[^>]*name=\"liste\"[^>]*>([^<]*)</textarea>",
                         page_cascade).group(1)
        self.assertNotIn("Nadia", zone)
        # The direct individual callback is refused outright (403).
        with self.assertRaises(urllib.error.HTTPError) as contexte:
            self._poster("/rappeler", {"rdv": 1})
        self.assertEqual(contexte.exception.code, 403)
        self.assertIn("Ne plus appeler",
                      contexte.exception.read().decode("utf-8"))
        # Reversible: we lower the flag, everything comes back.
        _, page = self._poster("/clients/ne-plus-appeler",
                               {"client": 1, "valeur": 0})
        self.assertIn("peut de nouveau être appelé", page)
        _, page_file = self._poster("/file/tout-rappeler")
        self.assertIn("1 appel(s) mis en file", page_file)  # the missing one arrives

    def test_marquer_retire_aussi_de_la_file_en_attente(self):
        self._poster("/file/tout-rappeler")                 # 4 appels en file
        _, _ = self._poster("/clients/ne-plus-appeler", {"client": 1, "valeur": 1})
        _, page_file = self._obtenir("/file")
        self.assertIn("Appels en attente (3)", page_file)  # removed from the queue
        self.assertNotIn("Mme Nadia Lefèvre", page_file)

    def test_suppression_confirmee_jamais_en_un_clic(self):
        base = self.application.base
        avant_rdv = base.conn.execute("SELECT COUNT(*) FROM rendezvous").fetchone()[0]
        # 1. The confirmation page deletes NOTHING.
        statut, page = self._obtenir("/clients/supprimer?id=2")
        self.assertEqual(statut, 200)
        self.assertIn("Supprimer ce contact ?", page)
        self.assertIn("Action définitive", page)
        self.assertIn("M. Karim Osman", page)
        self.assertIn("Supprimer définitivement", page)
        self.assertIsNotNone(base.obtenir_client(2))  # still there
        # 2. A POST WITHOUT the confirmation field is refused.
        with self.assertRaises(urllib.error.HTTPError) as contexte:
            self._poster("/clients/supprimer", {"client": 2})
        self.assertEqual(contexte.exception.code, 400)
        self.assertIsNotNone(base.obtenir_client(2))
        # 3. The confirmation page's POST deletes client + appointments.
        _, page = self._poster("/clients/supprimer",
                               {"client": 2, "confirmer": "oui"})
        self.assertIn("Client supprimé", page)
        self.assertIn("1 de ses", page)  # 1 appointment taken along
        self.assertIsNone(base.obtenir_client(2))
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM rendezvous").fetchone()[0], avant_rdv - 1)
        _, page = self._obtenir("/clients")
        self.assertIn("Contacts (3)", page)
        self.assertNotIn("Karim", page)

    def test_suppression_purge_la_file(self):
        self._poster("/file/tout-rappeler")
        _, _ = self._poster("/clients/supprimer", {"client": 3, "confirmer": "oui"})
        _, page_file = self._obtenir("/file")
        self.assertIn("Appels en attente (3)", page_file)
        self.assertNotIn("Élise", page_file)


class TestServeurViderLesListes(_TestAvecServeurWeb):
    """The two `Empty` buttons: the callback list, and the call queue."""

    def test_vider_a_rappeler_puis_retablir(self):
        """THE BUTTON NO LONGER EXISTS, NOR ITS MESSAGE (10/08/2026). Both lived
        in `A rappeler (manques)`, removed at the owner's request. The gesture
        itself still works: this test now exercises its EFFECT — four missed
        appointments turn to `ignore` — instead of a confirmation sentence that
        is no longer displayed anywhere. It is waiting for a new home, and this
        comment is here so that we do not forget it.
        """
        base = self.application.base
        avant = len([r for r in base.tous_les_rendezvous()
                     if r["statut"] == "manqué"])
        self.assertEqual(avant, 4)
        self._poster("/ignorer-tout")
        self.assertEqual([r for r in base.tous_les_rendezvous()
                          if r["statut"] == "manqué"], [])
        # `Tous les rendez-vous` shows them as `ignore`, greyed, reversible.
        _, tous = self._obtenir("/tous")
        self.assertIn("st-ignore", tous)
        self.assertIn("Remettre à rappeler", tous)
        # We restore appointment no. 1: it becomes missed again.
        _, tous = self._poster("/retablir", {"rdv": 1})
        self.assertIn("Rendez-vous rétabli", tous)
        self.assertEqual(len([r for r in base.tous_les_rendezvous()
                              if r["statut"] == "manqué"]), 1)
        # Emptying again: only one this time.
        self._poster("/ignorer-tout")
        self.assertEqual([r for r in base.tous_les_rendezvous()
                          if r["statut"] == "manqué"], [])

    def test_vider_la_file_d_appels(self):
        _, page = self._poster("/file/tout-rappeler")
        self.assertIn("Appels en attente (4)", page)
        self.assertIn("Vider la file", page)
        _, page = self._poster("/file/annuler-tout")        # 303 suivi -> /file
        self.assertIn("File vidée : 4 appel(s) annulé(s)", page)
        self.assertIn("La file est vide", page)
        # The calls really are `annule` in the database (reversible by
        # refilling).
        base = self.application.base
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM appels WHERE statut = 'annulé'").fetchone()[0], 4)
        # Emptying an empty queue: an honest message, no error.
        _, page = self._poster("/file/annuler-tout")
        self.assertIn("La file était déjà vide", page)


