class TestServeurRappelSouhaite(_TestAvecServeurWeb):
    """An appointment's optional `wished callback date/time` field."""

    def test_ajout_affichage_et_optionnel(self):
        donnees = urllib.parse.urlencode({
            "nom": "Mme Rappel Choisi", "telephone": "+33 6 39 98 50 47",
            "date_heure": HIER, "motif": "Essai",
            "rappel_souhaite": "2026-08-03T15:00"}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            confirmation = reponse.read().decode("utf-8")
        self.assertIn("Rendez-vous enregistré", confirmation)
        self.assertIn("🔔 Rappel souhaité : 03/08/2026 à 15h00", confirmation)
        # Displayed in `Tous les rendez-vous` (the missed list on the
        # Appointments page was removed on 10/08/2026). And on `Tous les
        # rendez-vous`.
        _, tous = self._obtenir("/tous")
        self.assertIn("🔔 rappel souhaité", tous)
        # The field stays optional: without it, nothing extra is displayed.
        donnees = urllib.parse.urlencode({
            "nom": "M. Sans Souhait", "telephone": "+33 6 39 98 50 48",
            "date_heure": DEMAIN, "motif": "Essai",
            "rappel_souhaite": ""}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            confirmation = reponse.read().decode("utf-8")
        self.assertIn("Rendez-vous enregistré", confirmation)
        self.assertNotIn("🔔", confirmation.split("<h1>")[1].split("</p>")[0])

    def test_rappel_souhaite_illisible_refuse(self):
        donnees = urllib.parse.urlencode({
            "nom": "Mme Date Fausse", "telephone": "+33 6 39 98 50 49",
            "date_heure": DEMAIN, "motif": "Essai",
            "rappel_souhaite": "bientôt"}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn("Saisie refusée", page)
        self.assertIn("Rappel souhaité", page)
        self.assertIn("Date illisible", page)



# --------------------------------------------------------------------------
# NEW MODEL: campaigns (work themes instantiated on a list of the moment) and
# scheduled follow-ups. Everything is exercised for real — in-memory database,
# never the real donnees/ringback.db one.
