class TestEcheanceRelance(unittest.TestCase):
    """The follow-up delay counted in WORKING hours within the calling window.
    """

    def _echeance(self, depart, heures):
        return campagnes.echeance_apres_heures_ouvrees(
            datetime.datetime.fromisoformat(depart), heures, "09:00", "19:00")

    def test_dans_la_plage(self):
        self.assertEqual(self._echeance("2026-07-27T10:00", 4),
                         datetime.datetime(2026, 7, 27, 14, 0))

    def test_a_cheval_sur_deux_jours(self):
        # 6pm + 4 working hours: 1 h today (18->19), 3 h tomorrow (9->12).
        self.assertEqual(self._echeance("2026-07-27T18:00", 4),
                         datetime.datetime(2026, 7, 28, 12, 0))

    def test_depart_apres_fermeture(self):
        self.assertEqual(self._echeance("2026-07-27T20:00", 2),
                         datetime.datetime(2026, 7, 28, 11, 0))

    def test_depart_avant_ouverture_et_delai_nul(self):
        # Delay 0: the next opening (or the current moment if it is inside
        # one).
        self.assertEqual(self._echeance("2026-07-27T07:00", 0),
                         datetime.datetime(2026, 7, 27, 9, 0))
        self.assertEqual(self._echeance("2026-07-27T11:30", 0),
                         datetime.datetime(2026, 7, 27, 11, 30))


class TestCampagnesModele(unittest.TestCase):
    """The campaign model at module level: themes, calls, follow-ups."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.prefs = generation.Preferences()
        self.prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        self.prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        self.prefs.definir(campagnes.CLE_RELANCE_DELAI, 0)  # dues tout de suite
        self.planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=8, latence=0))

    # ------------------------------------------------------------- outillage
    def _campagne(self, theme, contacts, mission="Bonjour [client].",
                  creneau=None, sujet=""):
        campagne_id = campagnes.creer_campagne(
            self.base, theme, contacts, mission, creneau=creneau, sujet=sujet)
        campagnes.executer_campagne_initiale(
            self.base, self.planif, self.prefs, campagne_id)
        return campagne_id

    # ------------------------------------------------------ names and
    # templates
    def test_nom_auto_lisible(self):
        quand = datetime.date(2026, 7, 28)
        self.assertEqual(
            campagnes.nom_auto("creneau_libere", creneau="2026-08-03T14:00",
                               quand=quand),
            "Créneau libéré du 03/08 14h — 28/07")
        self.assertIn("2 contact(s)",
                      campagnes.nom_auto("confirmation", nb_contacts=2))
        self.assertEqual(
            campagnes.nom_auto("manque", nb_contacts=3, quand=quand),
            "Rappel de rendez-vous manqués (3 contact(s)) — 28/07")

    def test_un_theme_retire_garde_son_nom_a_l_ecran(self):
        """Removing a theme must not make the campaigns already in the database
        ANONYMOUS: a campaign we can no longer name is lost data.
        """
        self.assertNotIn("contact_unique", campagnes.THEMES_CAMPAGNE)
        self.assertNotIn("personnalise", campagnes.THEMES_CAMPAGNE)
        self.assertEqual(campagnes.libelle_theme("contact_unique"),
                         "Contact unique avec sujet (retiré)")
        self.assertEqual(campagnes.libelle_theme("personnalise"),
                         "Personnalisé (retiré)")
        # A code never seen before comes back as is: we do not invent a label.
        self.assertEqual(campagnes.libelle_theme("martien"), "martien")
        # But no new one can be INSTANTIATED: no template, hence a refusal.
        for retire in ("contact_unique", "personnalise"):
            with self.assertRaises(ValueError):
                campagnes.gabarit_mission(retire, self.prefs)

    def test_gabarit_mission_par_theme(self):
        self.prefs.definir(themes.CLE_ENTREPRISE, "Cabinet Essai")
        texte = campagnes.gabarit_mission("manque", self.prefs)
        self.assertIn("Cabinet Essai", texte)
        self.assertNotRegex(texte, r"\d{4}")  # never a number
        self.assertIn("confirmer", campagnes.gabarit_mission("confirmation",
                                                             self.prefs))
        with self.assertRaises(ValueError):
            campagnes.gabarit_mission("martien", self.prefs)

    def test_analyse_csv_contacts(self):
        personnes, erreurs = campagnes.analyser_csv_contacts(
            "nom;telephone\n"
            "Mme Une Exemple;+33 6 39 98 50 51\n"
            "M. Faux Numero;12345\n"
            "Mme Doublon Exemple;+33 6 39 98 50 51\n")
        self.assertEqual([p["nom"] for p in personnes], ["Mme Une Exemple"])
        self.assertEqual(len(erreurs), 2)
        # The old 4-column format is tolerated (extra columns ignored).
        personnes, erreurs = campagnes.analyser_csv_contacts(
            "nom;telephone;date_heure;motif\n"
            f"Mme Complete Exemple;0639985052;{DEMAIN};Essai\n")
        self.assertEqual(erreurs, [])
        self.assertEqual(personnes[0]["telephone"], "06 39 98 50 52")
        with self.assertRaises(saisie.SaisieInvalide):
            campagnes.analyser_csv_contacts("prenom;tel\nA;B\n")

    def test_contacts_depuis_rendezvous_exclusions(self):
        libre = self.base.ajouter_client("Mme Libre Exemple", "+33 6 39 98 50 41")
        rdv_libre = self.base.ajouter_rendezvous(libre, DEMAIN, "Essai")
        stop = self.base.ajouter_client("M. Stop Exemple", "+33 6 39 98 50 42")
        self.base.ajouter_rendezvous(stop, DEMAIN, "Essai")
        self.base.definir_ne_plus_appeler(stop, True)
        sans = self.base.ajouter_client("Mme Sans Fil", "")
        self.base.ajouter_rendezvous(sans, DEMAIN, "Essai")
        contacts, sans_numero, exclus_stop = campagnes.contacts_depuis_rendezvous(
            self.base, "prévu")
        self.assertEqual([c["nom"] for c in contacts], ["Mme Libre Exemple"])
        self.assertEqual(contacts[0]["rendezvous_id"], rdv_libre)
        self.assertEqual((sans_numero, exclus_stop), (1, 1))

    # --------------------------------------------- one campaign per theme
    def test_campagne_confirmation_liee_a_la_base(self):
        client_id = self.base.ajouter_client("Mme Sure Exemple",
                                             "+33 6 39 98 50 51")
        rdv_id = self.base.ajouter_rendezvous(client_id, DEMAIN, "Bilan annuel")
        campagne_id = self._campagne(
            "confirmation",
            [{"nom": "Mme Sure Exemple", "telephone": "+33 6 39 98 50 51",
              "rendezvous_id": rdv_id}])
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual((contact["etat"], contact["issue"]),
                         ("abouti", "confirmed"))
        self.assertEqual(contact["telephone_masque"], "+33 6 •• •• •• 51")
        self.assertNotIn("telephone", contact)  # the raw form does not come out
        # The LINKED appointment was confirmed by the existing logic.
        self.assertEqual(self.base.obtenir_rendezvous(rdv_id)["statut"],
                         "confirmé")
        self.assertEqual(self.base.obtenir_campagne(campagne_id)["statut"],
                         "terminée")  # no follow-up to expect

    def test_deplacement_non_conclu_cree_une_relance_theme_conserve(self):
        """Scenario (c) at module level: 55 = move not concluded."""
        client_id = self.base.ajouter_client("M. Hesitant Exemple",
                                             "+33 6 39 98 50 55")
        rdv_id = self.base.ajouter_rendezvous(client_id, DEMAIN, "Contrôle")
        campagne_id = self._campagne(
            "confirmation",
            [{"nom": "M. Hesitant Exemple", "telephone": "+33 6 39 98 50 55",
              "rendezvous_id": rdv_id}],
            mission="Bonjour [client], je confirme votre rendez-vous [date_rdv].")
        # Nothing is concluded: the appointment is INTACT.
        self.assertEqual(self.base.obtenir_rendezvous(rdv_id)["statut"], "prévu")
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual((contact["etat"], contact["issue"]),
                         ("appelé", "to_reschedule"))
        # The follow-up exists, with THE campaign's theme and parameters.
        relances = self.base.relances_de_campagne(campagne_id)
        self.assertEqual(len(relances), 1)
        relance = relances[0]
        self.assertEqual(relance["statut"], "planifiée")
        self.assertEqual(relance["motif"], "déplacement non conclu")
        self.assertEqual(relance["campagne_theme"], "confirmation")
        self.assertEqual(relance["tentative"], 1)
        self.assertEqual(relance["telephone_masque"], "+33 6 •• •• •• 55")
        campagne = self.base.obtenir_campagne(campagne_id)
        self.assertEqual(campagne["statut"], "en cours")
        self.assertIn("je confirme votre rendez-vous", campagne["mission"])

    def test_contact_unique_sans_reponse_puis_relance_aboutie(self):
        """Scenario (b) at module level: 56 = no answer, then yes."""
        campagne_id = self._campagne(
            "contact_unique",
            [{"nom": "Secrétariat Spécialiste", "telephone": "+33 6 39 98 50 56"}],
            mission="Bonjour, rendez-vous pour M. Martin au sujet : [sujet].",
            sujet="Rendez-vous chez le spécialiste pour M. Martin")
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual((contact["etat"], contact["issue"]),
                         ("appelé", "no_answer"))
        dues = self.base.relances_dues()
        self.assertEqual(len(dues), 1)  # delay 0: due immediately
        self.assertEqual(dues[0]["campagne_theme"], "contact_unique")
        self.assertEqual(dues[0]["motif"], "pas de réponse")
        # HUMAN gesture: we launch the due follow-ups — this time, there is an
        # answer.
        comptes = campagnes.executer_relances_dues(self.base, self.planif,
                                                   self.prefs)
        self.assertEqual(len(comptes), 1)
        self.assertTrue(comptes[0]["abouti"])
        self.assertEqual(comptes[0]["issue"], "confirmed")
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(contact["etat"], "abouti")
        # The chain is closed: no follow-up scheduled any more, campaign
        # finished.
        self.assertEqual(self.base.relances_dues(), [])
        self.assertEqual(self.base.obtenir_campagne(campagne_id)["statut"],
                         "terminée")
        # The successful call created the appointment obtained (client with no
        # linked appointment).
        rdv = self.base.tous_les_rendezvous()[0]
        self.assertEqual(rdv["nom"], "Secrétariat Spécialiste")
        self.assertEqual(rdv["statut"], "confirmé")

    def test_max_tentatives_puis_abandon(self):
        self.prefs.definir(campagnes.CLE_RELANCE_MAX, 2)
        campagne_id = self._campagne(
            "contact_unique",
            [{"nom": "M. Toujours Absent", "telephone": "+33 6 39 98 50 53"}],
            mission="Bonjour.", sujet="Relance fournisseur")
        # Follow-up 1 then follow-up 2: still no answer.
        for tentative in (1, 2):
            dues = self.base.relances_dues()
            self.assertEqual(len(dues), 1)
            self.assertEqual(dues[0]["tentative"], tentative)
            comptes = campagnes.executer_relances_dues(self.base, self.planif,
                                                       self.prefs)
            self.assertFalse(comptes[0]["abouti"])
        # Maximum reached: chain abandoned, NOTHING new is scheduled.
        self.assertEqual(self.base.relances_dues(), [])
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(contact["etat"], "abandonné")
        self.assertEqual(self.base.obtenir_campagne(campagne_id)["statut"],
                         "terminée")
        # Complete trace: initial call + 2 follow-ups.
        appels = self.base.appels_du_contact_campagne(contact["id"])
        self.assertEqual([a["tentative"] for a in appels], [0, 1, 2])

    def test_cascade_pourvue_aucune_relance(self):
        personnes = [
            {"nom": "Mme Refus Un", "telephone": "+33 6 39 98 50 52"},
            {"nom": "Mme Accord Deux", "telephone": "+33 6 39 98 50 51"},
            {"nom": "M. Epargne Trois", "telephone": "+33 6 39 98 50 49"},
        ]
        cascade_id = self.planif.executer_cascade(personnes, "Mission.", DEMAIN)
        campagne_id = campagnes.campagne_depuis_cascade(
            self.base, self.prefs, cascade_id, personnes, "Mission.", DEMAIN)
        campagne = self.base.obtenir_campagne(campagne_id)
        self.assertEqual(campagne["cascade_id"], cascade_id)
        self.assertEqual(campagne["statut"], "terminée")  # slot filled
        etats = {c["nom"]: c["etat"]
                 for c in self.base.contacts_de_campagne(campagne_id)}
        self.assertEqual(etats, {"Mme Refus Un": "appelé",
                                 "Mme Accord Deux": "abouti",
                                 "M. Epargne Trois": "épargné"})
        # Slot filled: NOBODY is followed up.
        self.assertEqual(self.base.relances_de_campagne(campagne_id), [])

    def test_un_stop_dans_une_cascade_part_vers_un_humain(self):
        """THE ENTRY POINT MY FIRST THREE TESTS DID NOT HOLD.

        The `first yes` cascade has its own path: the scheduler writes `exclu`
        into ITS OWN table, and the campaign takeover then copies that state
        onto the contact. Replacing each entry point with the old spelling, one
        after another, this one made NO test fall: the person silently
        disappeared there again, and nothing said so.

        THE CASCADE'S TABLE KEEPS ITS VOCABULARY (`exclu` / `epargne`): it is
        what the Cascade page shows, and changing it would have meant fixing a
        screen that asked for nothing. What travels in addition is the REASON,
        and it is the reason that decides the campaign contact's state.
        """
        exclu = self.base.ajouter_client("Mme Stop Cascade",
                                         "+33 6 39 98 50 61")
        self.base.definir_ne_plus_appeler(exclu, True)
        personnes = [
            {"nom": "Mme Stop Cascade", "telephone": "+33 6 39 98 50 61"},
            {"nom": "Mme Accord Deux", "telephone": "+33 6 39 98 50 51"},
        ]
        cascade_id = self.planif.executer_cascade(personnes, "Mission.", DEMAIN)
        # The cascade, for its part, still says `exclu` — and now carries the
        # reason.
        lignes = self.base.appels_de_cascade(cascade_id)
        self.assertEqual(lignes[0]["etat"], "exclu")
        self.assertIsNone(lignes[0]["issue"])  # never dialled
        self.assertEqual(lignes[0]["note"], db.REFUS_STOP)
        # And the campaign contact, for their part, goes to a human.
        campagne_id = campagnes.campagne_depuis_cascade(
            self.base, self.prefs, cascade_id, personnes, "Mission.", DEMAIN)
        contacts = {c["nom"]: c
                    for c in self.base.contacts_de_campagne(campagne_id)}
        stop = contacts["Mme Stop Cascade"]
        self.assertEqual(stop["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertTrue(db.refus_de_l_agent(stop["detail"]))
        self.assertEqual(self.base.appels_du_contact_campagne(stop["id"]), [])
        # She is in the human callback list, and not followed up.
        self.assertIn(stop["id"],
                      [c["id"] for c in self.base.contacts_rappel_humain()])
        self.assertEqual([r for r in self.base.relances_de_campagne(campagne_id)
                          if r["contact_id"] == stop["id"]], [])

    def test_un_stop_pose_avant_une_relance_de_cascade_va_vers_un_humain(self):
        """THE LAST OF THE SIX ENTRY POINTS, and the easiest to forget: the
        FOLLOW-UP of a freed-slot campaign has its own call code
        (`_executer_relance_cascade`), distinct from the initial call.

        The scenario is the one that really happens: the cascade filled nobody,
        follow-ups are armed — and in the meantime somebody asks not to be
        called again. It is at the follow-up, not at the initial call, that the
        do-not-call is read back.
        """
        client = self.base.ajouter_client("M. Silence Deux",
                                          "+33 6 39 98 50 53")
        personnes = [
            {"nom": "Mme Refus Un", "telephone": "+33 6 39 98 50 52"},
            {"nom": "M. Silence Deux", "telephone": "+33 6 39 98 50 53"},
        ]
        cascade_id = self.planif.executer_cascade(personnes, "Mission.", DEMAIN)
        campagne_id = campagnes.campagne_depuis_cascade(
            self.base, self.prefs, cascade_id, personnes, "Mission.", DEMAIN)
        # Follow-ups really are armed: the slot was not filled.
        contacts = {c["nom"]: c
                    for c in self.base.contacts_de_campagne(campagne_id)}
        silence = contacts["M. Silence Deux"]
        self.assertTrue([r for r in self.base.relances_dues()
                         if r["contact_id"] == silence["id"]])
        # THE DO-NOT-CALL ARRIVES HERE, between the initial call and its
        # follow-up.
        self.base.definir_ne_plus_appeler(client, True)
        avant = len(self.base.appels_du_contact_campagne(silence["id"]))
        campagnes.executer_relances_dues(self.base, self.planif, self.prefs)
        repris = self.base.obtenir_contact_campagne(silence["id"])
        self.assertEqual(repris["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertTrue(db.refus_de_l_agent(repris["detail"]))
        # And the follow-up dialled NO number: not one further attempt.
        self.assertEqual(len(self.base.appels_du_contact_campagne(silence["id"])),
                         avant)

    def test_un_stop_dans_la_file_d_appels_part_vers_un_humain(self):
        """THE FIFTH ENTRY POINT, held by no test either — and the one the
        `Rappeler les rendez-vous manques` button goes through.

        The scheduler reads the do-not-call back at the moment of dialling and
        cancels the call with the reason as a NOTE; it is the campaign takeover
        that decides the contact's state. `campagne_depuis_file` had no test at
        all before today.
        """
        client = self.base.ajouter_client("M. Stop File", "+33 6 39 98 50 63")
        rdv = self.base.ajouter_rendezvous(client, HIER, "Séance",
                                           statut="manqué")
        appel_id = self.planif.programmer(rdv)
        # THE DO-NOT-CALL ARRIVES AFTER queueing, before dialling.
        self.base.definir_ne_plus_appeler(client, True)
        passes = self.planif.executer()
        appel = self.base.obtenir_appel(appel_id)
        self.assertEqual(appel["statut"], "annulé")
        self.assertEqual(appel["note"], db.REFUS_STOP)
        campagne_id = campagnes.campagne_depuis_file(
            self.base, self.prefs, passes or [appel_id], "Mission.")
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(contact["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertTrue(db.refus_de_l_agent(contact["detail"]))
        self.assertIn(contact["id"],
                      [c["id"] for c in self.base.contacts_rappel_humain()])

    def test_un_refus_sans_numero_dans_la_file_reste_exclu(self):
        """THE QUEUE'S COUNTER-TEST: without a number, a human has nothing to dial
        either. That refusal does not move.
        """
        client = self.base.ajouter_client("M. Sans Numero File", "")
        rdv = self.base.ajouter_rendezvous(client, HIER, "Séance",
                                           statut="manqué")
        appel_id = self.planif.programmer(rdv)
        self.planif.executer()
        appel = self.base.obtenir_appel(appel_id)
        self.assertEqual(appel["note"], db.REFUS_SANS_NUMERO)
        campagne_id = campagnes.campagne_depuis_file(
            self.base, self.prefs, [appel_id], "Mission.")
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertNotEqual(contact["etat"], db.ETAT_RAPPEL_HUMAIN)

    def test_une_cascade_d_avant_la_regle_reste_lisible(self):
        """THE TAKEOVER'S COUNTER-TEST: the cascades already in the database have
        no written reason (the column was empty before 20/08/2026). They must
        stay exactly what they were — `exclu` — rather than going to a human on
        an assumption.
        """
        personnes = [
            {"nom": "Mme Ancienne", "telephone": "+33 6 39 98 50 62"},
            {"nom": "Mme Accord Deux", "telephone": "+33 6 39 98 50 51"},
        ]
        cascade_id = self.planif.executer_cascade(personnes, "Mission.", DEMAIN)
        # We rebuild the BEFORE state: `exclu` without the slightest note.
        rang1 = self.base.appels_de_cascade(cascade_id)[0]
        self.base.conn.execute(
            "UPDATE appels_cascade SET etat = 'exclu', issue = NULL, "
            "note = NULL WHERE id = ?", (rang1["id"],))
        self.base.conn.commit()
        campagne_id = campagnes.campagne_depuis_cascade(
            self.base, self.prefs, cascade_id, personnes, "Mission.", DEMAIN)
        contacts = {c["nom"]: c
                    for c in self.base.contacts_de_campagne(campagne_id)}
        self.assertEqual(contacts["Mme Ancienne"]["etat"], "exclu")

    def test_cascade_epuisee_relances_avec_theme_conserve(self):
        personnes = [
            {"nom": "Mme Refus Un", "telephone": "+33 6 39 98 50 52"},
            {"nom": "M. Silence Deux", "telephone": "+33 6 39 98 50 53"},
        ]
        cascade_id = self.planif.executer_cascade(personnes, "Mission.", DEMAIN)
        campagne_id = campagnes.campagne_depuis_cascade(
            self.base, self.prefs, cascade_id, personnes, "Mission.", DEMAIN)
        self.assertEqual(self.base.obtenir_campagne(campagne_id)["statut"],
                         "en cours")
        relances = self.base.relances_de_campagne(campagne_id)
        self.assertEqual({r["motif"] for r in relances},
                         {"refus à requalifier", "pas de réponse"})
        self.assertTrue(all(r["campagne_theme"] == "creneau_libere"
                            for r in relances))

    def test_relance_cascade_qui_aboutit_clot_la_campagne(self):
        """56: no answer to the cascade, YES to the follow-up -> slot taken."""
        personnes = [
            {"nom": "M. Occupe Un", "telephone": "+33 6 39 98 50 56"},
            {"nom": "Mme Refus Deux", "telephone": "+33 6 39 98 50 52"},
        ]
        cascade_id = self.planif.executer_cascade(personnes, "Mission.", DEMAIN)
        campagne_id = campagnes.campagne_depuis_cascade(
            self.base, self.prefs, cascade_id, personnes, "Mission.", DEMAIN)
        self.assertEqual(len(self.base.relances_dues()), 2)  # exhausted: 2 chains
        comptes = campagnes.executer_relances_dues(self.base, self.planif,
                                                   self.prefs)
        # M. Occupe accepts at the follow-up: slot allocated, appointment
        # created, and Mme Refus's follow-up (slot now taken) is CANCELLED.
        self.assertEqual(comptes[0]["issue"], "accepted")
        self.assertTrue(comptes[0]["abouti"])
        self.assertEqual(len(comptes), 1)  # the 2nd one did not go out
        self.assertEqual(self.base.obtenir_campagne(campagne_id)["statut"],
                         "terminée")
        self.assertEqual(self.base.relances_dues(), [])
        rdv = self.base.tous_les_rendezvous()[0]
        self.assertEqual((rdv["nom"], rdv["horaire"], rdv["statut"]),
                         ("M. Occupe Un", DEMAIN, "confirmé"))
        # The attached cascade went back to `filled`.
        self.assertEqual(self.base.obtenir_cascade(cascade_id)["statut"],
                         "pourvue")

    def test_contact_exclu_jamais_compose_dans_une_campagne(self):
        stop = self.base.ajouter_client("Mme Stop Exemple", "+33 6 39 98 50 51")
        self.base.definir_ne_plus_appeler(stop, True)
        campagne_id = self._campagne(
            "personnalise",
            [{"nom": "Mme Stop Exemple", "telephone": "+33 6 39 98 50 51"},
             {"nom": "M. Libre Exemple", "telephone": "+33 6 39 98 50 52"}],
            mission="Bonjour [client].")
        etats = [c["etat"] for c in self.base.contacts_de_campagne(campagne_id)]
        # `a rappeler par un humain`, NO LONGER `exclu` (his request of
        # 20/08/2026): she refused the AGENT, not the practice. The guarantee
        # that counts has not moved an inch — no attempt, below.
        self.assertEqual(etats, [db.ETAT_RAPPEL_HUMAIN, "abouti"])
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(self.base.appels_du_contact_campagne(contact["id"]),
                         [])                                # aucune tentative
        self.assertTrue(db.refus_de_l_agent(contact["detail"]))
        # And she is indeed IN the human callback list.
        self.assertIn(contact["id"],
                      [c["id"] for c in self.base.contacts_rappel_humain()])

    def test_cloture_manuelle_annule_les_relances(self):
        campagne_id = self._campagne(
            "contact_unique",
            [{"nom": "M. Toujours Absent", "telephone": "+33 6 39 98 50 53"}],
            mission="Bonjour.", sujet="Essai")
        self.assertEqual(len(self.base.relances_dues()), 1)
        annulees = campagnes.clore_campagne(self.base, campagne_id)
        self.assertEqual(annulees, 1)
        self.assertEqual(self.base.relances_dues(), [])
        self.assertEqual(self.base.obtenir_campagne(campagne_id)["statut"],
                         "close")
        # The `launch the follow-ups` gesture finds nothing any more.
        self.assertEqual(campagnes.executer_relances_dues(
            self.base, self.planif, self.prefs), [])

    def test_verrous_reels_sur_les_relances(self):
        """The 3 locks apply to follow-ups: dry_run blocks EVERYTHING."""
        campagne_id = self._campagne(
            "contact_unique",
            [{"nom": "M. Toujours Absent", "telephone": "+33 6 39 98 50 53"}],
            mission="Bonjour.", sujet="Essai")
        reel = calle_client.AppelReel(cle_api="cle-de-test-0123456789")  # never used
        planif_reel = planificateur.Planificateur(self.base, reel)  # dry_run
        with self.assertRaises(planificateur.GardeFou):
            campagnes.executer_relances_dues(self.base, planif_reel, self.prefs)
        # The follow-up was NOT consumed: it stays scheduled, intact.
        dues = self.base.relances_dues()
        self.assertEqual(len(dues), 1)
        self.assertEqual(dues[0]["statut"], "planifiée")
        self.assertEqual(self.base.obtenir_campagne(campagne_id)["statut"],
                         "en cours")

    def test_lancement_campagne_reelle_bloque_par_dry_run(self):
        reel = calle_client.AppelReel(cle_api="cle-de-test-0123456789")
        planif_reel = planificateur.Planificateur(self.base, reel)
        campagne_id = campagnes.creer_campagne(
            self.base, "contact_unique",
            [{"nom": "Mme Test", "telephone": "+33 6 39 98 50 51"}], "Bonjour.")
        with self.assertRaises(planificateur.GardeFou):
            campagnes.executer_campagne_initiale(
                self.base, planif_reel, self.prefs, campagne_id)
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(contact["etat"], "à appeler")  # nothing moved


class TestServeurCampagnes(_TestAvecServeurWeb):
    """The `New campaign` wizard and the Campaigns home page, through real HTTP
    requests — masking checked at every step.
    """

    def test_accueil_campagnes_et_etape_theme(self):
        statut, page = self._obtenir("/")
        self.assertEqual(statut, 200)
        self.assertIn("📣 Campagnes", page)
        self.assertIn("➕ Nouvelle campagne", page)
        self.assertIn("Aucune campagne pour l'instant", page)
        # ONE SINGLE creation route: the old address leads to the wizard
        # (clickable tiles), never again to the radio-button themes page.
        statut, page = self._obtenir("/campagne/nouvelle")
        self.assertEqual(statut, 200)
        self.assertGreaterEqual(page.count("carte-nature"), 5)
        self.assertNotIn('type="radio" name="theme"', page)
        self.assertNotIn("étape ① sur 3", page)
        # The kind's name no longer carries the calling policy: the cascade is
        # an OPTION, not the kind.
        self.assertNotIn("cascade « premier oui »)", page)

    def _etape2_liste_nue(self, mission="Bonjour [identite], petit message."):
        """Opens a draft that requires NOTHING but a name and a phone number, goes
        through step 2 with a hand-written text, and returns the draft's
        identifier (we are then at step 3).

        It is `appointment booking`: since the `Personnalise` kind was removed
        (03/08/2026), it is the only kind whose GRID imposes no column — which
        is what is needed to exercise a paste or an import in its bare state.
        The text stays hand-written: what the agent will read therefore does
        not depend on the kind's template.
        """
        _, page = self._poster("/assistant/nature", {"nature": "prise_rdv"})
        identifiant = self._brouillon(page)
        _, page = self._poster("/assistant/message", {
            "b": identifiant, "action": "continuer",
            "info_entreprise": "Cabinet Essai",
            "info_origine": "vous avez demandé un rendez-vous",
            "info_creneaux_proposes": "lundi 10h, mardi 14h",
            "politique": "tous",
            "ordre": "liste", "mission": mission, "mission_editee": "1",
            "opt_recontacter": "1", "opt_liberer": "1", "opt_repondeur": "1",
            "relance_mode": "delai", "relance_delai": "4", "relance_max": "3"})
        self.assertIn("3. Les personnes", page)
        return identifiant

    def test_nature_manquante_refusee(self):
        """Step 1 refuses to open a draft without a kind (empty or unknown) — it
        is the kind that decides the message, the information and the columns.
        """
        for envoye in ({"nature": ""}, {"nature": "martien"}):
            _, page = self._poster("/assistant/nature", envoye)
            self.assertIn("Choisissez d&#x27;abord une nature de campagne", page)
            self.assertGreaterEqual(page.count("carte-nature"), 5)  # step 1
        self.assertEqual(self.application.brouillons_assistant, {})

    def test_brouillon_inconnu_en_404(self):
        for chemin in ("/assistant/message?b=999", "/assistant/liste?b=999"):
            with self.assertRaises(urllib.error.HTTPError) as contexte:
                self._obtenir(chemin)
            self.assertEqual(contexte.exception.code, 404)
            self.assertIn("recommencez",
                          contexte.exception.read().decode("utf-8"))

    def test_collage_puis_lancement_texte_ecrit_a_la_main(self):
        base = self.application.base
        identifiant = self._etape2_liste_nue()
        _, page = self._poster("/assistant/importer", {
            "b": identifiant, "mode": "collage",
            "liste": "Mme Une Exemple;+33 6 39 98 50 51\n"
                     "M. Deux Exemple;+33 6 39 98 50 52\n"})
        # Step 3: the grid is MASKED, never a number in clear.
        self.assertIn("2 contact(s) ajouté(s)", page)
        self.assertIn("+33 6 •• •• •• 51", page)
        self.assertNotIn("+33 6 39 98 50 51", page)
        self.assertNotIn("+33 6 39 98 50 52", page)
        _, page = self._poster("/assistant/liste",
                               {"b": identifiant, "action": "valider"})
        self.assertIn("prête", page)  # nobody is called
        campagne = base.lister_campagnes()[0]
        self.assertIn("Prise de rendez-vous (2 contact(s))", campagne["nom"])
        self._demarrer(campagne["id"])
        self._attendre_statut(campagne["id"], "terminée")
        # Both contacts are handled (51 confirms, 52 cancels — two chains
        # concluded, no follow-up), no number in clear.
        _, page = self._obtenir(f"/campagne?id={campagne['id']}")
        self.assertIn("terminée", page)
        self.assertIn("Confirmé", page)
        self.assertIn("Annulé par le client", page)
        self.assertIn("Agent : Bonjour Mme Une Exemple, petit message.", page)
        self.assertNotIn("+33 6 39 98 50 5", page)
        etats = {c["nom"]: c["etat"]
                 for c in base.contacts_de_campagne(campagne["id"])}
        self.assertEqual(etats, {"Mme Une Exemple": "accepté",
                                 "M. Deux Exemple": "le client rappellera"})
        self.assertEqual(base.relances_de_campagne(campagne["id"]), [])
        # The home page lists the campaign with its progress.
        _, accueil = self._obtenir("/")
        self.assertIn("Prise de rendez-vous", accueil)
        self.assertIn("2/2 appelé(s) · 1 accepté(s) · 0 relance(s)", accueil)

    def test_import_csv_dans_l_assistant(self):
        identifiant = self._etape2_liste_nue()
        contenu = ("nom;telephone\n"
                   "Mme Fichier Exemple;+33 6 39 98 50 51\n"
                   "M. Faux Numero;12345\n")
        frontiere = "----frontiereDeTest"
        corps = (f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="b"\r\n\r\n'
                 f"{identifiant}\r\n"
                 f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="mode"\r\n\r\n'
                 "csv\r\n"
                 f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="fichier"; filename="liste.csv"\r\n'
                 "Content-Type: text/csv\r\n\r\n"
                 f"{contenu}\r\n--{frontiere}--\r\n").encode("utf-8")
        requete = urllib.request.Request(
            self.racine + "/assistant/importer", data=corps,
            headers={"Content-Type": f"multipart/form-data; boundary={frontiere}"})
        with urllib.request.urlopen(requete, timeout=15) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn("1 contact(s) ajouté(s)", page)  # one good row is enough
        self.assertIn("Numéro de téléphone invalide", page)  # the offending one reported
        self.assertIn("Mme Fichier Exemple", page)
        self.assertIn("+33 6 •• •• •• 51", page)
        self.assertNotIn("+33 6 39 98 50 51", page)  # masked

    def test_liste_vide_reste_a_l_etape_3(self):
        identifiant = self._etape2_liste_nue()
        _, page = self._poster("/assistant/importer", {
            "b": identifiant, "mode": "collage", "liste": "  \n"})
        self.assertIn("Liste vide", page)
        self.assertIn("3. Les personnes", page)  # we do not get through
        # And validating an empty grid is still refused: nothing is created.
        _, page = self._poster("/assistant/liste",
                               {"b": identifiant, "action": "valider"})
        self.assertIn("La grille est vide", page)
        self.assertEqual(self.application.base.lister_campagnes(), [])

    def test_sans_creneau_refuse_pour_creneau_libere(self):
        _, page = self._poster("/assistant/nature", {"nature": "creneau_libere"})
        identifiant = self._brouillon(page)
        _, page = self._poster("/assistant/message", {
            "b": identifiant, "action": "continuer",
            "info_entreprise": "Cabinet Essai", "politique": "premier_oui",
            "ordre": "liste", "opt_recontacter": "1", "relance_mode": "delai",
            "relance_delai": "4", "relance_max": "3"})
        self.assertIn("Créneau libéré (date et heure) » est obligatoire", page)
        self.assertIn('id="apercu"', page)  # we stay at step 2
        _, accueil = self._obtenir("/")
        self.assertIn("Aucune campagne pour l'instant", accueil)  # nothing created

    def test_ancien_parcours_cascade_rattache_aux_campagnes(self):
        # An exhausted cascade launched from the OLD page creates its campaign,
        # with the `refusal to requalify` / `no answer` follow-ups.
        _, page = self._poster("/cascade/executer", {
            "liste": "Mme Refus Un;+33 6 39 98 50 52\n"
                     "M. Silence Deux;+33 6 39 98 50 53\n",
            "mission": "Un créneau s'est libéré.", "creneau": DEMAIN})
        self.assertIn("liste épuisée", page)
        _, accueil = self._obtenir("/")
        self.assertIn("Créneau libéré du", accueil)
        self.assertIn("2 relance(s)", accueil)
        _, relances = self._obtenir("/relances")
        self.assertIn("refus à requalifier", relances)
        self.assertIn("pas de réponse", relances)
        self.assertIn("Relances à venir (2)", relances)  # default delay 4 h
        self.assertNotIn("+33 6 39 98 50 5", relances)  # masked everywhere

    def test_ancien_parcours_file_rattache_aux_campagnes(self):
        self._poster("/file/tout-rappeler")
        _, page = self._poster("/file/executer")
        self.assertIn("campagne de rappel des manqués", page)
        _, accueil = self._obtenir("/")
        self.assertIn("Rappel de rendez-vous manqués", accueil)

    def test_reglages_relances_enregistres(self):
        _, page = self._obtenir("/reglages")
        self.assertIn("relance_delai", page)
        self.assertIn("relance_max", page)
        _, page = self._poster("/reglages/enregistrer", {
            "entreprise": "Cabinet Essai", "plage_debut": "00:00",
            "plage_fin": "23:59", "relance_delai": "2", "relance_max": "5"})
        self.assertIn("Réglages enregistrés", page)
        preferences = self.application.preferences
        self.assertEqual(campagnes.parametres_relance(preferences), (2, 5))
        # Out-of-bounds value refused in French.
        _, page = self._poster("/reglages/enregistrer", {
            "entreprise": "", "plage_debut": "00:00", "plage_fin": "23:59",
            "relance_delai": "999", "relance_max": "3"})
        self.assertIn("entre 0 et 168", page)
        self.assertEqual(campagnes.parametres_relance(preferences), (2, 5))


class TestServeurRelances(_TestAvecServeurWeb):
    """The `Follow-ups` page: due ones highlighted, human gesture, postpone,
    cancel, locks — through real HTTP requests.
    """

    def _creer_relance_due(self, telephone="+33 6 39 98 50 53"):
        """A `single contact` campaign whose initial call fails: with a delay of 0
        h, the follow-up is due immediately.
        """
        application = self.application
        application.preferences.definir(campagnes.CLE_RELANCE_DELAI, 0)
        campagne_id = campagnes.creer_campagne(
            application.base, "contact_unique",
            [{"nom": "Secrétariat Exemple", "telephone": telephone}],
            "Bonjour, au sujet de : [sujet].", sujet="Demande de devis")
        campagnes.executer_campagne_initiale(
            application.base, application.planif, application.preferences,
            campagne_id)
        relance = application.base.relances_dues()[0]
        return campagne_id, relance["id"]

    def test_page_vide_et_execution_sans_dues(self):
        statut, page = self._obtenir("/relances")
        self.assertEqual(statut, 200)
        # A MENU OF TYPES, NOT A PARAGRAPH (owner's request, 02/08/2026). All
        # five types are there, each with ITS OWN count — that is how one
        # learns there is nothing, without five empty blocks. And the page
        # never goes mute: when everything is at zero, it says so. FOUR
        # FAMILIES SINCE 21/08/2026: `Demandes deja traitees` was removed (his
        # request). It kept, in a fifth tab, what he had just taken out of his
        # work list.
        self.assertEqual(self._menu_relances(page), {
            "🙋 Rappels par un humain": 0, "⏰ Relances dues": 0,
            "🕓 Relances à venir": 0,
            "📵 Non joints — maximum de rappels atteint": 0})
        self.assertIn("Rien n'attend de rappel", page)
        # The landing type is `human callbacks`, and it alone is visible.
        visible, contenu = self._panneau_relance(page, "humains")
        self.assertTrue(visible)
        self.assertIn("Aucun rappel par un humain en attente", contenu)
        for autre in ("dues", "a_venir", "bloques"):
            self.assertFalse(self._panneau_relance(page, autre)[0], autre)
        _, page = self._poster("/relances/executer")
        self.assertIn("Aucune relance n'était due", page)

    def test_le_menu_mene_a_chaque_type_meme_vide(self):
        """Clicking a type displays it: empty list, but title and explanation.

        Without JavaScript the link reloads the page with ?vue= — that is what
        this test exercises, so the fallback is verified for real.
        """
        for code, titre in (("dues", "⏰ Relances dues (0)"),
                            ("a_venir", "🕓 Relances à venir (0)"),
                            ("bloques", "📵 Non joints — maximum de rappels atteint (0)"),
                            ("humains", "🙋 Rappels par un humain (0)")):
            with self.subTest(vue=code):
                _, page = self._obtenir(f"/relances?vue={code}")
                visible, contenu = self._panneau_relance(page, code)
                self.assertTrue(visible)
                self.assertIn(titre, page)  # the title is kept
                self.assertIn("<p>", contenu)       # l'explication aussi
                self.assertIn("vide-famille", contenu)
                # The other three stay in reserve, hidden.
                for autre, _, _ in serveur.VUES_RELANCES:
                    if autre != code:
                        self.assertFalse(self._panneau_relance(page, autre)[0])
        # An unknown view breaks nothing: we fall back on the landing one.
        _, page = self._obtenir("/relances?vue=n_importe_quoi")
        self.assertTrue(self._panneau_relance(page, "humains")[0])

    def test_due_en_evidence_puis_geste_reporter_annuler(self):
        campagne_id, relance_id = self._creer_relance_due()
        _, page = self._obtenir("/relances?vue=dues")
        self.assertIn("⏰ Relances dues (1)", page)
        self.assertEqual(self._menu_relances(page)["⏰ Relances dues"], 1)
        visible, contenu = self._panneau_relance(page, "dues")
        self.assertTrue(visible)
        self.assertIn("Lancer les 1 relance(s) due(s)", contenu)
        self.assertIn("Secrétariat Exemple", contenu)
        self.assertIn("pas de réponse", contenu)
        self.assertIn("+33 6 •• •• •• 53", contenu)
        self.assertNotIn("+33 6 39 98 50 53", page)          # jamais en clair
        # Postpone to 2030: no longer due, but upcoming — the deadline is
        # editable. The gesture carries the type we were looking at: we do not
        # lose our place.
        _, page = self._poster("/relances/reporter", {
            "relance": relance_id, "vue": "dues",
            "echeance": "2030-01-01T10:00"})
        self.assertIn("Relance reportée", page)
        self.assertTrue(self._panneau_relance(page, "dues")[0])
        menu = self._menu_relances(page)
        self.assertEqual(menu["⏰ Relances dues"], 0)
        self.assertEqual(menu["🕓 Relances à venir"], 1)
        self.assertIn("01/01/2030", self._panneau_relance(page, "a_venir")[1])
        # Postpone to a past date: it becomes due again (the gesture decides).
        self._poster("/relances/reporter", {
            "relance": relance_id, "echeance": "2020-01-01T10:00"})
        _, page = self._obtenir("/relances")
        self.assertEqual(self._menu_relances(page)["⏰ Relances dues"], 1)
        # Cancel: the chain stops, the campaign finishes.
        _, page = self._poster("/relances/annuler", {"relance": relance_id})
        self.assertIn("Relance annulée", page)
        self.assertIn("Rien n'attend de rappel", page)
        base = self.application.base
        self.assertEqual(base.obtenir_relance(relance_id)["statut"], "annulée")
        self.assertEqual(base.obtenir_campagne(campagne_id)["statut"],
                         "terminée")
        # Cancelling it again: an honest message, nothing breaks.
        _, page = self._poster("/relances/annuler", {"relance": relance_id})
        self.assertIn("Relance introuvable", page)

    def test_echeance_illisible_refusee(self):
        _, relance_id = self._creer_relance_due()
        _, page = self._poster("/relances/reporter", {
            "relance": relance_id, "echeance": "bientôt"})
        self.assertIn("Date illisible", page)

    def test_hors_plage_refuse_le_geste_et_garde_la_relance(self):
        campagne_id, relance_id = self._creer_relance_due()
        if datetime.datetime.now().hour < 12:
            debut, fin = "22:00", "23:00"
        else:
            debut, fin = "01:00", "02:00"
        preferences = self.application.preferences
        preferences.definir(serveur.themes.CLE_PLAGE_DEBUT, debut)
        preferences.definir(serveur.themes.CLE_PLAGE_FIN, fin)
        with self.assertRaises(urllib.error.HTTPError) as contexte:
            self._poster("/relances/executer")
        self.assertEqual(contexte.exception.code, 403)
        self.assertIn("hors de la plage",
                      contexte.exception.read().decode("utf-8"))
        # The follow-up was not consumed.
        preferences.definir(serveur.themes.CLE_PLAGE_DEBUT, "00:00")
        preferences.definir(serveur.themes.CLE_PLAGE_FIN, "23:59")
        self.assertEqual(len(self.application.base.relances_dues()), 1)


class TestServeurRelancesDeuxFamilles(_TestAvecServeurWeb):
    """Follow-ups shows EVERYTHING that is waiting for a callback, in TWO
    families: the automatic callbacks (scheduled by the system, unreachable
    contacts included) and the human callbacks (never called automatically).
    """

    def _campagne_injoignable_et_humain(self):
        """A REAL campaign in simulation: the silent one (53) with a cap of 0
        callbacks ends up unreachable, and the one who wants to move without
        concluding (55) ends up `to be called back by a human`.
        """
        _, page = self._poster("/assistant/nature", {"nature": "prise_rdv"})
        identifiant = self._brouillon(page)
        _, page = self._poster("/assistant/message", {
            "b": identifiant, "action": "continuer",
            "info_entreprise": "Cabinet Essai",
            "info_origine": "vous avez demandé un rendez-vous",
            "info_creneaux_proposes": "lundi 10h, mardi 14h",
            "ordre": "liste", "mission_editee": "1",
            "mission": "Bonjour [client], au sujet de votre dossier.",
            "opt_recontacter": "1", "relance_mode": "delai",
            "relance_delai": "0", "relance_max": "0"})
        self.assertIn("3. Les personnes", page)
        _, page = self._poster("/assistant/importer", {
            "b": identifiant, "mode": "collage",
            "liste": "Mme Silence Essai;+33 6 39 98 50 53\n"
                     "M. Hesitant Essai;+33 6 39 98 50 55"})
        self.assertIn("2 contact(s) ajouté(s)", page)
        self._poster("/assistant/liste", {"b": identifiant, "action": "valider"})
        campagne = self.application.base.lister_campagnes()[0]
        self._demarrer(campagne["id"])
        self._attendre_statut(campagne["id"], "terminée")
        return campagne["id"]

    def test_injoignable_et_humain_chacun_dans_sa_famille(self):
        campagne_id = self._campagne_injoignable_et_humain()
        base = self.application.base
        etats = {c["nom"]: c for c in base.contacts_de_campagne(campagne_id)}
        self.assertEqual(etats["Mme Silence Essai"]["etat"], "injoignable")
        self.assertEqual(etats["M. Hesitant Essai"]["etat"],
                         "à rappeler par un humain")
        # Cap 0: NO follow-up is scheduled — and yet both people are indeed
        # waiting for a callback, so they are displayed.
        self.assertEqual(base.lister_relances("planifiée"), [])
        _, page = self._obtenir("/relances")
        # ONE NUMBER PER REALITY. The counter added up the scheduled follow-ups
        # and the people for whom nothing more will go out: it announced `1
        # automatic callback` while NONE was scheduled. The owner asked what
        # that meant — it meant nothing. Each type now carries its own.
        self.assertEqual(self._menu_relances(page), {
            "🙋 Rappels par un humain": 1, "⏰ Relances dues": 0,
            "🕓 Relances à venir": 0,
            "📵 Non joints — maximum de rappels atteint": 1})
        _, bloques = self._panneau_relance(page, "bloques")
        self.assertIn("Mme Silence Essai", bloques)  # the unreachable one IS THERE
        self.assertIn("plus de relance programmée", bloques)
        self.assertNotIn("M. Hesitant Essai", bloques)       # chacun chez soi
        humains_visible, humains = self._panneau_relance(page, "humains")
        self.assertTrue(humains_visible)  # the landing type
        self.assertIn("M. Hesitant Essai", humains)
        self.assertNotIn("Mme Silence Essai", humains)
        # Their request no longer sprawls across the cell: a link opens it.
        self.assertIn("Voir sa demande…", humains)
        self.assertNotIn("Demande du client", humains)
        self.assertIn("Prise de rendez-vous", humains)  # where it comes from
        self.assertNotIn("+33 6 39 98 50 5", page)  # masked everywhere
        # And the request is indeed at the end of the link, word for word.
        contact = self.application.base.contacts_rappel_humain()[0]
        _, modale = self._obtenir(f"/relances/demande?contact={contact['id']}")
        self.assertIn("Demande du client", modale)
        self.assertIn("Sa demande — M. Hesitant Essai", modale)
        self.assertNotIn("<!DOCTYPE", modale)  # a fragment

    def test_rappel_humain_traite_puis_repris_et_jamais_appele_seul(self):
        campagne_id = self._campagne_injoignable_et_humain()
        base = self.application.base
        contact = base.contacts_rappel_humain()[0]
        # Never called automatically: no follow-up targets them, and the
        # `Launch the due follow-ups` gesture does not touch them.
        self.assertEqual([r for r in base.relances_de_campagne(campagne_id)
                          if r["contact_id"] == contact["id"]], [])
        _, page = self._poster("/relances/executer")
        self.assertIn("Aucune relance n'était due", page)
        self.assertEqual(base.obtenir_contact_campagne(contact["id"])["etat"],
                         "à rappeler par un humain")
        self.assertEqual(len(base.appels_du_contact_campagne(contact["id"])), 1)
        # `DONE` TAKES IT OUT OF THE LIST, AND NOTHING IS ERASED. Since
        # 21/08/2026 (his request), there is no fifth `Demandes deja traitees`
        # tab: what he has just filed away has no business coming back to
        # occupy a tab. The DATA remains — the handling date is in the database
        # and the campaign's record shows everything.
        _, page = self._poster("/relances/humain",
                               {"contact": contact["id"], "valeur": 1,
                                "vue": "humains"})
        menu = self._menu_relances(page)
        self.assertEqual(menu["🙋 Rappels par un humain"], 0)
        self.assertNotIn("✅ Demandes déjà traitées", menu)
        self.assertNotIn('id="panneau-traites"', page)
        # The gesture brings us back to the type we were looking at, which says
        # it is empty.
        visible, humains = self._panneau_relance(page, "humains")
        self.assertTrue(visible)
        self.assertIn("Aucun rappel par un humain en attente", humains)
        # NOTHING IS ERASED: the handling date is written, and their request
        # stays openable — that is what makes removing the tab bearable.
        self.assertIsNotNone(
            base.obtenir_contact_campagne(contact["id"])["traite_le"])
        _, modale = self._obtenir(f"/relances/demande?contact={contact['id']}")
        self.assertIn("Demande du client", modale)
        self.assertEqual(base.contacts_rappel_humain(), [])
        # GOING BACK STILL EXISTS, BUT IT NO LONGER HAS A BUTTON. The `Remettre
        # dans la liste` gesture lived in the `deja traitees` tab, removed on
        # 21/08/2026 at his request. The ROUTE has not moved — it is what we
        # exercise here — and an unknown view falls back on the landing family,
        # without breaking.
        _, page = self._poster("/relances/humain",
                               {"contact": contact["id"], "valeur": 0,
                                "vue": "traites"})
        self.assertEqual(self._menu_relances(page)["🙋 Rappels par un humain"], 1)
        self.assertTrue(self._panneau_relance(page, "humains")[0])
        self.assertIsNone(
            base.obtenir_contact_campagne(contact["id"])["traite_le"])


class TestServeurEditionEnModale(_TestAvecServeurWeb):
    """We EDIT in a modal, never by changing page: only the element concerned
    comes back (the schedule's zone, the client's row).
    """

    def _poster_modale(self, chemin, donnees):
        """The POST as the modal sends it; returns (target, body).

        The target is the X-RingBack-Cible header: `modale` when the input is
        refused, otherwise the identifier of the element to fill in again.
        """
        octets = urllib.parse.urlencode(donnees, doseq=True).encode("utf-8")
        requete = urllib.request.Request(
            self.racine + chemin, data=octets,
            headers={"X-RingBack-Fragment": "1"})
        with urllib.request.urlopen(requete, timeout=15) as reponse:
            return (reponse.headers.get("X-RingBack-Cible"),
                    reponse.read().decode("utf-8"))

    def test_rendezvous_modifie_dans_la_modale(self):
        base = self.application.base
        rdv = base.tous_les_rendezvous()[0]
        # The modal carries the detail AND the editing; each value is INSIDE
        # its field.
        _, modale = self._obtenir(f"/suivi/detail?rdv={rdv['id']}")
        self.assertIn('action="/suivi/detail/enregistrer"', modale)
        self.assertIn("data-modale-envoi", modale)
        self.assertIn(f'value="{html.escape(rdv["motif"])}"', modale)
        self.assertIn(f'value="{rdv["horaire"]}"', modale)
        # Input refused: the MODAL comes back, with the error and the input.
        cible, corps = self._poster_modale("/suivi/detail/enregistrer", {
            "rdv": rdv["id"], "motif": "", "horaire": rdv["horaire"],
            "duree": "30", "statut": "manqué"})
        self.assertEqual(cible, "modale")
        self.assertIn("Saisie refusée", corps)
        self.assertIn("motif du rendez-vous est obligatoire", corps)
        self.assertIn('value="30"', corps)                  # rien n'est perdu
        self.assertEqual(base.obtenir_rendezvous(rdv["id"])["motif"],
                         rdv["motif"])  # nothing is written
        # On save: only the SCHEDULE comes back, the page does not move.
        cible, corps = self._poster_modale("/suivi/detail/enregistrer", {
            "rdv": rdv["id"], "motif": "  Bilan   complet  ",
            "horaire": rdv["horaire"], "duree": "30", "statut": "manqué"})
        self.assertEqual(cible, "planning")
        self.assertIn("Semaine du", corps)
        self.assertNotIn("<html", corps)  # a fragment, not the page
        frais = base.obtenir_rendezvous(rdv["id"])
        self.assertEqual(frais["motif"], "Bilan complet")
        self.assertEqual(frais["duree_tranches"], 2)
        self.assertEqual(frais["statut"], "manqué")
        # The fallback without JavaScript stays whole: the full-page record
        # works.
        statut, page = self._obtenir(f"/rendezvous?id={rdv['id']}")
        self.assertEqual(statut, 200)
        self.assertIn("Bilan complet", page)

    def test_client_modifie_dans_la_modale_seule_sa_ligne_revient(self):
        base = self.application.base
        client = base.lister_clients()[0]
        masque = client["telephone_masque"]
        # The list opens the MODAL, and keeps the link to the record
        # (fallback).
        _, liste = self._obtenir("/clients")
        self.assertIn(f'data-modale="/clients/detail?id={client["id"]}"', liste)
        self.assertIn(f'href="/clients/fiche?id={client["id"]}"', liste)
        self.assertIn(f'<tr id="client-{client["id"]}">', liste)
        _, modale = self._obtenir(f"/clients/detail?id={client['id']}")
        self.assertIn('action="/clients/detail/enregistrer"', modale)
        self.assertIn(f'value="{html.escape(client["nom"])}"', modale)
        self.assertIn(masque, modale)  # masked, even here
        self.assertIn("Laissez le champ", modale)  # keep the number
        # Input refused: the modal comes back with the error AND the input.
        cible, corps = self._poster_modale("/clients/detail/enregistrer", {
            "client": client["id"], "nom": "X", "telephone": "12345"})
        self.assertEqual(cible, "modale")
        self.assertIn("Saisie refusée", corps)
        self.assertIn('value="X"', corps)
        self.assertIn('value="12345"', corps)
        self.assertEqual(base.obtenir_client(client["id"])["nom"], client["nom"])
        # On save: ONLY this client's row comes back.
        cible, corps = self._poster_modale("/clients/detail/enregistrer", {
            "client": client["id"], "nom": "Mme Nadia Lefèvre-Roy",
            "telephone": "", "ne_plus_appeler": "1"})
        self.assertEqual(cible, f"client-{client['id']}")
        self.assertIn("Mme Nadia Lefèvre-Roy", corps)
        self.assertIn("🚫 ne plus appeler", corps)
        self.assertNotIn("<html", corps)
        self.assertNotIn("<tr", corps)  # the cells alone
        frais = base.obtenir_client(client["id"])
        self.assertEqual(frais["nom"], "Mme Nadia Lefèvre-Roy")
        self.assertEqual(frais["telephone_masque"], masque)  # number kept
        self.assertTrue(frais["ne_plus_appeler"])
        # The fallback without JavaScript stays whole.
        statut, page = self._obtenir(f"/clients/fiche?id={client['id']}")
        self.assertEqual(statut, 200)
        self.assertIn("Mme Nadia Lefèvre-Roy", page)


class TestScenariosProprietaire(_TestAvecServeurWeb):
    """The product owner's THREE exact scenarios, played end to end against the
    server, through real HTTP requests.
    """

    def test_scenario_a_place_liberee_cascade_premier_oui(self):
        """(a) Freed slot -> list of the moment + slot -> calls one by one ->
        first yes: slot allocated, the following ones spared.
        """
        base = self.application.base
        ancien = (datetime.datetime.now() + datetime.timedelta(days=10)
                  ).replace(hour=9, minute=0, second=0,
                            microsecond=0).isoformat(timespec="minutes")
        # (1) the `freed slot` kind (the cascade is its OPTION).
        _, page = self._poster("/assistant/nature", {"nature": "creneau_libere"})
        identifiant = self._brouillon(page)
        # (2) the message: the FREED SLOT and stopping at the first yes.
        _, page = self._poster("/assistant/message", {
            "b": identifiant, "action": "continuer",
            "info_entreprise": "Cabinet Essai", "info_creneau_libere": DEMAIN,
            "politique": "premier_oui", "ordre": "liste",
            "opt_recontacter": "1", "opt_liberer": "1", "opt_repondeur": "1",
            "relance_mode": "delai", "relance_delai": "4", "relance_max": "3"})
        self.assertIn("3. Les personnes", page)
        # MANUAL MODE: a freed-slot campaign opens in AUTOMATIC since
        # 09/08/2026, and its rule would recruit additional people from the
        # database. This scenario bears on a PASTED list, chosen by hand — that
        # is manual mode, the one the operator will ask for.
        self._poster("/assistant/liste",
                     {"b": identifiant, "action": "liste:manuel"})
        # (3) the list of the moment, pasted on the spot.
        _, page = self._poster("/assistant/importer", {
            "b": identifiant, "mode": "collage",
            "liste": f"Mme Refus Un;+33 6 39 98 50 52;{ancien};Séance\n"
                     f"M. Silence Deux;+33 6 39 98 50 53;{ancien};Séance\n"
                     f"Mme Accord Trois;+33 6 39 98 50 51;{ancien};Séance\n"
                     f"M. Épargné Quatre;+33 6 39 98 50 49;{ancien};Séance\n"})
        self.assertIn("4 contact(s) ajouté(s)", page)
        self.assertNotIn("+33 6 39 98 50 5", page)  # masked from the grid on
        # Validating creates the `prete` campaign: NOBODY is called yet.
        _, page = self._poster("/assistant/liste",
                               {"b": identifiant, "action": "valider"})
        self.assertIn("prête", page)
        campagne = base.lister_campagnes()[0]
        self.assertIn("Créneau libéré du", campagne["nom"])
        for contact in base.contacts_de_campagne(campagne["id"]):
            self.assertEqual(base.appels_du_contact_campagne(contact["id"]), [])
        # Start: one call at a time, stopping at the first yes.
        self._demarrer(campagne["id"])
        self._attendre_statut(campagne["id"], "terminée")
        # The cockpit proves the sequence: first yes, stop.
        _, page = self._obtenir(f"/campagne?id={campagne['id']}")
        self.assertIn("terminée", page)  # slot filled
        self.assertIn("Mme Accord Trois", page)
        self.assertIn("ligne-acceptee", page)  # the yes highlighted
        self.assertIn("Accepté — créneau attribué", page)    # l'issue de l'appel
        # THE DISPLAYED WORD IS `pas appele` since 11/08/2026: the owner did
        # not understand `epargne`. The CODE in the database is still `epargne`
        # (see assistant.mot_etat).
        self.assertIn("💤 pas appelé : 1", page)  # M. Epargne Quatre
        self.assertIn("🔁 à recontacter : 1", page)          # M. Silence Deux
        self.assertNotIn("+33 6 39 98 50 5", page)  # masked everywhere
        self.assertNotIn("+33 6 39 98 50 49", page)
        etats = {c["nom"]: c for c in base.contacts_de_campagne(campagne["id"])}
        self.assertEqual(etats["Mme Refus Un"]["etat"], "refusé")
        self.assertEqual(etats["M. Silence Deux"]["etat"], "à recontacter")
        self.assertEqual(etats["Mme Accord Trois"]["etat"], "accepté")
        # The first yes's appointment exists, AT THE SLOT, confirmed.
        pris = [r for r in base.tous_les_rendezvous()
                if r["nom"] == "Mme Accord Trois"]
        self.assertEqual([(r["horaire"], r["statut"]) for r in pris],
                         [(DEMAIN, "confirmé")])
        # Slot filled: NO follow-up pending any more — and the spared one was
        # never called.
        self.assertEqual([r for r in base.relances_de_campagne(campagne["id"])
                          if r["statut"] == "planifiée"], [])
        self.assertEqual(etats["M. Épargné Quatre"]["etat"], "épargné")
        self.assertEqual(base.appels_du_contact_campagne(
            etats["M. Épargné Quatre"]["id"]), [])
        # The home page shows the progress: 3 called out of 4, 1 accepted.
        _, accueil = self._obtenir("/")
        self.assertIn("3/4 appelé(s) · 1 accepté(s) · 0 relance(s)", accueil)

    def test_scenario_b_prise_rdv_relance_aboutie(self):
        """(b) Appointment booking -> no answer -> follow-up visible with its
        theme -> human gesture -> concluded, appointment created.

        This scenario relied on `single contact with a subject`, removed on
        03/08/2026. The MECHANISM exercised is the same — a call that does not
        succeed schedules a follow-up that keeps the theme, and the human
        gesture concludes it — and it now bears on a kind that really writes
        into the appointment book.
        """
        base = self.application.base
        origine = "vous avez demandé un rendez-vous sur notre site"
        # (1) the `appointment booking` kind.
        _, page = self._poster("/assistant/nature", {"nature": "prise_rdv"})
        self.assertIn("2. Le message", page)
        self.assertIn("Origine de la demande", page)  # the dedicated field
        identifiant = self._brouillon(page)
        # (2) the origin + follow-up due IMMEDIATELY (delay 0 working hours).
        _, page = self._poster("/assistant/message", {
            "b": identifiant, "action": "continuer",
            "info_entreprise": "Cabinet Essai", "info_origine": origine,
            "info_creneaux_proposes": "lundi 10h, mardi 14h",
            "ordre": "liste", "opt_recontacter": "1", "opt_repondeur": "1",
            "relance_mode": "delai", "relance_delai": "0", "relance_max": "3"})
        self.assertIn("3. Les personnes", page)
        # The origin feeds the pre-filled mission: no [origine] left waiting.
        _, etape2 = self._obtenir(f"/assistant/message?b={identifiant}")
        apercu = etape2.split('id="apercu"')[1].split("</div>")[0]
        # Honorifics EXPANDED: the preview shows what will be SAID over the
        # phone, not what is written in the record.
        self.assertIn(consigne.developper_civilites(origine), apercu)
        self.assertNotIn("[origine]", apercu)
        # (3) THE contact, number masked from the grid on.
        _, page = self._poster("/assistant/importer", {
            "b": identifiant, "mode": "collage",
            "liste": "Mme Demandeuse Exemple;+33 6 39 98 50 56\n"})
        self.assertIn("+33 6 •• •• •• 56", page)
        self.assertNotIn("+33 6 39 98 50 56", page)
        self._poster("/assistant/liste", {"b": identifiant, "action": "valider"})
        campagne = base.lister_campagnes()[0]
        self.assertIn("Prise de rendez-vous (1 contact(s))", campagne["nom"])
        self.assertIn(origine, campagne["mission"])  # the origin IS read
        # (1) the initial call gets no answer -> follow-up scheduled, theme
        # kept.
        self._demarrer(campagne["id"])
        self._attendre_statut(campagne["id"], "terminée")
        _, fiche = self._obtenir(f"/campagne?id={campagne['id']}")
        self.assertIn("🔁 à recontacter : 1", fiche)
        # The DEADLINE is read on Follow-ups, and the record links there: the
        # contacts table's `Detail` column was removed (11/08/2026).
        self.assertIn("Des relances sont programmées", fiche)
        self.assertIn('href="/relances"', fiche)
        _, relances_page = self._obtenir("/relances?vue=dues")
        self.assertEqual(
            self._menu_relances(relances_page)["⏰ Relances dues"], 1)
        _, dues = self._panneau_relance(relances_page, "dues")
        self.assertIn("Prise de rendez-vous (1 contact(s))", dues)
        self.assertIn("Prise de rendez-vous", dues)  # the THEME
        self.assertIn("pas de réponse", dues)
        self.assertNotIn("+33 6 39 98 50 56", relances_page)
        # (2) the human GESTURE: `Launch the due follow-ups` -> it succeeds.
        _, resultat = self._poster("/relances/executer")
        self.assertIn("Relances exécutées", resultat)
        self.assertIn("Confirmé", resultat)
        self.assertIn("Chaîne conclue", resultat)
        # (3) the campaign is finished, the chain closed, appointment obtained.
        campagne = base.lister_campagnes()[0]
        self.assertEqual(campagne["statut"], "terminée")
        self.assertEqual(campagne["relances"], 0)            # plus rien en attente
        _, fiche = self._obtenir(f"/campagne?id={campagne['id']}")
        self.assertIn("✅ accepté : 1", fiche)
        self.assertNotIn("+33 6 39 98 50 56", fiche)
        rdv = base.tous_les_rendezvous()[0]
        self.assertEqual(rdv["nom"], "Mme Demandeuse Exemple")
        self.assertEqual(rdv["statut"], "confirmé")

    def test_scenario_c_deplacement_non_conclu_relance_theme_sauvegarde(self):
        """(c) Confirmation: the client wants to move WITHOUT agreeing a date ->
        NOTHING is invented (their appointment stays intact, they go to `to be
        called back by a human`); and the follow-up of the unreached contact in
        the SAME campaign keeps the theme and the parameters.
        """
        base = self.application.base
        plus_tard = (datetime.datetime.fromisoformat(DEMAIN)
                     + datetime.timedelta(hours=2)).isoformat(timespec="minutes")
        # Two FUTURE appointments: `wants to move` (55) and `silent` (53).
        self._poster("/ajouter", {
            "nom": "M. Hesitant Exemple", "telephone": "+33 6 39 98 50 55",
            "date_heure": DEMAIN, "motif": "Bilan annuel"})
        self._poster("/ajouter", {
            "nom": "M. Silence Deux", "telephone": "+33 6 39 98 50 53",
            "date_heure": plus_tard, "motif": "Contrôle"})
        # (1) the `appointment confirmation` kind.
        _, page = self._poster("/assistant/nature", {"nature": "confirmation"})
        identifiant = self._brouillon(page)
        # (2) the message + follow-up due immediately (delay 0 working hours).
        _, page = self._poster("/assistant/message", {
            "b": identifiant, "action": "continuer",
            "info_entreprise": "Cabinet Essai", "ordre": "liste",
            "opt_recontacter": "1", "opt_liberer": "1", "opt_repondeur": "1",
            "relance_mode": "delai", "relance_delai": "0", "relance_max": "3"})
        self.assertIn("3. Les personnes", page)
        # (3) takeover FROM THE DATABASE: the upcoming appointments fill the
        # grid's `existing appointment` and `reason` columns. The label now
        # SAYS what the source contains. `a venir` takes only the appointments
        # NOT YET confirmed; for everything occupying a slot (scheduled +
        # confirmed), it is `poses` — the source added on 02/08/2026, the one
        # that counts like the schedule.
        self.assertIn("Rendez-vous à venir, pas encore confirmés", page)
        self.assertIn("prévus ET confirmés (comme au planning)", page)
        _, page = self._poster("/assistant/importer", {
            "b": identifiant, "mode": "base", "source": "a_venir"})
        self.assertIn("2 contact(s) ajouté(s)", page)
        self.assertIn("M. Hesitant Exemple", page)
        self.assertIn("Bilan annuel", page)
        self.assertNotIn("+33 6 39 98 50 55", page)  # masked
        _, page = self._poster("/assistant/liste",
                               {"b": identifiant, "action": "valider"})
        self.assertIn("prête", page)
        campagne = base.lister_campagnes()[0]
        self.assertEqual(campagne["theme"], "confirmation")  # THEME saved
        self.assertEqual(campagne["nature"], "confirmation")
        mission = campagne["mission"]  # PARAMETERS kept
        self.assertIn("merci de me confirmer votre présence", mission)
        self._demarrer(campagne["id"])
        self._attendre_statut(campagne["id"], "terminée")
        etats = {c["nom"]: c for c in base.contacts_de_campagne(campagne["id"])}
        # THE RULE CHANGED ON 11/08/2026 (owner's decision): the human callback
        # now exists only on `appointment move` and `appointment booking`. On a
        # CONFIRMATION, nothing is pending on our side — the appointment in
        # question is theirs, they can call us back themselves. Hence `le
        # client rappellera`, and what they said is quoted in clear: nothing is
        # invented.
        self.assertEqual(etats["M. Hesitant Exemple"]["etat"],
                         "le client rappellera")
        self.assertEqual(etats["M. Hesitant Exemple"]["issue"], "to_reschedule")
        self.assertIn("Rien n'a été conclu au téléphone",
                      etats["M. Hesitant Exemple"]["detail"])
        self.assertIn("le client rappellera : 1",
                      self._obtenir(f"/campagne?id={campagne['id']}")[1])
        # The appointment is CANCELLED, and its DATE does not move.  THIS TEST
        # EXPECTED `prevu` UNTIL 17/08/2026. His rule of that day: `si la
        # personne doit rappeler, le rendez-vous est simplement annule`. What
        # remains true of the old reason: we above all do NOT set it to
        # `confirme` — that would be inventing the very confirmation we did not
        # obtain. But leaving it `prevu` kept the slot blocked for somebody who
        # has just said they will not come as planned; `annule` frees the slot,
        # and the row stays on the schedule.
        rdv = [r for r in base.tous_les_rendezvous()
               if r["nom"] == "M. Hesitant Exemple"][0]
        self.assertEqual(rdv["statut"], "annulé")
        self.assertEqual(rdv["horaire"], DEMAIN)
        # The silent one, for their part, schedules a follow-up that KEEPS the
        # theme.
        self.assertEqual(etats["M. Silence Deux"]["etat"], "à recontacter")
        relance = base.relances_dues()[0]
        self.assertEqual(relance["campagne_theme"], "confirmation")
        self.assertEqual(relance["motif"], "pas de réponse")
        self.assertEqual(relance["telephone_masque"], "+33 6 •• •• •• 53")
        self.assertEqual(base.obtenir_campagne(relance["campagne_id"])["mission"],
                         mission)
        # The Follow-ups page carries the kept theme, spelled out in full.
        _, relances_page = self._obtenir("/relances")
        self.assertIn("Confirmation de rendez-vous", relances_page)
        self.assertIn("pas de réponse", relances_page)
        self.assertNotIn("+33 6 39 98 50 5", relances_page)
        # The record: outcome displayed, transcript with the mission
        # substituted for THIS contact (the appointment's date and reason),
        # never the number.
        _, fiche = self._obtenir(f"/campagne?id={campagne['id']}")
        self.assertIn("À reprogrammer (date non conclue)", fiche)
        self.assertIn("Agent : Bonjour M. Hesitant Exemple", fiche)
        self.assertIn("pour Bilan annuel : merci de me confirmer votre présence.",
                      fiche)
        self.assertNotIn("+33 6 39 98 50 55", fiche)


class TestAssistantUnite(unittest.TestCase):
    """The 3-step wizard: the targeted unit pieces (mock-up)."""

    def test_collage_multi_colonnes_avec_dates_validees(self):
        champs = assistant.champs_campagne(
            {"champs": list(assistant.NATURES["creneau_libere"]["champs"])})
        contacts, erreurs, refusees = assistant.analyser_collage(
            f"Mme Une Exemple;+33 6 39 98 50 51;{DEMAIN};Séance\n"
            "M. Deux Exemple;0639985052\n"
            "M. Date Fausse;0639985053;bientôt;Séance\n", champs)
        self.assertEqual(len(contacts), 2)
        self.assertEqual(contacts[0]["champs"],
                         {"rdv_existant": DEMAIN, "motif": "Séance"})
        self.assertEqual(contacts[1]["champs"], {})  # required columns
        # Row 2: required columns absent -> REPORTED, saying what is expected,
        # but the row is kept (it gets completed in the grid).
        ligne_manque = [e for e in erreurs if "Ligne 2" in e][0]
        self.assertIn("il manque", ligne_manque)
        self.assertIn("Rendez-vous existant", ligne_manque)
        self.assertIn("Motif", ligne_manque)
        # Row 3: unreadable date -> REFUSED, and returned for correction.
        ligne_date = [e for e in erreurs if "Ligne 3" in e][0]
        self.assertIn("Date illisible", ligne_date)
        self.assertEqual(refusees, ["M. Date Fausse;0639985053;bientôt;Séance"])

    def test_periode_interdite_traverse_minuit(self):
        prefs = generation.Preferences()
        prefs.definir(assistant.CLE_INTERDIT_DEBUT, "20:00")
        prefs.definir(assistant.CLE_INTERDIT_FIN, "08:00")
        soir = datetime.datetime(2026, 7, 28, 21, 30)
        matin = datetime.datetime(2026, 7, 29, 7, 0)
        midi = datetime.datetime(2026, 7, 29, 12, 0)
        self.assertIn("période interdite",
                      assistant.dans_periode_interdite(prefs, soir))
        self.assertIn("période interdite",
                      assistant.dans_periode_interdite(prefs, matin))
        self.assertIsNone(assistant.dans_periode_interdite(prefs, midi))


class TestAssistantCampagne(_TestAvecServeurWeb):
    """THE wizard's nominal route (specification v1.1), through real HTTP
    requests: freed slot -> blocked -> fill in -> paste -> validate (ready,
    nobody is called) -> start in simulation -> stop at the first yes + spared
    contact + old appointment freed.
    """

    def test_parcours_nominal_creneau_libere(self):
        base = self.application.base
        # The future `yes` already has an appointment in the database: it will
        # be freed.
        rdv_lointain = (datetime.datetime.now() + datetime.timedelta(days=10)
                        ).replace(hour=9, minute=0, second=0, microsecond=0
                                  ).isoformat(timespec="minutes")
        client_id = base.ajouter_client("Mme Accord Trois",
                                        "+33 6 39 98 50 51")
        rdv_ancien = base.ajouter_rendezvous(client_id, rdv_lointain,
                                             "Séance d'essai")
        # Step 1: the eight cards, default policy displayed; the breadcrumb
        # shows the current step and blocks those that are not reachable.
        statut, page = self._obtenir("/assistant")
        self.assertEqual(statut, 200)
        self.assertGreaterEqual(page.count("carte-nature"), 5)
        self.assertIn("arrêt au premier OUI", page)
        self.assertIn('class="fil-ariane"', page)
        self.assertIn("1. La nature", page)
        self.assertIn("fa-etape fa-courante", page)
        # `Freed slot` kind -> step 2, live preview. Step 1 becomes clickable
        # (change kind), step 3 stays blocked.
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        self.assertIn('<a id="fa-etape-1" class="fa-etape fa-faite" '
                      'href="/assistant">', page)
        self.assertIn("2. Le message", page)
        self.assertIn("fa-bloquee", page)  # step 3 not reachable
        self.assertIn('id="apercu"', page)
        self.assertIn("var-manquante", page)  # variables en rouge
        b = self._brouillon(page)
        formulaire = {
            "b": b, "action": "continuer", "info_entreprise": "Cabinet Essai",
            "ordre": "liste", "opt_recontacter": "1", "opt_liberer": "1",
            "opt_repondeur": "1", "relance_mode": "delai",
            "relance_delai": "4", "relance_max": "3"}
        # Continuing WITHOUT the freed slot's date is REFUSED (server side).
        _, page = self._poster("/assistant/message", formulaire)
        self.assertIn("obligatoire pour cette nature", page)
        self.assertIn('id="apercu"', page)  # we did not get through
        self.assertNotIn("3. Les personnes</span></a>", page)  # step 3 closed
        # Filling in the date -> step 3 (the breadcrumb opens all the way).
        formulaire["info_creneau_libere"] = DEMAIN
        _, page = self._poster("/assistant/message", formulaire)
        self.assertIn("3. Les personnes", page)
        self.assertIn('<a id="fa-etape-2" class="fa-etape fa-faite" '
                      f'href="/assistant/message?b={b}">', page)
        # STEP 3 OPENS IN AUTOMATIC since 09/08/2026. This route exercises the
        # grid, from the paste to the validation: it therefore asks for MANUAL
        # mode, as the operator who wants to choose their people will.
        _, page = self._poster("/assistant/liste",
                               {"b": b, "action": "liste:manuel"})
        # Both progress bars are full (the CSS style does not count).
        self.assertEqual(page.count('class="fa-trait fa-trait-fait"'), 2)
        # Paste: 3 contacts (endings 52, 53, 51) + a 4th to prove the sparing —
        # the 4th row WITHOUT an existing appointment (required field empty).
        _, page = self._poster("/assistant/importer", {
            "b": b, "mode": "collage", "liste":
            f"Mme Refus Un;+33 6 39 98 50 52;{rdv_lointain};Séance\n"
            f"M. Silence Deux;+33 6 39 98 50 53;{rdv_lointain};Séance\n"
            f"Mme Accord Trois;+33 6 39 98 50 51;{rdv_lointain};Séance d'essai\n"
            "M. Épargné Quatre;+33 6 39 98 50 49\n"})
        self.assertIn("4 contact(s) ajouté(s)", page)
        self.assertIn("•• •• ••", page)  # grid masked
        self.assertNotIn("+33 6 39 98 50 51", page)
        # Grid check: validating with row 4 incomplete is REFUSED. ONE SINGLE
        # SENTENCE since 02/08/2026, and the offending CELL coloured: thirty
        # identical sentences never said where to type.
        _, page = self._poster("/assistant/liste", {"b": b, "action": "valider"})
        self.assertIn(assistant.MESSAGE_CHAMPS_OBLIGATOIRES, page)
        self.assertIn('name="c_rdv_existant_4" class="manque"', page)
        # And a complete row is NOT coloured.
        self.assertNotIn('name="c_rdv_existant_1" class="manque"', page)
        # Fill in row 4 in the grid, then validate.
        self._poster("/assistant/liste", {
            "b": b, "action": "enregistrer",
            "c_rdv_existant_4": rdv_lointain, "c_motif_4": "Séance"})
        _, page = self._poster("/assistant/liste", {"b": b, "action": "valider"})
        self.assertIn("prête", page)
        campagne = base.lister_campagnes()[0]
        self.assertEqual(campagne["statut"], "prête")
        contacts = base.contacts_de_campagne(campagne["id"])
        for contact in contacts:  # NOBODY is called
            self.assertEqual(base.appels_du_contact_campagne(contact["id"]), [])
        # Start: the thread calls one contact at a time, in simulation.
        _, page = self._demarrer(campagne["id"])
        self._attendre_statut(campagne["id"], "terminée")
        etats = {c["nom"]: c for c in base.contacts_de_campagne(campagne["id"])}
        self.assertEqual(etats["Mme Refus Un"]["etat"], "refusé")        # 52
        self.assertEqual(etats["M. Silence Deux"]["etat"], "à recontacter")  # 53
        self.assertEqual(etats["Mme Accord Trois"]["etat"], "accepté")   # 51
        # Stop at the first yes: the 4th was NEVER called.
        self.assertEqual(etats["M. Épargné Quatre"]["etat"], "épargné")
        self.assertEqual(base.appels_du_contact_campagne(
            etats["M. Épargné Quatre"]["id"]), [])
        # ONE SINGLE ROW, WHICH CHANGES DATE (owner's decision of 14/08/2026:
        # `tu deplaces un rendez-vous d'une date a une autre`). Before, we
        # created a SECOND row at the new date and marked the old one
        # `deplace`: it stayed in the calendar, and he saw two appointments for
        # a single move. It is the SAME row that moves, and it is confirmed —
        # the history, for its part, lives in the change log.
        ancien = base.obtenir_rendezvous(rdv_ancien)
        self.assertEqual(ancien["statut"], "confirmé")
        self.assertEqual(ancien["horaire"], DEMAIN)
        self.assertIn("DÉPLACÉ", etats["Mme Accord Trois"]["detail"])
        # And the change log carries A SINGLE gesture: one move with its two
        # dates, not a deletion + addition pair that would tell of two.
        changements = base.changements_de_campagne(campagne["id"])
        gestes = [c["genre"] for c in changements
                  if c["nom"] == "Mme Accord Trois"]
        self.assertIn("deplacement", gestes)
        self.assertNotIn("suppression", gestes)
        self.assertNotIn("ajout", gestes)
        ligne = next(c for c in changements
                     if c["nom"] == "Mme Accord Trois"
                     and c["genre"] == "deplacement")
        self.assertTrue(ligne["ancienne_date"])
        self.assertEqual(ligne["nouvelle_date"], DEMAIN)
        nouveaux = [r for r in base.tous_les_rendezvous()
                    if r["nom"] == "Mme Accord Trois"
                    and r["statut"] == "confirmé"]
        self.assertEqual([r["horaire"] for r in nouveaux], [DEMAIN])
        # The silent one's follow-up is cancelled: the objective is reached.
        relances = base.relances_de_campagne(campagne["id"])
        self.assertEqual([r["statut"] for r in relances], ["annulée"])
        # The cockpit: accepted highlighted, spared, masked.
        _, fiche = self._obtenir(f"/campagne?id={campagne['id']}")
        self.assertIn("ligne-acceptee", fiche)
        self.assertIn("épargné", fiche)
        # The cascade shift is no longer `coming soon`: it is configurable, and
        # this campaign did not tick it — the record says so in plain words.
        self.assertIn("Décaler en cascade : non", fiche)
        # THE CHANGE LOG CARRIES A SINGLE GESTURE since 03/08/2026: this YES
        # MOVED the appointment. Writing `deleted` then `added` would have told
        # of two gestures for one, and the operator copying into their own
        # software would have removed one row to create another.
        self.assertIn("Le cahier des changements à reporter", fiche)
        self.assertIn("Rendez-vous déplacé", fiche)
        self.assertNotIn("Rendez-vous supprimé", fiche)
        self.assertNotIn("+33 6 39 98 50 5", fiche)
        self.assertNotIn("+33 6 39 98 50 49", fiche)

    def test_periode_interdite_bloque_le_demarrage(self):
        # Set THROUGH THE SETTINGS SCREEN, the forbidden period covers the
        # whole day: Start is genuinely refused, the campaign stays `prete`.
        # The start goes out here WITH the gesture on the calendar: it is the
        # proof that the forbidden period stays paramount — the new reminder
        # does not slip in ahead of the existing locks.
        self._poster("/reglages/enregistrer", {
            "entreprise": "Cabinet Essai", "plage_debut": "00:00",
            "plage_fin": "23:59", "interdit_debut": "00:00",
            "interdit_fin": "23:59"})
        _, page = self._poster("/assistant/nature", {"nature": "prise_rdv"})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "ordre": "liste",
            "info_entreprise": "Cabinet Essai",
            "info_origine": "vous avez demandé un rendez-vous",
            "info_creneaux_proposes": "lundi 10h, mardi 14h",
            "mission": "Bonjour [identite], petit message.",
            "mission_editee": "1"})
        self._poster("/assistant/importer", {
            "b": b, "mode": "collage", "liste": "Mme Test;+33 6 39 98 50 41"})
        self._poster("/assistant/liste", {"b": b, "action": "valider"})
        campagne = self.application.base.lister_campagnes()[0]
        self.assertEqual(campagne["statut"], "prête")
        with self.assertRaises(urllib.error.HTTPError) as contexte:
            self._demarrer(campagne["id"])
        self.assertEqual(contexte.exception.code, 403)
        self.assertIn("période interdite",
                      contexte.exception.read().decode("utf-8"))
        self.assertEqual(self.application.base.obtenir_campagne(
            campagne["id"])["statut"], "prête")  # nothing moved

    def test_etape3_voies_format_attendu_et_saisie_conservee(self):
        """Step 3: radio buttons that open a screen, expected format, input kept.
        """
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "info_entreprise": "Cabinet Essai",
            "info_creneau_libere": DEMAIN, "politique": "premier_oui",
            "ordre": "liste", "opt_recontacter": "1", "relance_mode": "delai",
            "relance_delai": "4", "relance_max": "3"})
        # Each filling route OPENS a different screen: here radio buttons are
        # the right shape, and only one panel is open at the start.
        _, page = self._poster("/assistant/importer", {
            "b": b, "mode": "collage", "liste":
            f"Mme Bonne Ligne;+33 6 39 98 50 51;{DEMAIN};Séance\n"
            "M. Date Fausse;+33 6 39 98 50 53;bientôt;Séance\n"})
        # SIX routes since 02/08/2026: `Reprendre depuis la base` mixed two
        # unrelated questions (which DATES? which CLIENTS?); it is broken down
        # into three distinct routes, arranged in two columns — what we bring,
        # and what RingBack already has.
        self.assertEqual(page.count('name="remplissage"'), 6)
        self.assertEqual(page.count('class="panneau" id="panneau-'), 6)
        self.assertEqual(page.count('id="panneau-collage">'), 1)   # ouvert
        self.assertEqual(len(re.findall(r'id="panneau-\w+" hidden', page)), 5)
        self.assertEqual(page.count('class="deux-colonnes"'), 1)
        for voie in ("clients", "rendezvous", "campagne"):
            with self.subTest(voie=voie):
                self.assertIn(f'id="panneau-{voie}" hidden', page)
        # The expected format is displayed, required columns marked, and an
        # example as a watermark (never submitted: that would be a fake
        # contact).
        self.assertIn("Nom;Téléphone;Rendez-vous existant (date + heure) ⚠;"
                      "Motif ⚠", page)
        self.assertIn('placeholder="Mme Dupont Martine;+33 6 39 98 12 34;', page)
        # The error message says what was EXPECTED, not just what is wrong.
        self.assertIn("Date illisible", page)
        # The refused row comes back into the paste area; the good one, already
        # in the grid, does NOT (otherwise a second submission = a duplicate).
        zone = re.search(r'<textarea name="liste"[^>]*>(.*?)</textarea>',
                         page, re.S).group(1)
        self.assertIn("M. Date Fausse", zone)
        self.assertNotIn("Mme Bonne Ligne", zone)
        # The masked number is INSIDE its field (not above it: no offset) and
        # sending it back as is means `unchanged`.
        self.assertIn('name="tel_1" value="+33 6 •• •• •• 51"', page)
        self.assertNotIn("+33 6 39 98 50 51", page)
        _, page = self._poster("/assistant/liste", {
            "b": b, "action": "enregistrer", "nom_1": "Mme Bonne Ligne",
            "tel_1": "+33 6 •• •• •• 51", "c_rdv_existant_1": DEMAIN,
            "c_motif_1": "Séance"})
        self.assertIn('name="tel_1" value="+33 6 •• •• •• 51"', page)
        self.assertNotIn("À corriger", page)

    def test_regles_de_forme_des_formulaires(self):
        """The interface rules: selectors, revealed options, no page reload."""
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        b = self._brouillon(page)
        # Rule: a selector rather than a stack of radio buttons.
        self.assertNotIn('<input type="radio"', page)
        for nom in ('name="politique"', 'name="relance_mode"', 'name="ordre"'):
            self.assertIn(f"<select class=\"select-option\" {nom}", page)
        # CALL ORDER REVERSED ON 03/08/2026: `freed slot` now offers the MOST
        # DISTANT appointment first — they have the most to gain by moving
        # forward onto the slot that frees up. The choice stays open.
        self.assertIn('<option value="eloignement" selected>', page)
        self.assertIn("— à choisir —", page)
        # A kind with no obvious order still preselects NOTHING.
        _, libre = self._poster("/assistant/nature", {"nature": "prise_rdv"})
        self.assertIn('<option value="" selected>— à choisir —</option>', libre)
        # Rule: a checkbox never takes the full width.
        self.assertIn('<label class="option">', page)
        # Rule: an option's options are in a block the script reveals only when
        # the parent is active.
        for bloc in ("bloc-relance", "bloc-delai", "bloc-creneau", "bloc-cascade"):
            self.assertIn(f'id="{bloc}"', page)
        self.assertIn("b.hidden=!(r&&r.checked)", page)  # the reveal
        # Rule: adding a field does not reload the page — it travels inside the
        # form and arrives as a column at step 3.
        formulaire = {
            "b": b, "action": "continuer", "info_entreprise": "Cabinet Essai",
            "info_creneau_libere": DEMAIN, "politique": "premier_oui",
            "ordre": "liste", "opt_recontacter": "1", "relance_mode": "delai",
            "relance_delai": "4", "relance_max": "3",
            "champ_perso": ["Numéro de dossier|texte|", "Visite|date|1"]}
        _, page = self._poster("/assistant/message", formulaire)
        self.assertIn("Numéro de dossier", page)
        self.assertIn("Visite", page)
        # Removing a field = no longer sending it; the others stay.
        formulaire["champ_perso"] = ["Numéro de dossier|texte|"]
        _, page = self._poster("/assistant/message", formulaire)
        self.assertIn("Numéro de dossier", page)
        self.assertNotIn("Visite", page)


class TestVerificationAgendaAvantDemarrage(_TestAvecServeurWeb):
    """Start requires a CONSCIOUS GESTURE about the calendar's state.

    The work is twofold (8.1 of CAS_DE_FIGURE_CAMPAGNES.md): what is decided
    over the phone changes RingBack's LOCAL calendar **and** feeds the change
    log to be carried over into the scheduling software. Since the slots
    announced over the phone are DERIVED from that calendar, an out-of-date
    calendar leads to offering slots already taken in real life. The reminder
    is therefore shown AT THE MOMENT of starting — and nowhere else — with the
    day's figures taken from the database.
    """

    def _campagne_prete(self, contacts="Mme Essai Une;+33 6 39 98 50 51",
                        nature="prise_rdv"):
        _, page = self._poster("/assistant/nature", {"nature": nature})
        b = self._brouillon(page)
        formulaire = {"b": b, "action": "continuer", "ordre": "liste",
                      "info_entreprise": "Cabinet Essai",
                      "mission": "Bonjour [identite], essai du rappel.",
                      "mission_editee": "1"}
        if nature == "prise_rdv":
            formulaire["info_origine"] = "vous avez demandé un rendez-vous"
            formulaire["info_creneaux_proposes"] = "lundi 10h, mardi 14h"
        self._poster("/assistant/message", formulaire)
        self._poster("/assistant/importer",
                     {"b": b, "mode": "collage", "liste": contacts})
        self._poster("/assistant/liste", {"b": b, "action": "valider"})
        campagne = self.application.base.lister_campagnes()[0]
        self.assertEqual(campagne["statut"], "prête")
        return campagne["id"]

    def _agenda_garni(self):
        """A standard week open every day + three known appointments."""
        preferences = self.application.preferences
        preferences.definir(horaires.CLE_SEMAINE,
                            {str(jour): [[540, 720]] for jour in range(7)})
        base = self.application.base
        client = base.ajouter_client("Mme Agenda Essai", "+33 6 39 98 50 61")
        demain = (datetime.datetime.now() + datetime.timedelta(days=1)).replace(
            hour=9, minute=0, second=0, microsecond=0)
        base.ajouter_rendezvous(client, demain.isoformat(timespec="minutes"),
                                "Séance", statut="prévu")
        base.ajouter_rendezvous(
            client, (demain + datetime.timedelta(minutes=30)).isoformat(
                timespec="minutes"), "Séance", statut="confirmé")
        # A cancelled one: KNOWN over the period, but it no longer occupies its
        # slot.
        base.ajouter_rendezvous(
            client, (demain + datetime.timedelta(minutes=60)).isoformat(
                timespec="minutes"), "Séance", statut="annulé")

    def test_aucun_appel_ne_part_sans_le_geste(self):
        campagne_id = self._campagne_prete()
        base = self.application.base
        _, page = self._poster("/campagne/demarrer", {"campagne": campagne_id})
        # The campaign has not moved, and nobody was dialled.
        self.assertEqual(base.obtenir_campagne(campagne_id)["statut"], "prête")
        for contact in base.contacts_de_campagne(campagne_id):
            self.assertEqual(base.appels_du_contact_campagne(contact["id"]), [])
        # The page comes back WITH the reminder open (the fallback without
        # JavaScript): the reason is stated, and nothing is lost.
        self.assertIn("Rien n&#x27;est parti", page)
        self.assertIn('class="verif-agenda"', page)
        self.assertIn("sortent de l&#x27;agenda de RingBack", page)
        self.assertIn('name="agenda_verifie"', page)
        self.assertNotIn("+33 6 39 98 50 51", page)  # number never in clear

    def test_le_geste_lance_vraiment_la_campagne(self):
        campagne_id = self._campagne_prete()
        _, page = self._poster("/campagne/demarrer",
                               {"campagne": campagne_id, "agenda_verifie": "1"})
        self.assertIn("Campagne démarrée", page)
        self._attendre_statut(campagne_id, "terminée")

    def test_les_chiffres_du_panneau_sont_ceux_de_la_base(self):
        """No invented figure: the panel and the database say the same thing.
        """
        self._agenda_garni()
        campagne_id = self._campagne_prete(
            "Mme Essai Une;+33 6 39 98 50 51\nM. Essai Deux;+33 6 39 98 50 52")
        base, preferences = self.application.base, self.application.preferences

        def places_libres():
            return len([creneau for creneau
                        in horaires.creneaux_proposables(base, preferences)
                        if not creneau["occupe"]])

        # The number of slots changes with the hour: we compare only if the
        # computation gives the same result just before and just after the
        # request.
        for _ in range(3):
            avant = places_libres()
            _, panneau = self._obtenir(
                f"/campagne/verification-agenda?id={campagne_id}")
            apres = places_libres()
            if avant == apres:
                break
        self.assertEqual(avant, apres, "le calcul a changé pendant l'essai")
        self.assertIn(f"<strong>{avant}</strong> place(s) libre(s)", panneau)
        # Three known appointments over the period, two of which occupy a slot.
        self.assertIn("<strong>3</strong> rendez-vous connu(s)", panneau)
        self.assertIn("<strong>2</strong> qui occupe(nt)", panneau)
        self.assertIn("<strong>2</strong> personne(s) à appeler", panneau)
        # The first slots announced are the ones RingBack will offer.
        self.assertIn(horaires.creneaux_lisibles(base, preferences, limite=3),
                      panneau)
        self.assertNotIn("+33 6 39 98 50 5", panneau)  # never a number

    def test_agenda_douteux_le_panneau_le_dit_franchement(self):
        """No standard week, no appointment: it is said, not sugar-coated."""
        campagne_id = self._campagne_prete()
        _, panneau = self._obtenir(
            f"/campagne/verification-agenda?id={campagne_id}")
        self.assertIn("Ce que RingBack constate lui-même", panneau)
        self.assertIn("Aucune semaine type n&#x27;est réglée", panneau)
        self.assertIn("Aucun rendez-vous n&#x27;est connu sur la période",
                      panneau)
        # No trace of an import: it is said to be UNKNOWN, never an invented
        # date.
        self.assertIn("Dernier import de rendez-vous par fichier : "
                      "<strong>inconnu</strong>", panneau)
        # The button changes its wording when there is a doubt: one does not
        # click the same button out of habit.
        self.assertIn("Démarrer quand même", panneau)

    def test_agenda_sain_le_bouton_porte_les_chiffres(self):
        self._agenda_garni()
        campagne_id = self._campagne_prete()
        _, panneau = self._obtenir(
            f"/campagne/verification-agenda?id={campagne_id}")
        self.assertNotIn("Ce que RingBack constate lui-même", panneau)
        self.assertIn("Oui, l&#x27;agenda est à jour", panneau)
        self.assertIn("1 personne(s), ", panneau)
        self.assertIn("place(s) libre(s)</button>", panneau)

    def test_la_date_du_dernier_import_vient_de_l_import_reel(self):
        """The displayed date is written BY the import, not guessed."""
        frontiere = "----frontiereAgenda"
        with open(os.path.join(RACINE, "exemple_agenda.ics"),
                  encoding="utf-8") as fichier:
            contenu = fichier.read()
        corps = (f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="fichier"; '
                 'filename="agenda.ics"\r\n'
                 "Content-Type: text/calendar\r\n\r\n"
                 f"{contenu}\r\n--{frontiere}--\r\n").encode("utf-8")
        requete = urllib.request.Request(
            self.racine + "/importer-ics", data=corps,
            headers={"Content-Type": f"multipart/form-data; boundary={frontiere}"})
        with urllib.request.urlopen(requete, timeout=10) as reponse:
            reponse.read()
        trace = horaires.dernier_import_agenda(self.application.preferences)
        self.assertEqual(trace["quoi"], "agenda ICS")
        self.assertEqual(trace["rendezvous"], 3)  # the file carries 3
        campagne_id = self._campagne_prete()
        _, panneau = self._obtenir(
            f"/campagne/verification-agenda?id={campagne_id}")
        self.assertIn(themes.date_lisible(trace["quand"]), panneau)
        self.assertIn("agenda ICS, 3 rendez-vous", panneau)

    def test_le_rappel_n_est_montre_qu_au_moment_de_demarrer(self):
        """A warning one sees everywhere gets read nowhere."""
        campagne_id = self._campagne_prete()
        for chemin in ("/", "/suivi", "/clients", "/relances", "/reglages"):
            _, page = self._obtenir(chemin)
            self.assertNotIn('class="verif-agenda"', page, chemin)
        # On the cockpit itself, the block exists but stays EMPTY until a click
        # has requested it from the server.
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn('<div id="verification-agenda" hidden></div>', page)
        self.assertNotIn('class="verif-agenda"', page)
        # Once the campaign is launched, the reminder no longer has a reason to
        # be.
        self._demarrer(campagne_id)
        self._attendre_statut(campagne_id, "terminée")
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertNotIn('id="verification-agenda"', page)


class TestJeuEssai(unittest.TestCase):
    """The test data: loaded on an explicit gesture, additive, removable."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)

    def test_numeros_dans_les_racines_reservees_a_la_fiction(self):
        # Safety lock: NO number in the test data must be able to ring at
        # anybody's home. They all come from the six roots the Arcep reserves
        # for audiovisual works (see jeu_essai.py for the source).
        terminaisons = set()
        for nom, telephone, _ in jeu_essai.CLIENTS:
            if not telephone:
                continue
            compact = re.sub(r"\D", "", telephone)
            racines = {re.sub(r"\D", "", r) for r in jeu_essai.RACINES_FICTION}
            self.assertTrue(any(compact.startswith(r) for r in racines),
                            f"{nom} : {telephone} hors des racines de fiction")
            terminaisons.add(compact[-2:])
        # A handful carry the endings the simulator recognises: a test campaign
        # thus produces every case.
        self.assertTrue({"51", "52", "53", "54", "55", "56"} <= terminaisons)
        # AND NO CONTACT CARRIES 57, 58 OR 59: those three leave a lasting
        # trace or put the campaign on hold. Placed on a test contact, they
        # would change every campaign that crosses it — and the bench would no
        # longer return the same report twice.
        self.assertFalse({"57", "58", "59"} & terminaisons)

    def test_recharger_un_autre_jour_ne_double_pas_l_agenda(self):
        """THE REAL CASE: we reload the test data DAYS LATER, to get enriched
        demonstration data.

        Since the times are computed from `now`, comparing by time would have
        recognised nothing — hence the identity (patient, reason). Without it,
        each reload added 112 more appointments.
        """
        jeu_essai.charger(self.base)
        combien = len(self.base.tous_les_rendezvous())
        demain = datetime.datetime.now() + datetime.timedelta(days=1)
        self.assertEqual(jeu_essai.charger(self.base, maintenant=demain),
                         (0, 0))
        self.assertEqual(len(self.base.tous_les_rendezvous()), combien)

    def test_un_rendez_vous_de_demonstration_a_une_identite_unique(self):
        """RATCHET ON THE IDENTITY. The deduplication rests on (patient, reason):
        if two rows of the test data shared that pair, one of them would never
        be loaded again — silently.
        """
        vus, doubles = set(), set()
        for entree in jeu_essai.RENDEZVOUS:
            cle = (entree[0], entree[4])
            if cle in vus:
                doubles.add(cle)
            vus.add(cle)
        self.assertEqual(doubles, set())

    def test_le_jeu_d_essai_porte_sur_cent_jours(self):
        """THE REQUEST OF 11/08/2026: `puisqu'on a du 90 jours on devrait avoir
        des exemples sur 100 jours`.

        MEASURED BEFORE: the most distant upcoming appointment was at +9 days.
        A slot freed beyond that therefore found NOBODY, and the list rule's
        `up to 30 days` and `up to 90 days` options could give nothing
        different from `no limit`.
        """
        futurs = [jours for _, jours, *_ in jeu_essai.RENDEZVOUS if jours > 0]
        self.assertGreaterEqual(max(futurs), 90,
                                "il faut de la matière au-delà de 90 jours")
        # Spread out, not piled up: every month of the quarter has some.
        for borne_basse, borne_haute in ((10, 30), (30, 60), (60, 90),
                                         (90, 101)):
            with self.subTest(entre=(borne_basse, borne_haute)):
                self.assertTrue([j for j in futurs
                                 if borne_basse <= j < borne_haute])

    def test_deux_patients_n_ont_de_rendez_vous_qu_au_dela_de_quatre_vingt_dix(self):
        """THE FIX BORN OF A MEASUREMENT. Four appointments go past 90 days, but
        they belonged to patients who ALSO have a nearer one — and the list
        keeps only one appointment per person, the first. `Up to 90 days after`
        therefore still returned exactly the same list as `no limit`. People
        whose ONLY appointment is outside the window are needed for the window
        to be visible.
        """
        par_client = {}
        for nom, jours, *_ in jeu_essai.RENDEZVOUS:
            par_client.setdefault(nom, []).append(jours)
        seulement_loin = [nom for nom, jours in par_client.items()
                          if jours and min(jours) > 90]
        self.assertGreaterEqual(len(seulement_loin), 2, par_client)

    def test_la_source_des_deplaces_en_attente_garde_ses_candidats(self):
        """THE REINFORCEMENT'S SAFETY LOCK. `Moved, waiting` keeps only the
        clients WITHOUT any upcoming appointment: giving a distant session to
        the six patients who serve it would have taken them out of it, and a
        whole campaign kind would have had no material left.
        """
        jeu_essai.charger(self.base)
        candidats, _, _ = self.base.candidats_cascade("deplaces")
        self.assertGreaterEqual(len(candidats), 6)

    def test_charge_puis_retire_sans_toucher_aux_vraies_donnees(self):
        mien = self.base.ajouter_client("Mme Vraie Cliente",
                                        "+33 6 39 98 50 42")
        self.base.ajouter_rendezvous(mien, DEMAIN, "Mon vrai rendez-vous")
        self.assertFalse(jeu_essai.est_charge(self.base))
        clients, rendezvous = jeu_essai.charger(self.base)
        self.assertEqual(clients, len(jeu_essai.CLIENTS))
        self.assertEqual(rendezvous, len(jeu_essai.RENDEZVOUS))
        self.assertTrue(jeu_essai.est_charge(self.base))
        # Additive: the user's client is still there, unflagged.
        self.assertEqual(self.base.compter_clients(), clients + 1)
        self.assertFalse(self.base.obtenir_client(mien)["jeu_essai"])
        # A SECOND LOAD DOUBLES NOTHING — NEITHER THE CLIENTS NOR THE
        # APPOINTMENTS. This test only looked at the CLIENTS, and the defect
        # slipped underneath: the appointments were recreated every time.
        # Measured on 11/08/2026: 112, then 224, then 336. And it is a defect
        # that bites — to get enriched data one MUST reload.
        agenda_avant = len(self.base.tous_les_rendezvous())
        self.assertEqual(jeu_essai.charger(self.base), (0, 0))
        self.assertEqual(len(self.base.tous_les_rendezvous()), agenda_avant)
        # Reversible: only the test records go away.
        self.base.supprimer_jeu_essai()  # (retirer() is only its alias)
        self.assertFalse(jeu_essai.est_charge(self.base))
        self.assertEqual(self.base.compter_clients(), 1)
        self.assertEqual(self.base.obtenir_client(mien)["nb_rendezvous"], 1)

    def test_contenu_realiste_annonce_avant_le_chargement(self):
        info = jeu_essai.resume()
        jeu_essai.charger(self.base)
        clients = self.base.lister_clients()
        self.assertEqual(sum(1 for c in clients if c["ne_plus_appeler"]),
                         info["ne_plus_appeler"])
        self.assertEqual(sum(1 for c in clients if not c["telephone_masque"]),
                         info["sans_numero"])
        noms = [c["nom"] for c in clients]
        self.assertEqual(noms.count("M. Jean Martin"), 2)       # homonymes
        self.assertIn("Mme Marie-Christine de La Tour du Pin", noms)  # nom long
        # Past AND future, with missed, cancelled and moved ones.
        statuts = {r["statut"] for r in self.base.tous_les_rendezvous()}
        self.assertTrue({"manqué", "annulé", "déplacé", "prévu"} <= statuts)


class TestImportICSRealiste(unittest.TestCase):
    """The phone number read WHERE IT ACTUALLY IS in an .ics file."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)

    @staticmethod
    def _lire(nom):
        with open(os.path.join(RACINE, nom), encoding="utf-8") as fichier:
            return fichier.read()

    def test_export_google_agenda_description_etiquetee(self):
        evenements, erreurs = ics.analyser_ics(
            self._lire("exemple_agenda_realiste.ics"))
        par_nom = {e["nom"]: e for e in evenements}
        # DESCRIPTION `Telephone : ...` (by far the most frequent case).
        self.assertEqual(par_nom["Mme Solange Dupuis-Ferrand"]["telephone"],
                         "06 39 98 01 23")
        # DESCRIPTION `Mobile ...` (another label, folded line).
        self.assertEqual(par_nom["M. Théo Sanchez"]["telephone"],
                         "02 61 91 06 53")
        # No number in the calendar: the contact stays WITHOUT a number — never
        # an invented number, even when the note contains other figures.
        self.assertEqual(par_nom["Mme Perrine Vasseur-Delaunay"]["telephone"], "")
        self.assertEqual(par_nom["Mme Zoé Berthier"]["telephone"], "")
        # STATUS:CANCELLED becomes a `cancelled` appointment.
        self.assertEqual(par_nom["M. Sébastien Nguyen"]["statut"], "annulé")
        # The `all day` one is still rejected, in French.
        self.assertEqual(len(erreurs), 1)
        self.assertIn("journée entière", erreurs[0])

    def test_export_outlook_uri_tel_contact_et_x_alt_desc(self):
        evenements, erreurs = ics.analyser_ics(
            self._lire("exemple_agenda_outlook.ics"))
        self.assertEqual(erreurs, [])
        par_nom = {e["nom"]: e for e in evenements}
        # ATTENDEE en URI « tel: » (RFC 5545 § 3.3.3 + RFC 3966).
        self.assertEqual(par_nom["M. Hervé Dombasle"]["telephone"],
                         "+33 6 39 98 00 56")
        # CONTACT as free text (RFC 5545 3.8.4.2's own example).
        self.assertEqual(par_nom["Mme Gaëlle Le Goff"]["telephone"],
                         "06 39 98 01 14")
        # X-ALT-DESC: the HTML version Outlook adds to DESCRIPTION.
        self.assertEqual(par_nom["Mme Noémie Fauconnier"]["telephone"],
                         "06 39 98 01 16")

    def test_import_relie_les_fiches_au_lieu_de_les_doubler(self):
        jeu_essai.charger(self.base)
        avant = self.base.compter_clients()
        importes, _ = ics.importer_ics(
            self.base, self._lire("exemple_agenda_outlook.ics"))
        self.assertEqual(importes, 3)
        # `+33 6 39 98 00 56` and `06 39 98 00 56` are the SAME number: no
        # second record for M. Herve Dombasle.
        noms = [c["nom"] for c in self.base.lister_clients()]
        self.assertEqual(noms.count("M. Hervé Dombasle"), 1)
        self.assertEqual(self.base.compter_clients(), avant)
        # The do-not-call safety lock survives a change in the number's
        # spelling.
        stop = self.base.conn.execute(
            "SELECT id, telephone FROM clients WHERE ne_plus_appeler = 1"
        ).fetchone()
        international = "+33 " + stop["telephone"][1:]
        self.assertTrue(self.base.telephone_exclu(international))


class TestRepriseDepuisCampagne(unittest.TestCase):
    """Starting again from a previous campaign's RESULTS, filtered by state."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.campagne_id = self.base.creer_campagne(
            "Rappel du 28/07", "rappel_rdv", nature="rappel_rdv")
        etats = (("Mme Injoignable Une", "06 39 98 02 01", "injoignable"),
                 ("M. Injoignable Deux", "06 39 98 02 02", "injoignable"),
                 ("Mme Refus Trois", "06 39 98 02 03", "refusé"),
                 ("M. Accepté Quatre", "06 39 98 02 04", "accepté"),
                 ("Mme Sans Numéro", "", "injoignable"),
                 ("M. Stop Six", "06 39 98 02 06", "injoignable"))
        for rang, (nom, telephone, etat) in enumerate(etats, start=1):
            self.base.ajouter_contact_campagne(
                self.campagne_id, rang, nom, telephone, etat=etat,
                champs=json.dumps({"motif": "Séance de kinésithérapie"}))
        # The last one asked not to be called again from within the campaign.
        client = self.base.ajouter_client("M. Stop Six", "06 39 98 02 06")
        self.base.definir_ne_plus_appeler(client, True)
        self.champs = assistant.champs_campagne(
            {"champs": [assistant._champ("motif", "Motif")]})

    def test_comptes_par_etat_visibles_avant_l_ajout(self):
        comptes = self.base.compter_contacts_par_etat(self.campagne_id)
        self.assertEqual(comptes["tous"], 6)
        self.assertEqual(comptes["injoignable"], 4)
        self.assertEqual(comptes["refusé"], 1)
        reprenables = assistant.campagnes_reprenables(self.base)
        self.assertEqual(len(reprenables), 1)
        self.assertIn("6 contact(s)", reprenables[0][1])

    def test_filtre_injoignables_ecarte_sans_numero_et_stop(self):
        contacts, complements = assistant.contacts_depuis_campagne(
            self.base, self.campagne_id, "injoignable", self.champs)
        self.assertEqual([c["nom"] for c in contacts],
                         ["Mme Injoignable Une", "M. Injoignable Deux"])
        # The already-filled columns follow: nothing to retype.
        self.assertEqual(contacts[0]["champs"]["motif"],
                         "Séance de kinésithérapie")
        self.assertIn("1 contact(s) sans numéro écarté(s)", complements)
        self.assertIn("1 contact(s) 🚫 « Ne plus appeler » écarté(s)",
                      complements)

    def test_autres_etats_et_etat_inconnu_refuse(self):
        for etat, attendu in (("refusé", 1), ("accepté", 1), ("tous", 4)):
            contacts, _ = assistant.contacts_depuis_campagne(
                self.base, self.campagne_id, etat, self.champs)
            self.assertEqual(len(contacts), attendu, f"état « {etat} »")
        with self.assertRaises(saisie.SaisieInvalide):
            assistant.contacts_depuis_campagne(
                self.base, self.campagne_id, "inventé", self.champs)


class TestInstallationUnite(unittest.TestCase):
    """The installer's MAP: its sections, its pages, its progress."""

    NATURES = (("creneau_libere", "📞", "Créneau libéré"),
               ("prise_rdv", "🗓", "Prise de rendez-vous"))

    def setUp(self):
        self.prefs = generation.Preferences()

    def test_la_carte_suit_les_natures_du_produit(self):
        """A removed kind removes its section: the installer follows the product,
        it does not keep a second list that would end up diverging.
        """
        parties = installation.parties(self.NATURES)
        codes = [code for code, _, _ in parties]
        # THE CALENDAR COMES BEFORE THE CAMPAIGNS (03/08/2026): the slots a
        # campaign offers come from the calendar, so it is as well to have
        # filled it before configuring what uses it.
        self.assertEqual(codes, ["bienvenue", "appel", "agenda",
                                 "nature-creneau_libere",
                                 "nature-prise_rdv", "fin"])
        # No decorative pictogram left in the labels: only the tick and the
        # cross have a place in this menu.
        for _, libelle, _ in parties:
            with self.subTest(libelle=libelle):
                self.assertTrue(libelle.isprintable())
                self.assertNotRegex(libelle, r"[\U0001F300-\U0001FAFF☀-➿]")
        self.assertEqual([libelle for _, libelle, _ in parties],
                         ["Bienvenue", "Appeler", "Agenda", "Créneau libéré",
                          "Prise de rendez-vous", "Terminer"])
        # Two pages per kind: its options, then its script.
        pages_nature = dict((c, [p for p, _ in s]) for c, _, s in parties)
        self.assertEqual(pages_nature["nature-prise_rdv"],
                         ["prise_rdv-comportement", "prise_rdv-discours"])
        # The calendar does NOT ask for the slots to offer: they are computed.
        self.assertEqual(pages_nature["agenda"],
                         ["horaires", "jours-fermes", "import"])
        self.assertNotIn("creneaux", installation.pages(self.NATURES))

    def test_le_parcours_est_un_fil_sans_trou(self):
        pages = installation.pages(self.NATURES)
        self.assertEqual(pages[0], "bienvenue")
        self.assertEqual(pages[-1], "fin")
        for avant, apres in zip(pages, pages[1:]):
            self.assertEqual(installation.suivante(avant, self.NATURES), apres)
        self.assertIsNone(installation.suivante("fin", self.NATURES))
        # An unknown page breaks nothing: we start again from the beginning.
        self.assertEqual(installation.page_valide("martien", self.NATURES),
                         "bienvenue")
        self.assertEqual(installation.suivante("martien", self.NATURES),
                         "bienvenue")

    def test_une_partie_ne_verdit_qu_entierement_faite(self):
        # `calle` JOINED THE `Appeler` SECTION on 10/08/2026, at the TOP: it is
        # what decides whether the product can call at all. The section
        # therefore only goes green with it — the test reads that from the map
        # instead of copying the list, so that a future addition does not make
        # it false.
        toutes = [code for code, _ in installation.PAGES_APPELS]
        self.assertEqual(toutes[0], "calle")
        for page in toutes[:-1]:
            installation.marquer_faite(self.prefs, page)
            self.assertFalse(installation.partie_faite(
                "appel", self.prefs, self.NATURES), page)
        installation.marquer_faite(self.prefs, toutes[-1])
        self.assertTrue(installation.partie_faite("appel", self.prefs,
                                                  self.NATURES))
        # Marking twice does not count twice.
        installation.marquer_faite(self.prefs, toutes[-1])
        self.assertEqual(installation.progression(self.prefs, self.NATURES),
                         (len(toutes), len(installation.pages(self.NATURES))))

    def test_reprendre_efface_les_coches_pas_les_reglages(self):
        installation.marquer_faite(self.prefs, "identite")
        installation.marquer_terminee(self.prefs)
        self.prefs.definir(themes.CLE_ENTREPRISE, "Cabinet Essai")
        installation.rouvrir(self.prefs)
        self.assertFalse(installation.terminee(self.prefs))
        self.assertEqual(installation.faites(self.prefs), set())
        # The setting itself is intact: we go round again, we do not start from
        # scratch.
        self.assertEqual(self.prefs.obtenir(themes.CLE_ENTREPRISE),
                         "Cabinet Essai")


class TestServeurInstallation(_TestAvecServeurWeb):
    """The installer on screen: it opens, it writes through the same path as the
    Settings, it records what is done, and it closes on a gesture.
    """

    def _natures(self):
        return [(code, fiche["icone"], fiche["nom"])
                for code, fiche in assistant.NATURES.items()]

    def _ouvert(self, page):
        """True if the installer's window is visible on this page."""
        return ('id="fond-installeur"' in page
                and 'id="fond-installeur" hidden' not in page)

    @staticmethod
    def _fenetre(page):
        """The installer's window ALONE, apostrophes restored.

        Two traps, both met on 03/08/2026:
        - the stylesheet is included in every page, so searching for
        `arbre-installeur` in the whole page finds it first in the CSS — the
        assertion then proves nothing;
        - the labels are escaped, so a test searching for the text as we write
        it fails on a correct page.
        """
        # The prefix ALONE: the window carries an extra class on the home and
        # the end screens (`installeur-libre`, height fitted to the content).
        # Searching for the exact string no longer found anything.
        marque = '<div class="modale installeur'
        if marque not in page:
            return ""
        return html.unescape(page[page.index(marque):])

    @staticmethod
    def _sous_menu(fenetre, classe):
        """The contents of one of the window's two navigations."""
        marque = f'class="{classe}"'
        if marque not in fenetre:
            return ""
        debut = fenetre.index(marque)
        return fenetre[debut:fenetre.index("</nav>", debut)]

    def test_il_s_ouvre_au_premier_lancement_et_pas_apres(self):
        accueil = self._obtenir("/")[1]
        self.assertTrue(self._ouvert(accueil))
        self.assertIn("Bienvenue dans RingBack", accueil)
        # THE HOME SCREEN HAS NO NAVIGATION (03/08/2026): no tree, no page
        # list, not the slightest cross. They arrive when it starts.
        fenetre = self._fenetre(accueil)
        self.assertTrue(fenetre, "la fenêtre de l'installeur est introuvable")
        self.assertNotIn('class="barre-installeur"', fenetre)
        self.assertNotIn('class="menu-installeur"', fenetre)
        self.assertNotIn("marque-partie", fenetre)
        self._poster("/installation/terminer", {})
        self.assertFalse(self._ouvert(self._obtenir("/")[1]))
        # But it stays reachable on request: the Settings link must have
        # something to reopen.
        self.assertTrue(self._ouvert(self._obtenir("/?installation=1")[1]))

    def test_demarrer_mene_a_la_premiere_page_et_fait_paraitre_le_menu(self):
        """`Demarrer` opens `Appeler`, and the navigation then appears.

        Owner's request of 03/08/2026: the home screen is bare, clicking
        `Demarrer` takes you to the calls page, and the menu shows itself —
        without `Bienvenue`, which one does not come back to.
        """
        _, page = self._poster("/installation/valider", {"page": "bienvenue"})
        fenetre = self._fenetre(page)
        self.assertIn('class="barre-installeur"', fenetre)
        self.assertIn('class="menu-installeur"', fenetre)
        # We did land on the first page of `Appeler`.
        self.assertIn('data-page="identite"', fenetre)
        self.assertIn("Identité de l'établissement", fenetre)
        # `Bienvenue` has disappeared from the menu: the word is no longer
        # there.
        self.assertNotIn("Bienvenue",
                         self._sous_menu(fenetre, "barre-installeur"))

    def test_le_bandeau_est_horizontal_et_deroule_les_campagnes(self):
        """Four sections in a band; the campaigns in a panel.

        The panel sits ON TOP of the content instead of pushing it: that is
        what lets the window keep its height. It starts CLOSED — a drop-down
        menu that is already open is no longer a drop-down menu.
        """
        def bandeau_de(page):
            """We NAVIGATE, we do not validate: `marking` moves on a page, and the
            test would have found itself somewhere other than it thought.
            """
            return self._sous_menu(
                self._fenetre(self._obtenir(f"/installation?page={page}")[1]),
                "barre-installeur")

        bandeau = bandeau_de("identite")
        for libelle in ("Appeler", "Agenda", "Comportement de l'agent IA",
                        "Terminer"):
            with self.subTest(libelle=libelle):
                self.assertIn(libelle, bandeau)
        # The five campaigns are in the panel, and it is folded.
        self.assertIn('class="panneau-deroulant" id="panneau-campagnes" hidden',
                      bandeau)
        self.assertIn('aria-expanded="false"', bandeau)
        for _, _, nom in self._natures():
            with self.subTest(nom=nom):
                self.assertIn(nom, bandeau)
        # Only one entry unfolds: the other three lead to a page.
        self.assertEqual(bandeau.count("data-menu-deroulant"), 1)

        # On a campaign: it is the entry that unfolds which becomes active.
        bandeau = bandeau_de("confirmation-discours")
        self.assertIn('class="actif" data-menu-deroulant', bandeau)
        self.assertIn('class="actif" data-page="confirmation-comportement"',
                      bandeau)

    def test_le_menu_des_pages_suit_la_section(self):
        """To the left of the form, the pages of the section we are in.

        The band carries the sections, this menu carries the pages. Two levels,
        two places — and `Terminer`, which has only one page, has no menu at
        all.
        """
        def menu_de(page):
            return self._sous_menu(
                self._fenetre(self._obtenir(f"/installation?page={page}")[1]),
                "menu-installeur")

        menu = menu_de("identite")
        self.assertIn("Quand appeler", menu)
        self.assertIn("Délais d'un appel réel", menu)
        self.assertNotIn("Créneau libéré", menu)  # that is the band

        menu = menu_de("confirmation-discours")
        self.assertIn("Options de comportement", menu)
        self.assertIn("Discours de l'agent", menu)
        self.assertNotIn("Quand appeler", menu)  # plus the neighbouring section

        self.assertEqual(menu_de("fin"), "",
                         "une section d'une seule page n'a pas de menu")

    def test_le_panneau_deroulant_fait_naviguer(self):
        """Each panel entry really does lead to its campaign.

        A button leading nowhere would not be visible by simply reading the
        HTML — so we make the complete round trip.
        """
        bandeau = self._sous_menu(
            self._fenetre(self._obtenir(
                "/installation?page=creneau_libere-discours")[1]),
            "barre-installeur")
        # We stop at the panel's closing tag: going to the end of the band also
        # caught `Terminer`, and the test counted six campaigns for five.
        debut = bandeau.index('class="panneau-deroulant"')
        panneau = bandeau[debut:bandeau.index("</div>", debut)]
        cibles = re.findall(r'data-page="([^"]+)"', panneau)
        self.assertEqual(len(cibles), len(self._natures()))
        for cible in cibles:
            with self.subTest(cible=cible):
                _, arrivee = self._obtenir(f"/installation?page={cible}")
                fenetre = self._fenetre(arrivee)
                self.assertIn("Options de comportement", fenetre)
                # We are indeed in the campaigns section, on the right one.
                self.assertIn('class="actif" data-menu-deroulant', fenetre)
                self.assertIn(f'class="actif" data-page="{cible}"', fenetre)

    def test_le_panneau_se_referme_de_trois_facons(self):
        """Once open, it must be able to close — and not only from outside.

        It only closed on a click OUTSIDE the window: it stayed across the form
        while one filled it in. Seen by measuring, not by reading. The three
        routes live in the script: a click on the entry, a click elsewhere in
        the window, Escape.
        """
        script = _sans_espaces_superflus(serveur.SCRIPT_INSTALLATION)
        # A single function closes everything: three closings written three
        # times would have fallen out of step.
        self.assertIn("function fermerDeroulants()", script)
        # (1) the entry itself toggles; (2) a click elsewhere INSIDE the
        # window; (3) a click outside the window; (4) the Escape key.
        self.assertIn("data-menu-deroulant", script)
        self.assertIn("closest('.entree-deroulante')", script)
        self.assertIn("!fond.contains(e.target)", script)
        self.assertIn("e.key==='Escape'", script)

    def test_le_menu_ne_porte_que_des_coches_et_des_croix(self):
        """No decorative icon: no confetti, no telephone, no calendar.

        They said nothing. The tick and the cross, on the other hand, carry
        information — and the sign can be read even without seeing the colour.
        """
        _, page = self._poster("/installation/marquer", {"page": "identite"})
        bandeau = self._sous_menu(self._fenetre(page), "barre-installeur")
        self.assertIn("marque-partie a-faire", bandeau)
        for icone in ("🎉", "📞", "🗓", "🔔", "📆", "🚀"):
            with self.subTest(icone=icone):
                self.assertNotIn(icone, bandeau)

    def test_la_fenetre_a_une_hauteur_fixe(self):
        """It breathed from 349 to 774 pixels depending on the page opened.

        A window that changes size at every move jumps before your eyes. It now
        has an imposed height, and it is the content that scrolls — both
        columns have their own scrollbar.
        """
        corps = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE, ".modale.installeur"))
        self.assertIn("height: min(", corps)
        self.assertIn("display: flex", corps)
        self.assertIn("flex-direction: column", corps)
        # TWO REGIMES since 03/08/2026: the home and the end screens fit their
        # content, the configuration pages keep their height. It is between the
        # latter that one navigates.
        libre = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE, ".modale.installeur.installeur-libre"))
        self.assertIn("height: auto", libre)
        self.assertIn("max-height: min(", libre)
        # And their title is bigger: it carries the whole screen.
        titre = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE,
                            ".installeur-libre .page-installeur h2"))
        self.assertIn("font-size: 1.75rem", titre)
        # The footer does not scroll: it is stuck to the bottom of the window.
        pied = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE, ".pied-installeur"))
        self.assertIn("flex: none", pied)
        # The content scrolls, otherwise the fixed height would cut pages off.
        colonnes = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE, ".installeur-deux-parts > *"))
        self.assertIn("overflow-y: auto", colonnes)
        self.assertIn("min-height: 0", colonnes)
        # And the columns stretch: without that, `overflow` is of no use.
        grille = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE, ".installeur-deux-parts"))
        self.assertIn("align-items: stretch", grille)

    def test_le_groupe_des_campagnes_ne_verdit_qu_entierement_fait(self):
        """A tick on the group while a campaign is still to be done would be a
        lie: the group follows ALL its campaigns.
        """
        prefs = self.application.preferences
        natures = self._natures()
        self.assertFalse(installation.noeud_fait(installation.GROUPE_AGENT,
                                                 prefs, natures))
        for code, _, _ in natures[:-1]:
            for page in (f"{code}-comportement", f"{code}-discours"):
                installation.marquer_faite(prefs, page)
        self.assertFalse(installation.noeud_fait(installation.GROUPE_AGENT,
                                                 prefs, natures),
                         "il reste une campagne : pas de coche verte")
        dernier = natures[-1][0]
        for page in (f"{dernier}-comportement", f"{dernier}-discours"):
            installation.marquer_faite(prefs, page)
        self.assertTrue(installation.noeud_fait(installation.GROUPE_AGENT,
                                                prefs, natures))

    def test_l_accueil_et_la_fin_sont_debarrasses(self):
        """The texts and icons removed on 03/08/2026 do not come back."""
        accueil = self._fenetre(self._obtenir("/")[1])
        # The four configuration points, in blue. The labels are compared
        # WITHOUT their line breaks: the source's formatting must not decide
        # whether a test passes.
        self.assertEqual(accueil.count('class="point-config"'), 4)
        plat = _sans_espaces_superflus(accueil)
        for intitule in ("Ce que l'agent dit",
                         "Quand il a le droit d'appeler",
                         "Les places qu'il peut proposer",
                         "Ce qu'il fait quand ça n'aboutit pas"):
            with self.subTest(intitule=intitule):
                self.assertIn(intitule, plat)
        # The two deleted blocks.
        self.assertNotIn("Trois choses à savoir", plat)
        self.assertNotIn("ferme cette fenêtre pour aujourd'hui", plat)

        fin = self._fenetre(
            self._poster("/installation/marquer", {"page": "fin"})[1])
        self.assertIn("Vous êtes désormais prêt", fin)
        self.assertNotIn("🎉", fin)
        self.assertNotIn("🚀", fin)
        self.assertNotIn("Votre établissement est déclaré", fin)
        # The final button: bigger and bold.
        self.assertIn("bouton-final", fin)
        corps = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE,
                            ".installeur-accueil .bouton-final"))
        self.assertIn("font-weight: 700", corps)
        self.assertIn("font-size", corps)

    def test_plus_tard_ne_s_ecrit_pas_sur_le_disque(self):
        """`Configurer plus tard` holds for the session, not for ever: those words
        do not mean `never ask me again`.
        """
        self._poster("/installation/plus-tard", {})
        self.assertFalse(self._ouvert(self._obtenir("/")[1]))
        self.assertFalse(installation.terminee(self.application.preferences))
        # A restart (here: we erase the session marker) brings it back.
        self.application.installation_reportee = False
        self.assertTrue(self._ouvert(self._obtenir("/")[1]))

    def test_toutes_les_pages_se_rendent(self):
        for page in installation.pages(self._natures()):
            with self.subTest(page=page):
                statut, fragment = self._obtenir(f"/installation?page={page}")
                self.assertEqual(statut, 200)
                # The prefix: the home and the end screens also carry
                # `installeur-libre` (height fitted to their content).
                self.assertIn('class="modale installeur', fragment)
                self.assertNotIn("Page inconnue", fragment)
                self.assertNotIn("<!DOCTYPE", fragment)  # a fragment

    def test_valider_ecrit_pour_de_vrai_et_passe_a_la_suite(self):
        _, page = self._poster("/installation/valider?page=identite",
                               {"entreprise": "Cabinet Val Fleuri"})
        self.assertEqual(
            self.application.preferences.obtenir(themes.CLE_ENTREPRISE),
            "Cabinet Val Fleuri")
        # We are on the NEXT page, and the completed page carries its tick.
        self.assertIn("Quand RingBack a le droit d'appeler", page)
        self.assertIn("identite", installation.faites(
            self.application.preferences))
        self.assertIn("marque-partie faite", page)
        # And the setting really is the Settings one: the page shows it.
        self.assertIn("Cabinet Val Fleuri", self._obtenir("/reglages")[1])

    def test_une_saisie_refusee_reste_sur_place_et_n_ecrit_rien(self):
        _, page = self._poster("/installation/valider?page=appel",
                               {"plage_debut": "19:00", "plage_fin": "09:00"})
        self.assertIn("doit précéder", page)
        self.assertIn("Quand RingBack a le droit d'appeler", page)  # in place
        self.assertNotIn("appel", installation.faites(
            self.application.preferences))

    def test_le_discours_refuse_un_numero_ici_comme_ailleurs(self):
        cle = assistant.cle_discours("confirmation")
        _, page = self._poster(
            "/installation/valider?page=confirmation-discours",
            {cle: "Bonjour, rappelez-nous au 06 12 34 56 78."})
        self.assertIn("numéro de téléphone a été trouvé", page)
        self.assertFalse(self.application.preferences.obtenir(cle))

    def test_charger_la_meme_configuration_ne_copie_que_le_comportement(self):
        # A kind configured in detail...
        self._poster("/installation/valider?page=rappel_rdv-comportement",
                     {"nature": "rappel_rdv", "recontacter": "1",
                      "relance_mode": "delai", "relance_delai": "7",
                      "relance_max": "2", "ordre": "proximite"})
        self.application.preferences.definir(
            assistant.cle_discours("rappel_rdv"), "Un texte à moi.")
        # ...copied onto another.
        _, page = self._poster("/installation/copier",
                               {"page": "confirmation-comportement",
                                "nature": "confirmation",
                                "source": "rappel_rdv"})
        self.assertIn("Options reprises de", page)
        regle = self.application.preferences.obtenir(
            assistant.cle_comportement("confirmation"))
        self.assertEqual(regle["relance_delai"], "7")
        self.assertEqual(regle["relance_max"], "2")
        self.assertEqual(regle["ordre"], "proximite")
        # The SCRIPT, however, does not follow: it talks about something else.
        self.assertFalse(self.application.preferences.obtenir(
            assistant.cle_discours("confirmation")))
        # Without choosing a source: we say so, we copy nothing at random.
        _, page = self._poster("/installation/copier",
                               {"page": "confirmation-comportement",
                                "nature": "confirmation", "source": ""})
        self.assertIn("Choisissez la campagne", page)

    def test_recharger_les_valeurs_par_defaut(self):
        preferences = self.application.preferences
        preferences.definir(assistant.cle_comportement("confirmation"),
                            {"recontacter": False, "relance_max": "9"})
        preferences.definir(assistant.cle_discours("confirmation"), "À moi.")
        _, page = self._poster("/installation/defauts",
                               {"page": "confirmation-comportement",
                                "nature": "confirmation",
                                "quoi": "comportement"})
        self.assertIn("valeurs d&#x27;origine", page)
        self.assertEqual(
            preferences.obtenir(assistant.cle_comportement("confirmation")), {})
        self._poster("/installation/defauts",
                     {"page": "confirmation-discours",
                      "nature": "confirmation", "quoi": "discours"})
        self.assertEqual(
            preferences.obtenir(assistant.cle_discours("confirmation")), "")

    def test_charger_un_agenda_depuis_l_installeur(self):
        contenu = ("BEGIN:VCALENDAR\r\nVERSION:2.0\r\nBEGIN:VEVENT\r\n"
                   "SUMMARY:Mme Agenda Essai - Séance\r\n"
                   "DTSTART:20261201T090000\r\nDTEND:20261201T100000\r\n"
                   "END:VEVENT\r\nEND:VCALENDAR\r\n")
        frontiere = "----frontiereInstalleur"
        corps = (f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="page"\r\n\r\nimport\r\n'
                 f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="fichier"; '
                 'filename="agenda-cabinet.ics"\r\n'
                 "Content-Type: text/calendar\r\n\r\n"
                 f"{contenu}\r\n--{frontiere}--\r\n").encode("utf-8")
        requete = urllib.request.Request(
            self.racine + "/installation/agenda", data=corps,
            headers={"Content-Type":
                     f"multipart/form-data; boundary={frontiere}"})
        with urllib.request.urlopen(requete, timeout=15) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn("Agenda chargé", page)
        # THE CALENDAR NOW PRECEDES THE CAMPAIGNS (03/08/2026): after `Charger
        # votre agenda` one lands on the first campaign, no longer on the end
        # page.
        self.assertIn("Options de comportement", page)
        self.assertTrue(any(r["nom"] == "Mme Agenda Essai"
                            for r in self.application.base.tous_les_rendezvous()))

    def test_sans_fichier_on_le_dit_et_on_reste(self):
        frontiere = "----frontiereVide"
        corps = (f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="page"\r\n\r\nimport\r\n'
                 f"--{frontiere}--\r\n").encode("utf-8")
        requete = urllib.request.Request(
            self.racine + "/installation/agenda", data=corps,
            headers={"Content-Type":
                     f"multipart/form-data; boundary={frontiere}"})
        with urllib.request.urlopen(requete, timeout=15) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn("Choisissez un fichier", page)
        self.assertIn("Charger votre agenda", page)  # we did not move

    def test_reglages_essais_installeur_remet_la_variable(self):
        """Settings -> Tests -> Installer: the button resets the first-launch
        variable, and simply refreshing the home page makes the installer
        reappear.
        """
        self._poster("/installation/valider?page=identite",
                     {"entreprise": "Cabinet Val Fleuri"})
        self._poster("/installation/terminer", {})
        reglages = self._obtenir("/reglages")[1]
        # The subsection lives under `Tests`, not in a section of its own.
        self.assertIn('data-section="installeur"', reglages)
        self.assertIn("Réinitialiser l'installeur", reglages)
        self.assertIn("est <strong>posée</strong>", reglages)
        # The gesture: the variable falls back, the pages become to-do again...
        self._poster("/installation/rouvrir", {})
        preferences = self.application.preferences
        self.assertFalse(installation.terminee(preferences))
        self.assertEqual(installation.faites(preferences), set())
        # ...but the SETTING is intact: we go round again, not through the
        # values. That is what the button promises.
        self.assertEqual(preferences.obtenir(themes.CLE_ENTREPRISE),
                         "Cabinet Val Fleuri")
        # And the screen says so, rather than forcing the installer under his
        # nose.
        reglages = self._obtenir("/reglages?installeur=remis")[1]
        self.assertIn("Installeur réinitialisé", reglages)
        self.assertIn("Actualisez l'accueil", reglages)
        # Refreshing the home page is enough.
        self.assertTrue(self._ouvert(self._obtenir("/")[1]))

    def test_aucun_appel_ne_peut_partir_de_l_installeur(self):
        """A configuration screen dials no number. None of its addresses touches
        the scheduler: we check that by counting.
        """
        compte = {"appels": 0}
        vrai = self.application.planif.executer

        def compter(*args, **mots):
            compte["appels"] += 1
            return vrai(*args, **mots)

        self.application.planif.executer = compter
        try:
            for page in installation.pages(self._natures()):
                self._obtenir(f"/installation?page={page}")
                self._poster("/installation/marquer", {"page": page})
        finally:
            self.application.planif.executer = vrai
        self.assertEqual(compte["appels"], 0)


class TestCalendrierDansLesDeuxEcrans(_TestAvecServeurWeb):
    """The standard-week calendar behaves the SAME in the Settings and in the
    installer — it is the same block, served to both.

    The defect that led here (03/08/2026): in the installer, opening or closing
    a period with the fallback form returned the settings PAGE, which came and
    replaced the window. Three causes, all fixed: the installer's listener took
    every form; the routes did not know how to answer with a fragment; and the
    mouse gesture was only bound to the calendar present at load time.
    """

    def _bloc(self, page, identifiant):
        """The contents of an identified element, in a served page."""
        marque = f'id="{identifiant}"'
        self.assertIn(marque, page, f"élément « {identifiant} » absent")
        debut = page.index(marque)
        return page[debut:debut + 40000]

    def test_les_deux_ecrans_servent_le_meme_bloc(self):
        reglages = self._obtenir("/reglages")[1]
        installeur = self._obtenir("/installation?page=horaires")[1]
        for page, ou in ((reglages, "réglages"), (installeur, "installeur")):
            with self.subTest(ou=ou):
                # The zone names itself: that is what binds the mouse gesture,
                # wherever the calendar was inserted.
                self.assertIn('data-calendrier="calendrier"', page)
                self.assertIn('id="bloc-horaires"', page)
                # The period form says which element to reload.
                self.assertIn('action="/reglages/semaine" class="carte"\n'
                              '      data-fragment-cible="calendrier"', page)
                self.assertIn('class="calendrier"', page)
                # And it is a TABLE since 03/08/2026: four columns, the two
                # buttons in the last one.
                self.assertIn('class="tableau-saisie"', page)
                for entete in ("Jour", "Début", "Fin", "Période"):
                    self.assertIn(f'<th scope="col">{entete}</th>', page)
                self.assertIn('<button name="geste" value="ouvrir">Ouvrir'
                              "</button>", page)
        # ONE SINGLE DIFFERENCE, AND IT IS DELIBERATE: the average appointment
        # duration is only displayed in the Settings. The owner had its button
        # removed from the installer on 03/08/2026, and a field without a
        # button can no longer be saved — so the whole card goes, there only.
        self.assertIn('data-fragment-cible="bloc-horaires"', reglages)
        self.assertIn("Enregistrer la durée", reglages)
        self.assertNotIn("Enregistrer la durée", installeur)
        self.assertNotIn("Durée moyenne d'un rendez-vous", installeur)

    def test_le_formulaire_de_repli_rend_un_fragment(self):
        """THIS is THE defect: without a fragment, the answer was a whole page and
        the installer's window found itself replaced.
        """
        _, fragment = self._poster("/reglages/semaine", {
            "jour": "1", "debut": "09:00", "fin": "12:00",
            "geste": "ouvrir", "fragment": "1"})
        self.assertNotIn("<!DOCTYPE", fragment)
        self.assertNotIn("<nav class=\"onglets\">", fragment)
        self.assertIn('class="calendrier"', fragment)
        self.assertIn("tranche ouverte", fragment)
        # Closing the same period again: reversible, and still a fragment.
        _, fragment = self._poster("/reglages/semaine", {
            "jour": "1", "debut": "09:00", "fin": "12:00",
            "geste": "fermer", "fragment": "1"})
        self.assertNotIn("<!DOCTYPE", fragment)
        semaine = horaires.semaine(self.application.preferences)
        self.assertEqual(semaine[1], [])
        # Without `fragment`, the fallback for browsers with no JavaScript
        # keeps its behaviour: we come back to the settings page.
        statut, page = self._poster("/reglages/semaine", {
            "jour": "1", "debut": "09:00", "fin": "12:00", "geste": "ouvrir"})
        self.assertEqual(statut, 200)
        self.assertIn("<!DOCTYPE", page)

    def test_le_pas_rend_un_fragment_et_son_refus_reste_dedans(self):
        _, fragment = self._poster("/reglages/pas", {"pas": "60",
                                                     "fragment": "1"})
        self.assertNotIn("<!DOCTYPE", fragment)
        self.assertIn('class="calendrier"', fragment)
        self.assertEqual(horaires.pas_minutes(self.application.preferences), 60)
        # A refusal is displayed INSIDE the block, where the gesture happened.
        _, fragment = self._poster("/reglages/pas", {"pas": "3",
                                                     "fragment": "1"})
        self.assertNotIn("<!DOCTYPE", fragment)
        self.assertIn("Refusé", fragment)
        self.assertIn("hors des bornes", fragment)
        # And nothing was written: the previous setting holds.
        self.assertEqual(horaires.pas_minutes(self.application.preferences), 60)

    def test_les_jours_fermes_se_rechargent_seuls(self):
        _, fragment = self._poster("/reglages/jour-ferme", {
            "date": "2026-12-24", "libelle": "Réveillon", "fragment": "1"})
        self.assertNotIn("<!DOCTYPE", fragment)
        self.assertIn("24/12/2026", fragment)
        self.assertIn("Réveillon", fragment)
        _, fragment = self._poster("/reglages/jour-ferme", {
            "action": "retirer", "date": "2026-12-24", "fragment": "1"})
        self.assertNotIn("<!DOCTYPE", fragment)
        self.assertNotIn("Réveillon", fragment)
        # An unreadable date: the refusal stays in the block, nothing is added.
        _, fragment = self._poster("/reglages/jour-ferme", {
            "date": "pas-une-date", "fragment": "1"})
        self.assertIn("Refusé", fragment)
        self.assertEqual(horaires.jours_fermes(self.application.preferences), [])

    def test_l_installeur_ne_prend_que_ses_propres_formulaires(self):
        """The safety lock, read in the script: without it, the window's listener
        swallowed the settings forms and displayed their answer in place of the
        installation page.
        """
        script = serveur.SCRIPT_INSTALLATION
        self.assertIn("action.indexOf('/installation/')!==0", script)
        # And the shared machinery is served on EVERY page: it is what takes
        # the other forms, including those that arrived later through innerHTML
        # (the installer's calendar).
        for chemin in ("/", "/reglages", "/suivi"):
            with self.subTest(chemin=chemin):
                self.assertIn("data-fragment-cible",
                              self._obtenir(chemin)[1])

    def test_la_periode_interdite_donne_le_bon_exemple(self):
        """Owner's request: 12:00 -> 14:00 (the lunch break), and not another word
        about midnight — which suggested something else.
        """
        for page in (self._obtenir("/reglages")[1],
                     self._obtenir("/installation?page=appel")[1]):
            self.assertIn("ex. 12:00", page)
            self.assertIn("ex. 14:00", page)
            self.assertNotIn("traverser minuit", page)
            # And the fields stay EMPTY by default: no forbidden period is
            # imposed on anybody.
            self.assertIn('name="interdit_debut"\n           value=""', page)
            self.assertIn('name="interdit_fin"\n           value=""', page)


class TestServeurJeuEssai(_TestAvecServeurWeb):
    """The test data on screen: explicit gesture, announced, removable."""

    def test_charger_annonce_puis_retirer_en_requetes_reelles(self):
        base = self.application.base
        propres = base.compter_clients()  # the 4 demo clients
        # Nothing is loaded until something has been asked for.
        statut, page = self._obtenir("/reglages")
        self.assertEqual(statut, 200)
        self.assertIn("Charger un jeu d'essai…", page)
        self.assertNotIn("JEU D'ESSAI CHARGÉ", page)
        # The button leads to a CONFIRMATION page which announces the content.
        _, page = self._obtenir("/reglages/jeu-essai?action=charger")
        self.assertIn("Charger un jeu d'essai ?", page)
        self.assertIn(f"<strong>{len(jeu_essai.CLIENTS)} contacts</strong>",
                      page)
        self.assertIn("Arcep", page)  # where the numbers come from
        # Without confirmation, nothing is loaded.
        self.assertEqual(base.compter_clients_jeu_essai(), 0)
        _, page = self._poster("/reglages/jeu-essai",
                               {"action": "charger", "confirmer": "oui"})
        self.assertIn("Jeu d'essai chargé", page)
        self.assertEqual(base.compter_clients_jeu_essai(),
                         len(jeu_essai.CLIENTS))
        # THE BANNER ON EVERY PAGE IS GONE (21/08/2026, his request). What
        # remains — and it is enough — is the per-record test marking,
        # exercised just below.
        _, accueil = self._obtenir("/suivi")
        self.assertNotIn("JEU D'ESSAI CHARGÉ", accueil)
        # `par_page=0` = ALL: the page has been paginated since 10/08/2026 (25
        # by default) and the test data has 36 contacts. Counting the test
        # markers on the first page alone found 23.
        _, clients = self._obtenir("/clients?par_page=0")
        self.assertEqual(clients.count("🧪 jeu d'essai"),
                         len(jeu_essai.CLIENTS))
        self.assertNotIn("06 39 98 00 51", clients)  # numbers still masked
        self.assertIn("06 39 •• •• 51", clients)
        # Removal: only the test records go away, the clean data stays.
        _, page = self._poster("/reglages/jeu-essai",
                               {"action": "retirer", "confirmer": "oui"})
        self.assertIn("Jeu d'essai retiré", page)
        self.assertEqual(base.compter_clients(), propres)


class TestServeurRepriseCampagne(_TestAvecServeurWeb):
    """Step 3: a campaign built on a past campaign's results."""

    def test_filtre_deroulant_puis_seconde_campagne(self):
        base = self.application.base
        campagne_id = base.creer_campagne("Rappel d'essai", "rappel_rdv",
                                          nature="rappel_rdv")
        for rang, (nom, tel, etat) in enumerate(
                (("Mme Injoignable Une", "+33 6 39 98 50 53", "injoignable"),
                 ("M. Injoignable Deux", "+33 6 39 98 50 56", "injoignable"),
                 ("Mme Acceptée Trois", "+33 6 39 98 50 51", "accepté")),
                start=1):
            base.ajouter_contact_campagne(campagne_id, rang, nom, tel,
                                          etat=etat)
        _, page = self._poster("/assistant/nature", {"nature": "rappel_rdv"})
        b = self._brouillon(page)
        _, page = self._poster("/assistant/message", {
            "b": b, "action": "continuer", "info_entreprise": "Cabinet Essai",
            "ordre": "liste", "relance_mode": "delai", "relance_delai": "4",
            "relance_max": "0"})
        # A FILTER, hence two drop-down lists (not radio buttons), and the
        # number found is readable BEFORE adding anything.
        self.assertIn('<select class="select-option" name="campagne"', page)
        self.assertIn('<select class="select-option" name="etat"', page)
        self.assertIn("📵 Injoignables", page)
        self.assertIn("personne(s) trouvée(s) avec ce filtre", page)
        self.assertIn('"injoignable": 2', page)  # real counts, read from the database
        # Taking only the unreachable ones.
        _, page = self._poster("/assistant/importer", {
            "b": b, "mode": "campagne", "campagne": campagne_id,
            "etat": "injoignable"})
        self.assertIn("2 contact(s) ajouté(s)", page)
        self.assertIn("Mme Injoignable Une", page)
        self.assertNotIn("Mme Acceptée Trois", page)
        self.assertNotIn("+33 6 39 98 50 53", page)  # still masked
        # An empty state says so, instead of pretending.
        _, page = self._poster("/assistant/importer", {
            "b": b, "mode": "campagne", "campagne": campagne_id,
            "etat": "à rappeler par un humain"})
        self.assertIn("Aucun contact de cette campagne n&#x27;est dans cet "
                      "état", page)
        # The chosen filter is redisplayed INSIDE its fields (nothing to
        # re-choose).
        self.assertIn('<option value="à rappeler par un humain" selected>', page)
        self.assertIn("0 personne(s) trouvée(s) avec ce filtre", page)
        # The second campaign really is created from the first.
        self._poster("/assistant/liste", {
            "b": b, "action": "enregistrer",
            "c_rdv_existant_1": DEMAIN, "c_motif_1": "Séance",
            "c_rdv_existant_2": DEMAIN, "c_motif_2": "Séance"})
        _, page = self._poster("/assistant/liste", {"b": b, "action": "valider"})
        self.assertIn("prête", page)
        self.assertEqual(len(base.lister_campagnes()), 2)
        nouvelle = base.lister_campagnes()[0]
        self.assertEqual(nouvelle["contacts"], 2)


class TestHorairesOuverture(unittest.TestCase):
    """Standard week, closed days, consecutive slices and computed slots.

    A reference Monday is chosen far in the future (2026-09-07, a Monday) so
    that the tests never depend on the day they are run.
    """

    LUNDI = datetime.date(2026, 9, 7)

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.preferences = generation.Preferences(None)
        self.client_id = self.base.ajouter_client("Mme Horaire Exemple",
                                                  "+33 6 39 98 50 61")
        # Standard week: Monday 9am -> 12pm, with a 15-minute step.
        self.preferences.definir(horaires.CLE_PAS, 15)
        horaires.basculer_periode(self.preferences, 0, 9 * 60, 12 * 60,
                                  "ouvrir")

    def _matin(self, heure, minute=0, jours=0):
        return (datetime.datetime.combine(self.LUNDI, datetime.time())
                + datetime.timedelta(days=jours, hours=heure, minutes=minute))

    def test_glisser_relache_ouvre_puis_referme_la_meme_periode(self):
        """The gesture is a TOGGLE: repeated on an open period, it closes it.
        """
        semaine = horaires.semaine(self.preferences)
        self.assertEqual(semaine[0], [(540, 720)])       # lundi 9h→12h
        self.assertEqual(semaine[1], [])                 # mardi intact
        # The same gesture on a half-hour that is ALREADY open: it closes.
        ouverte = horaires.basculer_periode(self.preferences, 0, 600, 630,
                                            "basculer")
        self.assertFalse(ouverte)
        self.assertEqual(horaires.semaine(self.preferences)[0],
                         [(540, 600), (630, 720)])
        # And the same gesture reopens the gap (no data lost along the way).
        self.assertTrue(horaires.basculer_periode(self.preferences, 0, 600,
                                                  630, "basculer"))
        self.assertEqual(horaires.semaine(self.preferences)[0], [(540, 720)])

    def test_periode_vide_ou_jour_inconnu_refuses_avec_le_format_attendu(self):
        with self.assertRaises(ValueError) as refus:
            horaires.basculer_periode(self.preferences, 9, 540, 600, "ouvrir")
        self.assertIn("0 = lundi", str(refus.exception))
        with self.assertRaises(ValueError):
            horaires.minutes_depuis_hhmm("9h00")   # format non attendu

    def test_creneaux_libres_retire_ce_qui_est_deja_pris(self):
        """Open minus busy: an appointment eats EXACTLY its slices."""
        self.base.ajouter_rendezvous(self.client_id,
                                     self._matin(9, 30).isoformat(timespec="minutes"),
                                     "Séance", duree_tranches=2)
        libres = horaires.creneaux_libres(self.base, self.preferences,
                                          depuis=self._matin(0), jours=0)
        heures = [creneau[11:] for creneau in libres]
        self.assertIn("09:00", heures)
        self.assertIn("09:15", heures)
        self.assertNotIn("09:30", heures)  # taken (slice 1 of 2)
        self.assertNotIn("09:45", heures)  # taken (slice 2 of 2)
        self.assertIn("10:00", heures)
        self.assertEqual(len(libres), 10)  # 12 slices minus 2 busy

    def test_annuler_un_rendezvous_de_deux_tranches_en_libere_deux(self):
        rdv_id = self.base.ajouter_rendezvous(
            self.client_id, self._matin(10).isoformat(timespec="minutes"),
            "Séance de 30 minutes", duree_tranches=2)
        avant = horaires.creneaux_libres(self.base, self.preferences,
                                         depuis=self._matin(0), jours=0)
        self.base.mettre_a_jour_rendezvous(rdv_id, statut="annulé")
        apres = horaires.creneaux_libres(self.base, self.preferences,
                                         depuis=self._matin(0), jours=0)
        self.assertEqual(len(apres) - len(avant), 2)
        rendues = sorted(set(apres) - set(avant))
        self.assertEqual([c[11:] for c in rendues], ["10:00", "10:15"])

    def test_creneaux_d_une_demi_heure_exigent_deux_tranches_consecutives(self):
        """A 30-minute client is only offered RUNS of 2."""
        # Only a one-slice gap is left, between 10:15 and 10:30.
        self.base.ajouter_rendezvous(self.client_id,
                                     self._matin(9).isoformat(timespec="minutes"),
                                     "Séance", duree_tranches=5)   # 9h→10h15
        self.base.ajouter_rendezvous(self.client_id,
                                     self._matin(10, 30).isoformat(timespec="minutes"),
                                     "Séance", duree_tranches=6)   # 10h30→12h
        seules = horaires.creneaux_libres(self.base, self.preferences,
                                          tranches=1, depuis=self._matin(0),
                                          jours=0)
        self.assertEqual([c[11:] for c in seules], ["10:15"])
        doubles = horaires.creneaux_libres(self.base, self.preferences,
                                           tranches=2, depuis=self._matin(0),
                                           jours=0)
        self.assertEqual(doubles, [])  # no run of 2: nothing is offered

    def test_jour_ferme_supprime_toutes_ses_tranches(self):
        libres = horaires.creneaux_libres(self.base, self.preferences,
                                          depuis=self._matin(0), jours=0)
        self.assertEqual(len(libres), 12)
        horaires.ajouter_jour_ferme(self.preferences, self.LUNDI.isoformat(),
                                    "vacances d'été")
        self.assertEqual(horaires.est_ferme(self.preferences, self.LUNDI),
                         "vacances d'été")
        self.assertEqual(horaires.creneaux_libres(self.base, self.preferences,
                                                  depuis=self._matin(0),
                                                  jours=0), [])
        # Removal: the day becomes offerable again (nothing is lost).
        self.assertTrue(horaires.retirer_jour_ferme(self.preferences,
                                                    self.LUNDI.isoformat()))
        self.assertEqual(len(horaires.creneaux_libres(
            self.base, self.preferences, depuis=self._matin(0), jours=0)), 12)

    def test_refus_de_deplacer_un_client_trop_long_dit_ce_qui_manque(self):
        """The owner's rule, to the letter — and the refusal is explicit."""
        # 9am->11:45am busy: only ONE free slice is left, 11:45.
        self.base.ajouter_rendezvous(self.client_id,
                                     self._matin(9).isoformat(timespec="minutes"),
                                     "Long", duree_tranches=11)
        rdv_id = self.base.ajouter_rendezvous(
            self.client_id, self._matin(15).isoformat(timespec="minutes"),
            "Demi-heure", duree_tranches=2)
        rdv = self.base.obtenir_rendezvous(rdv_id)
        cible = self._matin(11, 45).isoformat(timespec="minutes")
        refus = horaires.refus_deplacement(self.base, self.preferences, rdv,
                                           cible)
        self.assertIsNotNone(refus)
        self.assertIn("2 tranches de 15 min (30 minutes)", refus)
        self.assertIn("1 tranche de 15 min", refus)
        self.assertIn("il en manque 1", refus)
        # A slot that is long enough, however, is accepted (no refusal).
        horaires.basculer_periode(self.preferences, 0, 14 * 60, 15 * 60,
                                  "ouvrir")
        self.assertIsNone(horaires.refus_deplacement(
            self.base, self.preferences, rdv, self._matin(14).isoformat(
                timespec="minutes")))

    def test_refus_de_deplacer_vers_un_jour_ferme(self):
        rdv_id = self.base.ajouter_rendezvous(
            self.client_id, self._matin(9).isoformat(timespec="minutes"),
            "Séance")
        horaires.ajouter_jour_ferme(self.preferences, self.LUNDI.isoformat(),
                                    "Assomption")
        refus = horaires.refus_deplacement(
            self.base, self.preferences, self.base.obtenir_rendezvous(rdv_id),
            self._matin(9, 30).isoformat(timespec="minutes"))
        self.assertIn("déclaré FERMÉ", refus)
        self.assertIn("Assomption", refus)

    def test_creneaux_ajoutes_a_la_main_completent_le_calcul(self):
        """The special case typed by hand is ADDED, it replaces nothing."""
        exception = self._matin(9, 0, jours=5).isoformat(timespec="minutes")
        self.preferences.definir(themes.CLE_CRENEAUX, [exception])
        proposes = horaires.creneaux_proposables(self.base, self.preferences,
                                                 depuis=self._matin(0),
                                                 jours=0)
        origines = {entree["horaire"]: entree["origine"] for entree in proposes}
        self.assertEqual(origines.get(exception), "à la main")
        self.assertEqual(
            origines.get(self._matin(9).isoformat(timespec="minutes")),
            "calculé")

    def test_jours_feries_francais_calcules_paques_comprise(self):
        """Easter by computation (no external library)."""
        self.assertEqual(horaires.paques(2026), datetime.date(2026, 4, 5))
        self.assertEqual(horaires.paques(2027), datetime.date(2027, 3, 28))
        feries2026 = dict(horaires.feries(2026))
        self.assertEqual(feries2026[datetime.date(2026, 4, 6)],
                         "Lundi de Pâques")
        self.assertEqual(feries2026[datetime.date(2026, 5, 14)], "Ascension")
        self.assertEqual(feries2026[datetime.date(2026, 5, 25)],
                         "Lundi de Pentecôte")
        self.assertEqual(len(feries2026), 11)
        # OFFERED, never added: the list of closed days stays empty.
        proposition = horaires.feries_a_proposer(
            self.preferences, depuis=datetime.date(2026, 7, 29))
        self.assertTrue(proposition)
        self.assertEqual(horaires.jours_fermes(self.preferences), [])


class TestMigrationDureeRendezvous(unittest.TestCase):
    """ADDITIVE migration: an appointment predating the duration is worth ONE
    slice.
    """

    def test_ancienne_base_sans_duree_vaut_une_tranche(self):
        dossier = tempfile.mkdtemp(prefix="ringback-duree-")
        self.addCleanup(shutil.rmtree, dossier, ignore_errors=True)
        chemin = os.path.join(dossier, "ringback.db")
        import sqlite3
        brute = sqlite3.connect(chemin)
        brute.executescript("""
            CREATE TABLE clients (id INTEGER PRIMARY KEY AUTOINCREMENT,
                                  nom TEXT NOT NULL, telephone TEXT NOT NULL);
            CREATE TABLE rendezvous (id INTEGER PRIMARY KEY AUTOINCREMENT,
                                     client_id INTEGER NOT NULL,
                                     horaire TEXT NOT NULL, motif TEXT NOT NULL,
                                     statut TEXT NOT NULL DEFAULT 'prévu');
            INSERT INTO clients (nom, telephone)
                VALUES ('Mme Avant Durée', '+33 6 39 98 50 62');
            INSERT INTO rendezvous (client_id, horaire, motif, statut)
                VALUES (1, '2026-09-07T09:00', 'Séance ancienne', 'prévu');
        """)
        brute.commit()
        brute.close()
        base = db.Base(chemin)  # the additive migration plays out here
        self.addCleanup(base.fermer)
        rdv = base.rendezvous_a_venir()[0]
        self.assertEqual(rdv["motif"], "Séance ancienne")  # data intact
        self.assertEqual(rdv["duree_tranches"], 1)  # one slice
        occupants = base.rendezvous_occupants("2026-09-07T00:00",
                                              "2026-09-08T00:00")
        self.assertEqual([o["duree_tranches"] for o in occupants], [1])


class TestServeurHoraires(_TestAvecServeurWeb):
    """The opening hours seen from the screen: calendar, fallback without
    JavaScript, closed days, computed slots, refused move.
    """

    LUNDI = datetime.date(2026, 9, 7)

    def test_calendrier_et_repli_sans_javascript(self):
        _, page = self._obtenir("/reglages")
        self.assertIn("Horaires d'ouverture", page)
        self.assertIn('data-jour="0" data-min="540"', page)   # lundi 9h00
        # The fallback is ALWAYS visible (not only without JavaScript).
        self.assertIn("Sans glisser-relâché", page)
        self.assertIn('name="geste" value="ouvrir"', page)
        # Fallback: open Tuesday 9am->12pm through the form.
        self._poster("/reglages/semaine", {"jour": 1, "debut": "09:00",
                                           "fin": "12:00", "geste": "ouvrir"})
        semaine = horaires.semaine(self.application.preferences)
        self.assertEqual(semaine[1], [(540, 720)])
        # Drag and release: same route, answer as a FRAGMENT (the whole page is
        # never reloaded).
        _, fragment = self._poster("/reglages/semaine",
                                   {"jour": 1, "debut_min": 600,
                                    "fin_min": 630, "geste": "basculer",
                                    "fragment": 1})
        self.assertNotIn("<!DOCTYPE", fragment)
        self.assertIn('title="mardi 10h00 — fermé"', fragment)
        self.assertEqual(horaires.semaine(self.application.preferences)[1],
                         [(540, 600), (630, 720)])

    def test_pas_refuse_dit_le_format_attendu_et_ne_change_rien(self):
        _, page = self._poster("/reglages/pas", {"pas": "un quart d'heure"})
        self.assertIn("Réglage refusé", page)
        self.assertIn("nombre entier de minutes", page)
        self.assertEqual(horaires.pas_minutes(self.application.preferences), 15)
        self._poster("/reglages/pas", {"pas": "30"})
        self.assertEqual(horaires.pas_minutes(self.application.preferences), 30)

    def test_jour_ferme_declare_puis_retire_depuis_l_ecran(self):
        self._poster("/reglages/jour-ferme", {"date": "15/08/2026",
                                              "libelle": "Assomption"})
        _, page = self._obtenir("/reglages")
        self.assertIn("samedi 15/08/2026", page)
        self.assertIn("Assomption", page)
        self._poster("/reglages/jour-ferme", {"action": "retirer",
                                              "date": "2026-08-15"})
        self.assertEqual(horaires.jours_fermes(self.application.preferences), [])
        # Public holidays are OFFERED, never added automatically.
        _, page = self._obtenir("/reglages")
        self.assertIn("Ajouter aux jours fermés", page)
        self.assertIn("ne les ajoute jamais tout seul", page)

    def test_un_creneau_passe_dit_son_etat_en_mots(self):
        """Colour never carries the meaning alone — that is what allows it to be
        unified.

        The three calendars have shown the SAME green since 03/08/2026, without
        dimming. Removing the dimming of past slots takes away no information —
        but only because the state is written elsewhere. This test is the
        counterpart of that unification: if the tooltip or the screen-reader
        text disappeared, colour would carry the meaning alone.

        Two whole weeks, one behind us and one ahead: no dependency on what
        time it is when the test runs.
        """
        # This class starts WITHOUT opening hours: without opening some, there
        # would be no free cell and the test would run on nothing.
        for jour in range(5):
            horaires.basculer_periode(self.application.preferences,
                                      jour, 9 * 60, 12 * 60, "ouvrir")
        passee = datetime.date.today() - datetime.timedelta(days=28)
        future = datetime.date.today() + datetime.timedelta(days=28)

        _, page = self._obtenir(f"/suivi?date={passee:%d/%m/%Y}")
        cases = re.findall(r'<td class="libre revolue"[^>]*>.*?</td>', page)
        self.assertTrue(cases, "aucune case passée : l'essai ne prouve rien")
        for case in cases:
            with self.subTest(case=case[:90]):
                # The state, in words, TWICE: for the mouse and for the voice.
                self.assertIn("libre, déjà passé", case)
                self.assertIn('<span class="lecture-seule">libre, déjà passé',
                              case)
                # And no click: no data-modale, hence no outline.
                self.assertNotIn("data-modale", case)

        _, page = self._obtenir(f"/suivi?date={future:%d/%m/%Y}")
        cases = re.findall(r'<td class="libre"[^>]*>.*?</td>', page)
        self.assertTrue(cases, "aucune case ouvrable : l'essai ne prouve rien")
        for case in cases:
            with self.subTest(case=case[:90]):
                self.assertIn("data-modale", case)
                self.assertNotIn("déjà passé", case)

    def test_creneaux_calcules_puis_refus_de_deplacement_a_l_ecran(self):
        base, preferences = self.application.base, self.application.preferences
        horaires.basculer_periode(preferences, 0, 9 * 60, 10 * 60, "ouvrir")
        lundi = datetime.datetime.combine(self.LUNDI, datetime.time(9, 0))
        client_id = base.ajouter_client("Mme Créneau Exemple",
                                        "+33 6 39 98 50 63")
        # 9:00 -> 9:45 busy: only 9:45 is left (a single slice).
        base.ajouter_rendezvous(client_id, lundi.isoformat(timespec="minutes"),
                                "Long", duree_tranches=3)
        rdv_id = base.ajouter_rendezvous(
            client_id, (lundi + datetime.timedelta(days=7)).isoformat(
                timespec="minutes"), "Demi-heure", duree_tranches=2)
        _, fragment = self._obtenir("/reglages/creneaux")
        self.assertNotIn("<!DOCTYPE", fragment)
        self.assertIn("calculé", fragment)
        # Move refused, with what is missing, without losing the record.
        _, page = self._poster("/rendezvous/deplacer", {
            "rdv": rdv_id,
            "cible": (lundi + datetime.timedelta(minutes=45)).isoformat(
                timespec="minutes")})
        self.assertIn("Action refusée", page)
        self.assertIn("il en manque 1", page)
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["horaire"],
                         (lundi + datetime.timedelta(days=7)).isoformat(
                             timespec="minutes"))  # nothing moved

    def test_duree_et_annulation_depuis_la_fiche(self):
        base = self.application.base
        client_id = base.ajouter_client("M. Durée Exemple", "+33 6 39 98 50 64")
        # A DELIBERATELY DISTANT date, and not TOMORROW: the cancellation rule
        # depends on the replacement threshold (12 h by default), and `tomorrow
        # 10am` falls BELOW that threshold as soon as the test runs after 10pm
        # — the test then failed because of the time of day, not because of
        # what it checks. The `less than 12 h away` case has its own dedicated
        # tests (horaires.decision_annulation).
        loin = (datetime.datetime.now() + datetime.timedelta(days=3)).replace(
            hour=10, minute=0, second=0, microsecond=0).isoformat(
                timespec="minutes")
        rdv_id = base.ajouter_rendezvous(client_id, loin, "Séance")
        _, page = self._poster("/rendezvous/duree", {"rdv": rdv_id,
                                                     "duree": "22"})
        self.assertIn("Durée refusée", page)
        self.assertIn("multiple de 15", page)
        self.assertIn('value="22"', page)  # the refused input comes back
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["duree_tranches"], 1)
        self._poster("/rendezvous/duree", {"rdv": rdv_id, "duree": "30"})
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["duree_tranches"], 2)
        _, page = self._obtenir(f"/rendezvous?id={rdv_id}")
        self.assertIn("2 tranches de 15 min (30 minutes)", page)
        # The `Cancel` gesture on a FUTURE appointment DELETES it (owner's
        # rule): it no longer exists and its slot becomes free again. `annule`
        # applies only to past dates — the test right after this one checks
        # that.
        self._poster("/rendezvous/annuler", {"rdv": rdv_id})
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"],
                         db.STATUT_SUPPRIME)

    def test_annuler_un_rendezvous_passe_le_laisse_annule(self):
        """The HISTORY status: behind us, `annule` stays `annule`."""
        base = self.application.base
        client_id = base.ajouter_client("Mme Passée Fiche", "+33 6 39 98 50 65")
        rdv_id = base.ajouter_rendezvous(client_id, HIER, "Séance")
        self._poster("/rendezvous/annuler", {"rdv": rdv_id})
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"], "annulé")


class TestCampagneCreneauxCalcules(unittest.TestCase):
    """Campaigns offer the slots that are REALLY free, and of the right length for
    the client concerned.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.preferences = generation.Preferences(None)
        horaires.basculer_periode(self.preferences, 0, 9 * 60, 10 * 60,
                                  "ouvrir")
        # NEXT Monday (never today): the call mission computes its slots `from
        # now on`, so the test must live in the future, whatever day it is run.
        aujourdhui = datetime.date.today()
        self.lundi = aujourdhui + datetime.timedelta(
            days=(7 - aujourdhui.weekday()) % 7 or 7)
        self.depuis = datetime.datetime.combine(self.lundi, datetime.time())
        self.jour = f"{self.lundi:%d/%m/%Y}"
        self.client_id = self.base.ajouter_client("Mme Longue Séance",
                                                  "+33 6 39 98 50 65")

    def test_mission_adaptee_a_la_duree_du_contact(self):
        # 9h15 pris : restent 9h00 seul, puis 9h30-9h45 (une suite de 2).
        self.base.ajouter_rendezvous(
            self.client_id,
            (self.depuis + datetime.timedelta(hours=9, minutes=15)).isoformat(
                timespec="minutes"), "Séance")
        rdv_id = self.base.ajouter_rendezvous(
            self.client_id,
            (self.depuis + datetime.timedelta(days=14, hours=9)).isoformat(
                timespec="minutes"), "Demi-heure", duree_tranches=2)
        courts = horaires.creneaux_lisibles(self.base, self.preferences,
                                            tranches=1, depuis=self.depuis)
        longs = horaires.creneaux_lisibles(self.base, self.preferences,
                                           tranches=2, depuis=self.depuis)
        # WE COMPARE ITEMS, NOT SUBSTRINGS. `le lundi 31 aout 2026 a 9 heures`
        # is a PREFIX of `... a 9 heures 30`: an `assertNotIn` on the whole
        # text would be wrong as soon as the half hour is in the list. It is
        # the same trap as the one that spoiled the recomputation of the call's
        # moment — here it makes a test LIE instead of spoiling a text.
        neuf = date_parlee_de(f"{self.lundi:%Y-%m-%d}T09:00")
        neuf_trente = date_parlee_de(f"{self.lundi:%Y-%m-%d}T09:30")
        self.assertIn(neuf, courts.split(", "))  # one slice is enough
        self.assertNotIn(neuf, longs.split(", "))   # 30 min : trop court
        self.assertIn(neuf_trente, longs.split(", "))
        # The campaign: COMPUTED list (hence marked `auto`), contact whose
        # appointment lasts 30 minutes -> the mission is readjusted.
        campagne_id = self.base.creer_campagne(
            "Essai", theme="deplacement", nature="deplacement",
            mission=f"Je peux vous proposer : {courts}.",
            configuration=json.dumps({"infos": {"creneaux_remplacement": courts},
                                      "infos_auto": {"creneaux_remplacement":
                                                     courts}},
                                     ensure_ascii=False))
        contact_id = self.base.ajouter_contact_campagne(
            campagne_id, 1, "Mme Longue Séance", "+33 6 39 98 50 65",
            rendezvous_id=rdv_id)
        contact = self.base.obtenir_contact_campagne(contact_id)
        configuration = assistant.configuration_campagne(
            self.base.obtenir_campagne(campagne_id))
        adaptee = assistant.creneaux_adaptes_au_contact(
            self.base, self.preferences, configuration, contact,
            f"Je peux vous proposer : {courts}.")
        # BY ITEMS, not by substrings: `a 9 heures` is a PREFIX of `a 9 heures
        # 30`.
        proposees = adaptee.split(" : ")[1].rstrip(".").split(", ")
        self.assertIn(neuf_trente, proposees)
        # This Monday's single-slice gap disappears from the offer.
        self.assertNotIn(neuf, proposees)
        # List RETYPED by hand (not `auto`): never touched.
        configuration["infos_auto"] = {}
        intacte = assistant.creneaux_adaptes_au_contact(
            self.base, self.preferences, configuration, contact,
            "Je peux vous proposer : mardi matin.")
        self.assertEqual(intacte, "Je peux vous proposer : mardi matin.")


# --------------------------------------------------------------------------
# THE SCHEDULE (Appointments) and THE STATES WORKSTATION (Clients). Everything
# is exercised for real — in-memory database, never donnees/ringback.db.
# --------------------------------------------------------------------------
def _date_jour_lisible_test(jour):
    """`lundi 07/09/2026` — as the screen writes it, for the assertions."""
    return f"{horaires.JOURS[jour.weekday()]} {jour:%d/%m/%Y}"



class TestGrilleSemaine(unittest.TestCase):
    """The schedule's grid: one tile per appointment, never one per slice."""

    LUNDI = datetime.date(2026, 9, 7)

    def setUp(self):
        self.base = db.Base(":memory:")
        self.preferences = generation.Preferences(None)
        for jour in range(5):
            horaires.basculer_periode(self.preferences, jour, 9 * 60,
                                      12 * 60, "ouvrir")

    def _poser(self, nom, jour, heure, minute, tranches, statut="prévu"):
        client_id = self.base.obtenir_ou_creer_client(nom, "+33 6 39 98 50 70")
        quand = datetime.datetime.combine(
            self.LUNDI + datetime.timedelta(days=jour),
            datetime.time(heure, minute))
        return self.base.ajouter_rendezvous(
            client_id, quand.isoformat(timespec="minutes"), "Séance",
            statut=statut, duree_tranches=tranches)

    def test_trois_tranches_consecutives_font_UNE_tuile_de_hauteur_trois(self):
        self._poser("Mme Longue", 0, 9, 0, 3)
        grille = horaires.grille_semaine(self.base, self.preferences, self.LUNDI)
        lundi = grille["jours"][0]["cellules"]
        tuiles = [c for c in lundi if c["type"] == "tuile"]
        couvertes = [c for c in lundi if c["type"] == "couverte"]
        self.assertEqual(len(tuiles), 1)  # ONE tile, not three
        self.assertEqual(tuiles[0]["hauteur"], 3)   # de hauteur 3
        self.assertEqual(len(couvertes), 2)  # two slices swallowed
        self.assertFalse(tuiles[0]["tronquee"])
        # And the slices it occupies are no longer `free`.
        libres = [c for c in lundi if c["type"] == "libre"]
        self.assertEqual(len(libres), 12 - 3)       # 9h→12h = 12 tranches

    def test_seuls_les_rendezvous_qui_occupent_font_une_tuile(self):
        self._poser("Mme Annulée", 0, 9, 0, 2, statut="annulé")
        self._poser("M. Déplacé", 0, 10, 0, 2, statut="déplacé")
        self._poser("Mme Confirmée", 0, 11, 0, 2, statut="confirmé")
        grille = horaires.grille_semaine(self.base, self.preferences, self.LUNDI)
        tuiles = [c for c in grille["jours"][0]["cellules"] if c["type"] == "tuile"]
        self.assertEqual([t["rdv"]["nom"] for t in tuiles], ["Mme Confirmée"])

    def test_l_amplitude_s_elargit_pour_un_rendezvous_hors_horaires(self):
        self._poser("M. Très Tôt", 0, 6, 30, 2)
        grille = horaires.grille_semaine(self.base, self.preferences, self.LUNDI)
        self.assertEqual(grille["minutes"][0], 6 * 60 + 30)  # nothing is hidden
        tuiles = [c for c in grille["jours"][0]["cellules"] if c["type"] == "tuile"]
        self.assertEqual(len(tuiles), 1)

    def test_un_jour_ferme_n_a_aucune_tranche_libre(self):
        horaires.ajouter_jour_ferme(self.preferences,
                                    (self.LUNDI + datetime.timedelta(days=1)
                                     ).isoformat(), "Formation")
        grille = horaires.grille_semaine(self.base, self.preferences, self.LUNDI)
        mardi = grille["jours"][1]
        self.assertEqual(mardi["ferme"], "Formation")
        self.assertEqual([c for c in mardi["cellules"] if c["type"] == "libre"], [])

    def test_deux_rendezvous_superposes_ne_s_ecrasent_pas(self):
        self._poser("Mme Première", 0, 9, 0, 2)
        self._poser("M. Second", 0, 9, 0, 2)
        grille = horaires.grille_semaine(self.base, self.preferences, self.LUNDI)
        tuiles = [c for c in grille["jours"][0]["cellules"] if c["type"] == "tuile"]
        self.assertEqual(len(tuiles), 1)
        self.assertEqual(len(grille["superposes"]), 1)  # reported, never hidden

    def test_suites_libres_datees_donnent_les_trous_l_un_apres_l_autre(self):
        self._poser("Mme Milieu", 0, 10, 0, 2)  # cuts Monday in two
        depuis = datetime.datetime.combine(self.LUNDI, datetime.time(0, 0))
        trous = horaires.suites_libres_datees(self.base, self.preferences,
                                              depuis=depuis, jours=0)
        self.assertEqual([(t["debut"].strftime("%H:%M"), t["tranches"])
                          for t in trous],
                         [("09:00", 4), ("10:30", 6)])


class TestServeurPlanning(_TestAvecServeurWeb):
    """The schedule on screen: merged tiles, modal, navigation."""

    LUNDI = datetime.date(2026, 9, 7)

    def setUp(self):
        super().setUp()
        preferences = self.application.preferences
        for jour in range(5):
            horaires.basculer_periode(preferences, jour, 9 * 60, 12 * 60,
                                      "ouvrir")

    def _poser(self, nom, jour, heure, minute, tranches, statut="prévu"):
        base = self.application.base
        client_id = base.obtenir_ou_creer_client(nom, "+33 6 39 98 50 71")
        quand = datetime.datetime.combine(
            self.LUNDI + datetime.timedelta(days=jour),
            datetime.time(heure, minute))
        return base.ajouter_rendezvous(client_id,
                                       quand.isoformat(timespec="minutes"),
                                       "Séance longue", statut=statut,
                                       duree_tranches=tranches)

    def _semaine(self, **extra):
        parametres = {"annee": 2026, "semaine": 37}
        parametres.update(extra)
        return self._obtenir("/suivi/planning?"
                             + urllib.parse.urlencode(parametres))

    def test_le_planning_est_sur_la_page_rendez_vous(self):
        _, page = self._obtenir("/suivi")
        self.assertIn('id="planning"', page)
        self.assertIn("Prochain créneau disponible", page)
        # The green of the free slices is EXACTLY the settings calendar's: the
        # same CSS variable, not a copied colour. It changed name on 02/08/2026
        # (--creneau-libre, identical in both themes); what matters is still
        # that there be only ONE.
        self.assertIn("table.planning td.libre { background: var(--creneau-libre)",
                      serveur.STYLE)
        self.assertIn("table.calendrier td.tranche.ouverte { background: "
                      "var(--creneau-libre)", serveur.STYLE)

    def test_une_tuile_unique_pour_un_rendezvous_de_quatre_tranches(self):
        self._poser("Mme Quatre Tranches", 0, 9, 0, 4)
        _, fragment = self._semaine()
        self.assertNotIn("<!DOCTYPE", fragment)  # a FRAGMENT
        self.assertEqual(fragment.count('class="tuile" rowspan="4"'), 1)
        self.assertEqual(fragment.count("Mme Quatre Tranches"), 2)  # tuile + bulle
        # No tile of height 1: the other three slices are swallowed.
        self.assertNotIn('class="tuile" rowspan="1"', fragment)

    def test_la_modale_donne_le_detail_avec_le_numero_MASQUE(self):
        rdv_id = self._poser("Mme Modale Exemple", 0, 9, 0, 2)
        _, modale = self._obtenir(f"/suivi/detail?rdv={rdv_id}")
        self.assertNotIn("<!DOCTYPE", modale)
        self.assertIn("Mme Modale Exemple", modale)
        self.assertIn("Séance longue", modale)
        self.assertIn("lundi 07/09/2026", modale)
        self.assertIn("de 09h00 à 09h30", modale)
        self.assertIn("2 tranches de 15 min (30 minutes)", modale)
        self.assertIn("+33 6 •• •• •• 71", modale)  # masked, as everywhere
        self.assertNotIn("+33 6 39 98 50 71", modale)
        self.assertIn("modale-fermer", modale)
        # A free slot has its own modal, also computed.
        _, creneau = self._obtenir("/suivi/detail?creneau=2026-09-07T10:00")
        self.assertIn("Créneau libre", creneau)
        self.assertIn("lundi 07/09/2026", creneau)
        # R15 CLOSED: campaign creation is REAL, no longer `coming soon`.
        self.assertNotIn("à venir", creneau)
        self.assertIn('action="/suivi/creneau/campagne"', creneau)
        self.assertIn('value="2026-09-07T10:00"', creneau)

    def test_naviguer_autrement_que_par_la_date_REINITIALISE_le_champ_date(self):
        # 1. The date field leads to its week AND stays filled in.
        _, page = self._semaine(aller="date", date="2026-09-15")
        self.assertIn('name="date" value="2026-09-15"', page)
        self.assertIn("Semaine du 14/09/2026", page)
        # 2. The `next` arrow empties the date field — owner's rule.
        _, page = self._semaine(aller="suivant", semaine=38, date="2026-09-15")
        self.assertIn('name="date" value=""', page)
        self.assertIn("Semaine du 21/09/2026", page)
        # 3. And so does the `previous` arrow.
        _, page = self._semaine(aller="precedent", semaine=38,
                                date="2026-09-15")
        self.assertIn('name="date" value=""', page)
        self.assertIn("Semaine du 07/09/2026", page)
        # 4. So does the week selector.
        _, page = self._semaine(aller="semaine", semaine=40,
                                date="2026-09-15")
        self.assertIn('name="date" value=""', page)
        self.assertIn("Semaine du 28/09/2026", page)

    def test_date_illisible_refusee_sans_perdre_la_saisie(self):
        _, page = self._semaine(aller="date", date="bientôt")
        self.assertIn("Date refusée", page)
        self.assertIn("Date illisible", page)
        self.assertIn('name="date" value="bientôt"', page)   # jamais perdue

    def test_prochain_creneau_avance_de_trou_en_trou_puis_se_remet_a_zero(self):
        base = self.application.base
        # A single open day, cut in two by an appointment.
        for jour in range(5):
            horaires.basculer_periode(self.application.preferences, jour,
                                      9 * 60, 12 * 60, "fermer")
        futur = datetime.date.today() + datetime.timedelta(days=2)
        horaires.basculer_periode(self.application.preferences,
                                  futur.weekday(), 9 * 60, 10 * 60, "ouvrir")
        client_id = base.obtenir_ou_creer_client("M. Milieu", "+33 6 39 98 50 72")
        base.ajouter_rendezvous(
            client_id,
            datetime.datetime.combine(futur, datetime.time(9, 15)).isoformat(
                timespec="minutes"), "Séance", duree_tranches=1)
        # First click: the nearest gap (9:00, one slice).
        _, page = self._obtenir("/suivi/planning?aller=prochain&rang=0")
        self.assertIn("Prochain créneau disponible n° 1", page)
        self.assertIn("à 9h00", page)
        self.assertIn('name="rang" value="1"', page)
        self.assertIn("place libre : 1 tranche de 15 min", page)
        self.assertEqual(page.count('<td class="tuile"'), 1)
        # Second click: the gap AFTER it (9:30, two slices).
        _, page = self._obtenir("/suivi/planning?aller=prochain&rang=1")
        self.assertIn("Prochain créneau disponible n° 2", page)
        self.assertIn("à 9h30", page)
        self.assertIn('name="rang" value="2"', page)
        # Third click: the gap after that one — the NEXT WEEK.
        _, page = self._obtenir("/suivi/planning?aller=prochain&rang=2")
        self.assertIn("Prochain créneau disponible n° 3", page)
        self.assertIn(_date_jour_lisible_test(futur + datetime.timedelta(days=7)),
                      page)
        self.assertIn('name="rang" value="3"', page)
        # At the end of the list, the position starts again from zero (and says
        # so).
        _, page = self._obtenir("/suivi/planning?aller=prochain&rang=999")
        self.assertIn("Plus de créneau au-delà du n° 999", page)
        self.assertIn('name="rang" value="0"', page)
        # Navigating another way also resets the position to zero.
        _, page = self._obtenir("/suivi/planning?aller=suivant&rang=2")
        self.assertIn('name="rang" value="0"', page)

    def test_sans_horaires_ouverts_le_prochain_creneau_le_dit(self):
        for jour in range(5):
            horaires.basculer_periode(self.application.preferences, jour,
                                      9 * 60, 12 * 60, "fermer")
        _, page = self._obtenir("/suivi/planning?aller=prochain&rang=0")
        self.assertIn("Aucun créneau libre", page)
        self.assertIn('name="rang" value="0"', page)


class TestEtatsClients(unittest.TestCase):
    """A client's two states, and the exact definition of `not handled`."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.preferences = generation.Preferences(None)

    def _client(self, nom, telephone="+33 6 39 98 50 80"):
        return self.base.ajouter_client(nom, telephone)

    def test_un_rendezvous_long_compte_pour_UN_rendezvous(self):
        client_id = self._client("Mme Longue Séance")
        self.base.ajouter_rendezvous(client_id, DEMAIN, "Bilan",
                                     duree_tranches=4)
        client = self.base.obtenir_client(client_id)
        self.assertEqual(client["nb_rendezvous"], 1)  # 1, not 4
        fiche = etats_clients.tableau_clients(self.base, self.preferences)[0]
        self.assertEqual(fiche["resume"]["total"], 1)
        self.assertEqual(fiche["agenda"], "rendez-vous prévu")

    def test_etat_d_agenda_et_etat_de_conversation_sont_distincts(self):
        client_id = self._client("M. Deux États")
        self.base.ajouter_rendezvous(client_id, HIER, "Séance", statut="manqué")
        campagne_id = self.base.creer_campagne("Essai", "personnalise",
                                               nature="prise_rdv",
                                               statut="terminée")
        contact_id = self.base.ajouter_contact_campagne(
            campagne_id, 0, "M. Deux États", "+33 6 39 98 50 80",
            etat="injoignable")
        self.base.ajouter_appel_campagne(campagne_id, contact_id, 0,
                                         issue="no_answer")
        self.base.ajouter_appel_campagne(campagne_id, contact_id, 1,
                                         issue="no_answer")
        fiche = etats_clients.tableau_clients(self.base, self.preferences)[0]
        self.assertEqual(fiche["agenda"], "rendez-vous manqué (absent)")
        self.assertEqual(fiche["conversation"], "injoignable")
        self.assertEqual(fiche["tentatives"], 2)
        self.assertIn("(2)", etats_clients.libelle_conversation(
            "injoignable", fiche["tentatives"]))

    def test_non_traite_bascule_quand_une_campagne_EN_COURS_le_prend(self):
        client_id = self._client("Mme À Recaler")
        self.base.ajouter_rendezvous(client_id, HIER, "Séance", statut="manqué")
        fiche = etats_clients.tableau_clients(self.base, self.preferences)[0]
        self.assertTrue(fiche["non_traite"])
        self.assertEqual([b["etat"] for b in fiche["besoins"]],
                         ["rendez-vous manqué (absent)"])
        # A CLOSED campaign does not handle them.
        close_id = self.base.creer_campagne("Close", "personnalise",
                                            nature="prise_rdv", statut="close")
        self.base.ajouter_contact_campagne(close_id, 0, "Mme À Recaler",
                                           "+33 6 39 98 50 80")
        fiche = etats_clients.tableau_clients(self.base, self.preferences)[0]
        self.assertTrue(fiche["non_traite"])
        # A campaign IN PROGRESS of the right kind does.
        vivante_id = self.base.creer_campagne("Vivante", "personnalise",
                                              nature="prise_rdv",
                                              statut="en cours")
        self.base.ajouter_contact_campagne(vivante_id, 0, "Mme À Recaler",
                                           "+33 6 39 98 50 80")
        fiche = etats_clients.tableau_clients(self.base, self.preferences)[0]
        self.assertFalse(fiche["non_traite"])
        self.assertEqual([c["nom"] for c in fiche["campagnes"]], ["Vivante"])
        self.assertEqual(fiche["campagnes"][0]["etat_entree"],
                         "rendez-vous manqué (absent)")
        # A campaign of ANOTHER kind does not handle that state.
        autre_id = self.base.creer_campagne("Autre", "personnalise",
                                            nature="creneau_libere",
                                            statut="en cours")
        self.base.ajouter_contact_campagne(autre_id, 0, "Mme À Recaler",
                                           "+33 6 39 98 50 80")
        fiche = etats_clients.tableau_clients(self.base, self.preferences)[0]
        self.assertFalse(fiche["non_traite"])  # still taken by `Vivante`

    def test_exclu_ou_sans_numero_n_est_jamais_non_traite(self):
        exclu_id = self._client("M. Exclu", "+33 6 39 98 50 81")
        self.base.ajouter_rendezvous(exclu_id, HIER, "Séance", statut="manqué")
        self.base.definir_ne_plus_appeler(exclu_id, True)
        muet_id = self._client("Mme Sans Numéro", "")
        self.base.ajouter_rendezvous(muet_id, HIER, "Séance", statut="manqué")
        fiches = {f["client"]["nom"]: f for f in
                  etats_clients.tableau_clients(self.base, self.preferences)}
        self.assertFalse(fiches["M. Exclu"]["non_traite"])
        self.assertEqual(fiches["M. Exclu"]["conversation"], "ne plus appeler")
        self.assertFalse(fiches["Mme Sans Numéro"]["non_traite"])
        self.assertTrue(fiches["Mme Sans Numéro"]["sans_numero"])

    def test_les_etats_sans_campagne_restent_du_travail_humain(self):
        client_id = self._client("M. Humain")
        campagne_id = self.base.creer_campagne("Essai", "personnalise",
                                               nature="prise_rdv",
                                               statut="en cours")
        self.base.ajouter_contact_campagne(
            campagne_id, 0, "M. Humain", "+33 6 39 98 50 80",
            etat="à rappeler par un humain")
        fiche = etats_clients.tableau_clients(self.base, self.preferences)[0]
        self.assertEqual(fiche["conversation"], "à rappeler par un humain")
        self.assertTrue(fiche["humain"])
        self.assertTrue(fiche["non_traite"])  # no campaign will handle them

    def test_le_filtre_ignore_la_casse_et_les_accents(self):
        self._client("Mme Nadia Lefèvre")
        fiches = etats_clients.tableau_clients(self.base, self.preferences)
        self.assertEqual(len(etats_clients.filtrer(fiches, "LEFEVRE")), 1)
        self.assertEqual(len(etats_clients.filtrer(fiches, "lefèvre")), 1)
        self.assertEqual(len(etats_clients.filtrer(fiches, "durand")), 0)


class TestServeurPosteClients(_TestAvecServeurWeb):
    """The Clients page: states, campaigns, filters and record editing."""

    def test_la_liste_montre_les_deux_etats_et_le_compte_de_rendezvous(self):
        base = self.application.base
        client_id = base.obtenir_ou_creer_client("Mme Longue Séance",
                                                 "+33 6 39 98 50 82")
        base.ajouter_rendezvous(client_id, DEMAIN, "Bilan", duree_tranches=4)
        _, page = self._obtenir("/clients")
        self.assertIn("Contacts (5)", page)
        self.assertIn("État d'agenda", page)
        self.assertIn("État de conversation", page)
        ligne = page.split("Mme Longue Séance")[1].split("</tr>")[0]
        self.assertIn("<strong>1</strong>", ligne)  # 1 appointment, not 4
        self.assertIn("📅 rendez-vous prévu", ligne)
        self.assertIn("— jamais appelé", ligne)
        self.assertIn("+33 6 •• •• •• 82", ligne)
        self.assertNotIn("+33 6 39 98 50 82", page)  # masked everywhere

    def test_les_filtres_rechargent_la_SEULE_liste(self):
        _, fragment = self._obtenir("/clients/liste?recherche=nadia")
        self.assertNotIn("<!DOCTYPE", fragment)  # a FRAGMENT
        self.assertIn("<strong>1</strong> contact(s) sur 4", fragment)
        self.assertIn("Mme Nadia Lefèvre", fragment)
        self.assertNotIn("M. Karim Osman", fragment)
        # The `not handled` filter: the demo's 4 missed ones all are...
        _, fragment = self._obtenir("/clients/liste?non_traite=1")
        self.assertIn("<strong>4</strong> contact(s) sur 4", fragment)
        self.assertIn("non traité", fragment)
        # ...until a campaign IN PROGRESS takes one of them.
        base = self.application.base
        campagne_id = base.creer_campagne("Reprise", "personnalise",
                                          nature="prise_rdv", statut="en cours")
        base.ajouter_contact_campagne(campagne_id, 0, "Mme Nadia Lefèvre",
                                      "+33 6 39 98 50 41")
        _, fragment = self._obtenir("/clients/liste?non_traite=1")
        self.assertIn("<strong>3</strong> contact(s) sur 4", fragment)
        self.assertNotIn("Mme Nadia Lefèvre", fragment)
        # And that one appears as taken care of.
        _, fragment = self._obtenir("/clients/liste?recherche=nadia")
        self.assertIn("pris en charge", fragment)
        # THE CAMPAIGN DETAIL IS NO LONGER IN THE ROW (02/08/2026): it carries
        # only a COUNT, which leads to the detail. That is what brought the row
        # back to a readable height.
        self.assertNotIn("entré pour : rendez-vous manqué (absent)", fragment)
        self.assertIn('data-modale="/clients/detail-campagnes?id=1"', fragment)
        # And the detail is indeed at the end of the link — not lost.
        _, modale = self._obtenir("/clients/detail-campagnes?id=1")
        self.assertIn("Reprise", modale)
        self.assertIn("entré pour : rendez-vous manqué (absent)", modale)

    def test_les_deux_colonnes_ne_montrent_qu_un_nombre(self):
        """A client's row took up six screen lines."""
        _, fragment = self._obtenir("/clients/liste?recherche=nadia")
        self.assertIn('data-modale="/clients/detail-rendezvous?id=1"', fragment)
        self.assertIn('href="/clients/fiche?id=1"', fragment)
        # The former detail has left the row.
        self.assertNotIn("prochain :", fragment)
        self.assertNotIn("dernier :", fragment)
        # And it is at the end of the link, more complete than before: the
        # whole list.
        _, modale = self._obtenir("/clients/detail-rendezvous?id=1")
        self.assertIn("rendez-vous, du plus récent", modale)
        self.assertIn("<th>Motif</th>", modale)
        self.assertNotIn("<!DOCTYPE", modale)  # a fragment

    def test_un_client_sans_rien_n_a_aucun_lien_mort(self):
        """Zero is not clickable: an empty window says nothing."""
        base = self.application.base
        base.ajouter_client("M. Sans Rien", "+33 6 39 98 50 47")
        _, fragment = self._obtenir("/clients/liste?recherche=sans+rien")
        self.assertNotIn("detail-rendezvous", fragment)
        self.assertNotIn("detail-campagnes", fragment)
        self.assertIn("aucune", fragment)

    def test_un_identifiant_inconnu_est_refuse_proprement(self):
        for chemin in ("/clients/detail-rendezvous", "/clients/detail-campagnes"):
            with self.subTest(chemin=chemin):
                with self.assertRaises(urllib.error.HTTPError) as refus:
                    self._obtenir(f"{chemin}?id=999999")
                self.assertEqual(refus.exception.code, 404)
                with self.assertRaises(urllib.error.HTTPError) as refus:
                    self._obtenir(f"{chemin}?id=abc")
                self.assertEqual(refus.exception.code, 400)

    def test_editer_un_client_refus_puis_enregistrement(self):
        base = self.application.base
        _, page = self._obtenir("/clients/fiche?id=1")
        self.assertIn("Modifier sa fiche", page)
        self.assertIn('name="nom" value="Mme Nadia Lefèvre"', page)
        self.assertIn("+33 6 •• •• •• 41", page)  # masked even here
        self.assertNotIn("+33 6 39 98 50 41", page)
        self.assertIn("Laissez le champ", page)  # the format is stated
        # Refusal: the offending input comes back into its field, nothing is
        # written.
        _, page = self._poster("/clients/modifier",
                               {"client": 1, "nom": "N",
                                "telephone": "06 12"})
        self.assertIn("Saisie refusée", page)
        self.assertIn("deux caractères minimum", page)
        self.assertIn("Numéro de téléphone invalide", page)
        self.assertIn('name="nom" value="N"', page)
        self.assertIn('name="telephone" value="06 12"', page)
        self.assertEqual(base.obtenir_client(1)["nom"], "Mme Nadia Lefèvre")
        # On save: name corrected, number changed (and masked), do-not-call
        # set.
        _, page = self._poster("/clients/modifier",
                               {"client": 1, "nom": "Mme Nadia Lefèvre-Martin",
                                "telephone": "0199001234",
                                "ne_plus_appeler": "1"})
        self.assertIn("Fiche du client enregistrée", page)
        self.assertIn("Mme Nadia Lefèvre-Martin", page)
        self.assertIn("01 99 •• •• 34", page)
        self.assertNotIn("01 99 00 12 34", page)         # jamais en clair
        client = base.obtenir_client(1)
        self.assertEqual(client["nom"], "Mme Nadia Lefèvre-Martin")
        self.assertTrue(client["ne_plus_appeler"])
        self.assertEqual(base.telephone_de(1), "01 99 00 12 34")
        # Leaving the telephone field EMPTY keeps the number as it is.
        self._poster("/clients/modifier",
                     {"client": 1, "nom": "Mme Nadia Lefèvre-Martin",
                      "telephone": ""})
        self.assertEqual(base.telephone_de(1), "01 99 00 12 34")
        self.assertFalse(base.obtenir_client(1)["ne_plus_appeler"])  # unticked


# ========================================================================= R15
# - BOTH DOORS AT LAST LEAD TO A CAMPAIGN
# ------------------------------------------------------------------------- `A
# campaign is always created from what is missing` (1 of
# CAS_DE_FIGURE_CAMPAGNES.md): a TIME for a person who is waiting (Clients
# door), or a PERSON for an available time (Appointments door). Both doors were
# described and displayed as `coming soon`; these tests prove they now lead to
# the wizard, at step 2, list filled — and that NO CALL goes out of them.
# =========================================================================


class TestPorteClientsVersCampagne(_TestAvecServeurWeb):
    """4 - from the filtered state to the button, and from the button to step 2.
    """

    ETAT_MANQUE = "rendez-vous manqué (absent)"

    def _client_prevu(self, nom="M. Rendez Vous Prévu"):
        """A client whose appointment HOLDS: two kinds handle them."""
        base = self.application.base
        client_id = base.obtenir_ou_creer_client(nom, "+33 6 39 98 50 61")
        base.ajouter_rendezvous(client_id, DEMAIN, "Contrôle")
        return client_id

    def _client_humain(self, nom="M. Pour Un Humain"):
        """A client that ONLY a human can take over (6)."""
        base = self.application.base
        client_id = base.obtenir_ou_creer_client(nom, "+33 6 39 98 50 62")
        campagne_id = base.creer_campagne("Passée", "personnalise",
                                          nature="prise_rdv",
                                          statut="terminée")
        base.ajouter_contact_campagne(campagne_id, 1, nom,
                                      "+33 6 39 98 50 62",
                                      etat="à rappeler par un humain",
                                      client_id=client_id)
        return client_id

    def test_le_bouton_nait_du_filtre_et_nomme_la_nature_DEDUITE(self):
        # Without `not handled`, no button: the selection then contains clients
        # already taken care of, and a button would lie about its count.
        _, sans = self._obtenir("/clients/liste?etat="
                                + urllib.parse.quote(self.ETAT_MANQUE))
        self.assertNotIn("Créer la campagne", sans)
        # With `not handled`: one button, the KIND deduced from the state by
        # etats_clients.TRAITEMENT, and the exact count of the 4 demo missed
        # ones.
        _, fragment = self._obtenir(
            "/clients/liste?non_traite=1&etat="
            + urllib.parse.quote(self.ETAT_MANQUE))
        self.assertNotIn("<!DOCTYPE", fragment)  # it really is the FRAGMENT
        self.assertIn("➕ Créer la campagne « 🗓 Prise de rendez-vous » — "
                      "4 client(s) concerné(s)", fragment)
        self.assertIn('action="/clients/campagne"', fragment)
        self.assertIn('name="nature" value="prise_rdv"', fragment)
        self.assertIn("Aucun appel ne part de ces boutons", fragment)
        # The button is not greyed out, it announces nothing as `coming soon`.
        self.assertNotIn("badge-a-venir", fragment)

    def test_un_bouton_PAR_NATURE_quand_le_filtre_mele_les_etats(self):
        """The owner's decision of 31/07/2026, kept to the letter."""
        self._client_prevu()
        # A single state can already call TWO kinds (3).
        _, prevu = self._obtenir("/clients/liste?non_traite=1&etat="
                                 + urllib.parse.quote("rendez-vous prévu"))
        self.assertIn("« 🔔 Rappel de rendez-vous » — 1 client(s)", prevu)
        self.assertIn("« ✅ Confirmation de rendez-vous » — 1 client(s)",
                      prevu)
        self.assertNotIn("Prise de rendez-vous", prevu)
        # Without a state filter, the selection mixes both families: THREE
        # buttons, each with ITS OWN count — never a greyed-out button.
        _, mele = self._obtenir("/clients/liste?non_traite=1")
        self.assertIn("« 🗓 Prise de rendez-vous » — 4 client(s)", mele)
        self.assertIn("« 🔔 Rappel de rendez-vous » — 1 client(s)", mele)
        self.assertIn("« ✅ Confirmation de rendez-vous » — 1 client(s)",
                      mele)
        self.assertEqual(mele.count('action="/clients/campagne"'), 3)

    def test_un_etat_sans_campagne_ne_donne_AUCUN_bouton_mais_dit_pourquoi(self):
        self._client_humain()
        _, fragment = self._obtenir(
            "/clients/liste?non_traite=1&etat="
            + urllib.parse.quote("à rappeler par un humain"))
        self.assertIn("M. Pour Un Humain", fragment)
        self.assertNotIn("Créer la campagne", fragment)
        self.assertIn("aucune campagne ne traite cela", fragment)
        # And the page's human counter stays visible (6).
        _, page = self._obtenir("/clients")
        self.assertIn("🙋 1 client(s) attendent un appel HUMAIN", page)

    def test_le_clic_ouvre_l_ETAPE_2_liste_remplie_et_AUCUN_APPEL(self):
        base = self.application.base
        statut, page = self._poster("/clients/campagne",
                                    {"nature": "prise_rdv",
                                     "etat": self.ETAT_MANQUE,
                                     "recherche": ""})
        self.assertEqual(statut, 200)
        # We really are at step 2: the breadcrumb says so, and the kind is NOT
        # asked for again.
        self.assertIn('id="fa-etape-2" class="fa-etape fa-courante"', page)
        self.assertIn("Nouvelle campagne — message", page)
        self.assertIn("🗓 <strong>Prise de rendez-vous</strong>", page)
        # The list is already filled, and the count is stated.
        self.assertIn("👥 Liste déjà remplie : <strong>4</strong> personne(s)",
                      page)
        self.assertIn("depuis 👥 Contacts — état « ⚠ absent à son rendez-vous »",
                      page)
        # AUCUN APPEL, AUCUNE campagne : rien n'existe encore en base.
        self.assertEqual(base.lister_campagnes(), [])
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM appels").fetchone()[0], 0)
        # The draft does carry the 4 people, numbers included.
        brouillon = self.application.obtenir_brouillon_assistant(
            self._brouillon(page))
        self.assertEqual(len(brouillon["contacts"]), 4)
        self.assertIn("Mme Nadia Lefèvre",
                      [c["nom"] for c in brouillon["contacts"]])

    def test_la_recette_garde_le_critere_et_reste_REJOUABLE(self):
        _, page = self._poster("/clients/campagne",
                               {"nature": "prise_rdv",
                                "etat": self.ETAT_MANQUE, "recherche": ""})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "ordre": "liste",
            "info_entreprise": "Cabinet Essai",
            "info_origine": "vous avez demandé un rendez-vous",
            "info_creneaux_proposes": "mardi 9h00",
            "relance_mode": "delai", "relance_delai": "4", "relance_max": "3"})
        _, fiche = self._poster("/assistant/liste", {"b": b,
                                                     "action": "valider"})
        self.assertIn("prête", fiche)
        base = self.application.base
        campagne = base.lister_campagnes()[0]
        configuration = assistant.configuration_campagne(campagne)
        self.assertEqual(configuration["recette"]["apports"],
                         [{"mode": "etat", "etat": self.ETAT_MANQUE,
                           "nature": "prise_rdv", "recherche": ""}])
        self.assertTrue(assistant.recette_reproductible(
            configuration["recette"]))
        self.assertIn("rejouable sur un autre créneau", fiche)
        # And it really does REPLAY: the criterion rebuilds the list.
        contacts, _ = assistant.contacts_de_recette(
            base, configuration["recette"],
            assistant.champs_campagne(configuration),
            self.application.preferences)
        self.assertEqual(len(contacts), 4)


class TestPortePlanningVersCampagne(_TestAvecServeurWeb):
    """5 - the calendar's three gestures, and the loop closing."""

    def _poster_modale(self, chemin, donnees):
        """The POST as the modal sends it; returns (target, body)."""
        octets = urllib.parse.urlencode(donnees, doseq=True).encode("utf-8")
        requete = urllib.request.Request(
            self.racine + chemin, data=octets,
            headers={"X-RingBack-Fragment": "1"})
        with urllib.request.urlopen(requete, timeout=15) as reponse:
            return (reponse.headers.get("X-RingBack-Cible"),
                    reponse.read().decode("utf-8"))

    def _rendezvous(self, heures, nom="Mme Place Prise"):
        """An appointment in N hours — it is IT that decides the rule."""
        base = self.application.base
        client_id = base.obtenir_ou_creer_client(nom, "+33 6 39 98 50 63")
        quand = (datetime.datetime.now()
                 + datetime.timedelta(hours=heures)).replace(
                     second=0, microsecond=0)
        return base.ajouter_rendezvous(client_id,
                                       quand.isoformat(timespec="minutes"),
                                       "Séance")

    def test_un_creneau_libre_mene_a_la_campagne_sur_CETTE_place(self):
        for jour in range(7):
            horaires.basculer_periode(self.application.preferences, jour,
                                      9 * 60, 18 * 60, "ouvrir")
        creneau = (datetime.datetime.now()
                   + datetime.timedelta(days=3)).replace(
                       hour=10, minute=0, second=0,
                       microsecond=0).isoformat(timespec="minutes")
        _, modale = self._obtenir("/suivi/detail?creneau="
                                  + urllib.parse.quote(creneau))
        self.assertNotIn("à venir", modale)     # R15 : plus de promesse
        self.assertIn('action="/suivi/creneau/campagne"', modale)
        self.assertIn(f'name="creneau" value="{creneau}"', modale)
        # The click leads to step 2, slot ALREADY filled, without any call.
        _, page = self._poster("/suivi/creneau/campagne",
                               {"creneau": creneau, "depuis": "planning"})
        self.assertIn('id="fa-etape-2" class="fa-etape fa-courante"', page)
        self.assertIn("📞 <strong>Créneau libéré</strong>", page)
        self.assertIn(f'name="info_creneau_libere" value="{creneau}"', page)
        self.assertEqual(self.application.base.lister_campagnes(), [])
        self.assertEqual(self.application.base.conn.execute(
            "SELECT COUNT(*) FROM appels").fetchone()[0], 0)

    def test_un_rendezvous_propose_RAPPELER_DEPLACER_et_ANNULER(self):
        rdv_id = self._rendezvous(72)
        _, modale = self._obtenir(f"/suivi/detail?rdv={rdv_id}")
        # THREE gestures since 02/08/2026: the callback joined the move and the
        # cancellation, at the owner's request.
        self.assertIn("Les trois gestes", modale)
        self.assertIn('action="/suivi/detail/rappel"', modale)
        self.assertIn('action="/suivi/detail/deplacer"', modale)
        self.assertIn('action="/suivi/detail/annuler"', modale)
        # `Rappeler` builds the callback campaign on THIS appointment, at step
        # 2.
        _, page = self._poster("/suivi/detail/rappel", {"rdv": rdv_id})
        self.assertIn('id="fa-etape-2" class="fa-etape fa-courante"', page)
        self.assertIn("🔔 <strong>Rappel de rendez-vous</strong>", page)
        self.assertIn("👥 Liste déjà remplie : <strong>1</strong> personne(s)",
                      page)
        self.assertIn("Mme Place Prise", page)
        self.assertEqual(self.application.base.lister_campagnes(), [])
        # `Deplacer` builds the move campaign on THIS appointment, at step 2.
        _, page = self._poster("/suivi/detail/deplacer", {"rdv": rdv_id})
        self.assertIn('id="fa-etape-2" class="fa-etape fa-courante"', page)
        self.assertIn("📆 <strong>Déplacement de rendez-vous</strong>", page)
        self.assertIn("👥 Liste déjà remplie : <strong>1</strong> personne(s)",
                      page)
        self.assertIn("Mme Place Prise", page)
        self.assertEqual(self.application.base.lister_campagnes(), [])
        self.assertEqual(self.application.base.conn.execute(
            "SELECT COUNT(*) FROM appels").fetchone()[0], 0)

    def _lundi_du_rendezvous(self, rdv_id):
        rdv = self.application.base.obtenir_rendezvous(rdv_id)
        jour = datetime.date.fromisoformat(rdv["horaire"][:10])
        return jour, jour - datetime.timedelta(days=jour.weekday())

    def test_la_semaine_propose_une_campagne_de_rappel(self):
        """The header's button, and its week / chosen days window.

        Owner's request (02/08/2026). Two stages: we ask WHO to contact before
        showing the list of days — otherwise these would be an option's
        options.
        """
        rdv_id = self._rendezvous(72)
        jour, lundi = self._lundi_du_rendezvous(rdv_id)
        # We ask for THE APPOINTMENT'S WEEK: at +72 h it can fall in the
        # following week, and the button only appears if there are people.
        annee, semaine = lundi.isocalendar()[0], lundi.isocalendar()[1]
        _, page = self._obtenir(f"/suivi?annee={annee}&semaine={semaine}")
        self.assertIn("🔔 Créer une campagne de rappel", page)
        self.assertIn('class="entete-section"', page)
        _, modale = self._obtenir(
            f"/suivi/detail?rappel=semaine&lundi={lundi:%Y-%m-%d}")
        self.assertIn("Créer une campagne de rappel pour", modale)
        self.assertIn('name="qui" value="semaine"', modale)
        self.assertIn('name="qui" value="jours"', modale)
        # The days offered are those that CARRY appointments.
        self.assertIn(f'value="{jour:%Y-%m-%d}"', modale)
        self.assertIn('id="rappel-jours" hidden', modale)  # folded first
        # The whole week: the wizard opens, list filled, zero calls.
        _, page = self._poster("/suivi/rappel/campagne",
                               {"lundi": f"{lundi:%Y-%m-%d}", "qui": "semaine"})
        self.assertIn('id="fa-etape-2" class="fa-etape fa-courante"', page)
        self.assertIn("🔔 <strong>Rappel de rendez-vous</strong>", page)
        self.assertIn("personne(s) à rappeler pour la semaine du", page)
        self.assertEqual(self.application.base.lister_campagnes(), [])
        self.assertEqual(self.application.base.conn.execute(
            "SELECT COUNT(*) FROM appels").fetchone()[0], 0)

    def test_un_jour_choisi_ne_prend_que_ce_jour(self):
        rdv_id = self._rendezvous(72)
        jour, lundi = self._lundi_du_rendezvous(rdv_id)
        _, page = self._poster("/suivi/rappel/campagne", {
            "lundi": f"{lundi:%Y-%m-%d}", "qui": "jours",
            "jour": f"{jour:%Y-%m-%d}"})
        self.assertIn("👥 Liste déjà remplie : <strong>1</strong> personne(s)",
                      page)
        # The day is named IN FRENCH: `%A` follows the system's language and
        # wrote `Monday 03/08` on this machine (seen on screen on 02/08/2026).
        # The product's day names are in horaires.JOURS.
        self.assertIn(horaires.JOURS[jour.weekday()], page)
        for anglais in ("Monday", "Tuesday", "Wednesday", "Thursday",
                        "Friday", "Saturday", "Sunday"):
            self.assertNotIn(anglais, page)
        # No day ticked: refused, and nothing is built.
        with self.assertRaises(urllib.error.HTTPError) as refus:
            self._poster("/suivi/rappel/campagne",
                         {"lundi": f"{lundi:%Y-%m-%d}", "qui": "jours"})
        self.assertEqual(refus.exception.code, 409)

    def test_un_rendezvous_confirme_est_rappele_lui_aussi(self):
        """The header counted 13, the campaign took none of them.

        Observed by the owner on 02/08/2026: `erreur 409, personne a rappeler`,
        while his appointment was indeed there — but CONFIRMED. The schedule
        counts the scheduled AND the confirmed ones; the campaign took only the
        scheduled ones. A confirmed appointment can be called back about too.
        """
        base = self.application.base
        rdv_id = self._rendezvous(72)
        base.mettre_a_jour_rendezvous(rdv_id, statut="confirmé")
        jour, lundi = self._lundi_du_rendezvous(rdv_id)
        # The window counts it...
        _, modale = self._obtenir(
            f"/suivi/detail?rappel=semaine&lundi={lundi:%Y-%m-%d}")
        self.assertIn(f'value="{jour:%Y-%m-%d}"', modale)
        # ...and the campaign takes it, instead of the earlier 409.
        _, page = self._poster("/suivi/rappel/campagne",
                               {"lundi": f"{lundi:%Y-%m-%d}", "qui": "semaine"})
        self.assertIn("👥 Liste déjà remplie : <strong>1</strong> personne(s)",
                      page)

    def test_une_semaine_vide_ne_propose_rien(self):
        """Offering to call back an empty week would be hollow."""
        loin = datetime.date.today() + datetime.timedelta(days=400)
        lundi = loin - datetime.timedelta(days=loin.weekday())
        _, modale = self._obtenir(
            f"/suivi/detail?rappel=semaine&lundi={lundi:%Y-%m-%d}")
        self.assertIn("il n'y a personne à rappeler", modale)
        self.assertNotIn('name="qui"', modale)

    def test_annuler_APPELLE_la_regle_des_12h_et_propose_la_compensation(self):
        base = self.application.base
        rdv_id = self._rendezvous(72)  # well beyond the threshold
        rdv = base.obtenir_rendezvous(rdv_id)
        # 1st stage: we ANNOUNCE, we write nothing.
        cible, panneau = self._poster_modale("/suivi/detail/annuler",
                                             {"rdv": rdv_id,
                                              "geste": "demander"})
        self.assertEqual(cible, "modale")
        self.assertIn("« supprimé »", panneau)
        self.assertIn("Rien n'est encore écrit", panneau)
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"], "prévu")
        # 2nd stage: the rule applies — it is decision_annulation that decided,
        # and the slot leads in ONE CLICK to the campaign that will fill it.
        cible, resultat = self._poster_modale("/suivi/detail/annuler",
                                              {"rdv": rdv_id,
                                               "geste": "confirmer"})
        self.assertEqual(cible, "modale")
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"],
                         db.STATUT_SUPPRIME)
        self.assertIn('action="/suivi/creneau/campagne"', resultat)
        self.assertIn(f'name="creneau" value="{rdv["horaire"]}"', resultat)
        # The schedule behind the window updates ITSELF.
        self.assertIn('data-rafraichir="planning"', resultat)
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM appels").fetchone()[0], 0)

    def test_annuler_en_deca_du_seuil_reste_ANNULE_et_dit_pourquoi(self):
        base = self.application.base
        rdv_id = self._rendezvous(2)           # moins de 12 h : trop tard
        _, panneau = self._poster_modale("/suivi/detail/annuler",
                                         {"rdv": rdv_id, "geste": "demander"})
        self.assertIn("« annulé »", panneau)
        self.assertIn("ne proposera <strong>pas</strong>", panneau)
        _, resultat = self._poster_modale("/suivi/detail/annuler",
                                          {"rdv": rdv_id,
                                           "geste": "confirmer"})
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"], "annulé")
        self.assertIn("Le faire quand même à la main", resultat)
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM appels").fetchone()[0], 0)


# =========================================================================
# SAFETY TESTS - the four severity-1 breaks from INTERCONNEXIONS.md
# -------------------------------------------------------------------------
# These are the tests that stop the product making a phone ring that should not
# have rung. They count more than the others: if one of them falls, it is a
# PERSON who receives a call they refused, or an appointment that appears where
# it cannot exist.
# =========================================================================


class TestSecuriteNumeroCorrige(unittest.TestCase):
    """R1 - the do-not-call can no longer be bypassed by correcting a number.

    The scenario proved by the audit: a campaign copied the number when it was
    created and dialled that copy; correcting the client's number (and ticking
    do-not-call) let the campaign call the OLD number — hence, in real mode,
    somebody else's phone.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.preferences = generation.Preferences()
        self.planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=7, latence=0))
        self.campagne_id = self.base.creer_campagne(
            "Campagne d'essai", "personnalise", mission="Bonjour [client].")

    def _contact(self, nom="Mme Yvonne Lecomte", telephone="+33 6 39 98 07 51"):
        return self.base.ajouter_contact_campagne(
            self.campagne_id, 1, nom, telephone)

    def test_le_contact_porte_un_lien_vers_la_fiche_client(self):
        contact_id = self._contact()
        client_id = self.base.client_du_contact(contact_id)
        self.assertIsNotNone(client_id)  # a record was created on entry
        self.assertEqual(self.base.obtenir_client(client_id)["nom"],
                         "Mme Yvonne Lecomte")

    def test_le_numero_compose_est_celui_de_la_fiche_pas_la_copie(self):
        contact_id = self._contact()
        client_id = self.base.client_du_contact(contact_id)
        self.base.modifier_client(client_id, telephone="+33 6 39 98 07 77")
        # The period copy stays readable (it is history)...
        contact = self.base.conn.execute(
            "SELECT telephone FROM contacts_campagne WHERE id = ?",
            (contact_id,)).fetchone()
        self.assertEqual(contact["telephone"], "+33 6 39 98 07 51")
        # ...but it is the CURRENT number that would be dialled.
        self.assertEqual(self.base.telephone_contact_campagne(contact_id),
                         "+33 6 39 98 07 77")

    def test_numero_corrige_plus_stop_le_contact_est_exclu(self):
        """THE audit's scenario, to the letter."""
        contact_id = self._contact()
        client_id = self.base.client_du_contact(contact_id)
        # The form's exact gesture: new number AND do-not-call, same
        # submission.
        self.base.modifier_client(client_id, telephone="+33 6 39 98 07 77")
        self.base.definir_ne_plus_appeler(client_id, True)
        # The old safety lock, on its own, still does not recognise the person:
        # this really is the proven flaw, and it is bypassed another way.
        self.assertFalse(self.base.telephone_exclu("+33 6 39 98 07 51"))
        cible = self.base.cible_appel_contact(contact_id)
        self.assertIsNone(cible["telephone"])
        self.assertEqual(cible["refus"], db.REFUS_STOP)
        # And the call really does not go out.
        campagne = self.base.obtenir_campagne(self.campagne_id)
        contact = self.base.obtenir_contact_campagne(contact_id)
        compte_rendu = campagnes._appeler_contact_classique(
            self.base, self.planif, self.preferences, campagne, contact,
            tentative=0)
        self.assertEqual(compte_rendu["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertEqual(self.base.appels_du_contact_campagne(contact_id), [])
        self.assertEqual(
            self.base.obtenir_contact_campagne(contact_id)["detail"],
            db.suite_du_refus(db.REFUS_STOP)[1])

    def test_filet_de_securite_par_le_NOM_seul(self):
        """Even without a link or a shared number, the NAME is enough to set
        aside.
        """
        # Contact from an OLD database: no link to a record.
        contact_id = self.base.ajouter_contact_campagne(
            self.campagne_id, 2, "Mme Yvonne Lecomte", "+33 6 39 98 07 51",
            client_id=0)
        self.base.conn.execute(
            "UPDATE contacts_campagne SET client_id = NULL WHERE id = ?",
            (contact_id,))
        self.base.conn.commit()
        # ANOTHER record, same person, completely different number, flagged
        # do-not-call.
        autre = self.base.ajouter_client("mme  yvonne LEFEVRE", "01 99 00 00 01")
        self.base.definir_ne_plus_appeler(autre, True)
        self.assertIsNone(self.base.cible_appel_contact(contact_id)["refus"])
        # The exact name (case and accents ignored) is recognised.
        homonyme = self.base.ajouter_client("mme  YVONNE lecomte",
                                            "01 99 00 00 02")
        self.base.definir_ne_plus_appeler(homonyme, True)
        cible = self.base.cible_appel_contact(contact_id)
        self.assertEqual(cible["refus"], db.REFUS_STOP_NOM)
        self.assertIsNone(cible["telephone"])

    def test_cascade_collee_a_la_main_ecarte_aussi_par_le_nom(self):
        exclu = self.base.ajouter_client("M. Colle Exemple", "01 99 00 00 03")
        self.base.definir_ne_plus_appeler(exclu, True)
        cascade_id = self.planif.executer_cascade(
            [{"nom": "M. Colle Exemple", "telephone": "+33 6 39 98 07 51"}],
            "Mission [créneau].", DEMAIN)
        lignes = self.base.appels_de_cascade(cascade_id)
        self.assertEqual([l["etat"] for l in lignes], ["exclu"])
        self.assertIsNone(lignes[0]["issue"])  # never dialled


class TestSecuriteNumeroCorrigeWeb(_TestAvecServeurWeb):
    """R1, end to end: the campaign really runs and does not call."""

    def test_campagne_ne_compose_pas_un_numero_corrige_et_stoppe(self):
        base = self.application.base
        campagne_id = base.creer_campagne(
            "Essai R1", "personnalise", nature="personnalise",
            mission="Bonjour [client].", statut="prête",
            configuration=json.dumps({"politique": "tous", "ordre": "liste",
                                      "options": {}, "infos": {},
                                      "infos_auto": {}, "champs": []}))
        contact_id = base.ajouter_contact_campagne(
            campagne_id, 1, "Mme Yvonne Lecomte", "+33 6 39 98 07 51")
        client_id = base.client_du_contact(contact_id)
        # The client record's form: new number + do-not-call, same submission.
        self._poster("/clients/modifier",
                     {"client": client_id, "nom": "Mme Yvonne Lecomte",
                      "telephone": "+33 6 39 98 07 77", "ne_plus_appeler": "1"})
        self._demarrer(campagne_id)
        self._attendre_statut(campagne_id, "terminée")
        contact = base.obtenir_contact_campagne(contact_id)
        self.assertEqual(contact["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertEqual(base.appels_du_contact_campagne(contact_id), [])
        # IT IS SAID ON SCREEN, and no number appears there in clear. The
        # table's `Detail` column was removed on 11/08/2026 (his decision):
        # without this banner, the person would be one more badge, and nothing
        # would say there is a call to make oneself.
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn("🚫 1 personne(s) ont refusé d'être appelées par un "
                      "agent", page)
        self.assertIn("attendent qu'un <strong>humain</strong> les rappelle",
                      page)
        self.assertIn('href="/relances?vue=humains"', page)
        self.assertNotIn("+33 6 39 98 07 77", page)
        self.assertNotIn("+33 6 39 98 07 51", page)


class TestSecuritePeriodeInterdite(_TestAvecServeurWeb):
    """R2 - the forbidden period holds for all FIVE doors, with no exception.

    The audit had measured: 1 door out of 5 protected (campaign start), the
    other four let real calls go out.
    """

    def _interdire_toute_la_journee(self):
        preferences = self.application.preferences
        preferences.definir(assistant.CLE_INTERDIT_DEBUT, "00:00")
        preferences.definir(assistant.CLE_INTERDIT_FIN, "23:59")

    def _campagne_prete(self):
        base = self.application.base
        campagne_id = base.creer_campagne(
            "Essai R2", "personnalise", nature="personnalise",
            mission="Bonjour [client].", statut="prête",
            configuration=json.dumps({"politique": "tous", "ordre": "liste",
                                      "options": {}, "infos": {},
                                      "infos_auto": {}, "champs": []}))
        base.ajouter_contact_campagne(campagne_id, 1, "M. Porte Une",
                                      "+33 6 39 98 07 51")
        return campagne_id

    def test_les_cinq_portes_refusent_pendant_la_periode_interdite(self):
        base = self.application.base
        campagne_id = self._campagne_prete()
        self._poster("/file/tout-rappeler")  # the queue fills up (it does not call)
        appels_en_file = len(self.application.planif.file)
        self.assertGreater(appels_en_file, 0)
        self._interdire_toute_la_journee()
        portes = (
            ("/campagne/demarrer", {"campagne": campagne_id}),
            ("/rappeler", {"rdv": 1}),
            ("/cascade/executer", {"liste": "M. Test;+33 6 39 98 07 51",
                                   "mission": "Mission [créneau].",
                                   "creneau": DEMAIN}),
            ("/relances/executer", {}),
            ("/file/executer", {}),
        )
        for chemin, donnees in portes:
            with self.assertRaises(urllib.error.HTTPError,
                                   msg=f"{chemin} aurait dû être refusé") as ctx:
                self._poster(chemin, donnees)
            self.assertEqual(ctx.exception.code, 403, chemin)
            page = ctx.exception.read().decode("utf-8")
            self.assertIn("période interdite", page, chemin)
            self.assertIn("Réglages", page, chemin)
        # NOTHING went out: no call, no cascade, no campaign started.
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM appels WHERE statut != 'en file'").fetchone()[0], 0)
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM appels_campagne").fetchone()[0], 0)
        self.assertEqual(base.lister_cascades(), [])
        self.assertEqual(base.obtenir_campagne(campagne_id)["statut"], "prête")
        self.assertEqual(len(self.application.planif.file), appels_en_file)

    def test_le_message_dit_l_heure_et_la_periode_reglee(self):
        self._interdire_toute_la_journee()
        with self.assertRaises(urllib.error.HTTPError) as ctx:
            self._poster("/rappeler", {"rdv": 1})
        page = ctx.exception.read().decode("utf-8")
        self.assertIn(f"il est {datetime.datetime.now():%Hh}", page)
        self.assertIn("00 h 00", page)
        self.assertIn("23 h 59", page)
        self.assertIn("même déclenché à la main", page)  # no exception

    def test_le_verrou_tient_meme_sans_passer_par_la_page(self):
        """The manual gesture cannot be `forced` by short-circuiting the route:
        the scheduler itself refuses.
        """
        self._interdire_toute_la_journee()
        with self.assertRaises(planificateur.GardeFou) as ctx:
            self.application.planif.executer()
        self.assertIn("période interdite", str(ctx.exception))


class TestSecuriteRendezVousTelephone(unittest.TestCase):
    """R3 - a date agreed over the phone obeys the opening hours.

    The audit had proved that an automatic callback placed an appointment on a
    day DECLARED CLOSED, while the same move made by hand was refused. Here:
    nothing is written, and the reason is stated.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.preferences = generation.Preferences()
        # Standard week: Monday to Friday, 9am-6pm.
        horaires.definir_semaine(self.preferences,
                                 {jour: [(540, 1080)] for jour in range(5)})
        # The CALLING WINDOW, for its part, is thrown wide open: these tests
        # bear on the APPOINTMENT's hours, not on what time it is. Without this
        # line, they failed as soon as they were run in the evening — a net
        # that only holds during office hours protects nothing (seen at 22:28).
        self.preferences.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        self.preferences.definir(themes.CLE_PLAGE_FIN, "23:59")
        self.planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=1, latence=0),
            preferences=self.preferences)

    def _lundi_prochain(self, semaines=1):
        jour = datetime.date.today() + datetime.timedelta(days=7 * semaines)
        while jour.weekday() != 0:
            jour += datetime.timedelta(days=1)
        return jour

    def test_une_date_deja_passee_est_refusee(self):
        """FOUND BY THE BENCH ON 18/08/2026, and never by the tests.

        Yet the rule is written twice in `horaires`: `An appointment moved to
        yesterday is not a moved appointment: it is a lost appointment.` It was
        only honoured on the side of the dates OFFERED. On the side of what we
        AGREE to write, nothing looked at the calendar: a date agreed over the
        phone a month in the past was written without a word, status `confirme`
        — then the missed-appointment rule set it back to `manque` at the next
        load. The appointment disappeared and nobody could say why.
        """
        lundi = self._lundi_prochain()
        passe = (datetime.datetime.combine(lundi, datetime.time(10))
                 - datetime.timedelta(days=21)).isoformat(timespec="minutes")
        refus = horaires.refus_rendezvous_telephone(
            self.base, self.preferences, passe)
        self.assertIsNotNone(refus, "une date passée est acceptée")
        self.assertIn("DÉJÀ PASSÉ", refus)
        self.assertIn("perdu", refus)
        # AND THE SAME DATE, IN THE FUTURE, GOES THROUGH: without this
        # counter-test, a refusal that refused EVERYTHING would be green too.
        futur = datetime.datetime.combine(lundi, datetime.time(10)).isoformat(
            timespec="minutes")
        self.assertIsNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, futur))

    def test_on_refuse_le_passe_pas_aujourd_hui(self):
        """The boundary, and it matters: never OFFERING the same day is a rule
        about offering (`plancher_de_proposition`) — it protects the client,
        who cannot rearrange things in two hours. Refusing to WRITE a date this
        afternoon that has just been agreed WITH THEM over the phone would be
        something else: it would be losing a real agreement.
        """
        # An open day, an open hour, but `today`: we take midday on an upcoming
        # Monday and pretend it is the same day.
        lundi = self._lundi_prochain()
        midi = datetime.datetime.combine(lundi, datetime.time(12))
        self.assertIsNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, midi.isoformat(timespec="minutes"),
            maintenant=midi - datetime.timedelta(hours=3)))
        # Three hours LATER, the same slot is behind us: refused.
        self.assertIsNotNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, midi.isoformat(timespec="minutes"),
            maintenant=midi + datetime.timedelta(hours=3)))

    def test_la_file_propose_une_AUTRE_date_qui_existe_vraiment(self):
        """THE SAME RULE AS THE CAMPAIGNS, which the queue was missing (18/08).

        When the person offers ANOTHER date, the caller must supply a second,
        genuinely free slot — the campaigns have done so since 16/08/2026. The
        call queue, however, supplied only the first: the other date then fell
        back on the `missed appointment + 2 days` convention, hence into the
        PAST for something missed a month ago.
        """
        vieux = (datetime.datetime.now() - datetime.timedelta(days=30)).replace(
            hour=14, minute=0, second=0, microsecond=0)
        client_id = self.base.ajouter_client("M. Report Fil",
                                             "+33 6 39 98 07 54")
        rdv_id = self.base.ajouter_rendezvous(
            client_id, vieux.isoformat(timespec="minutes"), "Séance",
            statut="manqué")
        appel_id = self.planif.programmer(rdv_id)
        self.planif.executer(seulement=appel_id)
        appel = self.base.obtenir_appel(appel_id)
        convenue = (appel["resultat"] or {}).get("new_datetime")
        self.assertEqual((appel["resultat"] or {}).get("appointment_status"),
                         "rescheduled", "l'essai ne joue pas le bon cas")
        # THE AGREED DATE IS AHEAD OF US — that is the whole point.
        self.assertGreater(convenue,
                           datetime.datetime.now().isoformat(timespec="minutes"),
                           "l'autre date convenue est dans le passé")
        # And it was written: a single row, at that date.
        self.assertIsNone(appel["note"], appel["note"])
        siennes = [r for r in self.base.tous_les_rendezvous()
                   if r["nom"] == "M. Report Fil"]
        self.assertEqual([r["horaire"] for r in siennes], [convenue])
        self.assertEqual(siennes[0]["statut"], "confirmé")

    def test_jour_ferme_refuse(self):
        jour = self._lundi_prochain()
        horaires.ajouter_jour_ferme(self.preferences, jour.isoformat(),
                                    "Formation")
        refus = horaires.refus_rendezvous_telephone(
            self.base, self.preferences, f"{jour.isoformat()}T09:30")
        self.assertIsNotNone(refus)
        self.assertIn("FERMÉ", refus)
        self.assertIn("Formation", refus)

    def test_hors_horaires_refuse(self):
        jour = self._lundi_prochain()
        self.assertIsNotNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, f"{jour.isoformat()}T06:00"))
        self.assertIsNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, f"{jour.isoformat()}T09:00"))

    def test_place_deja_prise_refuse(self):
        jour = self._lundi_prochain()
        client_id = self.base.ajouter_client("M. Deja La", "+33 6 39 98 07 41")
        self.base.ajouter_rendezvous(client_id, f"{jour.isoformat()}T09:00",
                                     "Séance")
        self.assertIsNotNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, f"{jour.isoformat()}T09:00"))

    def test_duree_qui_ne_tient_pas_refuse(self):
        jour = self._lundi_prochain()
        client_id = self.base.ajouter_client("M. Bloque", "+33 6 39 98 07 41")
        self.base.ajouter_rendezvous(client_id, f"{jour.isoformat()}T09:15",
                                     "Séance")
        # 09:00 is free, but 09:15 is taken: two slices do not fit.
        self.assertIsNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, f"{jour.isoformat()}T09:00",
            tranches=1))
        refus = horaires.refus_rendezvous_telephone(
            self.base, self.preferences, f"{jour.isoformat()}T09:00",
            tranches=2)
        self.assertIsNotNone(refus)
        self.assertIn("il en manque 1", refus)

    def test_sans_semaine_type_reglee_rien_n_est_pretendu(self):
        """Honesty: without opening hours, RingBack knows nothing — it only
        refuses the day DECLARED closed and the DOUBLE booking.
        """
        preferences = generation.Preferences()
        jour = self._lundi_prochain()
        self.assertIsNone(horaires.refus_rendezvous_telephone(
            self.base, preferences, f"{jour.isoformat()}T03:00"))
        # Two people in the same slot is visible without knowing the opening
        # hours.
        client_id = self.base.ajouter_client("M. Deja La", "+33 6 39 98 07 41")
        self.base.ajouter_rendezvous(client_id, f"{jour.isoformat()}T03:00",
                                     "Séance")
        refus = horaires.refus_rendezvous_telephone(
            self.base, preferences, f"{jour.isoformat()}T03:00")
        self.assertIn("DÉJÀ PRISE", refus)
        horaires.ajouter_jour_ferme(preferences, jour.isoformat(), "Congé")
        self.assertIn("FERMÉ", horaires.refus_rendezvous_telephone(
            self.base, preferences, f"{jour.isoformat()}T04:00"))

    def test_une_place_choisie_a_la_main_reste_possible(self):
        """`Exceptionally, I can see people on Saturday`: a slot added by hand in
        the Settings is not judged against the opening hours — it is already a
        user decision.
        """
        samedi = self._lundi_prochain() + datetime.timedelta(days=5)
        self.assertEqual(samedi.weekday(), 5)
        horaire = f"{samedi.isoformat()}T10:00"
        # Without a declaration: Saturday is closed in the standard week.
        self.assertIsNotNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, horaire))
        self.preferences.definir(themes.CLE_CRENEAUX, [horaire])
        self.assertIsNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, horaire))
        # But two people in the same slot, never.
        client_id = self.base.ajouter_client("M. Samedi", "+33 6 39 98 07 41")
        self.base.ajouter_rendezvous(client_id, horaire, "Séance")
        self.assertIn("DÉJÀ PRISE", horaires.refus_rendezvous_telephone(
            self.base, self.preferences, horaire))

    def test_le_creneau_libere_choisi_par_l_utilisateur_n_est_pas_bloque(self):
        """A freed-slot campaign's slot comes from the user: outside opening hours
        it goes through, TAKEN it does not.
        """
        samedi = self._lundi_prochain() + datetime.timedelta(days=5)
        horaire = f"{samedi.isoformat()}T10:00"
        self.assertIsNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, horaire, place_choisie=True))
        horaires.ajouter_jour_ferme(self.preferences, samedi.isoformat(),
                                    "Congé")
        self.assertIn("FERMÉ", horaires.refus_rendezvous_telephone(
            self.base, self.preferences, horaire, place_choisie=True))

    def test_appel_sur_jour_ferme_ne_cree_aucun_rendezvous(self):
        """The audit's scenario: the callback for no. 44 created no. 45 on a
        closed day. Here: no appointment, the old one intact, the reason
        written.

        THE CLOSED DATE IS NOW IMPOSED, and it had to be (18/08/2026). This
        test relied on the fact that the queue offered `appointment + 2 days` —
        a date obtained by formula, which happened to fall on the closed day.
        Since the queue supplies ANOTHER genuinely free slot (see
        `planificateur._support_de_l_appel`), the simulator never offers a
        closed day any more: the test went green while no longer exercising its
        rule at all. So we give it directly the answer the agent might return —
        and that is indeed the question: what the interface refuses by hand,
        the phone must refuse too.
        """
        jour = self._lundi_prochain()
        ferme = jour + datetime.timedelta(days=2)
        horaires.ajouter_jour_ferme(self.preferences, ferme.isoformat(),
                                    "Formation")
        client_id = self.base.ajouter_client("M. Ferme Test",
                                             "+33 6 39 98 07 54")
        rdv_id = self.base.ajouter_rendezvous(
            client_id, f"{jour.isoformat()}T10:00", "Séance", statut="manqué")
        avant = len(self.base.tous_les_rendezvous())
        rdv = self.base.obtenir_rendezvous(rdv_id)
        note = self.planif.appliquer_issue(rdv, {
            "appointment_status": "rescheduled",
            "new_datetime": f"{ferme.isoformat()}T10:00",
            "notes": "Le client propose ce jour-là."})
        self.assertEqual(len(self.base.tous_les_rendezvous()), avant)
        self.assertEqual(self.base.obtenir_rendezvous(rdv_id)["statut"],
                         "manqué")  # NOTHING moved
        self.assertEqual(self.base.obtenir_rendezvous(rdv_id)["horaire"],
                         f"{jour.isoformat()}T10:00")
        self.assertIsNotNone(note)
        self.assertIn("FERMÉ", note)
        # The date obtained over the phone is NOT lost: it is there in clear.
        self.assertIn(f"{ferme:%d/%m/%Y}", note)
        self.assertIn("un humain", note)

    def test_campagne_le_contact_passe_a_rappeler_par_un_humain(self):
        jour = self._lundi_prochain()
        ferme = jour + datetime.timedelta(days=2)
        horaires.ajouter_jour_ferme(self.preferences, ferme.isoformat(), "")
        client_id = self.base.ajouter_client("M. Ferme Campagne",
                                             "+33 6 39 98 07 54")
        rdv_id = self.base.ajouter_rendezvous(
            client_id, f"{jour.isoformat()}T10:00", "Séance")
        campagne_id = self.base.creer_campagne(
            "Essai R3", "confirmation", mission="Bonjour [client].")
        contact_id = self.base.ajouter_contact_campagne(
            campagne_id, 1, "M. Ferme Campagne", "+33 6 39 98 07 54",
            rendezvous_id=rdv_id)
        campagnes._appeler_contact_classique(
            self.base, self.planif, self.preferences,
            self.base.obtenir_campagne(campagne_id),
            self.base.obtenir_contact_campagne(contact_id), tentative=0)
        contact = self.base.obtenir_contact_campagne(contact_id)
        self.assertEqual(contact["etat"], "à rappeler par un humain")
        self.assertEqual(contact["issue"], planificateur.ISSUE_DATE_REFUSEE)
        self.assertIn("FERMÉ", contact["detail"])
        self.assertIn(f"{ferme:%d/%m/%Y}", contact["detail"])
        self.assertEqual(self.base.obtenir_rendezvous(rdv_id)["statut"],
                         "prévu")  # never `deplace`

    def test_une_date_tenable_passe_toujours(self):
        """The safety lock does not block what is possible: counter-test."""
        jour = self._lundi_prochain()
        client_id = self.base.ajouter_client("Mme Date Tenable",
                                             "+33 6 39 98 07 54")
        rdv_id = self.base.ajouter_rendezvous(
            client_id, f"{jour.isoformat()}T10:00", "Séance", statut="manqué")
        appel_id = self.planif.programmer(rdv_id)
        self.planif.executer(seulement=appel_id)
        self.assertIsNone(self.base.obtenir_appel(appel_id)["note"])
        # The SAME row, moved and confirmed — not a second one alongside.
        bouge = self.base.obtenir_rendezvous(rdv_id)
        self.assertEqual(bouge["statut"], "confirmé")
        self.assertNotEqual(bouge["horaire"], f"{jour.isoformat()}T10:00")
        self.assertEqual(len(self.base.tous_les_rendezvous()), 1)

    def test_la_duree_suit_le_deplacement_telephonique(self):
        """The slot checked is that of the WHOLE appointment, and the moved row
        keeps its duration (otherwise the check would lie).
        """
        jour = self._lundi_prochain()
        client_id = self.base.ajouter_client("Mme Longue", "+33 6 39 98 07 54")
        rdv_id = self.base.ajouter_rendezvous(
            client_id, f"{jour.isoformat()}T10:00", "Séance", statut="manqué",
            duree_tranches=2)
        appel_id = self.planif.programmer(rdv_id)
        self.planif.executer(seulement=appel_id)
        lignes = self.base.tous_les_rendezvous()
        self.assertEqual(len(lignes), 1)
        self.assertEqual(lignes[0]["statut"], "confirmé")
        self.assertEqual(lignes[0]["duree_tranches"], 2)


class TestSecuriteCreneauxProposesAuTelephone(unittest.TestCase):
    """R3, OUTBOUND side: the agent receives only GENUINELY free slots."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.preferences = generation.Preferences()
        horaires.definir_semaine(self.preferences,
                                 {jour: [(540, 1080)] for jour in range(5)})

    def test_la_liste_est_recalculee_a_l_instant_de_l_appel(self):
        jour = datetime.date.today() + datetime.timedelta(days=7)
        while jour.weekday() != 0:
            jour += datetime.timedelta(days=1)
        depuis = datetime.datetime.combine(jour, datetime.time())
        liste_avant = horaires.creneaux_lisibles(
            self.base, self.preferences, depuis=depuis, limite=3)
        self.assertIn(date_parlee_de(f"{jour:%Y-%m-%d}T09:00"), liste_avant)
        # A campaign built WITH that list, then the slot gets taken.
        campagne_id = self.base.creer_campagne(
            "Essai créneaux", "confirmation",
            mission=f"Places libres : {liste_avant}.")
        contact_id = self.base.ajouter_contact_campagne(
            campagne_id, 1, "M. Ecoute", "+33 6 39 98 07 51")
        occupant = self.base.ajouter_client("Mme Occupe", "+33 6 39 98 07 41")
        self.base.ajouter_rendezvous(occupant, f"{jour.isoformat()}T09:00",
                                     "Séance")
        configuration = {"infos_auto": {"creneaux_disponibles": liste_avant}}
        mission = assistant.creneaux_adaptes_au_contact(
            self.base, self.preferences, configuration,
            self.base.obtenir_contact_campagne(contact_id),
            self.base.obtenir_campagne(campagne_id)["mission"])
        self.assertNotIn(f"{jour:%d/%m/%Y} à 09h00", mission)  # place prise
        self.assertNotIn("[créneaux_disponibles]", mission)  # nothing invented

    def test_un_jour_ferme_ne_se_propose_jamais(self):
        jour = datetime.date.today() + datetime.timedelta(days=7)
        while jour.weekday() != 0:
            jour += datetime.timedelta(days=1)
        horaires.ajouter_jour_ferme(self.preferences, jour.isoformat(), "Congé")
        depuis = datetime.datetime.combine(jour, datetime.time())
        liste = horaires.creneaux_lisibles(self.base, self.preferences,
                                           depuis=depuis, limite=6)
        self.assertNotIn(f"{jour:%d/%m/%Y}", liste)


class TestSecuriteSuppressionDesarme(unittest.TestCase):
    """R4 - deleting NEVER leaves an armed follow-up behind.

    The audit had brought a deleted client's follow-up to its deadline and seen
    the call GO OUT to a frozen number. Owner's decision: we keep the history,
    we disarm.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.campagne_id = self.base.creer_campagne(
            "Essai R4", "personnalise", mission="Bonjour [client].")

    def _contact_avec_relance(self, nom="Mme Relance Armee",
                              telephone="+33 6 39 98 07 53"):
        contact_id = self.base.ajouter_contact_campagne(
            self.campagne_id, 1, nom, telephone)
        self.base.ajouter_appel_campagne(self.campagne_id, contact_id, 0,
                                         issue="no_answer")
        relance_id = self.base.creer_relance(
            self.campagne_id, contact_id, HIER, tentative=1,
            motif="pas de réponse")
        return contact_id, relance_id

    def test_supprimer_un_client_annule_ses_relances_et_garde_l_histoire(self):
        contact_id, relance_id = self._contact_avec_relance()
        client_id = self.base.client_du_contact(contact_id)
        self.assertEqual(self.base.desarmer_contacts_du_client(client_id), 1)
        self.base.supprimer_client(client_id)
        self.assertEqual(self.base.obtenir_relance(relance_id)["statut"],
                         "annulée")
        self.assertEqual(self.base.relances_dues(), [])
        # The history stays readable: contact and calls are still there.
        contact = self.base.obtenir_contact_campagne(contact_id)
        self.assertIsNotNone(contact)
        self.assertEqual(contact["nom"], "Mme Relance Armee")
        self.assertEqual(len(self.base.appels_du_contact_campagne(contact_id)), 1)

    def test_un_contact_dont_le_client_a_disparu_n_est_plus_compose(self):
        contact_id, _ = self._contact_avec_relance()
        client_id = self.base.client_du_contact(contact_id)
        self.base.supprimer_client(client_id)
        cible = self.base.cible_appel_contact(contact_id)
        self.assertIsNone(cible["telephone"])
        self.assertEqual(cible["refus"], db.REFUS_CLIENT_SUPPRIME)
        self.assertIsNone(self.base.telephone_contact_campagne(contact_id))

    def test_une_relance_reamorcee_a_la_main_ne_compose_toujours_pas(self):
        """Belt and braces: even a follow-up put back to `scheduled` afterwards
        makes nobody's phone ring.
        """
        contact_id, relance_id = self._contact_avec_relance()
        client_id = self.base.client_du_contact(contact_id)
        self.base.supprimer_client(client_id)
        self.base.changer_relance(relance_id, statut="planifiée")
        preferences = generation.Preferences()
        planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=5, latence=0))
        comptes = campagnes.executer_relances_dues(self.base, planif,
                                                   preferences)
        self.assertEqual([c["etat"] for c in comptes], ["exclu"])
        self.assertEqual(len(self.base.appels_du_contact_campagne(contact_id)), 1)
        self.assertEqual(
            self.base.obtenir_contact_campagne(contact_id)["detail"],
            db.REFUS_CLIENT_SUPPRIME)

    def test_retirer_le_jeu_essai_desarme_aussi(self):
        client_id = self.base.ajouter_client("Mme Essai Jetable",
                                             "+33 6 39 98 07 53",
                                             jeu_essai=True)
        contact_id = self.base.ajouter_contact_campagne(
            self.campagne_id, 1, "Mme Essai Jetable", "+33 6 39 98 07 53",
            client_id=client_id)
        relance_id = self.base.creer_relance(self.campagne_id, contact_id,
                                             HIER, tentative=1, motif="essai")
        self.assertEqual(self.base.desarmer_jeu_essai(), 1)
        self.base.supprimer_jeu_essai()
        self.assertEqual(self.base.obtenir_relance(relance_id)["statut"],
                         "annulée")
        self.assertEqual(self.base.relances_dues(), [])
        self.assertEqual(
            self.base.cible_appel_contact(contact_id)["refus"],
            db.REFUS_CLIENT_SUPPRIME)

    def test_un_autre_client_n_est_pas_desarme_au_passage(self):
        contact_id, relance_id = self._contact_avec_relance()
        voisin_contact = self.base.ajouter_contact_campagne(
            self.campagne_id, 2, "M. Voisin Intact", "+33 6 39 98 07 44")
        voisine = self.base.creer_relance(self.campagne_id, voisin_contact,
                                          HIER, tentative=1, motif="voisin")
        client_id = self.base.client_du_contact(contact_id)
        self.base.supprimer_client(client_id)
        self.assertEqual(self.base.obtenir_relance(voisine)["statut"],
                         "planifiée")
        self.assertIsNotNone(
            self.base.cible_appel_contact(voisin_contact)["telephone"])


class TestSecuriteSuppressionClientWeb(_TestAvecServeurWeb):
    """R4, end to end: the page says so, and nothing goes out any more."""

