class TestImportICSHeureDeFin(unittest.TestCase):
    """Q8, import side — the imported calendar carries its REAL duration.

    Without DTEND, every event was worth a single slice: a one-hour
    consultation let the schedule sell three slots that did not exist.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.preferences = generation.Preferences()

    @staticmethod
    def _ics(*evenements):
        corps = "\n".join(evenements)
        return f"BEGIN:VCALENDAR\nVERSION:2.0\n{corps}\nEND:VCALENDAR"

    def test_une_heure_fait_quatre_tranches_de_quinze_minutes(self):
        texte = self._ics(
            "BEGIN:VEVENT\nSUMMARY:Mme Longue — Consultation\n"
            "DTSTART:20260810T090000\nDTEND:20260810T100000\nEND:VEVENT")
        importes, erreurs = ics.importer_ics(self.base, texte, self.preferences)
        self.assertEqual((importes, erreurs), (1, []))
        rdv = self.base.tous_les_rendezvous()[0]
        self.assertEqual(rdv["duree_tranches"], 4)

    def test_la_duration_remplace_l_heure_de_fin(self):
        texte = self._ics(
            "BEGIN:VEVENT\nSUMMARY:M. Duree — Contrôle\n"
            "DTSTART:20260810T140000\nDURATION:PT45M\nEND:VEVENT")
        ics.importer_ics(self.base, texte, self.preferences)
        self.assertEqual(self.base.tous_les_rendezvous()[0]["duree_tranches"], 3)

    def test_l_arrondi_se_fait_au_superieur(self):
        """20 minutes at a 15-minute step: 2 slices. Better to book one slice too
        many than to sell a slot already taken.
        """
        texte = self._ics(
            "BEGIN:VEVENT\nSUMMARY:Mme Bizarre — Vingt minutes\n"
            "DTSTART:20260810T110000\nDTEND:20260810T112000\nEND:VEVENT")
        ics.importer_ics(self.base, texte, self.preferences)
        self.assertEqual(self.base.tous_les_rendezvous()[0]["duree_tranches"], 2)

    def test_sans_heure_de_fin_une_seule_tranche_comme_avant(self):
        texte = self._ics(
            "BEGIN:VEVENT\nSUMMARY:M. Court — Rapide\n"
            "DTSTART:20260810T160000\nEND:VEVENT")
        ics.importer_ics(self.base, texte, self.preferences)
        self.assertEqual(self.base.tous_les_rendezvous()[0]["duree_tranches"], 1)

    def test_une_fin_anterieure_au_debut_ne_change_rien(self):
        texte = self._ics(
            "BEGIN:VEVENT\nSUMMARY:Mme Abimee — Fin avant début\n"
            "DTSTART:20260810T160000\nDTEND:20260810T150000\nEND:VEVENT")
        ics.importer_ics(self.base, texte, self.preferences)
        self.assertEqual(self.base.tous_les_rendezvous()[0]["duree_tranches"], 1)

    def test_le_pas_regle_est_respecte(self):
        self.preferences.definir(horaires.CLE_PAS, 30)
        texte = self._ics(
            "BEGIN:VEVENT\nSUMMARY:Mme Longue — Consultation\n"
            "DTSTART:20260810T090000\nDTEND:20260810T100000\nEND:VEVENT")
        ics.importer_ics(self.base, texte, self.preferences)
        self.assertEqual(self.base.tous_les_rendezvous()[0]["duree_tranches"], 2)

    def test_l_heure_importee_bloque_vraiment_les_places(self):
        """The useful proof: all four slices really are occupied."""
        horaires.definir_semaine(self.preferences,
                                 {jour: [(540, 1080)] for jour in range(7)})
        texte = self._ics(
            "BEGIN:VEVENT\nSUMMARY:Mme Longue — Consultation\n"
            "DTSTART:20260810T090000\nDTEND:20260810T100000\nEND:VEVENT")
        ics.importer_ics(self.base, texte, self.preferences)
        occupees = horaires.tranches_occupees(self.base, self.preferences,
                                              datetime.date(2026, 8, 10))
        attendues = {datetime.datetime(2026, 8, 10, 9, 0)
                     + datetime.timedelta(minutes=15 * rang)
                     for rang in range(4)}
        self.assertEqual(set(occupees), attendues)


class TestEcheanceRelanceJoursOuverts(unittest.TestCase):
    """Q9 — `Follow-ups must match the authorised communication settings and fall
    outside the closing dates`.

    The computation only knew about the time window: a follow-up requested on a
    Friday evening fell due on SATURDAY, a day when nobody works.
    """

    VENDREDI_SOIR = datetime.datetime(2026, 7, 31, 18, 0)

    def setUp(self):
        self.preferences = generation.Preferences()
        horaires.definir_semaine(self.preferences,
                                 {jour: [(540, 1140)] for jour in range(5)})

    def _echeance(self, preferences=None, heures=4):
        return campagnes.echeance_apres_heures_ouvrees(
            self.VENDREDI_SOIR, heures, "09:00", "19:00", preferences)

    def test_avant_l_echeance_tombait_le_samedi(self):
        """The FAULTY behaviour, reproduced: without the settings, Saturday."""
        avant = self._echeance()
        self.assertEqual(avant, datetime.datetime(2026, 8, 1, 12, 0))
        self.assertEqual(avant.weekday(), 5)          # samedi

    def test_apres_l_echeance_tombe_le_lundi(self):
        apres = self._echeance(self.preferences)
        self.assertEqual(apres, datetime.datetime(2026, 8, 3, 12, 0))
        self.assertEqual(apres.weekday(), 0)          # lundi

    def test_un_jour_ferme_declare_est_saute_aussi(self):
        horaires.ajouter_jour_ferme(self.preferences, "2026-08-03", "Pont")
        apres = self._echeance(self.preferences)
        self.assertEqual(apres, datetime.datetime(2026, 8, 4, 12, 0))

    def test_la_periode_interdite_ne_compte_pas_comme_heure_ouvree(self):
        """12pm-2pm forbidden: those two hours no longer count, and the deadline
        never falls inside them.
        """
        self.preferences.definir(assistant.CLE_INTERDIT_DEBUT, "12:00")
        self.preferences.definir(assistant.CLE_INTERDIT_FIN, "14:00")
        apres = self._echeance(self.preferences)
        self.assertEqual(apres, datetime.datetime(2026, 8, 3, 14, 0))

    def test_sans_semaine_type_reglee_rien_ne_change(self):
        """RingBack does not GUESS the working days: without a standard week, the
        computation stays exactly what it was.
        """
        vierges = generation.Preferences()
        self.assertEqual(self._echeance(vierges), self._echeance())

    def test_la_butee_ne_part_pas_en_boucle_infinie(self):
        """Everything closed: we stop searching, we say so in the log, and we fall
        back on the window alone — the follow-up is never lost.
        """
        horaires.definir_semaine(self.preferences,
                                 {jour: [(540, 1140)] for jour in range(7)})
        for rang in range(campagnes.JOURS_CHERCHES_ECHEANCE + 2):
            jour = self.VENDREDI_SOIR.date() + datetime.timedelta(days=rang)
            horaires.ajouter_jour_ferme(self.preferences, jour.isoformat())
        with self.assertLogs("ringback.campagnes", level="WARNING") as journal:
            repli = self._echeance(self.preferences)
        self.assertEqual(repli, self._echeance())     # plage seule
        self.assertIn("Aucun jour ouvert", "\n".join(journal.output))

    def test_le_creneau_de_rappel_quotidien_saute_aussi_le_week_end(self):
        """The other follow-up mode (`every day between 12pm and 2pm`) obeys the
        same day rule.
        """
        options = {"relance_mode": "creneau", "relance_creneau_debut": "12:00",
                   "relance_creneau_fin": "14:00"}
        echeance = assistant.echeance_relance_campagne(
            self.preferences, options, self.VENDREDI_SOIR)
        self.assertEqual(echeance, "2026-08-03T12:00")


class TestAnnuleHorsDesRendezVousAVenir(unittest.TestCase):
    """Owner's correction (31/07/2026) — `a cancelled appointment no longer
    exists`: it leaves `Upcoming appointments`.

    The previous gain is KEPT: a confirmed appointment does stay displayed —
    `ce n'est pas un contact qui disparait, mais une ligne qui evolue`. The two
    rules do not contradict each other: `upcoming` means the appointments that
    HOLD (scheduled, confirmed).
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.client_id = self.base.ajouter_client("Mme Test Exemple",
                                                  "+33 6 39 98 50 42")

    def test_l_annule_sort_de_a_venir_le_confirme_y_reste(self):
        prevu = self.base.ajouter_rendezvous(self.client_id, DEMAIN, "Prévu")
        confirme = self.base.ajouter_rendezvous(self.client_id, DEMAIN,
                                                "Confirmé", statut="confirmé")
        annule = self.base.ajouter_rendezvous(self.client_id, DEMAIN, "Annulé",
                                              statut="annulé")
        vus = {rdv["id"] for rdv in self.base.rendezvous_a_venir_tous()}
        self.assertEqual(vus, {prevu, confirme})
        self.assertNotIn(annule, vus)
        # Nothing is lost: the cancelled one stays in `Tous les rendez-vous`.
        self.assertIn(annule, {r["id"] for r in self.base.tous_les_rendezvous()})

    def test_le_prochain_rendezvous_d_un_client_ignore_l_annule(self):
        """The client record announced `next: 6 August` for a CANCELLED
        appointment — a false display, and the calendar state wrongly deduced
        `appointment scheduled` from it.
        """
        annule = self.base.ajouter_rendezvous(self.client_id, DEMAIN,
                                              "Annulé", statut="annulé")
        resume = self.base.etat_rendezvous_par_client()[self.client_id]
        self.assertIsNone(resume["prochain"])
        self.assertEqual(resume["statuts"], {"annulé": 1})  # nothing is lost
        self.assertEqual(etats_clients.etat_agenda(resume),
                         "rendez-vous annulé")
        # An appointment that HOLDS does come back as `next`.
        prevu = self.base.ajouter_rendezvous(self.client_id, DEMAIN, "Prévu")
        resume = self.base.etat_rendezvous_par_client()[self.client_id]
        self.assertEqual(resume["prochain"]["id"], prevu)
        self.assertNotEqual(resume["prochain"]["id"], annule)

    def test_le_deplace_et_l_ignore_sortent_aussi(self):
        """The OLD row of a moved appointment, and an ignored appointment, hold no
        better: only the new date counts.
        """
        ancien = self.base.ajouter_rendezvous(self.client_id, DEMAIN, "Ancien",
                                              statut="déplacé")
        ignore = self.base.ajouter_rendezvous(self.client_id, DEMAIN, "Ignoré",
                                              statut="ignoré")
        self.assertEqual(self.base.rendezvous_a_venir_tous(), [])
        garde = {r["id"] for r in self.base.tous_les_rendezvous()}
        self.assertEqual(garde, {ancien, ignore})


class TestEtatLeClientRappellera(unittest.TestCase):
    """The NEW state: `the client will call back`.

    They cancelled without setting a date: it is THEY who get back in touch. We
    do not follow up, we build no campaign for them — but they stay visible and
    counted in Clients. Not to be confused with `to be rescheduled`, where it
    is WE who must call back to set a date.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.preferences = generation.Preferences()

    def _fiche(self, issue):
        client_id = self.base.ajouter_client("Mme Annule", "+33 6 39 98 00 52")
        campagne_id = self.base.creer_campagne("Rappel du jour", "rappel_rdv",
                                               nature="rappel_rdv",
                                               statut="terminée")
        contact_id = self.base.ajouter_contact_campagne(
            campagne_id, 1, "Mme Annule", "+33 6 39 98 00 52",
            client_id=client_id)
        self.base.changer_etat_contact_campagne(
            contact_id,
            assistant.ETAT_RAPPELLERA if issue == "canceled"
            else "à rappeler par un humain", issue)
        fiches = etats_clients.tableau_clients(self.base, self.preferences)
        return next(f for f in fiches if f["client"]["id"] == client_id)

    def test_une_annulation_donne_l_etat_et_aucune_campagne(self):
        fiche = self._fiche("canceled")
        self.assertEqual(fiche["conversation"], "le client rappellera")
        # No action expected: they NEVER become an automatic task.
        self.assertEqual(fiche["besoins"], [])
        self.assertFalse(fiche["non_traite"])
        self.assertFalse(fiche["humain"])
        # And the screen says WHY, distinguishing it from `to be rescheduled`.
        self.assertIn("c'est LUI qui reprendra contact",
                      fiche["sans_campagne"])
        self.assertIn("à reprogrammer", fiche["sans_campagne"])

    def test_a_reprogrammer_reste_une_tache_a_nous(self):
        """The neighbouring state, so that the difference is MEASURED and not
        merely stated.

        `to be rescheduled`: it is WE who must call back to set a date — a
        booking campaign handles it. `the client will call back`: it is THEY —
        no campaign will ever handle it.
        """
        fiche = self._fiche("to_reschedule")
        self.assertEqual(fiche["conversation"], "à reprogrammer")
        self.assertEqual([b["natures"] for b in fiche["besoins"]],
                         [("prise_rdv",)])
        self.assertTrue(fiche["non_traite"])
        self.assertIsNone(fiche["sans_campagne"])
        # The other state is in NO handling table.
        self.assertIn("à reprogrammer", etats_clients.TRAITEMENT)
        self.assertNotIn("le client rappellera", etats_clients.TRAITEMENT)

    def test_l_etat_est_filtrable_et_compte_dans_la_liste(self):
        fiche = self._fiche("canceled")
        self.assertIn("le client rappellera", etats_clients.ETATS_CONVERSATION)
        retenues = etats_clients.filtrer([fiche], etat="le client rappellera")
        self.assertEqual(len(retenues), 1)
        # The `not handled` filter NEVER brings it back: nothing is waiting for
        # it.
        self.assertEqual(etats_clients.filtrer([fiche], non_traite=True), [])


class TestEntonnoirDesDates(unittest.TestCase):
    """HIS METHOD, ASKED FOR ON 16/08 AND REPEATED ON 31/08: `qu'il propose
    d'abord des jours, puis matin ou apres-midi, puis qu'il propose une heure.
    En fonction des reponses, soit le patient accepte, soit il demande de
    preciser les jours et LE FILTRE REPREND.`

    The move had it since 16/08. The confirmation and the appointment callback
    did not: they quoted a list and waited. Yet all three do the same thing —
    offer a date to somebody who does not want one yet.

    AND THE RESTART WAS MISSING FROM ALL THREE. The script said what to do when
    the agent has NO matching hour; it said nothing about the most frequent
    case — the person refuses the hour offered. The agent then reeled off hours
    one after another: exactly the enumeration we are trying to avoid.
    """

    NATURES = ("deplacement", "confirmation", "rappel_rdv")
    INFOS = {"entreprise": "Cabinet Essai", "raison": "un imprévu",
             "creneaux_annulation": "le mardi 1 septembre 2026 à 8 heures",
             "creneau_le_plus_proche": "le mardi 1 septembre 2026 à 8 heures",
             "creneaux_remplacement": "le mardi 1 septembre 2026 à 8 heures"}

    def _conduite(self, nature):
        """The script lines ACTUALLY dictated, in order."""
        cadre = assistant.construire_consigne(
            nature, self.INFOS, _PreferencesMuettes(),
            {assistant.CLE_REPLACER_ANNULATION: True})
        texte = cadre.texte()
        self.assertIn(consigne.TITRE_CONDUITE, texte)
        bloc = texte.split(consigne.TITRE_CONDUITE)[1]
        bloc = bloc.split(consigne.TITRE_CONTRAINTES)[0]
        return [l.strip() for l in bloc.splitlines() if l.strip()]

    def test_les_trois_natures_dictent_le_MEME_entonnoir(self):
        """THE RULE, NOT THE CASE. A method copied into three kinds diverges at
        the first touch-up: it is written once (`assistant._ENTONNOIR`) and the
        three take it up. This test checks that on the DICTATED TEXT, not on
        the table.
        """
        for nature in self.NATURES:
            with self.subTest(nature=nature):
                dit = " ".join(self._conduite(nature))
                for ligne in assistant._ENTONNOIR:
                    # The pictogram and the punctuation survive as they are; we
                    # look for the core of each step.
                    self.assertIn(ligne.rstrip(" ;"), dit)

    def test_l_ordre_est_jours_puis_demi_journee_puis_heure(self):
        """THE ORDER IS THE METHOD. Asking for the hour before the day means
        asking again at every refusal — exactly what he no longer wants.
        """
        for nature in self.NATURES:
            with self.subTest(nature=nature):
                dit = " ".join(self._conduite(nature))
                jours = dit.index("quels JOURS de la semaine")
                demi = dit.index("le MATIN ou l'APRÈS-MIDI")
                heure = dit.index("propose alors UNE SEULE heure")
                self.assertLess(jours, demi)
                self.assertLess(demi, heure)

    def test_le_filtre_REPREND_a_chaque_refus(self):
        """THE POINT THAT WAS MISSING FROM ALL THREE (31/08/2026). Without this
        line, the agent reels off hours instead of redoing the sorting.
        """
        for nature in self.NATURES:
            with self.subTest(nature=nature):
                dit = " ".join(self._conduite(nature))
                self.assertIn("REPRENDS LE FILTRE", dit)
                # AND IT IS SAID AFTER the hour: restarting before would make
                # no sense, there is nothing to restart yet.
                self.assertLess(dit.index("propose alors UNE SEULE heure"),
                                dit.index("REPRENDS LE FILTRE"))

    def test_une_heure_a_la_fois_jamais_une_liste(self):
        """His transcript of 31/08: six dates read one after another, `none` in
        answer. The script now says it twice — when offering, and when
        restarting.
        """
        for nature in self.NATURES:
            with self.subTest(nature=nature):
                dit = " ".join(self._conduite(nature))
                self.assertIn("UNE SEULE heure", dit)
                self.assertIn("Une heure à la fois, jamais une liste", dit)

    def test_la_confirmation_ne_l_ouvre_QU_APRES_un_non(self):
        """THE COUNTER-TEST, and it is his request of 31/08: the funnel does not
        open straight away. On a confirmation, it comes AFTER the question and
        AFTER the `I cannot come`.
        """
        for nature in ("confirmation", "rappel_rdv"):
            with self.subTest(nature=nature):
                lignes = self._conduite(nature)
                dit = " ".join(lignes)
                self.assertLess(dit.index("Ne cite AUCUNE date"),
                                dit.index("quels JOURS de la semaine"))
                self.assertLess(dit.index("si elle ne peut pas venir"),
                                dit.index("quels JOURS de la semaine"))

    def test_le_deplacement_l_ouvre_des_le_premier_refus(self):
        """AND IT IS RIGHT, DESPITE THE DIFFERENCE. A move announces from the
        start that the appointment MUST move: there is no `no` to expect, the
        first date is offered immediately.
        """
        lignes = self._conduite("deplacement")
        self.assertIn("commence par proposer LA date la plus proche",
                      lignes[0])
        dit = " ".join(lignes)
        self.assertNotIn("Ne cite AUCUNE date", dit)

    def test_chaque_nature_garde_sa_propre_sortie(self):
        """The trunk is shared, the ENDING is not: a move sends the contact to a
        human, a confirmation cancels the appointment.
        """
        depl = " ".join(self._conduite("deplacement"))
        self.assertIn("va vous rappeler pour convenir d'une date", depl)
        self.assertIn("conclus alors sur AUTRE, sans date", depl)
        for nature in ("confirmation", "rappel_rdv"):
            with self.subTest(nature=nature):
                dit = " ".join(self._conduite(nature))
                self.assertIn("son rendez-vous est annulé", dit)
                self.assertNotIn("va vous rappeler pour convenir", dit)


class TestPlacesDeRemplacementEtalees(unittest.TestCase):
    """HIS REQUEST OF 31/08/2026, noted on a REAL call: `ses dates c'etait tous
    les memes jours, ce serait bien qu'il recherche des dates a des jours
    differents, mais pas trop lointain (max 7 jours) ; le matin et l'apres-midi
    d'une meme journee cela me convient aussi. Bien entendu, il faut s'assurer
    que les dates proposees sont libres avant de les proposer.`

    WHAT HIS TRANSCRIPT SHOWED, word for word: `le mardi 1 septembre 2026 a 8
    heures 20, ... a 9 heures 20, ... a 9 heures 40, ... a 10 heures 20, ... a
    11 heures, ... a 11 heures 40.` SIX TIMES THE SAME DAY — and the very day
    of the appointment she had just said she could not attend. `None`, she
    answered.
    """

    LUNDI = datetime.datetime(2026, 9, 7, 0, 0)  # a Monday, empty calendar

    def _prefs(self):
        preferences = generation.Preferences()
        horaires.definir_semaine(preferences,
                                 {j: [(8 * 60, 18 * 60)] for j in range(5)})
        return preferences

    def _places(self, base=None, prefs=None):
        base = base or db.Base(":memory:")
        return horaires.places_de_remplacement(base, prefs or self._prefs(),
                                               depuis=self.LUNDI)

    @staticmethod
    def _jours(places):
        return sorted({p[:10] for p in places})

    def test_des_jours_differents_et_pas_tous_le_meme_matin(self):
        """THE HEART OF HIS REQUEST, measured on the DAYS. Six consecutive slots
        in one morning cannot be negotiated: `no` on the first is `no` on all
        six.
        """
        places = self._places()
        self.assertTrue(places, "aucune place proposable")
        self.assertGreaterEqual(
            len(self._jours(places)), 3,
            f"les places tiennent sur {len(self._jours(places))} journée(s)")
        # AND AT MOST ONE PER HALF-DAY while there are still days to cover:
        # that is what stops the whole morning.
        demi = [(p[:10], int(p[11:13]) < horaires.HEURE_BASCULE_MIDI)
                for p in places]
        self.assertEqual(len(demi), len(set(demi)),
                         f"deux places dans la même demi-journée : {places}")

    def test_le_matin_ET_l_apres_midi(self):
        """`morning and afternoon of the same day suits me too`: both halves of
        the day are represented.
        """
        places = self._places()
        heures = [int(p[11:13]) for p in places]
        self.assertTrue([h for h in heures if h < horaires.HEURE_BASCULE_MIDI],
                        "aucune place le matin")
        self.assertTrue([h for h in heures if h >= horaires.HEURE_BASCULE_MIDI],
                        "aucune place l'après-midi")

    def test_rien_au_dela_de_sept_jours(self):
        """`not too far off (max 7 days)` — his bound, counted from the FIRST free
        slot and not from today: a calendar full for eight days would otherwise
        return an empty list.

        A CALENDAR THAT FORCES THE BOUND TO BE CROSSED IS NEEDED. On a week
        open throughout, the six slots fit into three days: the bound is never
        reached, and this test went green even with it removed. One open day a
        week, and three Mondays — fourteen days — are needed to find six.
        """
        preferences = generation.Preferences()
        horaires.definir_semaine(preferences, {0: [(8 * 60, 18 * 60)]})
        places = horaires.places_de_remplacement(db.Base(":memory:"),
                                                 preferences,
                                                 depuis=self.LUNDI)
        self.assertTrue(places, "aucune place proposable")
        jours = self._jours(places)
        self.assertGreater(len(jours), 1, "un seul jour : la borne ne joue pas")
        ecart = (datetime.date.fromisoformat(jours[-1])
                 - datetime.date.fromisoformat(jours[0])).days
        # THE FIGURE, WRITTEN. Comparing with `JOURS_REMPLACEMENT_MAX` made
        # this test incapable of failing: raising the constant to 400 left it
        # green. A test that compares itself with what it guards guards
        # nothing.
        self.assertLessEqual(ecart, 7)
        # And the constant does SAY seven: the day it changes, this test will
        # say so instead of following in silence.
        self.assertEqual(horaires.JOURS_REMPLACEMENT_MAX, 7)

    def test_une_poignee_pas_un_catalogue(self):
        """We QUOTE them aloud, one by one: beyond a handful, nobody listens. That
        is what distinguishes this computation from the STOCK of a move
        negotiation.
        """
        self.assertLessEqual(len(self._places()),
                             horaires.PLACES_REMPLACEMENT)

    def test_elles_sont_toutes_LIBRES(self):
        """`we must make sure the dates offered are free`. We check it with the
        product's own check — the one that refuses a date agreed over the
        phone.
        """
        base, prefs = db.Base(":memory:"), self._prefs()
        places = self._places(base, prefs)
        self.assertTrue(places)
        for place in places:
            with self.subTest(place=place):
                self.assertIsNone(
                    horaires.refus_rendezvous_telephone(base, prefs, place))

    def test_une_place_deja_prise_n_est_jamais_proposee(self):
        """THE COUNTER-TEST of the previous one: it would be green on an empty
        calendar whatever happened. We OCCUPY the first slot and check that it
        disappears.
        """
        base, prefs = db.Base(":memory:"), self._prefs()
        premiere = self._places(base, prefs)[0]
        client = base.ajouter_client("M. Occupant", "+33 6 39 98 50 51")
        base.ajouter_rendezvous(client, premiere, "Séance", statut="prévu")
        self.assertNotIn(premiere, self._places(base, prefs))

    def test_sans_horaire_ouvert_on_ne_propose_rien(self):
        """Never an invented date: without a standard week, the list is empty and
        the message loses its sentence (see TestOptionAnnulationDansLeMessage).
        """
        self.assertEqual(
            horaires.places_de_remplacement(db.Base(":memory:"),
                                            generation.Preferences(),
                                            depuis=self.LUNDI),
            [])


class TestOptionAnnulationDansLeMessage(unittest.TestCase):
    """The campaign option `offer another date if the client cancels` REALLY
    changes the text dictated to the agent (step 2's `if` mechanism).
    """

    def setUp(self):
        self.preferences = generation.Preferences()

    def _mission(self, nature, active):
        infos = {"entreprise": "Cabinet Essai",
                 "creneaux_annulation": "mardi 9h00, jeudi 14h30"}
        return assistant.construire_mission(
            nature, infos, self.preferences,
            {assistant.CLE_REPLACER_ANNULATION: active})

    def test_option_active_l_ouverture_PROMET_sans_reciter(self):
        """HIS REQUEST OF 31/08/2026, noted on a REAL call: `avant meme que je
        confirme ou non ma presence, il m'a tout de suite liste les differentes
        dates [...] Il faut d'abord attendre que le client dise non avant de
        proposer une date.`

        The opening ANNOUNCES that another date is possible; it no longer
        recites them. The slots stay in `what you know`, and the script tells
        the agent when to bring them out.
        """
        for nature in ("rappel_rdv", "confirmation"):
            with self.subTest(nature=nature):
                texte = self._mission(nature, True)
                self.assertIn("je peux vous proposer une autre date", texte)
                self.assertNotIn("mardi 9h00", texte)
                self.assertIn("c'est vous qui nous rappelez", texte)
                self.assertNotIn("je ne vous propose pas d'autre date", texte)
                # AND THE AGENT STILL HAS THEM: without that, we would have
                # removed the dates from the call instead of delaying them.
                cadre = assistant.construire_consigne(
                    nature, {"entreprise": "Cabinet Essai",
                             "creneaux_annulation": "mardi 9h00, jeudi 14h30"},
                    self.preferences,
                    {assistant.CLE_REPLACER_ANNULATION: True})
                dit = cadre.texte()
                self.assertIn("mardi 9h00, jeudi 14h30", dit)
                self.assertIn("Ne cite AUCUNE date tant qu'elle n'a pas "
                              "répondu", dit)

    def test_option_inactive_l_agent_ne_propose_rien(self):
        for nature in ("rappel_rdv", "confirmation"):
            texte = self._mission(nature, False)
            self.assertIn("je ne vous propose pas d'autre date", texte)
            self.assertIn("c'est vous qui nous rappelez", texte)
            self.assertNotIn("mardi 9h00", texte)

    def test_l_option_n_est_proposee_que_la_ou_elle_change_le_message(self):
        for nature in ("rappel_rdv", "confirmation"):
            self.assertTrue(assistant.option_annulation_utile(nature))
        for nature in ("creneau_libere", "prise_rdv", "deplacement"):
            self.assertFalse(assistant.option_annulation_utile(nature))

    def test_sans_place_a_annoncer_on_ne_promet_RIEN(self):
        """THE SAFETY LOCK MOVED ON 31/08/2026, and it had to.

        Before, the sentence carried the list: without a slot, it fell away at
        the last moment (a sentence with an empty [bracket] is removed at call
        time). By taking the list out of the opening — his request — the
        sentence no longer had a bracket: so it could no longer fall away, and
        the agent promised `I can offer you another date` in front of a full
        calendar.

        The condition is now DECLARED: that segment is only written if the
        option is ticked AND there are slots.
        """
        texte = assistant.construire_mission(
            "confirmation", {"entreprise": "Cabinet Essai"}, self.preferences,
            {assistant.CLE_REPLACER_ANNULATION: True})
        self.assertNotIn("je peux vous proposer une autre date", texte)
        self.assertIn("je ne vous propose pas d'autre date", texte)

    def test_avec_des_places_la_promesse_revient(self):
        """THE COUNTER-TEST: the safety lock must not carry everything away."""
        texte = assistant.construire_mission(
            "confirmation", {"entreprise": "Cabinet Essai",
                             "creneaux_annulation": "mardi 9h00"},
            self.preferences, {assistant.CLE_REPLACER_ANNULATION: True})
        self.assertIn("je peux vous proposer une autre date", texte)
        self.assertNotIn("je ne vous propose pas d'autre date", texte)
        # AND ONLY ONE OF THE TWO SENTENCES: they would contradict each other.
        self.assertEqual(texte.count("c'est vous qui nous rappelez"), 1)


class TestAnnulationBoutEnBout(_CampagneAssistant):
    """The two cancellation settings, played out FOR REAL.

    Without the option: the client cancels, their appointment is cancelled,
    they become `the client will call back`, NO follow-up is scheduled and NO
    campaign takes them up. With the option and a client who accepts another
    date: it is a MOVE, with its move row in the change log.
    """

    def _rendezvous(self, terminaison, jours):
        base = self.application.base
        horaire = (datetime.datetime.now() + datetime.timedelta(days=jours)
                   ).replace(hour=9, minute=0, second=0, microsecond=0
                             ).isoformat(timespec="minutes")
        client_id = base.ajouter_client(f"Mme Annulante {terminaison}",
                                        f"+33 6 39 98 50 {terminaison}")
        rdv_id = base.ajouter_rendezvous(client_id, horaire, "Séance")
        ligne = (f"Mme Annulante {terminaison};+33 6 39 98 50 {terminaison};"
                 f"{horaire};Séance")
        return client_id, rdv_id, horaire, ligne

    def test_rien_de_conclu_annule_le_rendez_vous(self):
        """HIS RULE OF 17/08/2026, word for word: `si la personne doit rappeler,
        le rendez-vous est simplement annule`.

        Before, that path — the ending 55, `wants to move without concluding` —
        left the appointment INTACT: the slot stayed blocked for somebody who
        had just said they would not come as planned, and the practice kept a
        gap without knowing it.

        `Cancelled`, not `deleted`: the row stays on the schedule and its slot
        becomes free again, so a freed-slot campaign can take it up.
        """
        base = self.application.base
        client_id, rdv_id, horaire, ligne = self._rendezvous("55", 5)
        campagne_id = self._campagne("rappel_rdv", [ligne])
        etats = self._derouler(campagne_id)
        contact = etats[f"Mme Annulante 55"]
        self.assertEqual(contact["issue"], "to_reschedule")
        self.assertEqual(contact["etat"], assistant.ETAT_RAPPELLERA)
        # THE HEART: the appointment is cancelled, and its slot is given back.
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"], "annulé")
        self.assertIn("ANNULÉ", contact["detail"])
        # ONE ROW IN THE CHANGE LOG: the operator has that change to carry over
        # into their own software. A silent cancellation would make them keep
        # the slot blocked — that is the defect being fixed, not a detail.
        lignes = [l for l in base.changements_de_campagne(campagne_id)
                  if l["genre"] == "annulation"]
        self.assertEqual(len(lignes), 1)
        self.assertEqual(lignes[0]["ancienne_date"], horaire)
        self.assertIn("rappellera", lignes[0]["raison"])
        # And the slot really is GIVEN BACK: `annule` is among the statuses
        # that no longer hold a slot (db.STATUTS_SANS_PLACE), so the schedule
        # turns it green again. That is what lets a freed-slot campaign take it
        # up.
        self.assertIn("annulé", db.STATUTS_SANS_PLACE)

    def test_le_cahier_dit_le_meme_mot_que_le_rendez_vous(self):
        """HIS DEFECT NO. 5 OF 18/08/2026: the change log said `deleted` and
        `cancelled` for the SAME row.

        Measured on his day: CHANGE column `Rendez-vous supprime`, WHY column
        `il reste marque " annule "`, and in the database the status was indeed
        `annule`. The exported CSV file said the same. Three words for a single
        event, in the document whose whole purpose is to be RETYPED into
        another piece of software.

        And it is not just a word: the two states do not call for the same
        gesture. `deleted` = the slot reopens, there is a slot to free in the
        practice's software; `cancelled` = the slot stays blocked. Carrying
        over `deleted` where the product wrote `cancelled` means reopening a
        slot that is not open.

        The test bears on the RULE, not on a case: whatever the change log's
        removal row, its word must say what the appointment says.
        """
        base = self.application.base
        preferences = self.application.preferences
        # ON BOTH SIDES OF THE THRESHOLD, otherwise the test only compares one
        # branch: an appointment in 2 h (below -> `cancelled`, the slot stays
        # blocked) and one in 10 days (above -> `deleted`, it reopens).
        preferences.definir(horaires.CLE_SEUIL_REMPLACEMENT, "12")
        lignes = []
        for terminaison, heures in (("52", 2), ("62", 10 * 24)):
            horaire = (datetime.datetime.now()
                       + datetime.timedelta(hours=heures)).replace(
                           minute=0, second=0, microsecond=0).isoformat(
                               timespec="minutes")
            nom = f"Mme Annulante {terminaison}"
            client_id = base.ajouter_client(nom, f"+33 6 39 98 50 {terminaison}")
            base.ajouter_rendezvous(client_id, horaire, "Séance")
            lignes.append(f"{nom};+33 6 39 98 50 {terminaison};{horaire};Séance")
        campagne_id = self._campagne("rappel_rdv", lignes, opt_replacer="1")
        self._derouler(campagne_id)

        retraits = [l for l in base.changements_de_campagne(campagne_id)
                    if l["genre"] in assistant.GENRES_QUI_RETIRENT
                    and l["rendezvous_id"]]
        self.assertTrue(retraits, "aucune ligne de retrait : l'essai ne "
                                  "compare rien")
        mots = set()
        for ligne in retraits:
            statut = base.obtenir_rendezvous(ligne["rendezvous_id"])["statut"]
            with self.subTest(qui=ligne["nom"], statut=statut):
                # THE HEART: the change log's word says what the appointment
                # says.
                self.assertEqual(ligne["genre"],
                                 horaires.genre_de_retrait(statut),
                                 f"le cahier dit « {ligne['genre']} » pour un "
                                 f"rendez-vous « {statut} »")
                libelle = assistant.GENRES_CHANGEMENT[ligne["genre"]][1]
                mots.add(libelle)
                # And the REASON, which quotes the status in plain words, does
                # not contradict it: it is that contradiction he had before his
                # eyes.
                contraire = ("annulé" if statut == db.STATUT_SUPPRIME
                             else "supprimé")
                self.assertNotIn(contraire, libelle.lower())
                # The change-log row still carries its date, in both kinds
                # (`cancellation` showed none).
                lisible = assistant.ligne_cahier(ligne)
                self.assertIn(assistant.date_courte(ligne["ancienne_date"])[:5],
                              lisible)
        # WERE BOTH BRANCHES WALKED? Without both, the rule is only half
        # exercised — and it is precisely the missing half that caused the
        # defect.
        self.assertEqual(mots, {"Rendez-vous supprimé", "Rendez-vous annulé"},
                         f"une seule branche du seuil parcourue : {mots}")

    def test_sans_l_option_le_client_rappellera_et_rien_ne_part(self):
        base = self.application.base
        client_id, rdv_id, horaire, ligne = self._rendezvous("52", 4)
        campagne_id = self._campagne("rappel_rdv", [ligne])
        # The option really is UNTICKED: the message says so in black and
        # white.
        campagne = base.obtenir_campagne(campagne_id)
        configuration = assistant.configuration_campagne(campagne)
        self.assertFalse(configuration["options"].get(
            assistant.CLE_REPLACER_ANNULATION))
        self.assertIn("je ne vous propose pas d'autre date",
                      campagne["mission"])
        etats = self._derouler(campagne_id)
        contact = etats["Mme Annulante 52"]
        self.assertEqual(contact["etat"], "le client rappellera")
        # Their appointment was in 4 days, hence more than 12 h away: it is
        # DELETED, not `cancelled` (that one is reserved for the past).
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"],
                         db.STATUT_SUPPRIME)
        # NO follow-up scheduled, NO campaign built for them.
        self.assertEqual([r for r in base.relances_de_campagne(campagne_id)
                          if r["statut"] == "planifiée"], [])
        fiches = etats_clients.tableau_clients(base, self.application.preferences)
        fiche = next(f for f in fiches if f["client"]["id"] == client_id)
        self.assertEqual(fiche["conversation"], "le client rappellera")
        self.assertEqual(fiche["besoins"], [])
        self.assertFalse(fiche["non_traite"])
        # They are visible with that state in Clients, and the screen explains.
        _, page = self._obtenir("/clients")
        # THE LABEL changed, not the CODE: `le client rappellera` is still the
        # value written in the database (no row migration).
        self.assertIn("📞 le contact rappellera", page)
        self.assertEqual(assistant.ETAT_RAPPELLERA,
                         "le client rappellera")
        self.assertIn("il reprend contact lui-même", page)
        # And their slot really has left `Upcoming appointments`.
        _, suivi = self._obtenir("/suivi")
        _, _, a_venir = suivi.partition('id="a-venir"')
        self.assertNotIn("Mme Annulante 52", a_venir)

    def test_avec_l_option_un_accord_devient_un_deplacement(self):
        base = self.application.base
        _, rdv_id, horaire, ligne = self._rendezvous("54", 6)
        # OPENING HOURS ARE NEEDED, OTHERWISE THERE IS NOTHING TO OFFER
        # (31/08/2026). Since that day, the opening only promises another date
        # if slots really are free: without a standard week, this test
        # exercised the `full calendar` case while believing it exercised the
        # option.
        horaires.definir_semaine(self.application.preferences,
                                 {j: [(8 * 60, 19 * 60)] for j in range(7)})
        campagne_id = self._campagne("rappel_rdv", [ligne], opt_replacer="1",
                                     reprendre_les_calculs=True)
        campagne = base.obtenir_campagne(campagne_id)
        self.assertIn("je peux vous proposer une autre date",
                      campagne["mission"])
        # AND IT DOES NOT RECITE THEM: that is his request of 31/08, and it
        # holds here too.
        self.assertNotIn(" heures 20, ", campagne["mission"])
        etats = self._derouler(campagne_id)
        self.assertEqual(etats["Mme Annulante 54"]["etat"], "accepté")
        # ONE SINGLE ROW, WHICH CHANGES DATE (his rule of 14/08/2026, extended
        # to this outcome on 17/08). The test previously expected the old row
        # as `deplace` PLUS a new `prevu` one: two appointments for a single
        # move.
        siens = [r for r in base.tous_les_rendezvous()
                 if r["nom"] == "Mme Annulante 54"]
        self.assertEqual([r["id"] for r in siens], [rdv_id],
                         "une seconde ligne a été créée")
        bouge = base.obtenir_rendezvous(rdv_id)
        self.assertEqual(bouge["statut"], "confirmé")
        self.assertNotEqual(bouge["horaire"], horaire)
        # The change log carries the move row, with both dates — it is what
        # keeps the history, not a ghost row in the calendar.
        cahier = base.changements_de_campagne(campagne_id)
        self.assertEqual([c["genre"] for c in cahier], ["deplacement"])
        self.assertEqual(cahier[0]["ancienne_date"], horaire)
        self.assertEqual(cahier[0]["nouvelle_date"], bouge["horaire"])
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn("↔", page)

    def test_la_case_n_apparait_que_pour_les_natures_concernees(self):
        _, page = self._poster("/assistant/nature", {"nature": "rappel_rdv"})
        self.assertIn('id="opt_replacer"', page)
        self.assertIn("Proposer une autre date si le contact annule", page)
        # The detail (the slots to announce) is a REVEAL: it lives in the
        # option's block, not in the general information.
        self.assertIn('id="bloc-replacer"', page)
        self.assertIn('id="info_creneaux_annulation"', page)
        _, autre = self._poster("/assistant/nature", {"nature": "prise_rdv"})
        self.assertNotIn('id="opt_replacer"', autre)
        self.assertNotIn("info_creneaux_annulation", autre)


class TestLienVersLaCampagneAlEcran(_CampagneAssistant):
    """Q5 bis, SCREEN side — the `where does this appointment come from` link
    really is clickable where one looks for it.

    The 3 table checked it in the database only until now
    (TestOrigineCampagneDunRendezVous): this test exercises it on the pages.
    """

    def test_le_rendezvous_obtenu_renvoie_vers_sa_campagne(self):
        base = self.application.base
        campagne_id = self._campagne(
            "prise_rdv", ["M. Obtenu Oui;+33 6 39 98 50 51;Bilan"])
        etats = self._derouler(campagne_id)
        self.assertEqual(etats["M. Obtenu Oui"]["etat"], "accepté")
        rdv = next(r for r in base.tous_les_rendezvous()
                   if r["nom"] == "M. Obtenu Oui")
        lien = f'/campagne?id={campagne_id}'
        # `Upcoming appointments` WAS REMOVED on 10/08/2026: it is in `Tous les
        # rendez-vous` that the row is read, and the link is there.
        _, tous = self._obtenir("/tous")
        self.assertIn("M. Obtenu Oui", tous)
        self.assertIn(lien, tous)
        # ... and on the appointment's own record.
        _, fiche = self._obtenir(f"/rendezvous?id={rdv['id']}")
        self.assertIn(lien, fiche)
        self.assertIn("Obtenu par téléphone", fiche)

    def test_un_rendezvous_saisi_a_la_main_n_affiche_aucun_lien(self):
        """Jamais de lien mort : sans campagne, on n'affiche RIEN."""
        base = self.application.base
        client_id = base.ajouter_client("Mme Saisie Main", "+33 6 39 98 00 60")
        rdv_id = base.ajouter_rendezvous(client_id, DEMAIN, "Séance")
        _, fiche = self._obtenir(f"/rendezvous?id={rdv_id}")
        self.assertNotIn("/campagne?id=", fiche)
        self.assertNotIn("Obtenu par téléphone", fiche)


# ===========================================================================
# THE CANCELLATION RULE (31/07/2026) — `cancelled` for the past, otherwise we
# DELETE; and the 12 h threshold that decides whether compensation is possible.
# ===========================================================================
class TestDecisionAnnulation(unittest.TestCase):
    """The rule itself, isolated: three cases, one single place.

    It is horaires.decision_annulation that holds it. All the rest of the
    product — the schedule's modal, the campaign, the direct cascade — calls
    it: so there cannot be two rules diverging.
    """

    MAINTENANT = datetime.datetime(2026, 7, 31, 12, 0)

    def _decision(self, horaire, preferences=None):
        return horaires.decision_annulation(preferences, horaire,
                                            self.MAINTENANT)

    def test_une_date_passee_reste_annulee(self):
        """`cancelled is for past dates` — the history status."""
        decision = self._decision("2026-07-30T09:00")
        self.assertEqual(decision["statut"], "annulé")
        self.assertFalse(decision["compensable"])
        self.assertIn("déjà passé", decision["pourquoi"])

    def test_au_dela_du_seuil_le_rendezvous_est_supprime(self):
        """More than 12 h: it disappears, and compensation is possible."""
        decision = self._decision("2026-08-05T09:00")
        self.assertEqual(decision["statut"], db.STATUT_SUPPRIME)
        self.assertTrue(decision["compensable"])
        self.assertEqual(decision["seuil"], 12)

    def test_en_deca_du_seuil_il_reste_annule_et_on_dit_pourquoi(self):
        """Less than 12 h: `cancelled`, and the screen explains it is too late.
        """
        decision = self._decision("2026-07-31T20:00")  # in 8 h
        self.assertEqual(decision["statut"], "annulé")
        self.assertFalse(decision["compensable"])
        self.assertIn("moins de 12 h", decision["pourquoi"])
        self.assertIn("à la main", decision["pourquoi"])

    def test_la_bascule_se_fait_exactement_au_seuil(self):
        """12 h pile : c'est encore compensable ; 11 h 59, non."""
        self.assertTrue(self._decision("2026-08-01T00:00")["compensable"])
        self.assertFalse(self._decision("2026-07-31T23:59")["compensable"])

    def test_le_seuil_est_reglable(self):
        """The 12 h value is a DEFAULT, not a product constant."""
        preferences = _PreferencesEnMemoire(
            {horaires.CLE_SEUIL_REMPLACEMENT: 48})
        decision = self._decision("2026-08-01T09:00", preferences)  # in 21 h
        self.assertEqual(decision["seuil"], 48)
        self.assertEqual(decision["statut"], "annulé")
        self.assertFalse(decision["compensable"])

    def test_un_reglage_absurde_retombe_sur_le_defaut(self):
        for valeur in ("", "beaucoup", -3, 10000, None):
            preferences = _PreferencesEnMemoire(
                {horaires.CLE_SEUIL_REMPLACEMENT: valeur})
            self.assertEqual(horaires.seuil_remplacement(preferences), 12)

    def test_une_date_illisible_ne_supprime_rien(self):
        decision = self._decision("pas une date")
        self.assertEqual(decision["statut"], "annulé")
        self.assertFalse(decision["compensable"])
        self.assertIn("illisible", decision["pourquoi"])

    def test_le_seuil_saisi_est_valide_avec_le_format_attendu(self):
        self.assertEqual(horaires.valider_seuil_remplacement("24"), 24)
        self.assertEqual(horaires.valider_seuil_remplacement(" 0 "), 0)
        for mauvais in ("douze", "", "-1", "10000"):
            with self.assertRaises(ValueError) as capture:
                horaires.valider_seuil_remplacement(mauvais)
            self.assertIn("attendu", str(capture.exception))


class _PreferencesEnMemoire:
    """The settings interface's minimum, for isolated tests."""

    def __init__(self, valeurs=None):
        self.valeurs = dict(valeurs or {})

    def obtenir(self, cle, defaut=None):
        return self.valeurs.get(cle, defaut)

    def definir(self, cle, valeur):
        self.valeurs[cle] = valeur


class TestSuppressionRetireDesVues(_TestAvecServeurWeb):
    """A DELETED appointment leaves the views and gives back its slot.

    The deliberate choice: the row STAYS in the database (the change log's, the
    campaigns' and the calls' links are not broken), but it leaves every
    working view and the slot computation. Both archives — `Tous les
    rendez-vous` and the client's record — keep it, so that nothing is lost.
    """

    def _rendezvous_futur(self, nom="Mme Place Libre", jours=4):
        base = self.application.base
        horaire = (datetime.datetime.now() + datetime.timedelta(days=jours)
                   ).replace(hour=9, minute=0, second=0, microsecond=0
                             ).isoformat(timespec="minutes")
        client_id = base.ajouter_client(nom, "+33 6 39 98 07 90")
        return client_id, base.ajouter_rendezvous(client_id, horaire,
                                                  "Séance"), horaire

    def test_il_quitte_a_venir_le_planning_et_les_places_reprennent(self):
        base = self.application.base
        preferences = self.application.preferences
        # A standard week open: without it, no slot is COMPUTED.
        preferences.definir(horaires.CLE_SEMAINE,
                            {str(j): [[540, 720]] for j in range(7)})
        client_id, rdv_id, horaire = self._rendezvous_futur()
        libres_avant = len(horaires.creneaux_libres(base, preferences))
        self.assertIn(rdv_id, [r["id"] for r in base.rendezvous_a_venir_tous()])
        base.mettre_a_jour_rendezvous(rdv_id, statut=db.STATUT_SUPPRIME)
        libres_apres = len(horaires.creneaux_libres(base, preferences))
        # THE NUMERIC PROOF: the slot has come back into the computation.
        self.assertEqual(libres_apres, libres_avant + 1)
        self.assertNotIn(rdv_id,
                         [r["id"] for r in base.rendezvous_a_venir_tous()])
        self.assertNotIn(rdv_id, [r["id"] for r in base.rendezvous_occupants(
            horaire[:10] + "T00:00", horaire[:10] + "T23:59")])
        # The screen: neither in `Upcoming appointments` nor in the schedule.
        _, suivi = self._obtenir("/suivi")
        _, _, a_venir = suivi.partition('id="a-venir"')
        self.assertNotIn("Mme Place Libre", a_venir)
        _, planning = self._obtenir(f"/suivi/planning?date={horaire[:10]}")
        self.assertNotIn("Mme Place Libre", planning)
        # It never becomes `missed` when its hour passes.
        base.marquer_manques_echus(
            maintenant=(datetime.datetime.now()
                        + datetime.timedelta(days=30)).isoformat(
                            timespec="minutes"))
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"],
                         db.STATUT_SUPPRIME)
        # It feeds NO list source: neither `cancelled` nor `moved`.
        for source in ("annules", "deplaces"):
            candidats, _, _ = base.candidats_cascade(source)
            self.assertNotIn("Mme Place Libre",
                             [c["nom"] for c in candidats])
        # It no longer has a calendar state: its client has `no appointment`.
        fiches = etats_clients.tableau_clients(base, preferences)
        fiche = next(f for f in fiches if f["client"]["id"] == client_id)
        self.assertEqual(fiche["agenda"], "aucun rendez-vous")

    def test_les_deux_archives_le_gardent(self):
        """`No entry is lost`: it stays readable where that is the point."""
        base = self.application.base
        client_id, rdv_id, _ = self._rendezvous_futur("M. Trace Gardee")
        base.mettre_a_jour_rendezvous(rdv_id, statut=db.STATUT_SUPPRIME)
        self.assertIn(rdv_id, [r["id"] for r in base.tous_les_rendezvous()])
        _, tous = self._obtenir("/tous")
        self.assertIn("M. Trace Gardee", tous)
        self.assertIn("supprimé", tous)
        _, fiche = self._obtenir(f"/clients/fiche?id={client_id}")
        self.assertIn("supprimé", fiche)

    def test_la_modale_ne_propose_que_le_geste_legal(self):
        """Ahead of us: `deleted`. Behind us: `cancelled`."""
        base = self.application.base
        _, futur, _ = self._rendezvous_futur("Mme Devant Nous")
        client_id = base.ajouter_client("M. Derriere Nous", "+33 6 39 98 07 91")
        passe = base.ajouter_rendezvous(client_id, HIER, "Séance")
        _, modale = self._obtenir(f"/suivi/detail?rdv={futur}")
        self.assertIn(f'<option value="{db.STATUT_SUPPRIME}"', modale)
        self.assertNotIn('<option value="annulé"', modale)
        self.assertIn("sa place", modale)
        _, modale = self._obtenir(f"/suivi/detail?rdv={passe}")
        self.assertIn('<option value="annulé"', modale)
        self.assertNotIn(f'<option value="{db.STATUT_SUPPRIME}"', modale)

    def test_le_serveur_ramene_annule_a_la_regle(self):
        """A form that sends `cancelled` on a future date writes `deleted`."""
        base = self.application.base
        _, rdv_id, horaire = self._rendezvous_futur("Mme Formulaire Ancien")
        self._poster("/suivi/detail/enregistrer",
                     {"rdv": rdv_id, "motif": "Séance", "horaire": horaire,
                      "duree": "15", "statut": "annulé"})
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"],
                         db.STATUT_SUPPRIME)

    def test_un_rendezvous_passe_annule_garde_annule(self):
        """The past does not move: `cancelled` stays `cancelled`."""
        base = self.application.base
        client_id = base.ajouter_client("M. Passe Annule", "+33 6 39 98 07 92")
        rdv_id = base.ajouter_rendezvous(client_id, HIER, "Séance")
        self._poster("/suivi/detail/enregistrer",
                     {"rdv": rdv_id, "motif": "Séance", "horaire": HIER,
                      "duree": "15", "statut": "annulé"})
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"], "annulé")
        # And it still feeds the `Cancelled appointments` campaign source.
        candidats, _, _ = base.candidats_cascade("annules")
        self.assertIn("M. Passe Annule", [c["nom"] for c in candidats])

    def test_le_seuil_se_regle_dans_les_reglages(self):
        preferences = self.application.preferences
        self.assertEqual(horaires.seuil_remplacement(preferences), 12)
        _, page = self._obtenir("/reglages")
        self.assertIn('name="seuil_remplacement"', page)
        self._poster("/reglages/enregistrer",
                     {"entreprise": "Cabinet Essai", "plage_debut": "00:00",
                      "plage_fin": "23:59", "seuil_remplacement": "36"})
        self.assertEqual(horaires.seuil_remplacement(preferences), 36)
        _, page = self._poster("/reglages/enregistrer",
                               {"entreprise": "Cabinet Essai",
                                "plage_debut": "00:00", "plage_fin": "23:59",
                                "seuil_remplacement": "douze"})
        self.assertIn("Seuil de remplacement refusé", page)
        self.assertEqual(horaires.seuil_remplacement(preferences), 36)


class TestSeuilDeCompensation(_CampagneAssistant):
    """The 12 h threshold, played out FOR REAL on a callback campaign.

    Beyond the threshold: the appointment is deleted, its slot becomes free
    again, and the summary OFFERS the compensation campaign — without any call
    going out. Below it: it stays `cancelled` and the screen says why a
    replacement is not possible, with the means of doing it by hand.
    """

    def _campagne_annulation(self, nom, **options):
        """A real appointment IN THREE DAYS, and the campaign that calls it.

        The date is fixed (10am, D+3) so that the test does not depend on the
        time it is run; it is the THRESHOLD we vary to exercise both sides of
        the rule. The exact bounds, to the hour, are measured by
        TestDecisionAnnulation.
        """
        base = self.application.base
        horaire = (datetime.datetime.now() + datetime.timedelta(days=3)
                   ).replace(hour=10, minute=0, second=0, microsecond=0
                             ).isoformat(timespec="minutes")
        client_id = base.ajouter_client(nom, "+33 6 39 98 08 52")
        rdv_id = base.ajouter_rendezvous(client_id, horaire, "Séance")
        ligne = f"{nom};+33 6 39 98 08 52;{horaire};Séance"
        campagne_id = self._campagne("rappel_rdv", [ligne], **options)
        return campagne_id, rdv_id, horaire

    def test_au_dela_du_seuil_la_place_se_libere_et_l_ecran_propose(self):
        base = self.application.base
        preferences = self.application.preferences
        preferences.definir(horaires.CLE_SEMAINE,
                            {str(j): [[480, 1140]] for j in range(7)})
        campagne_id, rdv_id, horaire = self._campagne_annulation(
            "Mme Annule Loin")
        libres_avant = len(horaires.creneaux_libres(base, preferences))
        campagnes_avant = len(base.lister_campagnes())
        self._derouler(campagne_id)
        # (1) the appointment is DELETED, its slot is given back.
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"],
                         db.STATUT_SUPPRIME)
        libres_apres = len(horaires.creneaux_libres(base, preferences))
        self.assertEqual(libres_apres, libres_avant + 1)
        # (2) the change log's removal row carries WHO, WHEN, the REASON and
        # the WHY.
        cahier = base.changements_de_campagne(campagne_id)
        supprimes = [c for c in cahier if c["genre"] == "suppression"]
        self.assertEqual(len(supprimes), 1)
        self.assertEqual(supprimes[0]["nom"], "Mme Annule Loin")
        self.assertEqual(supprimes[0]["ancienne_date"], horaire)
        self.assertEqual(supprimes[0]["motif"], "Séance")
        self.assertIn("annulé par le client pendant l'appel",
                      supprimes[0]["raison"])
        self.assertIn("sa place redevient libre", supprimes[0]["raison"])
        self.assertTrue(supprimes[0]["cree_le"])
        # (3) the summary OFFERS the compensation — and nothing went out.
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn("Compenser une absence", page)
        self.assertIn("/campagne/compenser", page)
        self.assertIn("Aucun appel ne part d'ici", page)
        self.assertEqual(len(base.lister_campagnes()), campagnes_avant)
        # (4) the click OPENS the wizard, slot pre-filled — without creating
        # anything.
        _, page = self._poster("/campagne/compenser",
                               {"campagne": campagne_id, "creneau": horaire})
        self.assertIn("Créneau libéré", page)
        self.assertIn(horaire, page)
        self.assertEqual(len(base.lister_campagnes()), campagnes_avant)

    def test_en_deca_du_seuil_il_reste_annule_et_l_ecran_dit_pourquoi(self):
        """The threshold raised to 7 days puts the D+3 appointment BELOW it."""
        base = self.application.base
        preferences = self.application.preferences
        preferences.definir(horaires.CLE_SEUIL_REMPLACEMENT, 168)
        campagne_id, rdv_id, _ = self._campagne_annulation("Mme Annule Tard")
        etats = self._derouler(campagne_id)
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"], "annulé")
        detail = etats["Mme Annule Tard"]["detail"]
        self.assertIn("reste « annulé »", detail)
        self.assertIn("moins de 168 h", detail)
        self.assertIn("à la main", detail)
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn("trop tard pour organiser un remplacement", page)
        self.assertIn("Le faire quand même à la main", page)
        self.assertIn("Voir cette journée dans le planning", page)
        # No campaign was prepared on its own.
        self.assertEqual([c["id"] for c in base.lister_campagnes()],
                         [campagne_id])

    def test_avec_la_cascade_la_campagne_de_compensation_est_prete(self):
        """The cascade option PREPARES — state `prete`, no call went out.

        The list comes from the DATABASE (`upcoming appointments`): it is the
        condition already in place for replaying a campaign on another slot — a
        list pasted by hand has no criterion to replay, and RingBack then
        refuses to invent one.
        """
        base = self.application.base
        limite = (datetime.date.today()
                  + datetime.timedelta(days=90)).isoformat()
        horaire = (datetime.datetime.now() + datetime.timedelta(days=3)
                   ).replace(hour=10, minute=0, second=0, microsecond=0
                             ).isoformat(timespec="minutes")
        # Ending 52: the simulator makes this person CANCEL — so the sequence
        # is entirely deterministic.
        client_id = base.ajouter_client("Mme Annule Cascade",
                                        "+33 6 39 98 08 52")
        rdv_id = base.ajouter_rendezvous(client_id, horaire, "Séance")
        # A second client, LATER: they are the one who will be able to take the
        # slot.
        plus_tard = base.ajouter_client("M. Encore Apres",
                                        "+33 6 39 98 08 53")
        base.ajouter_rendezvous(
            plus_tard, (datetime.datetime.now() + datetime.timedelta(days=20)
                        ).replace(hour=10, minute=0, second=0, microsecond=0
                                  ).isoformat(timespec="minutes"), "Séance")
        _, page = self._poster("/assistant/nature", {"nature": "rappel_rdv"})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "ordre": "liste",
            "opt_recontacter": "1", "opt_liberer": "1", "opt_cascade": "1",
            "cascade_jusqu_au": limite, "relance_mode": "delai",
            "relance_delai": "4", "relance_max": "3",
            "info_entreprise": "Cabinet Essai"})
        self._poster("/assistant/importer",
                     {"b": b, "mode": "base", "source": "a_venir"})
        self._poster("/assistant/liste", {"b": b, "action": "valider"})
        campagne_id = base.lister_campagnes()[0]["id"]
        self._derouler(campagne_id)
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"],
                         db.STATUT_SUPPRIME)
        preparees = [c for c in base.lister_campagnes()
                     if c["id"] != campagne_id]
        self.assertEqual(len(preparees), 1)
        self.assertEqual(preparees[0]["statut"], "prête")
        self.assertEqual(preparees[0]["creneau"], horaire)
        # No call was made for that prepared campaign.
        self.assertEqual(
            [c["etat"] for c in base.contacts_de_campagne(preparees[0]["id"])
             if c["etat"] != "à appeler"], [])
        # And the summary points to it rather than offering it again.
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn(f"campagne n°{preparees[0]['id']} déjà préparée", page)


class TestCascadeDirecteAncienRendezvous(_TestAvecServeurWeb):
    """Q7 closed on the DIRECT cascade — its two branches.

    `accepted` as well as `moved` creates an appointment: the old one must go
    when we know which one it is, and only then. A pasted contact we do not
    recognise gets a NOTE, never an invented deletion.
    """

    class _Issue:
        def __init__(self, resultat):
            self.resultat = resultat
            self.transcription = "essai"

    class _ClientFixe(calle_client.ClientAppels):
        """A call client that ALWAYS returns the same outcome (no randomness).
        """

        def __init__(self, resultat):
            self.resultat = resultat

        def appeler_cascade(self, nom, telephone, mission, creneau,
                            consigne=None, nature=None):
            return TestCascadeDirecteAncienRendezvous._Issue(dict(self.resultat))

    def _dans(self, jours, heure=9):
        return (datetime.datetime.now() + datetime.timedelta(days=jours)
                ).replace(hour=heure, minute=0, second=0, microsecond=0
                          ).isoformat(timespec="minutes")

    def _cascade(self, resultat, personnes, creneau):
        planif = self.application.planif
        planif.client_appels = self._ClientFixe(resultat)
        return planif.executer_cascade(
            personnes, "Bonjour, une place s'est libérée [créneau].", creneau)

    def test_un_client_connu_ne_garde_pas_deux_rendezvous(self):
        base = self.application.base
        client_id = base.ajouter_client("Mme Connue Cascade",
                                        "+33 6 39 98 09 01")
        ancien = base.ajouter_rendezvous(client_id, self._dans(9), "Séance")
        avant = len(base.rendezvous_a_venir_du_client(client_id))
        self.assertEqual(avant, 1)
        creneau = self._dans(3, 14)
        cascade_id = self._cascade(
            {"outcome": "accepted"},
            [{"nom": "Mme Connue Cascade", "telephone": "+33 6 39 98 09 01"}],
            creneau)
        # BEFORE: 1 upcoming appointment. AFTER: still 1 — not 2.
        apres = base.rendezvous_a_venir_du_client(client_id)
        self.assertEqual(len(apres), 1)
        self.assertEqual(apres[0]["horaire"], creneau)
        self.assertEqual(base.obtenir_rendezvous(ancien)["statut"],
                         db.STATUT_SUPPRIME)
        ligne = base.appels_de_cascade(cascade_id)[0]
        self.assertEqual(ligne["rendezvous_libere"], ancien)
        self.assertIn("Ancien rendez-vous le ", ligne["note"])
        self.assertIn("libéré (supprimé)", ligne["note"])

    def test_une_autre_date_convenue_libere_aussi_l_ancienne_place(self):
        """The `moved` branch — the exact hole described by Q7."""
        base = self.application.base
        client_id = base.ajouter_client("M. Autre Date", "+33 6 39 98 09 02")
        ancien = base.ajouter_rendezvous(client_id, self._dans(9), "Séance")
        nouvelle = self._dans(4, 11)
        cascade_id = self._cascade(
            {"outcome": "moved", "new_datetime": nouvelle},
            [{"nom": "M. Autre Date", "telephone": "+33 6 39 98 09 02"}],
            self._dans(3, 14))
        apres = base.rendezvous_a_venir_du_client(client_id)
        self.assertEqual([r["horaire"] for r in apres], [nouvelle])
        self.assertEqual(base.obtenir_rendezvous(ancien)["statut"],
                         db.STATUT_SUPPRIME)
        self.assertEqual(base.appels_de_cascade(cascade_id)[0]
                         ["rendezvous_libere"], ancien)

    def test_un_contact_colle_inconnu_ne_subit_aucune_suppression(self):
        """We invent nothing: no record, so no appointment touched."""
        base = self.application.base
        avant = len(base.tous_les_rendezvous())
        cascade_id = self._cascade(
            {"outcome": "accepted"},
            [{"nom": "M. Jamais Vu", "telephone": "+33 6 39 98 09 03"}],
            self._dans(3, 14))
        ligne = base.appels_de_cascade(cascade_id)[0]
        self.assertIsNone(ligne["rendezvous_libere"])
        self.assertIsNone(ligne["note"])
        # One more appointment only: the one we have just created.
        self.assertEqual(len(base.tous_les_rendezvous()), avant + 1)
        statuts = [r["statut"] for r in base.tous_les_rendezvous()]
        self.assertNotIn(db.STATUT_SUPPRIME, statuts)

    def test_plusieurs_rendezvous_a_venir_font_ecrire_la_mention(self):
        """Ambiguous: RingBack SAYS so instead of choosing in the human's place.
        """
        base = self.application.base
        client_id = base.ajouter_client("Mme Deux Rendez-Vous",
                                        "+33 6 39 98 09 04")
        un = base.ajouter_rendezvous(client_id, self._dans(9), "Séance A")
        deux = base.ajouter_rendezvous(client_id, self._dans(12), "Séance B")
        cascade_id = self._cascade(
            {"outcome": "accepted"},
            [{"nom": "Mme Deux Rendez-Vous",
              "telephone": "+33 6 39 98 09 04"}],
            self._dans(3, 14))
        ligne = base.appels_de_cascade(cascade_id)[0]
        self.assertIsNone(ligne["rendezvous_libere"])
        self.assertIn("Ancien rendez-vous à libérer dans votre agenda",
                      ligne["note"])
        self.assertIn("2 rendez-vous à venir", ligne["note"])
        # BOTH are intact: nothing was deleted at random.
        self.assertEqual(base.obtenir_rendezvous(un)["statut"], "prévu")
        self.assertEqual(base.obtenir_rendezvous(deux)["statut"], "prévu")

    def test_le_cahier_de_la_campagne_rattachee_porte_la_decision(self):
        """The direct cascade builds its campaign: the change log follows."""
        base = self.application.base
        preferences = self.application.preferences
        client_id = base.ajouter_client("M. Cahier Cascade",
                                        "+33 6 39 98 09 05")
        ancien = base.ajouter_rendezvous(client_id, self._dans(9), "Séance")
        creneau = self._dans(3, 14)
        personnes = [{"nom": "M. Cahier Cascade",
                      "telephone": "+33 6 39 98 09 05"}]
        cascade_id = self._cascade({"outcome": "accepted"}, personnes, creneau)
        campagne_id = campagnes.campagne_depuis_cascade(
            base, preferences, cascade_id, personnes,
            "Bonjour, une place s'est libérée.", creneau)
        cahier = base.changements_de_campagne(campagne_id)
        supprimes = [c for c in cahier if c["genre"] == "suppression"]
        self.assertEqual(len(supprimes), 1)
        self.assertEqual(supprimes[0]["rendezvous_id"], ancien)
        self.assertEqual(supprimes[0]["nom"], "M. Cahier Cascade")
        self.assertTrue(supprimes[0]["ancienne_date"])
        self.assertIn("libéré", supprimes[0]["raison"])

    def test_un_inconnu_ambigu_donne_une_ligne_a_traiter_par_un_humain(self):
        base = self.application.base
        preferences = self.application.preferences
        client_id = base.ajouter_client("Mme Ambigue Cahier",
                                        "+33 6 39 98 09 06")
        base.ajouter_rendezvous(client_id, self._dans(9), "Séance A")
        base.ajouter_rendezvous(client_id, self._dans(12), "Séance B")
        creneau = self._dans(3, 14)
        personnes = [{"nom": "Mme Ambigue Cahier",
                      "telephone": "+33 6 39 98 09 06"}]
        cascade_id = self._cascade({"outcome": "accepted"}, personnes, creneau)
        campagne_id = campagnes.campagne_depuis_cascade(
            base, preferences, cascade_id, personnes,
            "Bonjour, une place s'est libérée.", creneau)
        cahier = base.changements_de_campagne(campagne_id)
        self.assertEqual([c["genre"] for c in cahier], ["humain"])
        self.assertIn("à libérer dans votre agenda", cahier[0]["raison"])
        # And the cascade's screen says so, on THAT person's row.
        _, page = self._obtenir(f"/cascade/resultat?id={cascade_id}")
        self.assertIn("<th>L'ancien rendez-vous</th>", page)
        self.assertIn("à libérer dans votre agenda", page)


class TestCascadeCampagneAutreDate(_CampagneAssistant):
    """Q7 closed on the CAMPAIGN cascade (freed-slot kind).

    Same rule, same code: `another date agreed` no longer leaves the same
    client with two appointments.
    """

    class _ClientMoved(calle_client.ClientAppels):
        def __init__(self, nouvelle):
            self.nouvelle = nouvelle

        def appeler_cascade(self, nom, telephone, mission, creneau,
                            consigne=None, nature=None):
            class _I:
                pass
            issue = _I()
            issue.resultat = {"outcome": "moved",
                              "new_datetime": self.nouvelle}
            issue.transcription = "essai"
            return issue

    def test_autre_date_convenue_libere_l_ancien_rendezvous(self):
        base = self.application.base
        ancien_horaire = (datetime.datetime.now()
                          + datetime.timedelta(days=9)).replace(
                              hour=9, minute=0, second=0, microsecond=0
                          ).isoformat(timespec="minutes")
        nouvelle = (datetime.datetime.now() + datetime.timedelta(days=4)
                    ).replace(hour=11, minute=0, second=0, microsecond=0
                              ).isoformat(timespec="minutes")
        creneau = (datetime.datetime.now() + datetime.timedelta(days=3)
                   ).replace(hour=14, minute=0, second=0, microsecond=0
                             ).isoformat(timespec="minutes")
        client_id = base.ajouter_client("M. Cascade Autre",
                                        "+33 6 39 98 10 01")
        ancien = base.ajouter_rendezvous(client_id, ancien_horaire, "Séance")
        self.assertEqual(len(base.rendezvous_a_venir_du_client(client_id)), 1)
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "ordre": "liste",
            "opt_recontacter": "1", "opt_liberer": "1",
            "relance_mode": "delai", "relance_delai": "4", "relance_max": "3",
            "info_entreprise": "Cabinet Essai",
            "info_creneau_libere": creneau})
        # A PASTED list, hence manual mode: in automatic the rule would add
        # people from the database, and that is not what we exercise here.
        self._poster("/assistant/liste", {"b": b, "action": "liste:manuel"})
        self._poster("/assistant/importer", {
            "b": b, "mode": "collage",
            "liste": f"M. Cascade Autre;+33 6 39 98 10 01;"
                     f"{ancien_horaire};Séance"})
        self._poster("/assistant/liste", {"b": b, "action": "valider"})
        campagne_id = base.lister_campagnes()[0]["id"]
        self.application.planif.client_appels = self._ClientMoved(nouvelle)
        assistant.executer_campagne(self.application, campagne_id)
        # BEFORE: 1 upcoming appointment. AFTER: still 1, at the NEW date.
        apres = base.rendezvous_a_venir_du_client(client_id)
        self.assertEqual([r["horaire"] for r in apres], [nouvelle])
        self.assertEqual(base.obtenir_rendezvous(ancien)["statut"],
                         db.STATUT_SUPPRIME)
        contact = base.contacts_de_campagne(campagne_id)[0]
        self.assertIn("reste à pourvoir", contact["detail"])
        self.assertIn("libéré", contact["detail"])
        cahier = base.changements_de_campagne(campagne_id)
        genres = [c["genre"] for c in cahier]
        self.assertEqual(sorted(genres), ["ajout", "suppression"])


# --------------------------------------------------------------------------
# REAL-CONDITIONS TRIAL — the declared test number  What these tests protect,
# in order of importance: 1. the anti-duplicate safety lock stays WHOLE for
# every number except ONE, the one the operator declared themselves (and
# erasing it restores the lock); 2. nothing is hidden: every contact on the
# test number carries a test marker in the grid, the campaign record, the
# schedule and Clients; 3. the test number stays MASKED on screen like all the
# others; 4. the `Prepare a real test campaign` button makes NO call.
# -------------------------------------------------------------------------- In
# real life, this field carries the operator's REAL number. Here, as everywhere
# in this repository, we only write numbers taken from the roots the Arcep
# reserves for audiovisual works: they are assigned to nobody and can neither
# call nor be called (see ringback/jeu_essai.py).
NUMERO_ESSAI = "06 39 98 09 88"
AUTRE_NUMERO = "06 39 98 07 77"
# The same number, written differently — that is what the recognition must see.
NUMERO_ESSAI_INTERNATIONAL = "+33 6 39 98 09 88"
# ANOTHER number that masks EXACTLY the same way: the trap that comparison by
# digits must avoid.
JUMEAU_MASQUE = "06 39 98 01 88"
# What the screen shows of it, and nothing else.
MASQUE_ESSAI = "06 39 •• •• 88"


class TestNumeroEssaiUnite(unittest.TestCase):
    """The recognition of the test number, outside the server."""

    def test_reconnu_quelle_que_soit_son_ecriture(self):
        self.assertTrue(db.est_numero_essai(NUMERO_ESSAI_INTERNATIONAL,
                                            NUMERO_ESSAI))
        self.assertTrue(db.est_numero_essai(NUMERO_ESSAI, NUMERO_ESSAI))
        # ...and the reverse: declaring the international form recognises the
        # national form, otherwise the setting would depend on the way it is
        # typed.
        self.assertTrue(db.est_numero_essai(NUMERO_ESSAI,
                                            NUMERO_ESSAI_INTERNATIONAL))

    def test_aucun_numero_declare_n_exempte_personne(self):
        self.assertFalse(db.est_numero_essai(NUMERO_ESSAI, ""))
        self.assertFalse(db.est_numero_essai(NUMERO_ESSAI, None))
        self.assertFalse(db.est_numero_essai("", ""))

    def test_deux_numeros_masques_pareil_ne_sont_pas_confondus(self):
        # Those two numbers both mask to the same string. Confusing them would
        # mark a REAL person as test data: the comparison bears on the digits,
        # never on the masked text.
        self.assertEqual(db.masquer_telephone(NUMERO_ESSAI),
                         db.masquer_telephone(JUMEAU_MASQUE))
        self.assertFalse(db.est_numero_essai(JUMEAU_MASQUE, NUMERO_ESSAI))

    def test_champ_vide_accepte_numero_invalide_refuse(self):
        self.assertEqual(essai_reel.valider_numero(""), "")
        self.assertEqual(essai_reel.valider_numero("   "), "")
        self.assertEqual(essai_reel.valider_numero("+33639980988"),
                         NUMERO_ESSAI_INTERNATIONAL)
        with self.assertRaises(saisie.SaisieInvalide):
            essai_reel.valider_numero("06 39 98")

    def test_collage_le_garde_fou_reste_entier_sauf_pour_le_numero_declare(self):
        champs = assistant.NATURES["confirmation"]["champs"]
        colle = (f"Mme Alice Dubreuil;{NUMERO_ESSAI};2026-08-05T09:00;Séance\n"
                 f"M. Rémi Chastain;{NUMERO_ESSAI};2026-08-05T10:00;Séance\n"
                 f"Mme Diane Verrier;{NUMERO_ESSAI};2026-08-05T11:00;Séance\n")
        # WITHOUT a declared number: a single row passes, the others are
        # duplicates — it is the original behaviour, it does not move.
        contacts, erreurs, _ = assistant.analyser_collage(colle, champs)
        self.assertEqual(len(contacts), 1)
        self.assertEqual(len(erreurs), 2)
        self.assertIn("doublon", erreurs[0])
        # WITH the number declared: all three identities pass, without an
        # error.
        contacts, erreurs, _ = assistant.analyser_collage(
            colle, champs, (), NUMERO_ESSAI)
        self.assertEqual([c["nom"] for c in contacts],
                         ["Mme Alice Dubreuil", "M. Rémi Chastain",
                          "Mme Diane Verrier"])
        self.assertEqual(erreurs, [])
        # ANOTHER repeated number is still refused, test number declared or
        # not.
        autre = (f"Mme A;{AUTRE_NUMERO};2026-08-05T09:00;Séance\n"
                 f"M. B;{AUTRE_NUMERO};2026-08-05T10:00;Séance\n")
        contacts, erreurs, _ = assistant.analyser_collage(
            autre, champs, (), NUMERO_ESSAI)
        self.assertEqual(len(contacts), 1)
        self.assertIn("doublon", erreurs[0])

    def test_csv_suit_la_meme_regle_que_le_collage(self):
        champs = assistant.NATURES["confirmation"]["champs"]
        fichier = ("nom;telephone;rdv_existant;motif\r\n"
                   f"Mme Alice Dubreuil;{NUMERO_ESSAI};2026-08-05T09:00;Séance\r\n"
                   f"M. Rémi Chastain;{NUMERO_ESSAI};2026-08-05T10:00;Séance\r\n"
                   ).encode("utf-8")
        contacts, erreurs = assistant.analyser_csv(fichier, champs)
        self.assertEqual(len(contacts), 1)  # strict rule by default
        contacts, erreurs = assistant.analyser_csv(fichier, champs, (),
                                                   NUMERO_ESSAI)
        self.assertEqual(len(contacts), 2)
        self.assertEqual(erreurs, [])

    def test_deja_dans_la_grille_le_numero_d_essai_peut_revenir(self):
        champs = assistant.NATURES["confirmation"]["champs"]
        colle = f"M. Hugo Sernin;{NUMERO_ESSAI};2026-08-05T09:00;Séance\n"
        # The number is ALREADY in the grid: without a declaration, refused.
        contacts, erreurs, _ = assistant.analyser_collage(
            colle, champs, (NUMERO_ESSAI,))
        self.assertEqual(contacts, [])
        self.assertIn("déjà dans la grille", erreurs[0])
        contacts, _, _ = assistant.analyser_collage(
            colle, champs, (NUMERO_ESSAI,), NUMERO_ESSAI)
        self.assertEqual(len(contacts), 1)

    def test_le_drapeau_ne_se_pose_que_si_la_base_le_connait(self):
        base = db.Base(":memory:")
        self.addCleanup(base.fermer)
        client_id = base.ajouter_client("Mme Essai", NUMERO_ESSAI)
        self.assertFalse(base.obtenir_client(client_id)["numero_essai"])
        base.definir_numero_essai(NUMERO_ESSAI)
        self.assertTrue(base.obtenir_client(client_id)["numero_essai"])
        # ...and it falls back as soon as the setting is erased.
        base.definir_numero_essai("")
        self.assertFalse(base.obtenir_client(client_id)["numero_essai"])


class TestServeurNumeroEssai(_TestAvecServeurWeb):
    """The test number on screen: declared, marked, masked, erasable."""

    CHAMPS_REGLAGES = {"entreprise": "Cabinet Essai", "plage_debut": "00:00",
                       "plage_fin": "23:59"}

    def _declarer(self, numero):
        champs = dict(self.CHAMPS_REGLAGES, numero_essai=numero)
        return self._poster("/reglages/enregistrer", champs)

    def _grille_essai(self, lignes):
        """Builds a `confirmation` campaign and pastes these rows."""
        _, page = self._poster("/assistant/nature", {"nature": "confirmation"})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "ordre": "liste",
            "opt_recontacter": "1", "opt_liberer": "1",
            "relance_mode": "delai", "relance_delai": "4", "relance_max": "3",
            "info_entreprise": "Cabinet Essai"})
        self._poster("/assistant/importer",
                     {"b": b, "mode": "collage", "liste": "\n".join(lignes)})
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        return b, page

    def test_reglage_declare_masque_et_effacable(self):
        preferences = self.application.preferences
        # At the start: nothing is declared, and the page says so.
        _, page = self._obtenir("/reglages")
        self.assertIn("Numéro d'essai", page)
        self.assertIn("Aucun numéro d'essai déclaré", page)
        # Declaration.
        self._declarer(NUMERO_ESSAI)
        self.assertEqual(preferences.obtenir(essai_reel.CLE_NUMERO_ESSAI),
                         NUMERO_ESSAI)
        self.assertEqual(self.application.base.numero_essai, NUMERO_ESSAI)
        _, page = self._obtenir("/reglages")
        # MASKED on screen, like every other number — without exception.
        self.assertNotIn(NUMERO_ESSAI, page)
        self.assertIn(MASQUE_ESSAI, page)
        # Leaving the field as it is (with its dots) changes nothing.
        self._declarer(MASQUE_ESSAI)
        self.assertEqual(preferences.obtenir(essai_reel.CLE_NUMERO_ESSAI),
                         NUMERO_ESSAI)
        # An unreadable number is REFUSED, with the reason, and nothing is
        # written.
        _, page = self._declarer("06 39 98")
        self.assertIn("Réglage refusé", page)
        self.assertIn("🧪 Numéro d'essai", page)
        self.assertEqual(preferences.obtenir(essai_reel.CLE_NUMERO_ESSAI),
                         NUMERO_ESSAI)
        # EMPTYING the field erases the setting: the strict rule comes back.
        self._declarer("")
        self.assertEqual(preferences.obtenir(essai_reel.CLE_NUMERO_ESSAI), "")
        self.assertEqual(self.application.base.numero_essai, "")

    def test_grille_le_doublon_refuse_puis_accepte_puis_de_nouveau_refuse(self):
        lignes = [f"Mme Alice Dubreuil;{NUMERO_ESSAI};{DEMAIN};Séance",
                  f"M. Rémi Chastain;{NUMERO_ESSAI};{DEMAIN};Séance",
                  f"Mme Diane Verrier;{NUMERO_ESSAI};{DEMAIN};Séance",
                  f"M. Hugo Sernin;{NUMERO_ESSAI};{DEMAIN};Séance"]
        # (1) WITHOUT a declared number: a single row goes in, the others are
        # reported as duplicates — the safety lock is intact.
        b, page = self._grille_essai(lignes)
        self.assertIn("doublon ignoré", page)
        brouillon = self.application.obtenir_brouillon_assistant(b)
        self.assertEqual(len(brouillon["contacts"]), 1)
        # (2) WITH the number declared: all four identities pass.
        self._declarer(NUMERO_ESSAI)
        b, page = self._grille_essai(lignes)
        brouillon = self.application.obtenir_brouillon_assistant(b)
        self.assertEqual([c["nom"] for c in brouillon["contacts"]],
                         ["Mme Alice Dubreuil", "M. Rémi Chastain",
                          "Mme Diane Verrier", "M. Hugo Sernin"])
        # ...each marked as test data, with the sentence saying why, and NO
        # duplicate message.
        self.assertNotIn("doublon ignoré", page)
        self.assertEqual(page.count("🧪 numéro d'essai"), 4)
        self.assertIn("VOTRE téléphone qui sonnera", page)
        self.assertNotIn(NUMERO_ESSAI, page)  # still masked
        # ...and the final validation does not refuse them either.
        _, page = self._poster("/assistant/liste", {"b": b, "action": "valider"})
        self.assertIn("prête", page)
        self.assertNotIn("retirez le doublon", page)
        campagne_id = self.application.base.lister_campagnes()[0]["id"]
        contacts = self.application.base.contacts_de_campagne(campagne_id)
        self.assertEqual(len(contacts), 4)
        # FOUR distinct client records: (name, number) makes the record.
        self.assertEqual(len({c["client_id"] for c in contacts}), 4)
        self.assertTrue(all(c["numero_essai"] for c in contacts))
        # (3) With the number erased, the strict rule comes back for it too.
        self._declarer("")
        b, page = self._grille_essai(lignes)
        self.assertIn("doublon ignoré", page)
        self.assertEqual(
            len(self.application.obtenir_brouillon_assistant(b)["contacts"]), 1)

    def test_un_autre_numero_repete_reste_toujours_refuse(self):
        self._declarer(NUMERO_ESSAI)
        lignes = [f"Mme Une;{AUTRE_NUMERO};{DEMAIN};Séance",
                  f"M. Deux;{AUTRE_NUMERO};{DEMAIN};Séance"]
        b, page = self._grille_essai(lignes)
        self.assertIn("doublon ignoré", page)
        self.assertEqual(
            len(self.application.obtenir_brouillon_assistant(b)["contacts"]), 1)

    def test_marque_visible_dans_clients_planning_et_fiche_de_campagne(self):
        self._declarer(NUMERO_ESSAI)
        _, page = self._poster("/reglages/essai-reel", {"confirmer": "oui"})
        self.assertIn("aucun appel n'est parti", page.lower())
        campagne_id = self.application.base.lister_campagnes()[0]["id"]
        # (1) The campaign record.
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertEqual(page.count("🧪 numéro d'essai"),
                         len(essai_reel.IDENTITES))
        self.assertNotIn(NUMERO_ESSAI, page)
        # ② 👥 Clients.
        _, page = self._obtenir("/clients")
        self.assertEqual(page.count("🧪 numéro d'essai"),
                         len(essai_reel.IDENTITES))
        self.assertNotIn(NUMERO_ESSAI, page)
        self.assertIn(MASQUE_ESSAI, page)
        # (3) The schedule — the tile carries the test marker, the window
        # carries the whole badge.
        rdv = [r for r in self.application.base.rendezvous_a_venir_tous()
               if r["numero_essai"]]
        self.assertEqual(len(rdv), len(essai_reel.IDENTITES))
        _, page = self._obtenir(f"/suivi/detail?rdv={rdv[0]['id']}")
        self.assertIn("🧪 numéro d'essai", page)
        self.assertNotIn(NUMERO_ESSAI, page)

    def test_preparer_sans_numero_le_dit_et_ne_fait_rien(self):
        base = self.application.base
        avant_clients, avant_campagnes = (base.compter_clients(),
                                          len(base.lister_campagnes()))
        # (the apostrophes come out escaped by html.escape: so we look for
        # pieces of sentence that carry none)
        _, page = self._obtenir("/reglages/essai-reel")
        self.assertIn("Aucun numéro d", page)
        self.assertIn("essai déclaré", page)
        self.assertIn("été créé", page)
        _, page = self._poster("/reglages/essai-reel", {"confirmer": "oui"})
        self.assertIn("rien n'a été préparé", page.lower())
        self.assertEqual(base.compter_clients(), avant_clients)
        self.assertEqual(len(base.lister_campagnes()), avant_campagnes)

    def test_campagne_preparee_est_prete_et_n_a_passe_aucun_appel(self):
        base = self.application.base
        self._declarer(NUMERO_ESSAI)
        # The confirmation page announces what will be created, and nothing
        # exists yet: preparing is a two-stage gesture.
        _, page = self._obtenir("/reglages/essai-reel")
        self.assertIn("AUCUN APPEL NE PART DE CE BOUTON", page)
        self.assertEqual(len(base.lister_campagnes()), 0)
        _, page = self._poster("/reglages/essai-reel", {"confirmer": "oui"})
        campagnes_creees = base.lister_campagnes()
        self.assertEqual(len(campagnes_creees), 1)
        campagne = campagnes_creees[0]
        self.assertEqual(campagne["statut"], "prête")
        contacts = base.contacts_de_campagne(campagne["id"])
        self.assertEqual(len(contacts), len(essai_reel.IDENTITES))
        self.assertTrue(all(c["etat"] == "à appeler" for c in contacts))
        # NO call: neither in the database nor in the summary.
        self.assertTrue(all(not base.appels_du_contact_campagne(c["id"])
                            for c in contacts))
        self.assertEqual(sum(base.bilan_issues().values()), 0)
        # The created records are marked `test data`: removable in one go.
        self.assertEqual(base.compter_clients_jeu_essai(),
                         len(essai_reel.IDENTITES))
        _, page = self._poster("/reglages/jeu-essai",
                               {"action": "retirer", "confirmer": "oui"})
        self.assertIn("Jeu d'essai retiré", page)
        self.assertEqual(base.compter_clients_jeu_essai(), 0)

    def test_campagne_d_essai_deroulee_en_simulation_donne_des_issues_variees(self):
        """The only possible run WITHOUT telephoning: the simulation.

        What this test proves: the five contacts are handled SEPARATELY — one
        call each, one outcome each, one state each, although they all carry
        THE SAME number. It is the mechanism the real trial will exercise for
        real.

        What it does NOT prove, and cannot prove: that the agent understands
        spoken French. Over the phone, it is what the operator says that
        decides the outcome; here, the five contacts having the same number, it
        is the simulator's draw (seeded, hence reproducible) that tells them
        apart. Only the real trial settles it — see PROCEDURE-ESSAI-REEL.md.
        """
        base = self.application.base
        self._declarer(NUMERO_ESSAI)
        self._poster("/reglages/essai-reel", {"confirmer": "oui"})
        campagne_id = base.lister_campagnes()[0]["id"]
        self.application.planif.client_appels = calle_client.AppelSimule(
            graine=15, latence=0)
        assistant.executer_campagne(self.application, campagne_id)
        contacts = base.contacts_de_campagne(campagne_id)
        self.assertEqual(len(contacts), len(essai_reel.IDENTITES))
        # Each contact was called, and their outcome belongs to them.
        for contact in contacts:
            self.assertEqual(len(base.appels_du_contact_campagne(contact["id"])),
                             1)
        self.assertGreaterEqual(len({c["issue"] for c in contacts}), 3)
        self.assertGreater(len({c["etat"] for c in contacts}), 1)
        # The campaign ran to its end without getting muddled.
        self.assertEqual(base.obtenir_campagne(campagne_id)["statut"],
                         "terminée")


# --------------------------------------------------------------------------
# SEVERAL TESTERS — his own, AND those of the people who play a role with him
# What these tests protect, in order of importance: 1. AN OLD SETTING IS NOT
# LOST: a single number already declared is taken over as the FIRST tester,
# with nothing to retype; 2. the anti-duplicate safety lock stays WHOLE outside
# the declared numbers — a fourth repeated number is still refused, and
# removing a tester immediately restores the strict rule for them; 3. the roles
# are SHARED OUT among the testers, in rotation, and the screen SAYS who will
# have to play what; 4. the recognition bears on the NINE DIGITS, never on the
# masked text: a number that masks the same way is NOT confused with it; 5. the
# prepared campaign stays `ready`, zero calls, numbers masked.
# --------------------------------------------------------------------------
# Three tester numbers + a fourth `ordinary` number. As everywhere in this
# repository, they are taken from the roots the Arcep reserves for audiovisual
# works: they are assigned to nobody.
TESTEUR_A = "06 39 98 09 88"          # « moi »
TESTEUR_B = "06 39 98 07 21"          # « Paul »
TESTEUR_C = "+33 6 39 98 06 43"  # `the practice next door`
QUATRIEME = "06 39 98 05 10"  # nobody: strict rule
MASQUE_A = "06 39 •• •• 88"
MASQUE_B = "06 39 •• •• 21"
MASQUE_C = "+33 6 •• •• •• 43"


class TestTesteursUnite(unittest.TestCase):
    """The testers outside the server: takeover, list, sharing out, safety lock.
    """

    def _preferences(self):
        return generation.Preferences(None)

    def test_ancien_reglage_a_numero_unique_est_repris_comme_premier_testeur(self):
        preferences = self._preferences()
        # The exact state of an installation from BEFORE the testers: a single
        # declared number, no list.
        preferences.definir(essai_reel.CLE_NUMERO_ESSAI, TESTEUR_A)
        self.assertEqual(essai_reel.testeurs(preferences),
                         [{"nom": essai_reel.NOM_PREMIER_TESTEUR,
                           "telephone": TESTEUR_A}])
        self.assertEqual(essai_reel.numeros_declares(preferences), [TESTEUR_A])
        # ...and the old name goes on returning what it returned.
        self.assertEqual(essai_reel.numero_declare(preferences), TESTEUR_A)
        # The takeover REWRITES nothing: the old setting is intact as long as
        # nobody has built a list.
        self.assertIsNone(preferences.obtenir(essai_reel.CLE_TESTEURS))

    def test_la_liste_prime_et_tient_l_ancien_reglage_a_jour(self):
        preferences = self._preferences()
        preferences.definir(essai_reel.CLE_NUMERO_ESSAI, TESTEUR_A)
        essai_reel.ajouter_testeur(preferences, "Paul", TESTEUR_B)
        self.assertEqual([t["nom"] for t in essai_reel.testeurs(preferences)],
                         [essai_reel.NOM_PREMIER_TESTEUR, "Paul"])
        # The old setting carries the FIRST tester's number: a program that
        # only knew about it reads something correct.
        self.assertEqual(preferences.obtenir(essai_reel.CLE_NUMERO_ESSAI),
                         TESTEUR_A)
        # With the first one removed, the next one takes its place.
        _, retire = essai_reel.retirer_testeur(preferences, 1)
        self.assertEqual(retire["telephone"], TESTEUR_A)
        self.assertEqual(preferences.obtenir(essai_reel.CLE_NUMERO_ESSAI),
                         TESTEUR_B)
        # Emptied, the list also erases the old setting.
        essai_reel.retirer_testeur(preferences, 1)
        self.assertEqual(essai_reel.testeurs(preferences), [])
        self.assertEqual(preferences.obtenir(essai_reel.CLE_NUMERO_ESSAI), "")

    def test_un_numero_deja_declare_est_refuse_meme_ecrit_autrement(self):
        preferences = self._preferences()
        essai_reel.ajouter_testeur(preferences, "moi", TESTEUR_A)
        with self.assertRaises(saisie.SaisieInvalide) as refus:
            essai_reel.ajouter_testeur(preferences, "Paul", "+33639980988")
        self.assertIn("déjà déclaré", str(refus.exception))
        self.assertEqual(len(essai_reel.testeurs(preferences)), 1)
        # The too-short name and the unreadable number are refused separately,
        # each with its own reason.
        with self.assertRaises(saisie.SaisieInvalide) as refus:
            essai_reel.ajouter_testeur(preferences, "P", TESTEUR_B)
        self.assertIn("nom du testeur", str(refus.exception))
        with self.assertRaises(saisie.SaisieInvalide) as refus:
            essai_reel.ajouter_testeur(preferences, "Paul", "06 39 98")
        self.assertIn("Numéro de téléphone invalide", str(refus.exception))
        self.assertEqual(len(essai_reel.testeurs(preferences)), 1)

    def test_le_nombre_de_testeurs_est_borne_et_le_refus_le_dit(self):
        preferences = self._preferences()
        for rang in range(essai_reel.TESTEURS_MAXIMUM):
            # Distinct numbers, all taken from the Arcep fiction root.
            essai_reel.ajouter_testeur(preferences, f"Testeur {rang}",
                                       f"06 39 98 0{rang} 11")
        self.assertEqual(len(essai_reel.testeurs(preferences)),
                         essai_reel.TESTEURS_MAXIMUM)
        with self.assertRaises(saisie.SaisieInvalide) as refus:
            essai_reel.ajouter_testeur(preferences, "un de trop", QUATRIEME)
        self.assertIn("au maximum", str(refus.exception))
        # Nothing was added, and a removal immediately reopens the place.
        self.assertEqual(len(essai_reel.testeurs(preferences)),
                         essai_reel.TESTEURS_MAXIMUM)
        essai_reel.retirer_testeur(preferences, 1)
        essai_reel.ajouter_testeur(preferences, "un de plus", QUATRIEME)
        self.assertEqual(len(essai_reel.testeurs(preferences)),
                         essai_reel.TESTEURS_MAXIMUM)

    def test_retirer_un_rang_qui_n_existe_pas_ne_touche_a_rien(self):
        preferences = self._preferences()
        essai_reel.ajouter_testeur(preferences, "moi", TESTEUR_A)
        liste, retire = essai_reel.retirer_testeur(preferences, 7)
        self.assertIsNone(retire)
        self.assertEqual(len(liste), 1)

    def test_la_reconnaissance_porte_sur_plusieurs_numeros_et_eux_seuls(self):
        numeros = [TESTEUR_A, TESTEUR_B, TESTEUR_C]
        for numero in numeros:
            self.assertTrue(db.est_numero_essai(numero, numeros))
        # ...whatever the spelling — it really is the DIGITS that count.
        self.assertTrue(db.est_numero_essai("+33639980988", numeros))
        self.assertTrue(db.est_numero_essai("06 39 98 06 43", numeros))
        # A fourth number is NOT exempted.
        self.assertFalse(db.est_numero_essai(QUATRIEME, numeros))
        # Empty list: nobody is exempted (the strict rule for everybody).
        self.assertFalse(db.est_numero_essai(TESTEUR_A, []))

    def test_un_numero_qui_se_masque_pareil_n_est_pas_confondu(self):
        # `06 39 98 01 88` masks EXACTLY like TESTEUR_A. Confusing them would
        # mark a REAL person as test data.
        jumeau = "06 39 98 01 88"
        self.assertEqual(db.masquer_telephone(jumeau),
                         db.masquer_telephone(TESTEUR_A))
        self.assertFalse(db.est_numero_essai(
            jumeau, [TESTEUR_A, TESTEUR_B, TESTEUR_C]))

    def test_les_roles_tournent_sur_les_testeurs(self):
        trois = [{"nom": "moi", "telephone": TESTEUR_A},
                 {"nom": "Paul", "telephone": TESTEUR_B},
                 {"nom": "le cabinet d'à côté", "telephone": TESTEUR_C}]
        repartition = essai_reel.repartir(
            essai_reel.identites_detaillees(), trois)
        self.assertEqual([p["testeur"] for p in repartition],
                         ["moi", "Paul", "le cabinet d'à côté", "moi", "Paul"])
        self.assertEqual([p["telephone"] for p in repartition],
                         [TESTEUR_A, TESTEUR_B, TESTEUR_C,
                          TESTEUR_A, TESTEUR_B])
        # The first name still recalls the role, whichever tester it is.
        self.assertEqual([essai_reel.prenom(p["identite"]) for p in repartition],
                         ["Alice", "Rémi", "Diane", "Hugo", "Nina"])

    def test_un_seul_testeur_donne_exactement_le_comportement_d_avant(self):
        seul = [{"nom": "moi", "telephone": TESTEUR_A}]
        repartition = essai_reel.repartir(
            essai_reel.identites_detaillees(), seul)
        self.assertEqual({p["telephone"] for p in repartition}, {TESTEUR_A})
        self.assertEqual([p["identite"] for p in repartition],
                         [nom for nom, _, _ in essai_reel.IDENTITES])
        # Without any tester, there is nothing to share out — and we say so.
        self.assertEqual(essai_reel.repartir(
            essai_reel.identites_detaillees(), []), [])

    def test_nombre_d_identites_borne_et_explique(self):
        self.assertEqual(essai_reel.valider_nombre_identites(""),
                         len(essai_reel.IDENTITES))
        self.assertEqual(essai_reel.valider_nombre_identites("8"), 8)
        for refuse, morceau in ((str(essai_reel.IDENTITES_MINIMUM - 1),
                                 "trop peu"),
                                (str(essai_reel.IDENTITES_MAXIMUM + 1),
                                 "au maximum"),
                                ("beaucoup", "illisible")):
            with self.assertRaises(saisie.SaisieInvalide) as refus:
                essai_reel.valider_nombre_identites(refuse)
            self.assertIn(morceau, str(refus.exception))

    def test_au_dela_de_cinq_les_roles_reviennent_avec_la_meme_initiale(self):
        details = essai_reel.identites_detaillees(8)
        self.assertEqual(len(details), 8)
        # The roles come back in the same order...
        self.assertEqual([d["court"] for d in details],
                         ["accepte", "refuse", "autre date", "humain",
                          "ne décroche pas", "accepte", "refuse",
                          "autre date"])
        # ...carried by OTHER identities, with the same initial.
        self.assertEqual(len({d["identite"] for d in details}), 8)
        for rang in range(5, 8):
            self.assertEqual(essai_reel.prenom(details[rang]["identite"])[0],
                             essai_reel.prenom(details[rang - 5]["identite"])[0])

    def test_le_cout_est_annonce_jamais_devine(self):
        self.assertIn("5 appel(s)", essai_reel.cout_lisible(5))
        self.assertIn("0,25 $", essai_reel.cout_lisible(5))
        self.assertIn("0,05 $ l'appel", essai_reel.cout_lisible(5))

    def test_l_application_reprend_un_fichier_de_reglages_d_avant(self):
        """The real case: a preferences.json written by the earlier version."""
        with tempfile.TemporaryDirectory() as dossier:
            chemin_base = os.path.join(dossier, "essai.db")
            with open(os.path.join(dossier, "preferences.json"), "w",
                      encoding="utf-8") as fichier:
                json.dump({"numero_essai": TESTEUR_A}, fichier)
            application = serveur.Application(chemin_base=chemin_base)
            try:
                # The database knows it from start-up, with nothing to retype.
                self.assertEqual(application.base.numeros_essai, [TESTEUR_A])
                self.assertEqual(application.base.numero_essai, TESTEUR_A)
                self.assertEqual(
                    essai_reel.testeurs(application.preferences),
                    [{"nom": essai_reel.NOM_PREMIER_TESTEUR,
                      "telephone": TESTEUR_A}])
            finally:
                application.base.fermer()


class TestServeurTesteurs(_TestAvecServeurWeb):
    """The testers on screen: declared one by one, masked, roles shared out."""

    CHAMPS_REGLAGES = {"entreprise": "Cabinet Essai", "plage_debut": "00:00",
                       "plage_fin": "23:59"}

    def _ajouter(self, nom, numero):
        return self._poster("/reglages/testeur",
                            {"action": "ajouter", "nom": nom,
                             "numero": numero})

    def _retirer(self, rang):
        return self._poster("/reglages/testeur",
                            {"action": "retirer", "rang": str(rang)})

    def _les_trois(self):
        self._ajouter("moi", TESTEUR_A)
        self._ajouter("Paul", TESTEUR_B)
        self._ajouter("le cabinet d'à côté", TESTEUR_C)

    def _grille_essai(self, lignes):
        """Builds a `confirmation` campaign and pastes these rows."""
        _, page = self._poster("/assistant/nature", {"nature": "confirmation"})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "ordre": "liste",
            "opt_recontacter": "1", "opt_liberer": "1",
            "relance_mode": "delai", "relance_delai": "4", "relance_max": "3",
            "info_entreprise": "Cabinet Essai"})
        self._poster("/assistant/importer",
                     {"b": b, "mode": "collage", "liste": "\n".join(lignes)})
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        return b, page

    def test_ancien_reglage_repris_puis_complete_sans_rien_retaper(self):
        preferences = self.application.preferences
        # (1) The earlier state: a single number declared through the old
        # field.
        self._poster("/reglages/enregistrer",
                     dict(self.CHAMPS_REGLAGES, numero_essai=TESTEUR_A))
        preferences.definir(essai_reel.CLE_TESTEURS, None)   # aucune liste
        # (2) The page shows it as the FIRST tester, named `me`, masked.
        _, page = self._obtenir("/reglages")
        self.assertIn(essai_reel.NOM_PREMIER_TESTEUR, page)
        self.assertIn(MASQUE_A, page)
        self.assertNotIn(TESTEUR_A, page)
        # (3) We add a second one: the first is STILL there.
        self._ajouter("Paul", TESTEUR_B)
        self.assertEqual([t["telephone"]
                          for t in essai_reel.testeurs(preferences)],
                         [TESTEUR_A, TESTEUR_B])
        self.assertEqual(self.application.base.numeros_essai,
                         [TESTEUR_A, TESTEUR_B])

    def test_trois_testeurs_declares_masques_et_retirables(self):
        self._les_trois()
        _, page = self._obtenir("/reglages")
        for nom, masque, clair in (("moi", MASQUE_A, TESTEUR_A),
                                   ("Paul", MASQUE_B, TESTEUR_B),
                                   ("le cabinet d", MASQUE_C, TESTEUR_C)):
            self.assertIn(nom, page)
            self.assertIn(masque, page)
            self.assertNotIn(clair, page)      # jamais en clair, nulle part
        self.assertEqual(len(self.application.base.numeros_essai), 3)
        # Removal brings the list back to two, without touching the others.
        self._retirer(2)
        self.assertEqual([t["nom"] for t
                          in essai_reel.testeurs(self.application.preferences)],
                         ["moi", "le cabinet d'à côté"])

    def test_saisie_refusee_jamais_perdue_et_dite(self):
        self._ajouter("moi", TESTEUR_A)
        # An unreadable number: the refusal says why, and both the name and the
        # number typed come back into their fields (nothing to retype).
        _, fragment = self._poster("/reglages/testeur",
                                   {"action": "ajouter", "nom": "Paul",
                                    "numero": "06 39 98", "fragment": "1"})
        self.assertIn("Testeur refusé", fragment)
        self.assertIn("Numéro de téléphone invalide", fragment)
        self.assertIn('value="Paul"', fragment)
        self.assertIn("06 39 98", fragment)
        # A number ALREADY declared: refused naming the tester who carries it,
        # and it comes back MASKED — it is already known, there is nothing to
        # recover.
        _, fragment = self._poster("/reglages/testeur",
                                   {"action": "ajouter", "nom": "Paul",
                                    "numero": "+33639980988",
                                    "fragment": "1"})
        self.assertIn("déjà déclaré", fragment)
        self.assertIn("moi", fragment)
        self.assertNotIn("+33639980988", fragment)
        self.assertIn(MASQUE_A, fragment)
        # Nothing was added or lost.
        self.assertEqual(len(essai_reel.testeurs(self.application.preferences)),
                         1)

    def test_l_ecran_annonce_qui_devra_jouer_quoi(self):
        self._les_trois()
        _, page = self._obtenir("/reglages")
        # The short summary, as it reads: `Alice (accepts) -> me`.
        for prenom, court, testeur in (("Alice", "accepte", "moi"),
                                       ("Rémi", "refuse", "Paul"),
                                       ("Diane", "autre date",
                                        "le cabinet d&#x27;à côté"),
                                       ("Hugo", "humain", "moi"),
                                       ("Nina", "ne décroche pas", "Paul")):
            self.assertIn(f"{prenom} ({court}) → <strong>{testeur}</strong>",
                          page)
        # ...and the detailed table, with the numbers MASKED.
        self.assertIn("<th>Rôle à jouer</th>", page)
        self.assertIn("<th>Par qui</th>", page)
        for masque, clair in ((MASQUE_A, TESTEUR_A), (MASQUE_B, TESTEUR_B),
                              (MASQUE_C, TESTEUR_C)):
            self.assertIn(masque, page)
            self.assertNotIn(clair, page)
        # The confirmation page repeats the same announcement, spelled out in
        # full.
        _, confirmation = self._obtenir("/reglages/essai-reel")
        self.assertIn("Qui devra jouer quoi", confirmation)
        for clair in (TESTEUR_A, TESTEUR_B, TESTEUR_C):
            self.assertNotIn(clair, confirmation)

    def test_le_garde_fou_tient_pour_les_autres_numeros(self):
        self._les_trois()
        lignes = [f"Mme Alice Dubreuil;{TESTEUR_A};{DEMAIN};Séance",
                  f"M. Rémi Chastain;{TESTEUR_B};{DEMAIN};Séance",
                  f"Mme Diane Verrier;{TESTEUR_C};{DEMAIN};Séance",
                  f"M. Hugo Sernin;{TESTEUR_A};{DEMAIN};Séance",
                  f"Mme Une;{QUATRIEME};{DEMAIN};Séance",
                  f"M. Deux;{QUATRIEME};{DEMAIN};Séance"]
        b, page = self._grille_essai(lignes)
        contacts = self.application.obtenir_brouillon_assistant(b)["contacts"]
        # The four tester rows pass (including TESTEUR_A twice); the FOURTH
        # repeated number is still refused.
        self.assertEqual([c["nom"] for c in contacts],
                         ["Mme Alice Dubreuil", "M. Rémi Chastain",
                          "Mme Diane Verrier", "M. Hugo Sernin", "Mme Une"])
        self.assertIn("doublon ignoré", page)
        self.assertEqual(page.count("🧪 numéro d'essai"), 4)
        # Removing a tester GIVES them back the strict rule, immediately.
        self._retirer(2)                      # Paul
        lignes_paul = [f"M. Un;{TESTEUR_B};{DEMAIN};Séance",
                       f"M. Deux;{TESTEUR_B};{DEMAIN};Séance"]
        b, page = self._grille_essai(lignes_paul)
        self.assertIn("doublon ignoré", page)
        self.assertEqual(
            len(self.application.obtenir_brouillon_assistant(b)["contacts"]), 1)
        # ...and the other two keep their exemption.
        lignes_moi = [f"M. Un;{TESTEUR_A};{DEMAIN};Séance",
                      f"M. Deux;{TESTEUR_A};{DEMAIN};Séance"]
        b, _ = self._grille_essai(lignes_moi)
        self.assertEqual(
            len(self.application.obtenir_brouillon_assistant(b)["contacts"]), 2)

    def test_campagne_preparee_repartit_les_roles_et_ne_passe_aucun_appel(self):
        base = self.application.base
        self._les_trois()
        _, page = self._obtenir("/reglages/essai-reel")
        self.assertIn("AUCUN APPEL NE PART DE CE BOUTON", page)
        self.assertIn("Qui devra jouer quoi", page)
        self.assertEqual(len(base.lister_campagnes()), 0)  # nothing created yet
        _, page = self._poster("/reglages/essai-reel", {"confirmer": "oui"})
        campagne = base.lister_campagnes()[0]
        self.assertEqual(campagne["statut"], "prête")
        contacts = base.contacts_de_campagne(campagne["id"])
        self.assertEqual([c["nom"] for c in contacts],
                         [nom for nom, _, _ in essai_reel.IDENTITES])
        # The roles ROTATED across the three testers: 1, 2, 3, 1, 2.
        numeros = [base.telephone_contact_campagne(c["id"]) for c in contacts]
        self.assertEqual(numeros, [TESTEUR_A, TESTEUR_B, TESTEUR_C,
                                   TESTEUR_A, TESTEUR_B])
        # NO call, and all marked as test data.
        self.assertTrue(all(not base.appels_du_contact_campagne(c["id"])
                            for c in contacts))
        self.assertEqual(sum(base.bilan_issues().values()), 0)
        self.assertTrue(all(c["numero_essai"] for c in contacts))
        # The campaign's screen says the roles are shared out, and nothing
        # appears there in clear.
        self.assertIn("répartis sur <strong>3 testeurs</strong>", page)
        for clair in (TESTEUR_A, TESTEUR_B, TESTEUR_C):
            self.assertNotIn(clair, page)

    def test_le_nombre_d_identites_est_choisi_borne_et_chiffre(self):
        base = self.application.base
        self._les_trois()
        # The cost is announced on the settings screen, never guessed.
        _, page = self._obtenir("/reglages")
        self.assertIn("5 appel(s), soit environ 0,25 $", page)
        # A number that is too small is REFUSED, with the reason, and nothing
        # is created.
        _, page = self._obtenir("/reglages/essai-reel?nombre=3")
        self.assertIn("trop peu", page)
        self.assertIn("Rien n", page)
        self.assertEqual(len(base.lister_campagnes()), 0)
        # Eight identities: eight contacts, still shared out in rotation.
        self._poster("/reglages/essai-reel", {"confirmer": "oui",
                                              "nombre": "8"})
        contacts = base.contacts_de_campagne(base.lister_campagnes()[0]["id"])
        self.assertEqual(len(contacts), 8)
        numeros = [base.telephone_contact_campagne(c["id"]) for c in contacts]
        self.assertEqual(numeros, [TESTEUR_A, TESTEUR_B, TESTEUR_C] * 2
                         + [TESTEUR_A, TESTEUR_B])
        self.assertEqual(len({c["nom"] for c in contacts}), 8)

    def test_sans_testeur_le_bouton_le_dit_et_ne_cree_rien(self):
        base = self.application.base
        _, page = self._obtenir("/reglages")
        self.assertIn("Aucun numéro d'essai déclaré", page)
        _, page = self._poster("/reglages/essai-reel", {"confirmer": "oui"})
        self.assertIn("rien n'a été préparé", page.lower())
        self.assertEqual(len(base.lister_campagnes()), 0)
        self.assertEqual(base.compter_clients_jeu_essai(), 0)


# --------------------------------------------------------------------------
# THE DEFECT OF 01/08/2026, AND ITS FIX  What actually happened: the
# CALLE_API_KEY variable contained the dashboard's ADDRESS instead of the key.
# The API answered 401 twice, and RingBack marked the contacts `unreachable - 1
# attempt(s), cap reached, to be handled by a human`. Three lies at once:
# nobody had been called, no attempt had taken place, and the fault was OURS.
# With a list of twenty people, all twenty would have been tainted.  The four
# guarantees exercised here, against the LOCAL FAKE API (the real one is NEVER
# contacted): 1. an authentication failure consumes no attempt and changes no
# contact's state; 2. the campaign goes ON HOLD (not `finished`) and is resumed
# as it was; 3. the message says what did NOT happen, and what to do; 4. a key
# that does not have the shape of a key is refused BEFORE any connection —
# without ever being displayed.
# --------------------------------------------------------------------------
class TestFormeDeLaCle(unittest.TestCase):
    """(4) The shape check: refusing what is plainly not a key."""

    ADRESSE = "dashboard.heycall-e.com"  # the mistake actually made
    # ANOTHER address, which appears nowhere in the product's texts: it alone
    # makes it possible to prove that a key is never copied out. (The
    # dashboard's address is quoted on purpose in the instructions — its
    # absence would prove nothing.)
    ADRESSE_ETRANGERE = "mon-espace-client.example.org"

    def test_une_adresse_web_est_refusee_et_seulement_decrite(self):
        with self.assertRaises(calle_client.CleMalFormee) as refus:
            calle_client.valider_forme_cle(self.ADRESSE)
        message = str(refus.exception)
        # WHAT WAS DETECTED, and the key DESCRIBED — never copied out.
        self.assertIn("ADRESSE WEB", message)
        self.assertIn("Ce qui a été fourni : 23 caractère(s), ressemble à "
                      "une adresse web", message)
        # It appears only once: in `where to find the real key`.
        self.assertEqual(message.count(self.ADRESSE), 1)
        self.assertIn(f"tableau de bord CALL-E ({self.ADRESSE})", message)
        # WHERE TO FIND THE REAL ONE.
        self.assertIn("API keys", message)
        self.assertIn("configurer_cle.cmd", message)

    def test_la_cle_fournie_n_est_jamais_recopiee_dans_le_message(self):
        with self.assertRaises(calle_client.CleMalFormee) as refus:
            calle_client.valider_forme_cle(self.ADRESSE_ETRANGERE)
        self.assertNotIn(self.ADRESSE_ETRANGERE, str(refus.exception))
        self.assertNotIn("example", str(refus.exception))

    def test_les_autres_formes_manifestement_fausses(self):
        cas = {
            "https://dashboard.heycall-e.com/keys": "ADRESSE WEB",
            '"cle-secrete-0123456789"': "guillemets",
            "cle secrete 0123456789": "espace",
            "trop-court": "trop courte",
        }
        for brut, attendu in cas.items():
            with self.subTest(brut=attendu):
                with self.assertRaises(calle_client.CleMalFormee) as refus:
                    calle_client.valider_forme_cle(brut)
                message = str(refus.exception)
                self.assertIn(attendu, message)
                self.assertNotIn(brut, message)  # NEVER the key

    def test_une_cle_plausible_passe_et_est_nettoyee(self):
        self.assertEqual(
            calle_client.valider_forme_cle("  sk-essai-0123456789abc  "),
            "sk-essai-0123456789abc")

    def test_absence_de_cle_reste_le_refus_d_avant(self):
        for rien in ("", "   ", None):
            with self.assertRaises(calle_client.CleApiAbsente) as refus:
                calle_client.valider_forme_cle(rien)
            self.assertNotIsInstance(refus.exception, calle_client.CleMalFormee)

    def test_le_client_reel_refuse_de_se_construire(self):
        """THE LOCK: no real client can exist with such a key."""
        with self.assertRaises(calle_client.CleMalFormee):
            calle_client.AppelReel(cle_api=self.ADRESSE)

    def test_le_mode_reel_du_serveur_refuse_au_demarrage(self):
        """(3)(4) The refusal comes BEFORE the first call, at launch itself."""
        ancienne = os.environ.get("CALLE_API_KEY")
        os.environ["CALLE_API_KEY"] = self.ADRESSE_ETRANGERE
        try:
            with self.assertRaises(calle_client.CleApiAbsente) as refus:
                serveur.Application(":memory:", appels_reels=True)
        finally:
            if ancienne is None:
                os.environ.pop("CALLE_API_KEY", None)
            else:
                os.environ["CALLE_API_KEY"] = ancienne
        self.assertIn("ADRESSE WEB", str(refus.exception))
        self.assertNotIn(self.ADRESSE_ETRANGERE, str(refus.exception))

    def test_le_controle_de_fichier_sert_configurer_cle_cmd(self):
        """The SAME check, called by configurer_cle.cmd (one single piece of
        code).
        """
        dossier = tempfile.mkdtemp(prefix="ringback-cle-")
        self.addCleanup(shutil.rmtree, dossier, ignore_errors=True)
        chemin = os.path.join(dossier, "call-e-key.txt")
        with open(chemin, "w", encoding="utf-8") as fichier:
            fichier.write(self.ADRESSE_ETRANGERE + "\n")
        accepte, message = calle_client.controle_fichier_cle(chemin)
        self.assertFalse(accepte)
        self.assertIn("ADRESSE WEB", message)
        self.assertNotIn(self.ADRESSE_ETRANGERE, message)
        with open(chemin, "w", encoding="utf-8") as fichier:
            fichier.write("\nsk-essai-0123456789abc\n")
        accepte, message = calle_client.controle_fichier_cle(chemin)
        self.assertTrue(accepte)
        self.assertNotIn("sk-essai-0123456789abc", message)  # never displayed


class TestPanneDeNotreCote(_CampagneAssistant):
    """(1)(2)(3) The campaign stops dead, and nobody is tainted along the way.
    """

    CLE = "cle-de-test-0123456789"
    LIGNES = ("M. Un Contact;+33 6 39 98 50 61;{h};Séance",
              "Mme Deux Contact;+33 6 39 98 50 62;{h};Séance",
              "M. Trois Contact;+33 6 39 98 50 63;{h};Séance")

    def setUp(self):
        super().setUp()
        self._cle_sauvee = os.environ.pop("CALLE_API_KEY", None)
        if self._cle_sauvee is not None:
            self.addCleanup(os.environ.__setitem__, "CALLE_API_KEY",
                            self._cle_sauvee)

        class Faux(_FauxApiCalle):
            creations = []
            etats = [{"status": "queued"}]
        self.faux = Faux
        self.serveur_api = HTTPServer(("127.0.0.1", 0), Faux)
        threading.Thread(target=self.serveur_api.serve_forever,
                         daemon=True).start()
        self.url_api = f"http://127.0.0.1:{self.serveur_api.server_address[1]}"
        self.addCleanup(self.serveur_api.server_close)
        self.addCleanup(self.serveur_api.shutdown)
        self.dossier = tempfile.mkdtemp(prefix="ringback-panne-")
        self.addCleanup(shutil.rmtree, self.dossier, ignore_errors=True)
        self.chemin_audit = os.path.join(self.dossier, "audit.jsonl")

    # ------------------------------------------------------------ outillage
    def _campagne_de_trois(self):
        horaire = (datetime.datetime.now() + datetime.timedelta(days=3)
                   ).replace(hour=9, minute=0, second=0,
                             microsecond=0).isoformat(timespec="minutes")
        return self._campagne("confirmation",
                              [ligne.format(h=horaire) for ligne in self.LIGNES])

    def _brancher_client_reel(self):
        """The REAL client, plugged into the FAKE API — never the real one.

        The three locks are lifted here as principal() does: it is the real
        path that is exercised, not an imitation.
        """
        planif = self.application.planif
        planif.client_appels = calle_client.AppelReel(
            cle_api=self.CLE, url_base=self.url_api, delai_total=2.0,
            intervalle=0.01, delai_requete=2.0, chemin_audit=self.chemin_audit)
        planif.dry_run = False
        planif.confirmer_appels_reels()

    def _derouler_en_reel(self, campagne_id):
        self._brancher_client_reel()
        assistant.executer_campagne(self.application, campagne_id)
        base = self.application.base
        return (base.obtenir_campagne(campagne_id),
                base.contacts_de_campagne(campagne_id))

    def _lignes_audit(self):
        if not os.path.exists(self.chemin_audit):
            return []
        with open(self.chemin_audit, encoding="utf-8") as fichier:
            return [json.loads(ligne) for ligne in fichier
                    if ligne.strip()]

    def _verifier_campagne_intacte(self, campagne, contacts):
        """GUARANTEE (1): nothing was written about anybody."""
        base = self.application.base
        self.assertEqual(campagne["statut"], "en pause")  # (2) never `finished`
        for contact in contacts:
            self.assertEqual(contact["etat"], "à appeler")
            self.assertIsNone(contact["issue"])
            self.assertFalse(contact["detail"])
            # NO attempt counted: it is that count which tipped the contact
            # over the cap.
            self.assertEqual(base.appels_du_contact_campagne(contact["id"]), [])
        self.assertEqual(base.relances_de_campagne(campagne["id"]), [])

    # -------------------------------------------------------- (1)(2)(3) the
    # 401
    def test_401_met_la_campagne_en_pause_sans_salir_personne(self):
        self.faux.code_erreur_post = 401
        campagne_id = self._campagne_de_trois()
        campagne, contacts = self._derouler_en_reel(campagne_id)
        self.assertEqual(len(contacts), 3)
        self._verifier_campagne_intacte(campagne, contacts)
        # ONE SINGLE call was attempted: the other two people were not even
        # disturbed (with twenty, nineteen were spared).
        self.assertEqual(len(self.faux.creations), 1)
        # (3) THE MESSAGE: what happened, what did NOT happen, what to do.
        raison = campagne["raison_pause"]
        self.assertIn("clé d'accès CALL-E a été refusée", raison)
        self.assertIn("code 401", raison)
        self.assertIn("Personne n'a été appelé", raison)
        self.assertIn("aucun crédit CALL-E n'a été consommé", raison)
        self.assertIn("aucune tentative n'a été comptée", raison)
        self.assertIn("personne n'a été marqué « injoignable »", raison)
        self.assertIn("API keys", raison)
        self.assertIn("configurer_cle.cmd", raison)
        # None of the earlier jargon left.
        self.assertNotIn("l'API a répondu 401", raison)
        # THE AUDIT LOG says no call went out, number masked.
        lignes = self._lignes_audit()
        self.assertEqual(len(lignes), 1)
        self.assertEqual(lignes[0]["statut"], "aucun appel lancé")
        self.assertIn("Personne n'a été appelé", lignes[0]["detail"])
        self.assertEqual(lignes[0]["telephone"], "+33 6 •• •• •• 61")
        # AND THE SCREEN SAYS SO, in French, without a bare code.
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn("Campagne mise en pause toute seule", page)
        self.assertIn("clé d’accès CALL-E a été refusée".replace("’", "'"),
                      page.replace("&#x27;", "'"))
        _personne_n_est_injoignable(self, campagne_id, page)

    def test_apres_correction_la_campagne_reprend_les_trois(self):
        """(2) `resumed as it was`: the proof, not the promise."""
        self.faux.code_erreur_post = 401
        campagne_id = self._campagne_de_trois()
        self._derouler_en_reel(campagne_id)
        base = self.application.base
        # The key is corrected (here: the fake API stops refusing).
        self.faux.code_erreur_post = None
        self.faux.etats[:] = [{"status": "completed"}]
        self.application.planif.client_appels = calle_client.AppelSimule(
            graine=1, latence=0)
        assistant.executer_campagne(self.application, campagne_id)
        campagne = base.obtenir_campagne(campagne_id)
        self.assertEqual(campagne["statut"], "terminée")
        self.assertIsNone(campagne["raison_pause"])
        contacts = base.contacts_de_campagne(campagne_id)
        # ALL THREE were called: none had been lost along the way.
        self.assertEqual([len(base.appels_du_contact_campagne(c["id"]))
                          for c in contacts], [1, 1, 1])
        self.assertNotIn("à appeler", [c["etat"] for c in contacts])

    # ------------------------------------------------- (2) the other failures
    def test_429_et_500_arretent_aussi_la_campagne_avec_leur_message(self):
        attendus = {
            429: ("trop d'appels en trop peu de temps", "attendez quelques"),
            500: ("le service call-e est en panne", "pas ringback qui est"),
            402: ("n'a plus de crédit", "rechargez le compte"),
            # THE 403 POINTS AT THE ACCOUNT, NOT THE KEY (03/09/2026). Measured
            # outside RingBack: without a key and with an invented key, CALL-E
            # answers 401; with the real key, 403. So a 403 proves the key WAS
            # RECOGNISED, and the message must say so — otherwise we send the
            # owner off to paste a key that is perfectly fine.
            403: ("n'a pas le droit", "pas un problème de clé"),
        }
        for code, (constat, quoi_faire) in attendus.items():
            with self.subTest(code=code):
                self.faux.creations[:] = []
                self.faux.code_erreur_post = code
                campagne_id = self._campagne_de_trois()
                campagne, contacts = self._derouler_en_reel(campagne_id)
                self._verifier_campagne_intacte(campagne, contacts)
                self.assertEqual(len(self.faux.creations), 1)
                raison = campagne["raison_pause"]
                self.assertIn(constat, raison.lower())
                self.assertIn(quoi_faire, raison.lower())
                self.assertIn("Personne n'a été appelé", raison)


    def test_le_403_dit_que_la_CLE_n_est_pas_en_cause(self):
        """BORN OF HALF AN HOUR LOST (03/09/2026).

        He got that 403, pasted his key again into the Settings, restarted, and
        got the same error — because the message sent him towards `API keys,
        recreate it if necessary`. Measured afterwards outside RingBack, with
        urllib and the key alone: without a key -> 401, invented key -> 401,
        HIS key -> 403. The two codes say two things, and 403 means the key is
        recognised.

        This test holds both halves: NO LONGER sending people to the key, and
        naming the account.
        """
        texte = calle_client.QUOI_FAIRE_DROITS.lower()
        self.assertIn("pas un problème de clé", texte)
        self.assertIn("compte", texte)
        # AND ABOVE ALL NOT THE OPPOSITE: not another word about recreating the
        # key.
        self.assertNotIn("recréez-la", texte)
        self.assertNotIn("configurer_cle", texte)

    def test_un_code_inconnu_a_la_creation_arrete_quand_meme(self):
        """What decides is WHERE the failure happens — not whether we know the
        code.

        Observed on 01/08/2026 at the owner's: a 400 `result_schema is not
        supported` was classified as an `occasional failure` for want of being
        a known code, and his contact ended up `unreachable, cap reached` while
        no phone had rung. As long as the creation has not succeeded, the fault
        is necessarily on OUR side and it will hit the next one identically.

        We keep the original honesty: we go on SAYING that we do not know this
        code. We assert only what is verifiable — that nothing went out.
        """
        self.faux.code_erreur_post = 418
        campagne_id = self._campagne_de_trois()
        campagne, contacts = self._derouler_en_reel(campagne_id)
        self.assertEqual(campagne["statut"], "en pause")
        self.assertEqual(len(self.faux.creations), 1)  # the 2 others spared
        for contact in contacts:
            self.assertEqual(contact["etat"], "à appeler")
            self.assertIsNone(contact["issue"])
        lignes = self._lignes_audit()
        self.assertIn("ne connaît pas la signification de ce code",
                      lignes[0]["detail"])
        self.assertIn("personne n'a été appelé", lignes[0]["detail"])
        self.assertEqual(lignes[0]["statut"], "aucun appel lancé")
        # And the message put before the owner's eyes QUOTES the response: it
        # is what names the failure when the code itself says nothing.
        self.assertIn("refus simulé", campagne["raison_pause"])

    def test_service_injoignable_arrete_la_campagne(self):
        """Network cut / service silent: the same logic, without an HTTP code.
        """
        campagne_id = self._campagne_de_trois()
        planif = self.application.planif
        planif.client_appels = calle_client.AppelReel(
            cle_api=self.CLE, url_base="http://127.0.0.1:1",  # port mort
            delai_total=2.0, intervalle=0.01, delai_requete=1.0,
            chemin_audit=self.chemin_audit)
        planif.dry_run = False
        planif.confirmer_appels_reels()
        assistant.executer_campagne(self.application, campagne_id)
        base = self.application.base
        campagne = base.obtenir_campagne(campagne_id)
        self._verifier_campagne_intacte(
            campagne, base.contacts_de_campagne(campagne_id))
        self.assertIn("injoignable depuis cet ordinateur",
                      campagne["raison_pause"])
        self.assertIn("connexion Internet", campagne["raison_pause"])

    # ------------------------------------------------- (1) NO REGRESSION
    def test_un_echec_du_contact_se_comporte_exactement_comme_avant(self):
        """WHAT MUST NOT MOVE: the contact who does not answer.

        Attempt counted, follow-up scheduled, campaign finished — the original
        behaviour, to the letter. It is the half of the distinction that counts
        most: we have not `softened` the real failures.
        """
        self.faux.etats[:] = [{"status": "no_answer"}]  # nobody answers
        campagne_id = self._campagne_de_trois()
        campagne, contacts = self._derouler_en_reel(campagne_id)
        base = self.application.base
        self.assertEqual(campagne["statut"], "terminée")
        self.assertIsNone(campagne["raison_pause"])
        self.assertEqual(len(self.faux.creations), 3)  # all three called
        for contact in contacts:
            self.assertEqual(contact["etat"], "à recontacter")
            self.assertEqual(contact["issue"], "no_answer")
            self.assertEqual(len(base.appels_du_contact_campagne(contact["id"])),
                             1)  # THE attempt counted
        planifiees = [r for r in base.relances_de_campagne(campagne_id)
                      if r["statut"] == "planifiée"]
        self.assertEqual(len(planifiees), 3)  # follow-ups scheduled
        self.assertEqual(self._lignes_audit()[0]["statut"], "pas de réponse")

    def test_au_maximum_de_rappels_un_vrai_non_joint_reste_injoignable(self):
        """The other half: at the maximum number of callbacks, a GENUINE unreached
        contact stays unreachable — and the text NAMES the setting (renamed on
        21/08/2026, `cap` did not say what it was a cap on).
        """
        self.faux.etats[:] = [{"status": "no_answer"}]
        campagne_id = self._campagne_de_trois()
        base = self.application.base
        campagne = base.obtenir_campagne(campagne_id)
        configuration = assistant.configuration_campagne(campagne)
        configuration["options"]["relance_max"] = "0"    # aucun rappel
        base.definir_configuration_campagne(campagne_id,
                                            json.dumps(configuration))
        campagne, contacts = self._derouler_en_reel(campagne_id)
        self.assertEqual(campagne["statut"], "terminée")
        for contact in contacts:
            self.assertEqual(contact["etat"], "injoignable")
            self.assertIn("maximum de rappels atteint", contact["detail"])
            self.assertNotIn("plafond", contact["detail"].lower())

    def _au_dela_du_plafond(self, campagne_id, plafond="1"):
        """A contact who has ALREADY exhausted their callback cap."""
        base = self.application.base
        campagne = base.obtenir_campagne(campagne_id)
        configuration = assistant.configuration_campagne(campagne)
        configuration["options"]["relance_max"] = plafond
        base.definir_configuration_campagne(campagne_id,
                                            json.dumps(configuration))
        contact = base.contacts_de_campagne(campagne_id)[0]
        for tentative in range(int(plafond) + 1):
            base.ajouter_appel_campagne(campagne_id, contact["id"], tentative,
                                        issue="no_answer")
        return (base.obtenir_campagne(campagne_id), contact,
                assistant.configuration_campagne(
                    base.obtenir_campagne(campagne_id))["options"])

    def test_le_maximum_de_rappels_s_applique_en_simulation_aussi(self):
        """HIS DECISION OF 21/08/2026, which replaces that of 18/08.

        On 18/08 he had asked for the opposite — `en mode simulation, il ne
        faut pas faire la finalite du plafond atteint` — and it was for a good
        reason: his test campaigns stopped there without his seeing what came
        next. Two things have changed since:

        - WHAT BOTHERED HIM IS SETTLED ANOTHER WAY: at the maximum number of
        callbacks, a move campaign now cancels the appointment and sends the
        person to a human callback (20/08). It is no longer a dead end.

        - THE LIFTING HAD NO BOUND, and it is a test that showed it: maximum set
        to 3, THIRTEEN callbacks armed in twelve rounds, endlessly. A
        simulation that behaves differently from reality no longer predicts
        anything.

        We measure the rule at its point of passage — `_apres_non_joint`, which
        EVERY unreached contact goes through, from whatever campaign.
        """
        base = self.application.base
        campagne_id = self._campagne_de_trois()
        campagne, contact, options = self._au_dela_du_plafond(campagne_id)
        # The calls are SIMULATED here — and that no longer changes anything.
        self.assertIsInstance(self.application.planif.client_appels,
                              calle_client.AppelSimule)
        assistant._apres_non_joint(base, self.application.preferences,
                                   campagne, options, contact["id"],
                                   "no_answer")
        fiche = base.obtenir_contact_campagne(contact["id"])
        self.assertEqual(fiche["etat"], "injoignable")
        self.assertIn("maximum de rappels atteint", fiche["detail"])
        # And no callback is armed any more: the chain stops for good.
        self.assertEqual(
            [r for r in base.relances_de_campagne(campagne_id)
             if r["statut"] == "planifiée" and r["contact_id"] == contact["id"]],
            [])

    def test_la_chaine_de_rappels_a_donc_une_fin_en_simulation(self):
        """THE MEASURED FACT THAT CHANGED THE RULE: without a maximum, the
        callbacks chained ENDLESSLY in simulation. Here we launch them to the
        very end — the number ends in 53, nobody ever answers — and the chain
        must stop by itself, without our having to close the campaign.
        """
        base = self.application.base
        horaire = (datetime.datetime.now() + datetime.timedelta(days=3)
                   ).replace(hour=9, minute=0, second=0,
                             microsecond=0).isoformat(timespec="minutes")
        campagne_id = self._campagne(
            "confirmation",
            [f"M. Jamais Là;+33 6 39 98 50 53;{horaire};Séance"],
            relance_max="2", relance_mode="delai", relance_delai="0")
        assistant.executer_campagne(self.application, campagne_id)
        tours = 0
        while [r for r in base.relances_de_campagne(campagne_id)
               if r["statut"] == "planifiée"]:
            tours += 1
            self.assertLess(tours, 8, "la chaîne de rappels ne s'arrête pas")
            campagnes.executer_relances_dues(base, self.application.planif,
                                             self.application.preferences)
        fiche = base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(fiche["etat"], "injoignable")
        self.assertIn("maximum de rappels atteint", fiche["detail"])
        # The attempt count does not exceed what he set.
        self.assertLessEqual(
            len(base.appels_du_contact_campagne(fiche["id"])), 3)

    def test_pour_de_vrais_appels_la_regle_est_la_meme(self):
        """WHAT COUNTS MOST: simulation and reality behave THE SAME. That is the
        whole point of a simulation — it is only worth something if it predicts
        what will really happen.
        """
        base = self.application.base
        campagne_id = self._campagne_de_trois()
        campagne, contact, options = self._au_dela_du_plafond(campagne_id)
        self._brancher_client_reel()
        self.assertNotIsInstance(self.application.planif.client_appels,
                                 calle_client.AppelSimule)
        assistant._apres_non_joint(base, self.application.preferences,
                                   campagne, options, contact["id"],
                                   "no_answer")
        fiche = base.obtenir_contact_campagne(contact["id"])
        self.assertEqual(fiche["etat"], "injoignable")
        self.assertIn("maximum de rappels atteint", fiche["detail"])

    def test_un_maximum_a_zero_ne_programme_rien(self):
        """The other boundary: `zero callbacks` is HIS decision, the same as
        unticking `Call back`. Nothing must be scheduled behind his back.
        """
        base = self.application.base
        campagne_id = self._campagne_de_trois()
        campagne, contact, options = self._au_dela_du_plafond(campagne_id,
                                                              plafond="0")
        assistant._apres_non_joint(base, self.application.preferences,
                                   campagne, options, contact["id"],
                                   "no_answer")
        fiche = base.obtenir_contact_campagne(contact["id"])
        self.assertEqual(fiche["etat"], "injoignable")
        self.assertIn("maximum de rappels atteint", fiche["detail"])

    def test_les_anciens_details_sont_traduits_a_l_affichage(self):
        """WHAT IS ALREADY WRITTEN IN THE DATABASE IS NOT REWRITTEN. Measured in
        his database: 39 contacts carry `cap reached`, frozen at the moment of
        their call.

        Rewriting them would be a DATA MIGRATION — the product only makes
        additive ones — and they are archives, not labels. So we translate them
        AT DISPLAY TIME, as `epargne` -> `pas appele` on 11/08/2026: the word
        changes, the data does not.
        """
        base = self.application.base
        campagne_id = self._campagne_de_trois()
        contact = base.contacts_de_campagne(campagne_id)[0]
        ancien = "1 tentative(s) — plafond atteint, à traiter par un humain"
        base.changer_etat_contact_campagne(contact["id"], "injoignable", None)
        base.definir_detail_contact(contact["id"], ancien)
        # THE DATA IS NOT TOUCHED.
        self.assertEqual(base.obtenir_contact_campagne(contact["id"])["detail"],
                         ancien)
        # BUT THE SCREEN NO LONGER SHOWS THE WORD.
        _, page = self._obtenir("/relances?vue=bloques")
        visible = _zone_visible(page)
        self.assertIn("1 tentative(s) — maximum de rappels atteint", visible)
        self.assertNotIn("plafond", visible.lower())

    def test_le_mot_plafond_ne_paraît_plus_dans_ce_qu_il_lit(self):
        """HIS REMARK OF 21/08/2026: `je ne comprends pas ce que tu appelles
        plafond. Pour moi le plafond c'est la limite de credit CALL-E.`

        He was right, and the product had something to do with it: the word
        designated TWO unrelated settings — the `Maximum number of callbacks`
        (step 2) and `At most, how many people` (step 3) — plus a third meaning
        in his head, the CALL-E credit. The text written on the contact now
        names the exact setting.
        """
        base = self.application.base
        campagne_id = self._campagne_de_trois()
        campagne, contact, options = self._au_dela_du_plafond(campagne_id)
        assistant._apres_non_joint(base, self.application.preferences,
                                   campagne, options, contact["id"],
                                   "no_answer")
        detail = base.obtenir_contact_campagne(contact["id"])["detail"]
        self.assertNotIn("plafond", detail.lower())
        self.assertIn("maximum de rappels", detail)

    # ------------------------------------------------ the failure DURING a
    # call
    def test_une_panne_pendant_le_suivi_ne_ment_pas_sur_l_appel(self):
        """The call HAD been placed: the message does not pretend otherwise.

        The boundary is the creation POST. After it, the phone may have rung:
        so we no longer say `nobody was called`.

        This test additionally checked that the contact went back to `to be
        called`. That was a trap: putting them back in the queue would have
        made their phone ring a SECOND time for a conversation already held,
        and its result would have been lost. Since 01/08/2026 the rule is
        single and has no special case — as soon as the creation has returned
        an identifier, any failure that follows puts the contact in `called,
        result unknown`, with their call's identifier kept.
        """
        self.faux.code_erreur_get = 401
        campagne_id = self._campagne_de_trois()
        campagne, contacts = self._derouler_en_reel(campagne_id)
        base = self.application.base
        self.assertEqual(campagne["statut"], "en pause")
        raison = campagne["raison_pause"]
        self.assertIn("clé d'accès CALL-E a été refusée", raison)  # the observation
        self.assertIn("EST BIEN PARTI", raison)  # the truth
        self.assertNotIn("Personne n'a été appelé", raison)
        self.assertIn("appel-essai-1", raison)  # the identifier is given
        # The contact called: neither `unreachable`, nor penalised, nor put
        # back in the queue.
        appele = contacts[0]
        self.assertEqual(appele["etat"], assistant.ETAT_RESULTAT_INCONNU)
        self.assertEqual(appele["appel_externe_id"], "appel-essai-1")
        self.assertEqual(base.appels_du_contact_campagne(appele["id"]), [])
        # The other two were not disturbed, and nothing was scheduled.
        for epargne in contacts[1:]:
            self.assertEqual(epargne["etat"], "à appeler")
            self.assertIsNone(epargne["issue"])
        self.assertEqual(base.relances_de_campagne(campagne_id), [])
        self.assertEqual(self._lignes_audit()[0]["statut"],
                         "résultat en attente")

    # ------------------------------------- the other call doors
    def test_la_file_d_appels_garde_ses_appels_et_le_dit(self):
        """The classic queue: nothing is marked `failure`, nothing is lost."""
        self.faux.code_erreur_post = 401
        base = self.application.base
        client_id = base.ajouter_client("M. File Attente", "+33 6 39 98 50 71")
        rdv_id = base.ajouter_rendezvous(client_id, HIER, "Séance",
                                         statut="manqué")
        self._brancher_client_reel()
        planif = self.application.planif
        appel_id = planif.programmer(rdv_id)
        with self.assertRaises(calle_client.EchecDeNotreCote):
            planif.executer()
        # The call is STILL in the queue, and nothing was written about it.
        self.assertEqual([e["appel_id"] for e in planif.file], [appel_id])
        self.assertEqual(base.obtenir_appel(appel_id)["statut"], "en file")
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"], "manqué")

    def test_la_cascade_est_interrompue_jamais_declaree_epuisee(self):
        """`Exhausted` would say the list had been tried: it has not been."""
        self.faux.code_erreur_post = 401
        self._brancher_client_reel()
        personnes = [{"nom": "M. Un", "telephone": "+33 6 39 98 50 81"},
                     {"nom": "Mme Deux", "telephone": "+33 6 39 98 50 82"}]
        creneau = (datetime.datetime.now() + datetime.timedelta(days=2)
                   ).replace(hour=10, minute=0, second=0,
                             microsecond=0).isoformat(timespec="minutes")
        with self.assertRaises(calle_client.EchecDeNotreCote):
            self.application.planif.executer_cascade(
                personnes, "Une place s'est libérée le [créneau].", creneau)
        base = self.application.base
        cascade = base.lister_cascades()[0]
        self.assertEqual(cascade["statut"], "interrompue")
        self.assertEqual(base.appels_de_cascade(cascade["id"]), [])
        self.assertEqual(len(self.faux.creations), 1)  # the 2nd spared

    def test_les_relances_dues_ne_sont_pas_consommees(self):
        """A follow-up not played stays SCHEDULED — otherwise it would be lost.
        """
        self.faux.etats[:] = [{"status": "no_answer"}]
        campagne_id = self._campagne_de_trois()
        self._derouler_en_reel(campagne_id)  # 3 follow-ups scheduled
        base = self.application.base
        plus_tard = datetime.datetime.now() + datetime.timedelta(days=30)
        self.faux.code_erreur_post = 401  # the key goes bad in the meantime
        comptes = campagnes.executer_relances_dues(
            base, self.application.planif, self.application.preferences,
            maintenant=plus_tard)
        self.assertEqual(len(comptes), 1)  # stop at the first one
        self.assertIn("clé d'accès CALL-E a été refusée", comptes[0]["panne"])
        planifiees = [r for r in base.relances_de_campagne(campagne_id)
                      if r["statut"] == "planifiée"]
        self.assertEqual(len(planifiees), 3)  # NONE consumed
        self.assertEqual(base.obtenir_campagne(campagne_id)["statut"],
                         "en pause")


class TestAppelPartiSansResultat(_CampagneAssistant):
    """THE CALL OF 01/08/2026, 10:54 — the one that went out and was lost.

    The owner's phone rang, he answered, he ACCEPTED the new slot — and
    RingBack wrote `unreachable` then forgot the conversation, because reading
    the answer had expired (`The read operation timed out`). These tests replay
    the scene, against the FAKE CALL-E interface, and prove the three nets: (1)
    the timeouts are those of a real call and can be set; (2) an exceeded wait
    is NEVER blamed on the contact; (3) the call is not lost: its identifier is
    kept and its result can be recovered later, without anybody being called
    again.
    """

    CLE = "cle-de-test-0123456789"
    LIGNES = ("M. Un Contact;+33 6 39 98 50 61;{h};Séance",
              "Mme Deux Contact;+33 6 39 98 50 62;{h};Séance",
              "M. Trois Contact;+33 6 39 98 50 63;{h};Séance")

    def setUp(self):
        super().setUp()
        self._cle_sauvee = os.environ.pop("CALLE_API_KEY", None)
        if self._cle_sauvee is not None:
            self.addCleanup(os.environ.__setitem__, "CALLE_API_KEY",
                            self._cle_sauvee)

        class Faux(_FauxApiCalle):
            creations = []
            lectures = []
            etats = [{"status": "queued"}]
        self.faux = Faux
        # THREADED server: a SLOW answer must not delay the next one, otherwise
        # the test would measure the bench rather than the product (a real API
        # does answer several requests at once).
        self.serveur_api = ThreadingHTTPServer(("127.0.0.1", 0), Faux)
        self.serveur_api.daemon_threads = True
        threading.Thread(target=self.serveur_api.serve_forever,
                         daemon=True).start()
        self.url_api = f"http://127.0.0.1:{self.serveur_api.server_address[1]}"
        self.addCleanup(self.serveur_api.server_close)
        self.addCleanup(self.serveur_api.shutdown)
        self.dossier = tempfile.mkdtemp(prefix="ringback-attente-")
        self.addCleanup(shutil.rmtree, self.dossier, ignore_errors=True)
        self.chemin_audit = os.path.join(self.dossier, "audit.jsonl")
        self.horaire = (datetime.datetime.now() + datetime.timedelta(days=3)
                        ).replace(hour=9, minute=0, second=0,
                                  microsecond=0).isoformat(timespec="minutes")

    # ------------------------------------------------------------ outillage
    def _campagne_de_trois(self):
        return self._campagne("confirmation",
                              [ligne.format(h=self.horaire)
                               for ligne in self.LIGNES])

    def _rendezvous_du_premier(self, campagne_id):
        """Gives the FIRST contact a real appointment in the database.

        Without it, a `rescheduled` would create an appointment; with it, it
        MOVES one — and it is that move which had been lost, so it is that
        which must be proved.
        """
        base = self.application.base
        contact = base.contacts_de_campagne(campagne_id)[0]
        return base.ajouter_rendezvous(contact["client_id"], self.horaire,
                                       "Séance")

    def _brancher_client_reel(self, **surcharge):
        """The REAL client, plugged into the FAKE API — never the real one."""
        options = dict(cle_api=self.CLE, url_base=self.url_api,
                       delai_total=2.0, intervalle=0.01, delai_requete=2.0,
                       chemin_audit=self.chemin_audit)
        options.update(surcharge)
        planif = self.application.planif
        planif.client_appels = calle_client.AppelReel(**options)
        planif.dry_run = False
        planif.confirmer_appels_reels()
        return planif.client_appels

    def _lignes_audit(self):
        if not os.path.exists(self.chemin_audit):
            return []
        with open(self.chemin_audit, encoding="utf-8") as fichier:
            return [json.loads(ligne) for ligne in fichier if ligne.strip()]

    def _appel_perdu(self, rdv=False, **surcharge):
        """Replays the scene: the call goes out, the answer never arrives.

        The API takes 0.6 s to answer the follow-up, the client only waits 0.15
        s: the read expires FOR REAL (TimeoutError raised by the real network
        stack, not an imitation). Once the scene is played, the API becomes
        normal again and so does the client — it is the moment the operator
        comes back for the result. Returns (campagne_id, contacts,
        rendezvous_id).
        """
        campagne_id = self._campagne_de_trois()
        rdv_id = self._rendezvous_du_premier(campagne_id) if rdv else None
        self.faux.lenteur_get = 0.6
        self._brancher_client_reel(delai_requete=0.15, **surcharge)
        assistant.executer_campagne(self.application, campagne_id)
        self.faux.lenteur_get = 0
        self._brancher_client_reel()  # the failure is over
        base = self.application.base
        return campagne_id, base.contacts_de_campagne(campagne_id), rdv_id

    # ------------------------- (2) the exceeded wait does not accuse the
    # contact
    def test_une_lecture_qui_expire_n_est_jamais_imputee_au_contact(self):
        """THE SCENE OF 01/08/2026, to the letter — and what it gives now."""
        campagne_id, contacts, _ = self._appel_perdu()
        base = self.application.base
        appele = contacts[0]
        # (1) NEITHER `unreachable` NOR `to be called again`: the state that
        # tells the truth.
        self.assertEqual(appele["etat"], assistant.ETAT_RESULTAT_INCONNU)
        self.assertIsNone(appele["issue"])
        # (2) NO attempt counted: it is that count which led to the cap.
        self.assertEqual(base.appels_du_contact_campagne(appele["id"]), [])
        # (3) THE IDENTIFIER IS KEPT: the call is not lost.
        self.assertEqual(appele["appel_externe_id"], "appel-essai-1")
        self.assertEqual(appele["appel_externe_tentative"], 0)
        self.assertIn("📥 Récupérer les résultats en attente", appele["detail"])
        # (4) No follow-up scheduled, nothing written about the other two.
        self.assertEqual(base.relances_de_campagne(campagne_id), [])
        for epargne in contacts[1:]:
            self.assertEqual(epargne["etat"], "à appeler")
        self.assertEqual(len(self.faux.creations), 1)
        # (5) The campaign is ON HOLD, with its reason in French.
        campagne = base.obtenir_campagne(campagne_id)
        self.assertEqual(campagne["statut"], "en pause")
        raison = campagne["raison_pause"]
        self.assertIn("EST BIEN PARTI", raison)
        self.assertIn("n'est PAS marquée « injoignable »", raison)
        self.assertIn("appel-essai-1", raison)
        self.assertIn("Récupérer les résultats en attente", raison)
        # (6) The audit log no longer says `failure`: it says what is true.
        lignes = self._lignes_audit()
        self.assertEqual(lignes[0]["statut"], "résultat en attente")
        self.assertEqual(lignes[0]["telephone"], "+33 6 •• •• •• 61")

    def test_l_attente_totale_depassee_garde_aussi_l_appel(self):
        """The other door: the call never concludes within the configured delay.
        """
        self.faux.etats[:] = [{"status": "in_progress"}]   # jamais fini
        campagne_id = self._campagne_de_trois()
        self._brancher_client_reel(delai_total=0.15, intervalle=0.02)
        assistant.executer_campagne(self.application, campagne_id)
        base = self.application.base
        appele = base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(appele["etat"], assistant.ETAT_RESULTAT_INCONNU)
        self.assertEqual(appele["appel_externe_id"], "appel-essai-1")
        self.assertEqual(base.appels_du_contact_campagne(appele["id"]), [])
        self.assertEqual(self._lignes_audit()[0]["statut"], "délai dépassé")
        self.assertIn("secondes d'attente réglées",
                      base.obtenir_campagne(campagne_id)["raison_pause"])

    def test_un_serveur_qui_raccroche_suit_la_meme_regle(self):
        """The FAMILY, not the case: RemoteDisconnected also went through.

        The server cuts the connection mid-read. urllib does not wrap that
        error in URLError (it comes out of getresponse()), so it went through
        exactly like the TimeoutError.
        """
        self.faux.coupure_get = True
        self.addCleanup(setattr, self.faux, "coupure_get", False)
        campagne_id = self._campagne_de_trois()
        self._brancher_client_reel()
        assistant.executer_campagne(self.application, campagne_id)
        base = self.application.base
        appele = base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(appele["etat"], assistant.ETAT_RESULTAT_INCONNU)
        self.assertEqual(appele["appel_externe_id"], "appel-essai-1")
        self.assertEqual(base.appels_du_contact_campagne(appele["id"]), [])

    def test_une_coupure_a_la_creation_ne_pretend_pas_savoir(self):
        """Before the identifier, we do not KNOW whether the phone rang.

        Saying `nobody was called` would be false (the request went out),
        saying `the call was placed` too. RingBack says it does not know.
        """
        self.faux.lenteur_post = 0.6
        self.addCleanup(setattr, self.faux, "lenteur_post", 0)
        campagne_id = self._campagne_de_trois()
        self._brancher_client_reel(delai_requete=0.15)
        assistant.executer_campagne(self.application, campagne_id)
        base = self.application.base
        campagne = base.obtenir_campagne(campagne_id)
        raison = campagne["raison_pause"]
        self.assertIn("La demande est bel et bien PARTIE", raison)
        self.assertNotIn("Personne n'a été appelé", raison)
        # No identifier: nothing to recover, the contact stays `to be called`
        # (it is the behaviour of a failure on our side, unchanged).
        for contact in base.contacts_de_campagne(campagne_id):
            self.assertEqual(contact["etat"], "à appeler")
            self.assertIsNone(contact["appel_externe_id"])
        self.assertEqual(self._lignes_audit()[0]["statut"], "appel incertain")

    # ----------------- (3) recovering the result, without calling anybody
    # again
    def test_le_geste_applique_le_resultat_sans_rappeler_personne(self):
        """THE HEART: the lost conversation is found again and applied."""
        campagne_id, contacts, rdv_id = self._appel_perdu(rdv=True)
        base = self.application.base
        creations_avant = len(self.faux.creations)
        nouvelle_date = (datetime.datetime.fromisoformat(self.horaire)
                         + datetime.timedelta(days=2)).replace(
                             hour=14, minute=0).isoformat(timespec="minutes")
        # CALL-E has finished: the real conversation's result is there, in the
        # documented shape (recipients[].structured_result).
        self.faux.etats[:] = [reponse_calle_terminee(
            {"appointment_status": "rescheduled",
             "new_datetime": nouvelle_date,
             "notes": "Le client accepte de décaler.",
             "duration_seconds": 96},
            tours=[{"offset_seconds": 0, "speaker": "bot", "text": "Bonjour…"},
                   {"offset_seconds": 3, "speaker": "user",
                    "text": "Oui, ça me va."}])]
        _, page = self._poster("/campagne/recuperer", {"campagne": campagne_id})
        # (1) NO CALL WENT OUT AGAIN: not one more creation.
        self.assertEqual(len(self.faux.creations), creations_avant)
        self.assertTrue(any("/v1/calls/appel-essai-1" in chemin
                            for chemin in self.faux.lectures))
        # (2) The result is applied EXACTLY as if it had arrived in time.
        appele = base.obtenir_contact_campagne(contacts[0]["id"])
        self.assertEqual(appele["etat"], "accepté")
        self.assertEqual(appele["issue"], "rescheduled")
        self.assertIsNone(appele["appel_externe_id"])   # plus rien en attente
        # The appointment REALLY moved: the SAME row changes hour and becomes
        # `confirme` — never a second one alongside (his rule of 14/08,
        # extended to this outcome on 17/08/2026).
        bouge = base.obtenir_rendezvous(rdv_id)
        self.assertEqual(bouge["statut"], "confirmé")
        self.assertEqual(bouge["horaire"], nouvelle_date)
        self.assertEqual(base.rendezvous_du_client(appele["client_id"]),
                         [rdv_id])
        # The attempt is recorded, with its transcript.
        appels = base.appels_du_contact_campagne(appele["id"])
        self.assertEqual([a["issue"] for a in appels], ["rescheduled"])
        self.assertIn("ça me va", appels[0]["transcription"])
        # (3) The change log carries the move.
        genres = [c["genre"] for c in base.changements_de_campagne(campagne_id)]
        self.assertIn("deplacement", genres)
        # (4) The screen says so, and repeats that nothing was dialled.
        self.assertIn("Résultat récupéré et appliqué", page)
        self.assertIn("ne compose AUCUN numéro", page)
        # (5) The explanation of the hold has disappeared: it is stale, there
        # is nothing left to recover. The campaign, for its part, waits for the
        # Resume gesture.
        campagne = base.obtenir_campagne(campagne_id)
        self.assertEqual(campagne["statut"], "en pause")
        self.assertIsNone(campagne["raison_pause"])
        self.assertNotIn("Campagne mise en pause toute seule", page)

    def test_le_geste_dit_la_verite_quand_l_appel_est_encore_en_cours(self):
        """`Still in progress`: we say so, and we write NOTHING."""
        campagne_id, contacts, _ = self._appel_perdu()
        base = self.application.base
        self.faux.etats[:] = [{"status": "in_progress"}]
        _, page = self._poster("/campagne/recuperer", {"campagne": campagne_id})
        self.assertIn("ENCORE EN COURS", page)
        appele = base.obtenir_contact_campagne(contacts[0]["id"])
        # Nothing moved: neither the state, nor the identifier, nor the
        # attempts.
        self.assertEqual(appele["etat"], assistant.ETAT_RESULTAT_INCONNU)
        self.assertEqual(appele["appel_externe_id"], "appel-essai-1")
        self.assertEqual(base.appels_du_contact_campagne(appele["id"]), [])
        self.assertEqual(len(self.faux.creations), 1)   # toujours aucun appel

    def test_le_geste_rend_au_contact_un_vrai_non_decroche(self):
        """NO REGRESSION: a genuine `nobody answered` is still attributed.

        We have not `softened` the real failures: if CALL-E answers that the
        call ended without an answer, the attempt is counted and the follow-up
        scheduled, exactly as usual.
        """
        campagne_id, contacts, _ = self._appel_perdu()
        base = self.application.base
        self.faux.etats[:] = [{"status": "no_answer"}]
        self._poster("/campagne/recuperer", {"campagne": campagne_id})
        appele = base.obtenir_contact_campagne(contacts[0]["id"])
        self.assertEqual(appele["etat"], "à recontacter")
        self.assertEqual(appele["issue"], "no_answer")
        self.assertEqual(len(base.appels_du_contact_campagne(appele["id"])), 1)
        self.assertIsNone(appele["appel_externe_id"])
        planifiees = [r for r in base.relances_de_campagne(campagne_id)
                      if r["statut"] == "planifiée"]
        self.assertEqual(len(planifiees), 1)

    def test_une_lecture_impossible_conserve_l_identifiant(self):
        """The key goes bad: nothing is written, and the call stays recoverable.
        """
        campagne_id, contacts, _ = self._appel_perdu()
        base = self.application.base
        self.faux.code_erreur_get = 401
        self.addCleanup(setattr, self.faux, "code_erreur_get", None)
        _, page = self._poster("/campagne/recuperer", {"campagne": campagne_id})
        self.assertIn("clé d’accès CALL-E a été refusée".replace("’", "'"),
                      page.replace("&#x27;", "'"))
        appele = base.obtenir_contact_campagne(contacts[0]["id"])
        self.assertEqual(appele["etat"], assistant.ETAT_RESULTAT_INCONNU)
        self.assertEqual(appele["appel_externe_id"], "appel-essai-1")

    def test_l_ecran_propose_le_geste_et_jure_qu_il_n_appelle_personne(self):
        """The screen: the state, the gesture, and the sentence that removes the
        doubt.
        """
        campagne_id, _, _ = self._appel_perdu()
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn("appelé, résultat inconnu", page)
        self.assertIn("Récupérer les résultats en attente", page)
        self.assertIn("ne compose AUCUN numéro", page)
        self.assertIn("/campagne/recuperer", page)
        _personne_n_est_injoignable(self, campagne_id, page)

    def test_la_fiche_client_dit_pourquoi_aucune_campagne_ne_le_traite(self):
        """Clients: the state is displayed, and the screen says what to do.

        Without an explanation, `nothing to do` would look like an oversight —
        and above all somebody could build a NEW campaign for a person whose
        phone has already rung.
        """
        campagne_id, contacts, _ = self._appel_perdu()
        base = self.application.base
        client_id = base.obtenir_contact_campagne(contacts[0]["id"])["client_id"]
        _, page = self._obtenir("/clients")
        self.assertIn("appelé, résultat inconnu", page)
        _, fiche = self._obtenir(f"/clients/fiche?id={client_id}")
        self.assertIn("appelé, résultat inconnu", fiche)
        self.assertIn("surtout pas de nouvelle campagne", fiche)
        self.assertIn("Récupérer les résultats en attente", fiche)

    def test_la_simulation_ne_pretend_pas_pouvoir_relire(self):
        """In simulation, nothing went out: we say so, we invent nothing."""
        campagne_id, contacts, _ = self._appel_perdu()
        self.application.planif.client_appels = calle_client.AppelSimule(
            graine=1, latence=0)
        comptes = assistant.recuperer_resultats_en_attente(self.application,
                                                           campagne_id)
        self.assertEqual(comptes[0]["sort"], "panne")
        self.assertIn("simulation", comptes[0]["message"])
        appele = self.application.base.obtenir_contact_campagne(
            contacts[0]["id"])
        self.assertEqual(appele["etat"], assistant.ETAT_RESULTAT_INCONNU)


class TestFormeDeLaReponseCalle(unittest.TestCase):
    """The documented shape, read as it is — without a server, without a network.

    THE RESPONSE BELOW IS COPIED FROM THE SPONSOR'S DOCUMENTATION
    (github.com/CALLE-AI/call-e-integrations), not from what RingBack thinks it
    understands. It is the only way to catch the mistake of 01/08/2026 (16:49):
    we read etat["result"] and etat["transcript"], two keys that do not exist —
    and the fake API answered as the product expected, so the 451 tests passed.
    """

    EXEMPLE_DOCUMENTE = {
        "status": "completed",
        "task_completed": True,
        "completion_confidence": {"score": 0.92, "label": "high"},
        "evidence": ["The recipient said they can attend Friday lunch."],
        "structured_result": {"completed_count": 1},
        "recipients": [
            {"structured_result": {"can_attend": "yes"},
             "attempts": [{"transcript_turns": [
                 {"offset_seconds": 0, "speaker": "bot", "text": "Hi..."},
                 {"offset_seconds": 4, "speaker": "user",
                  "text": "Yes, I can attend."}]}]}],
    }

    def test_le_resultat_se_lit_chez_le_destinataire(self):
        """ONE person's result: recipients[0].structured_result."""
        reponse = copy.deepcopy(self.EXEMPLE_DOCUMENTE)
        reponse["recipients"][0]["structured_result"] = dict(RESULTAT_CONFORME)
        resultat, transcription = calle_client.lire_appel_termine(
            reponse, calle_client.valider_resultat)
        self.assertEqual(resultat["appointment_status"], "confirmed")
        # `bot` and `user` become `Agent` and `Client`: the SAME labels as the
        # simulation, so that the screen stays consistent.
        self.assertEqual(transcription,
                         "Agent : Hi...\nClient : Yes, I can attend.")

    def test_le_bilan_global_n_est_jamais_pris_pour_un_resultat(self):
        """structured_result at the root = campaign summary, NOT our result.

        It is exactly the trap: a valid JSON object, with the right name, in
        the wrong place. Reading it would give a false result about somebody.
        """
        reponse = copy.deepcopy(self.EXEMPLE_DOCUMENTE)
        reponse["structured_result"] = dict(RESULTAT_CONFORME)
        with self.assertRaises(calle_client.ResultatInvalide):
            calle_client.lire_appel_termine(reponse,
                                            calle_client.valider_resultat)

    def test_sans_destinataire_on_le_dit_au_lieu_de_deviner(self):
        for absent in ({"status": "completed"},
                       {"status": "completed", "recipients": []},
                       {"status": "completed", "recipients": None}):
            with self.subTest(reponse=absent):
                with self.assertRaises(calle_client.ResultatInvalide) as refus:
                    calle_client.lire_appel_termine(
                        absent, calle_client.valider_resultat)
                self.assertIn("aucun destinataire", refus.exception.constat)
                # (3) the raw response is kept, even when empty of a result.
                self.assertIn("completed", refus.exception.reponse_brute)

    def test_plusieurs_tentatives_on_prend_la_derniere(self):
        """The conversation is that of the attempt that succeeded."""
        reponse = copy.deepcopy(self.EXEMPLE_DOCUMENTE)
        reponse["recipients"][0]["structured_result"] = dict(RESULTAT_CONFORME)
        reponse["recipients"][0]["attempts"] = [
            {"transcript_turns": []},  # ringing into the void
            {"transcript_turns": [
                {"offset_seconds": 0, "speaker": "bot", "text": "Rebonjour."},
                {"offset_seconds": 2, "speaker": "user", "text": "Oui, d'accord."}]},
        ]
        _, transcription = calle_client.lire_appel_termine(
            reponse, calle_client.valider_resultat)
        self.assertEqual(transcription,
                         "Agent : Rebonjour.\nClient : Oui, d'accord.")

    def test_un_interlocuteur_inconnu_garde_son_etiquette(self):
        """We do not file anybody on the agent's side by default."""
        self.assertEqual(
            calle_client.transcription_depuis_tours([
                {"speaker": "supervisor", "text": "Je reprends l'appel."},
                {"speaker": "user", "text": "Très bien."},
                {"speaker": "bot", "text": "   "},  # empty: ignored
                {"speaker": "bot"}]),  # without text: ignored
            "supervisor : Je reprends l'appel.\nClient : Très bien.")

    def test_la_reponse_brute_masque_les_numeros(self):
        """(3) Keeping the response must NEVER strip the contact."""
        brut = calle_client.reponse_brute_lisible(
            {"phones": ["+33639980024", "06 39 98 00 24"],
             "quand": "2026-08-02T09:30", "duree": 42})
        self.assertNotIn("+33639980024", brut)
        self.assertNotIn("06 39 98 00 24", brut)
        self.assertIn("+•••••••••24", brut)
        # An ISO date is NOT a number: it is precisely what we come to read in
        # a raw response.
        self.assertIn("2026-08-02T09:30", brut)
        self.assertIn("42", brut)

    def test_la_reponse_brute_est_tronquee_en_le_disant(self):
        brut = calle_client.reponse_brute_lisible({"notes": "z" * 5000})
        self.assertLess(len(brut), 5000)
        self.assertIn("tronqué", brut)


class TestReponseIllisibleNeSaliJamaisLeContact(_CampagneAssistant):
    """THE CALL OF 01/08/2026, 16:49 — the one that SUCCEEDED and was thrown away.

    The owner's phone rang, he answered, he TALKED. Then RingBack wrote
    {"statut": "echec", "detail": "le resultat doit etre un objet JSON"} and
    his contact became `unreachable - cap reached`.

    These tests replay the scene against the FAKE interface, which now answers
    like the documented API, and prove the rule: A RESULT WE CANNOT READ IS A
    RINGBACK FAULT, NEVER A FACT ABOUT THE PERSON.
    """

    CLE = "cle-de-test-0123456789"
    LIGNES = ("M. Un Contact;+33 6 39 98 50 61;{h};Séance",
              "Mme Deux Contact;+33 6 39 98 50 62;{h};Séance",
              "M. Trois Contact;+33 6 39 98 50 63;{h};Séance")

    def setUp(self):
        super().setUp()
        self._cle_sauvee = os.environ.pop("CALLE_API_KEY", None)
        if self._cle_sauvee is not None:
            self.addCleanup(os.environ.__setitem__, "CALLE_API_KEY",
                            self._cle_sauvee)

        class Faux(_FauxApiCalle):
            creations = []
            lectures = []
            etats = [{"status": "queued"}]
        self.faux = Faux
        self.serveur_api = ThreadingHTTPServer(("127.0.0.1", 0), Faux)
        self.serveur_api.daemon_threads = True
        threading.Thread(target=self.serveur_api.serve_forever,
                         daemon=True).start()
        self.url_api = f"http://127.0.0.1:{self.serveur_api.server_address[1]}"
        self.addCleanup(self.serveur_api.server_close)
        self.addCleanup(self.serveur_api.shutdown)
        self.dossier = tempfile.mkdtemp(prefix="ringback-illisible-")
        self.addCleanup(shutil.rmtree, self.dossier, ignore_errors=True)
        self.chemin_audit = os.path.join(self.dossier, "audit.jsonl")
        self.horaire = (datetime.datetime.now() + datetime.timedelta(days=3)
                        ).replace(hour=9, minute=0, second=0,
                                  microsecond=0).isoformat(timespec="minutes")

    # ------------------------------------------------------------ outillage
    def _campagne_de_trois(self, combien=3):
        return self._campagne("confirmation",
                              [ligne.format(h=self.horaire)
                               for ligne in self.LIGNES[:combien]])

    def _brancher_client_reel(self):
        planif = self.application.planif
        planif.client_appels = calle_client.AppelReel(
            cle_api=self.CLE, url_base=self.url_api, delai_total=2.0,
            intervalle=0.01, delai_requete=2.0, chemin_audit=self.chemin_audit)
        planif.dry_run = False
        planif.confirmer_appels_reels()
        return planif.client_appels

    def _lignes_audit(self):
        if not os.path.exists(self.chemin_audit):
            return []
        with open(self.chemin_audit, encoding="utf-8") as fichier:
            return [json.loads(ligne) for ligne in fichier if ligne.strip()]

    def _derouler(self, reponse, combien=3):
        """Builds a campaign, runs it in REAL mode on that response."""
        campagne_id = self._campagne_de_trois(combien)
        self.faux.etats[:] = [reponse]
        self._brancher_client_reel()
        assistant.executer_campagne(self.application, campagne_id)
        base = self.application.base
        return (campagne_id, base.obtenir_campagne(campagne_id),
                base.contacts_de_campagne(campagne_id))

    # -------------------------------------------- (1) the conversation is READ
    def test_un_appel_abouti_est_lu_a_la_bonne_place(self):
        """The path that had been wrong from the start: it works, proved here.

        ONE SINGLE contact: three would all have asked for THE SAME slot, and
        the last two would be refused for a slot already taken — a genuine
        product behaviour, but not what we measure here.
        """
        nouvelle_date = (datetime.datetime.fromisoformat(self.horaire)
                         + datetime.timedelta(days=2)).replace(
                             hour=14, minute=0).isoformat(timespec="minutes")
        campagne_id, campagne, contacts = self._derouler(reponse_calle_terminee(
            {"appointment_status": "rescheduled",
             "new_datetime": nouvelle_date,
             "notes": "Le client accepte de décaler.",
             "duration_seconds": 96},
            tours=[{"offset_seconds": 0, "speaker": "bot",
                    "text": "Bonjour, pouvons-nous décaler ?"},
                   {"offset_seconds": 5, "speaker": "user",
                    "text": "Oui, ça me va."}]), combien=1)
        base = self.application.base
        self.assertEqual(campagne["statut"], "terminée")
        # (1) THE OUTCOME IS APPLIED.
        self.assertEqual(contacts[0]["issue"], "rescheduled")
        self.assertEqual(contacts[0]["etat"], "accepté")
        # (2) The appointment REALLY is at the new date.
        horaires_client = [base.obtenir_rendezvous(i)["horaire"] for i in
                           base.rendezvous_du_client(contacts[0]["client_id"])]
        self.assertIn(nouvelle_date, horaires_client)
        # (3) The transcript is readable ON SCREEN, `Agent: / Client:`.
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn("Agent : Bonjour, pouvons-nous décaler ?", page)
        self.assertIn("Client : Oui, ça me va.", page)
        # (4) And the request that went out carries BOTH schemas from the
        # documented example: the per-recipient one (the only one RingBack
        # reads back) and the global summary.
        self.assertIn("recipient_result_schema", self.faux.creations[0])
        self.assertIn("result_schema", self.faux.creations[0])

    # ------------------------------ (2) an unreadable answer accuses nobody
    def test_une_reponse_illisible_envoie_vers_un_humain_sans_punir(self):
        """THE HEART: the scene of 01/08/2026 at 16:49, replayed and corrected.
        """
        campagne_id, campagne, contacts = self._derouler(reponse_calle_terminee(
            {"appointment_status": "peut-être", "new_datetime": "",
             "notes": "…", "duration_seconds": 96}))
        base = self.application.base
        premier = contacts[0]
        # (1) The contact goes to a HUMAN — never `unreachable`.
        self.assertEqual(premier["etat"], "à rappeler par un humain")
        self.assertEqual(premier["issue"], "reponse_illisible")
        # (2) ZERO punitive attempts: no follow-up, nobody unreachable, and the
        # next two were not even called.
        self.assertEqual(base.relances_de_campagne(campagne_id), [])
        self.assertEqual([c["etat"] for c in contacts[1:]],
                         ["à appeler", "à appeler"])
        self.assertEqual(len(self.faux.creations), 1)
        # (3) THE RAW RESPONSE IS KEPT — that is what was missing.
        self.assertIn("structured_result", premier["detail"])
        self.assertIn("peut-être", premier["detail"])
        # (4) The conversation is not lost either.
        appels = base.appels_du_contact_campagne(premier["id"])
        self.assertIn("Client : C'est parfait, je confirme.",
                      appels[0]["transcription"])
        # (5) The campaign is ON HOLD, and it says why.
        self.assertEqual(campagne["statut"], "en pause")
        self.assertIn("n'a pas su lire la réponse", campagne["raison_pause"])
        self.assertIn("A BIEN EU LIEU", campagne["raison_pause"])
        # (6) The audit log no longer says a bare `failure`, and it SHOWS.
        ligne = self._lignes_audit()[0]
        self.assertEqual(ligne["statut"], "réponse illisible")
        self.assertIn("peut-être", ligne["reponse_brute"])
        self.assertNotIn("+33639985061", ligne["reponse_brute"])

    def test_l_ecran_montre_la_reponse_brute_et_n_accuse_personne(self):
        """`THE SCREEN` CHANGED ON 11/08/2026, THE GUARANTEE DID NOT. The contacts
        table's `Detail` column is removed (owner's request): the campaign's
        record still says the STATE — `to be called back by a human`, and
        nobody flagged unreachable — and the raw response is read on
        Follow-ups, the screen made for those contacts.
        """
        campagne_id, _, _ = self._derouler(reponse_calle_terminee(
            {"appointment_status": "peut-être", "new_datetime": "",
             "notes": "…", "duration_seconds": 96}))
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn("à rappeler par un humain", page)
        _personne_n_est_injoignable(self, campagne_id, page)
        _, demande = self._obtenir(self._chemin_demande())
        self.assertIn("Réponse brute de CALL-E", demande)
        # AND THE WINDOW ACCUSES NOBODY — that is the heart of this test, and
        # it depends on no column: the sentence says the fault is RingBack's.
        # (The `Response unreadable by RingBack` label is the CALL's, it lives
        # in the campaign's `Transcript` disclosure — see
        # campagnes.ETIQUETTES_ISSUE.)
        self.assertIn("c&#x27;est un défaut de RingBack, pas un fait sur cette "
                      "personne", demande)
        self.assertIn("aucune tentative comptée", demande)

    def _chemin_demande(self):
        """The path to the waiting contact's `See their request...` window.

        A single place that finds it: three tests in this class need it since
        the detail is read on Follow-ups.
        """
        _, relances = self._obtenir("/relances?vue=humains")
        trouve = re.search(r"/relances/demande\?contact=\d+", relances)
        self.assertIsNotNone(trouve, "aucun contact en attente d'un humain")
        return trouve.group(0)

    def test_une_reponse_illisible_reste_lisible_sur_la_page_des_relances(self):
        """WHAT IS GUARDED HERE CHANGED SCREEN, NOT VALUE (11/08/2026).

        The earlier test checked that the detail of an unreadable answer was
        abbreviated in the contacts table's `Detail` column. That column is
        removed (owner's request) — but the guarantee cannot go with it: when
        RingBack could not read an answer, the reason AND CALL-E's raw response
        must stay reachable, otherwise we lose a second time what the person
        said.

        They are now read on Follow-ups, the `Human callbacks` view — the
        screen made for those contacts — through `See their request...`.
        """
        campagne_id, _, _ = self._derouler(reponse_calle_terminee(
            {"appointment_status": "peut-être", "new_datetime": "",
             "notes": "…", "duration_seconds": 96}))
        # The campaign's record no longer carries the detail: that is the
        # removal.
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertNotIn("<th>Détail</th>", page)
        self.assertNotIn("Réponse brute de CALL-E", page)
        # The contact went to a human, and the follow-ups page has them.
        _, relances = self._obtenir("/relances?vue=humains")
        self.assertIn("Voir sa demande…", relances)
        contact = re.search(r"/relances/demande\?contact=(\d+)", relances)
        self.assertIsNotNone(contact, relances[:600])
        # And the window carries the reason AND the raw response, word for
        # word.
        _, demande = self._obtenir(
            f"/relances/demande?contact={contact.group(1)}")
        self.assertIn("Réponse brute de CALL-E", demande)
        self.assertIn("peut-être", demande)

    def test_l_ecran_ne_pretend_pas_qu_aucun_appel_n_est_parti(self):
        """THE TITLE MUST BE TRUE: the phone rang, we do not say otherwise."""
        self.faux.etats[:] = [reponse_calle_terminee({"pas": "lisible"})]
        self._brancher_client_reel()
        self._poster("/file/tout-rappeler")
        try:
            self._poster("/file/executer")
            self.fail("La file aurait dû s'arrêter sur une réponse illisible.")
        except urllib.error.HTTPError as reponse:
            self.assertEqual(reponse.code, 503)
            page = reponse.read().decode("utf-8")
        self.assertNotIn("Aucun appel n'est parti", page)
        self.assertIn("L'appel a eu lieu — RingBack", page)
        # (3) The raw response is BEFORE YOUR EYES, immediately.
        self.assertIn("Ce que CALL-E a répondu", page)
        self.assertIn("structured_result", page)

    def test_aucun_destinataire_dans_la_reponse_est_dit_franchement(self):
        """Answer `finished` but empty: we SAY so, we do not guess."""
        _, campagne, contacts = self._derouler(
            {"status": "completed", "task_completed": True})
        self.assertEqual(contacts[0]["etat"], "à rappeler par un humain")
        self.assertIn("aucun destinataire", campagne["raison_pause"])
        self.assertEqual(campagne["statut"], "en pause")

    # ------------------------------------------ (3) the non-regression, proved
    def test_pas_de_reponse_reste_imputable_au_contact(self):
        """THE NON-REGRESSION: a no-answer stays a fact about the person."""
        campagne_id, campagne, contacts = self._derouler(
            {"status": "no_answer"})
        base = self.application.base
        # The campaign is NOT put on hold: nothing went wrong on our side, the
        # list was walked in full.
        self.assertNotEqual(campagne["statut"], "en pause")
        for contact in contacts:
            self.assertEqual(contact["etat"], "à recontacter")
            self.assertEqual(contact["issue"], "no_answer")
            self.assertEqual(len(base.appels_du_contact_campagne(contact["id"])),
                             1)
        self.assertEqual(len(base.relances_de_campagne(campagne_id)), 3)
        self.assertEqual([l["statut"] for l in self._lignes_audit()],
                         ["pas de réponse"] * 3)

    # ---------------------- (4) reading back does not go round in circles, and
    # calls nobody
    def test_le_geste_recuperer_conclut_au_lieu_d_attendre_pour_toujours(self):
        """An unreadable answer ARRIVES: reading back would give the same. We
        conclude.

        The trap was there: classifying that refusal as `result pending` would
        have left the contact waiting for a result that will never become
        readable, and the screen would have offered a gesture with no effect.
        """
        campagne_id = self._campagne_de_trois()
        self.faux.etats[:] = [{"status": "in_progress"}]  # never finishes
        planif = self.application.planif
        planif.client_appels = calle_client.AppelReel(
            cle_api=self.CLE, url_base=self.url_api, delai_total=0.05,
            intervalle=0.01, delai_requete=2.0, chemin_audit=self.chemin_audit)
        planif.dry_run = False
        planif.confirmer_appels_reels()
        assistant.executer_campagne(self.application, campagne_id)
        base = self.application.base
        contacts = base.contacts_de_campagne(campagne_id)
        self.assertEqual(contacts[0]["etat"], assistant.ETAT_RESULTAT_INCONNU)
        creations_avant = len(self.faux.creations)
        # CALL-E has finished — but RingBack cannot read its answer.
        self.faux.etats[:] = [reponse_calle_terminee({"statut": "ok"})]
        _, page = self._poster("/campagne/recuperer", {"campagne": campagne_id})
        # AUCUN APPEL N'EST REPARTI.
        self.assertEqual(len(self.faux.creations), creations_avant)
        appele = base.obtenir_contact_campagne(contacts[0]["id"])
        self.assertEqual(appele["etat"], "à rappeler par un humain")
        self.assertIsNone(appele["appel_externe_id"])  # nothing left to wait for
        self.assertIn("su lire", page)  # the screen says so
        # The raw response is read on Follow-ups since 11/08/2026: the contacts
        # table's `Detail` column is removed.
        _, demande = self._obtenir(self._chemin_demande())
        self.assertIn("Réponse brute de CALL-E", demande)
        self.assertEqual(base.relances_de_campagne(campagne_id), [])

    # -------------------------------------------- (5) the queue and the
    # cascade
    def test_une_relance_illisible_n_est_pas_remise_en_file(self):
        """The follow-up stays `done`: nobody is called back by the machine."""
        campagne_id, _, contacts = self._derouler({"status": "no_answer"})
        base = self.application.base
        relance = base.relances_de_campagne(campagne_id)[0]
        base.changer_relance(relance["id"], echeance="2000-01-01T00:00")
        self.faux.etats[:] = [reponse_calle_terminee({"rien": "de lisible"})]
        rendus = campagnes.executer_relances_dues(
            base, self.application.planif, self.application.preferences)
        self.assertIn("su lire", rendus[0]["panne"])
        # The report says the REAL state, read back from the database — not `to
        # be called again`.
        self.assertEqual(rendus[0]["etat"], "à rappeler par un humain")
        # THE FOLLOW-UP STAYS `DONE`: putting it back to `scheduled` would make
        # this person be called back automatically, although they have already
        # spoken.
        self.assertEqual(base.obtenir_relance(relance["id"])["statut"], "faite")
        vise = base.obtenir_contact_campagne(relance["contact_id"])
        self.assertEqual(vise["etat"], "à rappeler par un humain")
        self.assertIn("Réponse brute de CALL-E : ", vise["detail"])
        # And the campaign stops there: the other two follow-ups do not go out.
        self.assertEqual(base.obtenir_campagne(campagne_id)["statut"],
                         "en pause")

    def test_la_cascade_ne_declare_jamais_pas_de_reponse_a_tort(self):
        """Cascade: the row says `unreadable answer`, not `no_answer`."""
        base = self.application.base
        client = self._brancher_client_reel()
        self.faux.etats[:] = [reponse_calle_terminee({"outcome": "peut-être"})]
        planif = self.application.planif
        creneau = (datetime.datetime.now() + datetime.timedelta(days=4)
                   ).replace(hour=10, minute=0, second=0,
                             microsecond=0).isoformat(timespec="minutes")
        with self.assertRaises(calle_client.ResultatInvalide):
            planif.executer_cascade(
                [{"nom": "M. Un Contact", "telephone": "+33 6 39 98 50 61"},
                 {"nom": "Mme Deux", "telephone": "+33 6 39 98 50 62"}],
                "Une place se libère [créneau].", creneau)
        cascade_id = base.lister_cascades()[0]["id"]
        lignes = base.appels_de_cascade(cascade_id)
        self.assertEqual(len(lignes), 1)  # the next one is spared
        self.assertEqual(lignes[0]["issue"], "reponse_illisible")
        self.assertIn("Réponse brute de CALL-E", lignes[0]["note"])
        self.assertEqual(base.obtenir_cascade(cascade_id)["statut"],
                         "interrompue")
        self.assertTrue(client.est_reel)


class TestDelaisDAppelReglables(_TestAvecServeurWeb):
    """(1) The timeouts are those of a real call, and they can be set."""

    def test_les_valeurs_par_defaut_sont_celles_d_un_vrai_appel(self):
        """Ten minutes of waiting, 5 s between two checks, 30 s per request."""
        self.assertEqual(calle_client.DELAI_TOTAL_DEFAUT, 600.0)
        self.assertEqual(calle_client.DELAI_INTERVALLE_DEFAUT, 5.0)
        self.assertEqual(calle_client.DELAI_REQUETE_DEFAUT, 30.0)
        client = calle_client.AppelReel(cle_api="cle-de-test-0123456789",
                                        url_base="http://127.0.0.1:1")
        self.assertEqual((client.delai_total, client.intervalle,
                          client.delai_requete), (600.0, 5.0, 30.0))

    def test_la_simulation_n_est_pas_ralentie(self):
        """The 436 tests must stay fast: the simulation does not change."""
        debut = time.monotonic()
        calle_client.AppelSimule(graine=1, latence=0).appeler(
            "Mme Essai", "+33 6 39 98 50 51",
            {"horaire": datetime.datetime.now().isoformat(timespec="minutes"),
             "motif": "Séance"})
        self.assertLess(time.monotonic() - debut, 0.5)

    def test_les_delais_se_reglent_a_l_ecran_et_s_appliquent_aussitot(self):
        preferences = self.application.preferences
        _, page = self._obtenir("/reglages")
        self.assertIn("Combien de temps attendre un vrai appel", page)
        self.assertIn(calle_client.CLE_DELAI_TOTAL, page)
        self.assertIn('value="600"', page)
        self._poster("/reglages/enregistrer", {
            "entreprise": "Cabinet Essai", "plage_debut": "08:00",
            "plage_fin": "20:00",
            calle_client.CLE_DELAI_TOTAL: "900",
            calle_client.CLE_DELAI_INTERVALLE: "8",
            calle_client.CLE_DELAI_REQUETE: "45"})
        self.assertEqual(calle_client.delais_regles(preferences),
                         {"delai_total": 900.0, "intervalle": 8.0,
                          "delai_requete": 45.0})
        # And the client ALREADY built took them: no need to restart.
        client = calle_client.AppelReel(cle_api="cle-de-test-0123456789",
                                        url_base="http://127.0.0.1:1")
        self.application.planif.client_appels = client
        self._poster("/reglages/enregistrer", {
            "entreprise": "Cabinet Essai", "plage_debut": "08:00",
            "plage_fin": "20:00",
            calle_client.CLE_DELAI_TOTAL: "300",
            calle_client.CLE_DELAI_INTERVALLE: "3",
            calle_client.CLE_DELAI_REQUETE: "20"})
        self.assertEqual((client.delai_total, client.intervalle,
                          client.delai_requete), (300.0, 3.0, 20.0))

    def test_un_delai_hors_bornes_est_refuse_et_la_saisie_n_est_pas_perdue(self):
        _, page = self._poster("/reglages/enregistrer", {
            "entreprise": "Cabinet Essai", "plage_debut": "09:00",
            "plage_fin": "19:00",
            calle_client.CLE_DELAI_TOTAL: "5",  # below the floor
            calle_client.CLE_DELAI_INTERVALLE: "5",
            calle_client.CLE_DELAI_REQUETE: "30"})
        self.assertIn("Réglage refusé", page)
        self.assertIn("entre 60 et 3600 secondes", page)
        # Nothing was written: the earlier setting still holds.
        self.assertEqual(
            calle_client.delais_regles(self.application.preferences)
            ["delai_total"], 600.0)


# --------------------------------------------------------------------------
# THE THREE-PART BRIEF — introduction, free discussion, closed outcomes  What
# these tests protect, in order: 1. all EIGHT kinds do produce the three parts,
# and three outcomes — never a monologue, never a fourth conclusion; 2. every
# dictated code belongs to the imposed schema's enum: the loop is closed on
# both sides, nothing can be invented; 3. the honorifics are expanded in the
# TEXT SENT, and nowhere else — the client's record keeps its own spelling; 4.
# no phone number enters what is dictated; 5. step 2's preview shows exactly
# what will go out, including a hand-rewritten text.
# --------------------------------------------------------------------------
class TestCivilitesDeveloppees(unittest.TestCase):
    """`M.` is spoken as `monsieur` — in the text sent, and only there.

    The owner noticed it by ear at the 5th real test call: the agent does not
    read abbreviations correctly. So we expand them when building the brief;
    the records keep their own spelling.
    """

    def test_les_abreviations_connues_sont_developpees(self):
        attendu = {
            "Bonjour M. Ludovic.": "Bonjour monsieur Ludovic.",
            "Bonjour Mme Dupont.": "Bonjour madame Dupont.",
            "Bonjour Mlle Zoé.": "Bonjour mademoiselle Zoé.",
            "Bonjour Mr Smith.": "Bonjour monsieur Smith.",
            "Bonjour Dr Untel.": "Bonjour docteur Untel.",
            "Bonjour Pr Martin.": "Bonjour professeur Martin.",
            "Bonjour MM. Dupont et Durand.":
                "Bonjour messieurs Dupont et Durand.",
            "Bonjour Mmes Dupont et Durand.":
                "Bonjour mesdames Dupont et Durand.",
            # A name with a particle and a compound name: only the honorific
            # moves.
            "Mme Marie-Christine de La Tour":
                "Madame Marie-Christine de La Tour",
            "M. Jean-Baptiste d'Aubigné": "Monsieur Jean-Baptiste d'Aubigné",
        }
        for avant, apres in attendu.items():
            with self.subTest(avant=avant):
                self.assertEqual(consigne.developper_civilites(avant), apres)

    def test_m_sans_point_est_developpe_aussi(self):
        """`M Ludovic` — without a full stop — is spoken as `monsieur Ludovic`.

        Noticed by ear by the owner on 02/08/2026, at the 9th real test call:
        his record carries `M Ludovic`, the agent said `M Ludovic` throughout
        the call. Every other abbreviation is written without a full stop (Mme,
        Mlle, Dr, Pr) and already worked; `M` and `MM` were the only ones
        recognised solely with the stop.
        """
        attendu = {
            "M Ludovic": "Monsieur Ludovic",
            "Bonjour M Ludovic, votre rendez-vous":
                "Bonjour monsieur Ludovic, votre rendez-vous",
            "Personne appelée : M Ludovic JEAN.":
                "Personne appelée : monsieur Ludovic JEAN.",
            "MM Dupont et Durand": "Messieurs Dupont et Durand",
            # And what must NOT move: an `M` that does not introduce a name.
            # The condition is stricter than for the form with a stop — a
            # capital must follow.
            "un M isolé dans la phrase": "un M isolé dans la phrase",
            "le SMS M envoyé hier": "le SMS M envoyé hier",
        }
        for avant, apres in attendu.items():
            with self.subTest(avant=avant):
                self.assertEqual(consigne.developper_civilites(avant), apres)

    def test_la_majuscule_revient_en_debut_de_phrase(self):
        self.assertEqual(
            consigne.developper_civilites("Bonjour. M. Ludovic est là."),
            "Bonjour. Monsieur Ludovic est là.")
        # After a colon, French does not use a capital.
        self.assertEqual(
            consigne.developper_civilites("Personne appelée : M. Ludovic."),
            "Personne appelée : monsieur Ludovic.")

    def test_rien_n_est_developpe_a_l_aveugle(self):
        # No name after it: we touch nothing.
        self.assertEqual(consigne.developper_civilites("Signé M."), "Signé M.")
        self.assertEqual(consigne.developper_civilites(""), "")
        # An abbreviation that is not in the table stays as it is.
        self.assertEqual(consigne.developper_civilites("Me Dupont"),
                         "Me Dupont")

    def test_toutes_les_civilites_du_jeu_d_essai_sont_developpees(self):
        """No record in the product would go out with an abbreviation intact.

        The owner's rule: `traite au moins M., Mme, Mlle, Dr, Pr, et ce que tu
        trouveras dans les donnees`. This test reads back THE DATA — it does
        not settle for the hand-written list.
        """
        premiers = {nom.split(" ")[0] for nom, _t, _r in jeu_essai.CLIENTS}
        # What is written with a full stop is necessarily an abbreviation.
        abreges = {mot for mot in premiers if mot.endswith(".")}
        abreges |= premiers & {"Mme", "Mmes", "Mlle", "Mlles", "Mr", "Dr",
                               "Drs", "Pr"}
        self.assertTrue(abreges)  # there really are some in the data
        for mot in sorted(abreges):
            with self.subTest(civilite=mot):
                self.assertNotEqual(
                    consigne.developper_civilites(mot + " Untel"),
                    mot + " Untel")


class TestConsigneTroisParties(unittest.TestCase):
    """The five kinds produce three parts and three closed outcomes."""

    INFOS = {
        "entreprise": "Cabinet Essai",
        "creneau_libere": "2026-09-07T09:00",
        "lieu": "12 rue des Lilas",
        "duree": "30 minutes",
        "consignes": "venir à jeun",
        "raison": "un imprévu dans notre planning",
        "creneaux_remplacement": "mardi 9h00, mercredi 14h30",
        "creneaux_proposes": "mardi 9h00, mercredi 14h30",
        "creneaux_annulation": "jeudi 11h00",
        "sujet": "obtenir un rendez-vous de consultation",
        "contraintes": "plutôt le matin",
        "mandat": "oui",
        "origine": "vous avez demandé un rendez-vous sur notre site",
        "proposer_annulation": "oui",
    }
    CONTACT = {
        "id": 1, "nom": "M. Ludovic", "telephone": "+33 6 39 98 50 51",
        "champs": {"rdv_existant": "2026-09-20T10:00", "motif": "Contrôle",
                   "consigne": "apporter la carte grise",
                   "appel_manque": "2026-09-01T08:30"},
    }

    def _consigne(self, nature, presentation=None, infos=None, options=None):
        preferences = generation.Preferences()
        preferences.definir(themes.CLE_ENTREPRISE, "Cabinet Essai")
        champs = assistant.champs_campagne(
            {"champs": assistant.NATURES[nature]["champs"]})
        cadre = assistant.construire_consigne(
            nature, dict(self.INFOS if infos is None else infos), preferences,
            {assistant.CLE_REPLACER_ANNULATION: True} if options is None
            else options,
            champs, presentation=presentation)
        return assistant.finaliser_consigne(cadre, dict(self.CONTACT), champs)

    def test_les_cinq_natures_ont_bien_les_trois_parties(self):
        # Five since 03/08/2026: three kinds that wrote nothing into the
        # appointment book were removed.
        self.assertEqual(len(assistant.NATURES), 5)
        for nature in assistant.NATURES:
            with self.subTest(nature=nature):
                texte = self._consigne(nature).texte()
                self.assertIn(consigne.TITRE_PRESENTATION, texte)
                self.assertIn(consigne.TITRE_CONTEXTE, texte)
                self.assertIn(consigne.TITRE_ISSUES, texte)
                # (2) the objective, the facts, the constraints, the freedom to
                # discuss: it is THAT block that was entirely missing.
                self.assertIn("Ton objectif : ", texte)
                self.assertIn(consigne.TITRE_FAITS, texte)
                self.assertIn(consigne.TITRE_CONTRAINTES, texte)
                self.assertIn(consigne.LIBERTE, texte)
                self.assertIn("Personne appelée : monsieur Ludovic.", texte)
                # (3) three outcomes, not one more.
                for etiquette in ("- OUI — ", "- NON — ", "- AUTRE — "):
                    self.assertIn(etiquette, texte)

    def test_les_issues_sont_fermees_et_toutes_dans_le_schema(self):
        """Every dictated code belongs to the imposed schema's enum.

        It is the loop closed on both sides: what we ask of the agent is
        exactly what the schema allows it to return.
        """
        for nature in assistant.NATURES:
            with self.subTest(nature=nature):
                fixee = self._consigne(nature)
                autorises = (calle_client.ISSUES_CASCADE
                             if fixee.genre == consigne.GENRE_CASCADE
                             else calle_client.STATUTS_VALIDES)
                for code in fixee.codes_attendus():
                    self.assertIn(code, autorises)
                champ = consigne.CHAMP_ISSUE[fixee.genre]
                self.assertIn("rends " + champ + " = ", fixee.texte_issues())
                self.assertEqual(sorted(fixee.issues), ["autre", "non", "oui"])

    def test_les_huit_natures_ont_un_repli_sans_date(self):
        """NO kind must require a date to conclude on OTHER.

        The cascade was the only one without a fallback: the agent returned
        `moved` without a date, and RingBack declared the answer unreadable
        (9th real test call, 02/08/2026). The fallback has existed for that
        from the start — it was missing from one kind out of eight, and it was
        the freed slot's.
        """
        for nature in assistant.NATURES:
            with self.subTest(nature=nature):
                autre = self._consigne(nature).issues["autre"]
                # Two valid forms: either OTHER is already to_reschedule (kinds
                # where nothing is concluded by a date), or it declares its
                # fallback. What we forbid is the third: a move code WITHOUT a
                # fallback — the cascade's case.
                self.assertEqual(
                    autre["code_sans_date"] or autre["code"], "to_reschedule")
                # And the agent reads it in black and white in its brief.
                self.assertIn("to_reschedule",
                              self._consigne(nature).texte_issues())

    def test_repeter_n_est_pas_une_raison_de_passer_la_main(self):
        """What the agent did on the 8th test call, and must not do again.

        `Can you remind me of the date?` — the date was written in `what you
        know`, the agent had just said it — and it answered `I would rather not
        say something wrong` before hanging up. The emergency exit fired on `an
        unexpected question`.
        """
        texte = self._consigne("creneau_libere").texte()
        self.assertIn("redire ce que tu sais n'est JAMAIS une raison de "
                      "passer la main", texte)
        self.assertIn("redis-les simplement, aussi souvent qu'il le faut",
                      texte)
        # The emergency exit still exists, but it is BOUNDED.
        self.assertIn("UNIQUEMENT si la réponse ne se trouve nulle part",
                      texte)
        self.assertNotIn("devant une question imprévue", texte)
        # And the repetition rule is stated BEFORE the emergency exit: read in
        # order, the brief authorises before it evades.
        self.assertLess(texte.index("redire ce que tu sais"),
                        texte.index("sortie de secours"))

    def test_le_schema_de_resultat_reste_ferme(self):
        for schema in (calle_client.SCHEMA_RESULTAT,
                       calle_client.SCHEMA_RESULTAT_CASCADE):
            self.assertFalse(schema["additionalProperties"])
        self.assertEqual(
            calle_client.SCHEMA_RESULTAT["properties"]["appointment_status"]
            ["enum"], list(calle_client.STATUTS_VALIDES))
        self.assertEqual(
            calle_client.SCHEMA_RESULTAT_CASCADE["properties"]["outcome"]
            ["enum"], list(calle_client.ISSUES_CASCADE))

    def test_la_cascade_est_la_seule_nature_a_l_autre_schema(self):
        cascade = [nature for nature, definition in assistant.NATURES.items()
                   if definition["genre"] == consigne.GENRE_CASCADE]
        self.assertEqual(cascade, ["creneau_libere"])

    def test_aucun_numero_de_telephone_dans_la_consigne(self):
        for nature in assistant.NATURES:
            with self.subTest(nature=nature):
                texte = self._consigne(nature).texte()
                self.assertNotIn(self.CONTACT["telephone"], texte)
                self.assertNotIn("+33639985051", texte)
                self.assertNotIn("39 98 50 51", texte)

    def test_aucune_variable_ne_reste_en_crochets(self):
        for nature in assistant.NATURES:
            with self.subTest(nature=nature):
                texte = self._consigne(nature).texte()
                self.assertEqual(re.findall(r"\[[^\]\n]+\]", texte), [])

    def test_la_presentation_part_mot_pour_mot(self):
        fixee = self._consigne("confirmation")
        self.assertTrue(fixee.texte_presentation().startswith("« Bonjour "))
        # In quotation marks, whole, word for word — honorifics expanded.
        self.assertIn(consigne.developper_civilites(fixee.texte_presentation()),
                      fixee.texte())

    def test_un_texte_recrit_a_la_main_est_repris_tel_quel(self):
        ecrit = ("Bonjour [identite]. Ici le secrétariat.\n"
                 "Votre rendez-vous du [rdv_existant] tient-il toujours ?")
        fixee = self._consigne("confirmation", presentation=ecrit)
        attendu = (ecrit.replace("[identite]", "M. Ludovic")
                   .replace("[rdv_existant]",
                            "dimanche 20 septembre 2026 à 10 heures"))
        # The user's line break is kept; only the honorific is expanded,
        # because that is what will be SPOKEN.
        self.assertIn(consigne.developper_civilites(attendu), fixee.texte())

    def test_une_information_facultative_vide_ne_laisse_pas_de_ligne(self):
        infos = dict(self.INFOS)
        del infos["lieu"]
        texte = self._consigne("creneau_libere", infos=infos,
                               options={}).texte()
        self.assertNotIn("Lieu :", texte)
        self.assertIn("Durée de la prestation : 30 minutes.", texte)

    def test_les_contraintes_des_fiches_sont_toutes_la(self):
        texte = self._consigne("rappel_rdv").texte()
        self.assertIn("aucune information médicale", texte)
        self.assertIn("ne communique aucun numéro de téléphone", texte)
        self.assertIn("n'insiste jamais", texte)
        self.assertIn("Je suis un assistant automatique", texte)
        self.assertIn("Je préfère ne pas vous dire de bêtise", texte)
        self.assertIn("SANS le motif de l'appel", texte)

    def test_sans_nom_d_entreprise_la_sortie_de_secours_reste_dicible(self):
        preferences = generation.Preferences()
        champs = assistant.champs_campagne(
            {"champs": assistant.NATURES["rappel_rdv"]["champs"]})
        nu = assistant.construire_consigne("rappel_rdv", {}, preferences, {},
                                           champs).texte()
        self.assertIn("demande à " + consigne.ENTREPRISE_INCONNUE, nu)
        self.assertNotIn("[entreprise]", nu)
        self.assertNotIn("[plage_rappel]", nu)


class TestConsigneDeCampagne(_CampagneAssistant):
    """The brief that is built really is the one that goes out — and the screen
    shows it.
    """

    def _campagne_confirmation(self, nom="M. Ludovic"):
        base = self.application.base
        horaire = (datetime.datetime.now() + datetime.timedelta(days=3)
                   ).replace(hour=9, minute=0, second=0, microsecond=0
                             ).isoformat(timespec="minutes")
        client_id = base.ajouter_client(nom, "+33 6 39 98 50 51")
        base.ajouter_rendezvous(client_id, horaire, "Contrôle annuel")
        return self._campagne(
            "confirmation",
            [nom + ";+33 6 39 98 50 51;" + horaire + ";Contrôle annuel"])

    def _consigne_du_contact(self, campagne_id):
        """Exactly _appeler_contact's path — no other."""
        base = self.application.base
        campagne = base.obtenir_campagne(campagne_id)
        configuration = assistant.configuration_campagne(campagne)
        contact = base.contacts_de_campagne(campagne_id)[0]
        mission = assistant.finaliser_mission(
            campagne["mission"], contact,
            assistant.champs_campagne(configuration))
        return contact, assistant.consigne_de_l_appel(
            base, self.application.preferences, campagne, configuration,
            contact, mission, False)

    def test_civilite_developpee_dans_la_consigne_jamais_dans_la_fiche(self):
        campagne_id = self._campagne_confirmation()
        contact, fixee = self._consigne_du_contact(campagne_id)
        texte = fixee.texte()
        self.assertIn("monsieur Ludovic", texte)
        self.assertNotIn("M. Ludovic", texte)
        # THE RECORD, FOR ITS PART, HAS NOT MOVED: it is the owner's own
        # spelling.
        self.assertEqual(contact["nom"], "M. Ludovic")
        self.assertTrue(any(client["nom"] == "M. Ludovic" for client
                            in self.application.base.lister_clients()))
        # And never the number in what is dictated.
        self.assertNotIn("39 98 50 51", texte)
        self.assertNotIn("+33639985051", texte)

    def test_la_consigne_de_l_appel_a_les_trois_parties(self):
        campagne_id = self._campagne_confirmation()
        _, fixee = self._consigne_du_contact(campagne_id)
        texte = fixee.texte()
        self.assertIn(consigne.TITRE_PRESENTATION, texte)
        self.assertIn(consigne.TITRE_CONTEXTE, texte)
        self.assertIn(consigne.TITRE_ISSUES, texte)
        self.assertIn("Motif : Contrôle annuel.", texte)
        self.assertIn("Nom de l'entreprise : Cabinet Essai.", texte)

    def test_l_apercu_de_l_etape_2_montre_les_trois_parties(self):
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "info_entreprise": "Cabinet Essai",
            "info_creneau_libere": "2026-09-07T09:00", "ordre": "liste",
            "relance_mode": "delai", "relance_delai": "4", "relance_max": "3"})
        _, page = self._obtenir("/assistant/message?b=" + b)
        self.assertIn('id="apercu"', page)
        self.assertIn('id="apercu-contexte"', page)
        self.assertIn('id="apercu-issues"', page)
        contexte = page.split('id="apercu-contexte"')[1].split("</div>")[0]
        self.assertIn("Ton objectif", contexte)
        self.assertIn("Cabinet Essai", contexte)
        self.assertIn("Je préfère ne pas vous dire de bêtise", contexte)
        issues = page.split('id="apercu-issues"')[1].split("</div>")[0]
        for etiquette in ("OUI", "NON", "AUTRE"):
            self.assertIn(etiquette, issues)
        for code in calle_client.ISSUES_CASCADE:
            self.assertIn(code, issues)
        self.assertIn("exactement ce qui sera envoyé", page)

    def test_l_apercu_montre_le_texte_recrit_a_la_main(self):
        _, page = self._poster("/assistant/nature", {"nature": "confirmation"})
        b = self._brouillon(page)
        ecrit = "Bonjour [identite], ici Cabinet Essai. Serez-vous là ?"
        self._poster("/assistant/message", {
            "b": b, "info_entreprise": "Cabinet Essai", "ordre": "liste",
            "mission": ecrit, "mission_editee": "1",
            "relance_mode": "delai", "relance_delai": "4", "relance_max": "3"})
        _, page = self._obtenir("/assistant/message?b=" + b)
        apercu = page.split('id="apercu"')[1].split("</div>")[0]
        self.assertIn("ici Cabinet Essai. Serez-vous là ?", apercu)
        self.assertNotIn("merci de me confirmer votre présence", apercu)


class TestTacheHorsCampagne(unittest.TestCase):
    """Outside a campaign too (individual callback, direct cascade, real test
    call), the task has its three parts: no call goes out as a monologue.
    """

    RDV = {"horaire": "2026-09-20T10:00", "motif": "Séance d'essai"}

    def test_la_tache_de_repli_a_trois_parties_et_des_issues_fermees(self):
        tache = calle_client.AppelReel(cle_api="cle-de-test-0123456789")._tache(
            "M. Ludovic", dict(self.RDV))
        self.assertIn(consigne.TITRE_PRESENTATION, tache)
        self.assertIn(consigne.TITRE_CONTEXTE, tache)
        self.assertIn(consigne.TITRE_ISSUES, tache)
        for etiquette in ("- OUI — ", "- NON — ", "- AUTRE — "):
            self.assertIn(etiquette, tache)
        for code in calle_client.STATUTS_VALIDES:
            self.assertIn(code, tache)
        self.assertIn("monsieur Ludovic", tache)
        self.assertNotIn("[entreprise]", tache)
        self.assertNotIn("[plage_rappel]", tache)

    def test_la_tache_de_cascade_a_les_issues_de_cascade(self):
        tache = calle_client.AppelReel(cle_api="cle-de-test-0123456789")._tache_cascade(
            "M. Ludovic", "Bonjour, une place s'est libérée.",
            "2026-09-07T09:00")
        self.assertIn(consigne.TITRE_ISSUES, tache)
        for code in calle_client.ISSUES_CASCADE:
            self.assertIn(code, tache)
        self.assertNotIn("appointment_status", tache)
        self.assertIn("monsieur Ludovic", tache)

    def test_une_consigne_deja_construite_part_telle_quelle(self):
        fixee = consigne.Consigne("Bonjour, ceci est ma présentation.",
                                  "vérifier que rien n'est retouché")
        self.assertEqual(calle_client.AppelReel(cle_api="cle-de-test-0123456789")._tache(
            "M. Ludovic", dict(self.RDV), consigne=fixee), fixee.texte())


class TestEcranCleCalle(_TestAvecServeurWeb):
    """The end-to-end lock: the PAGE, requested from the real server.

    A TEST ON THE FUNCTION DOES NOT PROVE THE SCREEN. It is the lesson that
    keeps coming back in this project: the logic was right, and it was the
    page's wiring that showed nothing. So we request /reglages over HTTP.
    """

    MARQUE = TestCleCalleProtegee.MARQUE

    def test_l_ecran_CRIE_quand_la_cle_collee_ne_sert_pas(self):
        with sans_aucune_cle_calle():
            calle_client.ranger_cle(self.MARQUE)
            os.environ["CALLE_API_KEY"] = "iams_UNE_TOUTE_AUTRE_CLE_9876543210"
            try:
                code, page = self._obtenir("/reglages")
            finally:
                os.environ.pop("CALLE_API_KEY", None)
        self.assertEqual(code, 200)
        self.assertIn("PAS celle qui sert", page)
        # THE ESCAPED FORM: that value goes through html.escape, so its
        # apostrophe becomes an entity in the page.
        self.assertIn(html.escape(calle_client.SOURCE_VARIABLE), page)
        # AND THE KEY IS NOT IN THE PAGE, not even when sidelined.
        self.assertNotIn(self.MARQUE, page)

    def test_l_ecran_se_TAIT_quand_les_deux_portent_la_meme_cle(self):
        """His real case of 03/09: shouting there would have been a false signal.
        """
        with sans_aucune_cle_calle():
            calle_client.ranger_cle(self.MARQUE)
            os.environ["CALLE_API_KEY"] = self.MARQUE
            try:
                code, page = self._obtenir("/reglages")
            finally:
                os.environ.pop("CALLE_API_KEY", None)
        self.assertEqual(code, 200)
        # AND WE CHECK THE PAGE REALLY IS THE RIGHT ONE: an assertNotIn on an
        # object that is not the page would always succeed.
        self.assertIn("Réglages", page)
        self.assertNotIn("PAS celle qui sert", page)
        self.assertNotIn(self.MARQUE, page)



class TestConsigneDeRepliSuitLaLangue(unittest.TestCase):
    """The brief built WITHOUT the wizard must follow the language.

    FOUND BY THE AUDIT OF 03/09/2026, and confirmed by running it. Two paths do
    not pass a ready-made brief to the call client — the call queue (`Run the
    queue`, the `Rappeler` button) and the direct cascade. `AppelReel._tache`
    then rebuilds it itself, with `Consigne`'s default values: no translator,
    and the FRENCH honorifics table.

    AND THE VOICE, FOR ITS PART, ALREADY FOLLOWED THE LANGUAGE. The same POST
    set `region: "GB"`, `locale: "en-GB"`. So an English voice read French
    instructions, and said `monsieur Smith` to an English-speaking patient. It
    is worse than anything in French: the two halves contradict each other.
    """

    RDV = {"horaire": "2026-09-10T14:30", "motif": "check-up"}

    def _tache(self, langue_code):
        client = calle_client.AppelReel(cle_api="cle-de-test-0123456789",
                                        langue_appel=langue_code)
        return client._tache("Mr Smith", self.RDV,
                             mission="Hello Mr Smith, I am calling on behalf "
                                     "of Dr Martin about your appointment.")

    def test_la_consigne_de_la_file_suit_la_langue(self):
        anglaise = self._tache("en")
        # WHAT IS SAID OVER THE PHONE, not only the headings.
        self.assertNotIn("Tu es un assistant téléphonique français", anglaise)
        self.assertNotIn("Je préfère ne pas vous dire de bêtise", anglaise)
        self.assertNotIn("tu discutes librement, en français", anglaise)
        # AND THE HONORIFICS ARE NOT EXPANDED IN ENGLISH: `Mr Smith` reads
        # perfectly well; `monsieur Smith` is a mistake said aloud.
        self.assertNotIn("monsieur Smith", anglaise)
        self.assertNotIn("docteur Martin", anglaise)
        self.assertIn("Mr Smith", anglaise)
        # AND THE THREE LINES THAT DECIDE THE RESULT. They are what tell the
        # agent WHEN to choose which outcome: left in French, the
        # English-speaking agent concludes by guesswork. The counter-test of
        # 03/09 showed that without this check, the test went green while those
        # three lines stayed French.
        for morceau in ("la personne accepte", "elle refuse", "tout le reste"):
            self.assertNotIn(morceau, anglaise, morceau)

    def test_le_français_ne_bouge_pas(self):
        """THE OTHER HALF: the original product must not regress."""
        francaise = self._tache("fr")
        self.assertIn("Tu es un assistant téléphonique français", francaise)
        # In French, the honorifics ARE expanded — that is deliberate.
        self.assertIn("monsieur Smith", francaise)

    def test_la_cascade_aussi(self):
        client = calle_client.AppelReel(cle_api="cle-de-test-0123456789",
                                        langue_appel="en")
        tache = client._tache_cascade("Mr Smith", "", "2026-09-10T14:30")
        self.assertNotIn("Tu es un assistant téléphonique français", tache)
        self.assertNotIn("une place vient de se libérer", tache)
        # THE CASCADE OUTCOMES are passed EXPLICITLY: so they fell into the
        # other branch and stayed French.
        for morceau in ("la personne prend la place", "elle décline",
                        "tout le reste"):
            self.assertNotIn(morceau, tache, morceau)

    def test_la_date_dite_suit_la_langue(self):
        """Without a mission, the introduction carries a date — it is SPOKEN.
        """
        client = calle_client.AppelReel(cle_api="cle-de-test-0123456789",
                                        langue_appel="en")
        tache = client._tache("Mr Smith", self.RDV)
        for mot in ("jeudi", "septembre", "heures"):
            self.assertNotIn(mot, tache, tache[:200])



class TestPriseRdvAvecAncienRendezVous(_CampagneAssistant):
    """An appointment booking loaded from the appointments to be rebooked.

    FOUND BY THE AUDIT OF 03/09/2026. It is this kind's most obvious use: call
    back the people whose appointment was cancelled or missed, to set them a
    new one. The contact then carries the link to their OLD appointment.

    AND THAT LINK MADE EVERYTHING BE LOST. The `the contact has an appointment`
    branch came BEFORE the one that creates the new one: the old cancelled
    appointment went back to `confirme`, and the date agreed over the phone was
    thrown away. The person thought they were expected on Tuesday the 13th; the
    schedule showed the old date, marked confirmed.
    """

    def _monter(self):
        base = self.application.base
        prefs = self.application.preferences
        # THE CALLING WINDOW OPEN: without it the test measures nothing after
        # 7pm — the politeness safety lock refuses the call and the outcome
        # becomes `failure`. A test whose result depends on what time it is
        # does not measure the product.
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        # A CANCELLED appointment, in the past: the exact use case.
        passe = (datetime.datetime.now() - datetime.timedelta(days=10)
                 ).replace(hour=9, minute=0, second=0, microsecond=0)
        client_id = base.ajouter_client("M. Demandeur", "+33 6 39 98 50 51")
        ancien = base.ajouter_rendezvous(
            client_id, passe.isoformat(timespec="minutes"), "bilan",
            statut="annulé")
        definition = assistant.NATURES["prise_rdv"]
        contacts, _ = assistant.contacts_depuis_base(
            base, "a_recaser", definition["champs"], ())
        self.assertTrue(contacts, "le montage n'a produit aucun contact")
        # THE LINK TO THE OLD APPOINTMENT IS INDEED THERE: it is what triggers
        # the defect. If it ever disappears, this test measures nothing any
        # more — hence the check.
        self.assertEqual(contacts[0].get("rendezvous_id"), ancien)
        infos = {info["code"]: (info.get("exemple") or "Cabinet Essai")
                 for info in definition["infos"]}
        campagne_id = assistant.creer_campagne_prete(base, {
            "nature": "prise_rdv", "infos": infos, "infos_auto": {},
            "politique": "tous", "ordre": "liste", "options": {},
            "champs": [dict(c) for c in definition["champs"]],
            "mission": assistant.construire_mission("prise_rdv", infos,
                                                    prefs, {}),
            "recette": {"apports": [{"mode": "base", "source": "a_recaser"}],
                        "a_la_main": True},
            "contacts": contacts}, prefs)
        return base, ancien, campagne_id

    def test_la_date_convenue_cree_un_rendez_vous(self):
        base, ancien, campagne_id = self._monter()
        self._derouler(campagne_id)

        avant = base.obtenir_rendezvous(ancien)
        tous = base.tous_les_rendezvous()
        neufs = [r for r in tous if r["id"] != ancien]

        # (1) The date agreed over the phone exists somewhere.
        self.assertTrue(neufs, "aucun rendez-vous créé : la date convenue au "
                               "téléphone a été jetée")
        # (2) And the old CANCELLED appointment is not resurrected as
        # `confirme`.
        self.assertNotEqual(avant["statut"], "confirmé",
                            "un rendez-vous annulé est revenu « confirmé »")



class TestNePlusAppelerHorsCampagne(unittest.TestCase):
    """The promise made over the phone is kept on EVERY path.

    FOUND BY THE AUDIT OF 03/09/2026. The brief dictated to the agent always
    contains: `si la personne demande qu'on ne la rappelle plus, reponds "C'est
    note, vous ne serez plus appele" et rends do_not_call = yes`. That sentence
    goes out in the call queue as well as in a campaign.

    BUT ONLY ONE PATH READ IT. `ne_plus_appeler_demande` was only called by the
    wizard: from the call queue or the direct cascade, the person was promised
    they would not be called again, and nothing was written on their record.
    They were called back the next day.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.client_id = self.base.ajouter_client("M. Durand",
                                                  "+33 6 39 98 50 42")

    def test_la_file_d_appels_honore_le_refus(self):
        planif = planificateur.Planificateur(self.base,
                                             _ClientQuiRefuseTout())
        planif.dry_run = False
        planif.confirmer_appels_reels()
        horaire = (datetime.datetime.now() - datetime.timedelta(days=2)
                   ).replace(hour=9, minute=0, second=0, microsecond=0)
        rdv_id = self.base.ajouter_rendezvous(
            self.client_id, horaire.isoformat(timespec="minutes"),
            "séance", statut="manqué")
        planif.programmer(rdv_id)
        planif.executer()
        fiche = self.base.obtenir_client(self.client_id)
        self.assertTrue(fiche["ne_plus_appeler"],
                        "la promesse faite au téléphone n'a pas été tenue : "
                        "la fiche n'est pas marquée « ne plus appeler »")


class _ClientQuiRefuseTout:
    """A call client that ALWAYS returns `do not call me again`.

    NOT A FAKE RESULT: it is exactly the shape `valider_resultat` accepts, and
    exactly what the brief asks the agent to return when the person asks for
    it.
    """

    dernier_identifiant = ""

    def appeler(self, nom, telephone, rendezvous, mission=None,
                consigne=None):
        return calle_client.IssueAppel(
            resultat={"appointment_status": "canceled", "new_datetime": "",
                      "notes": "ne souhaite plus être appelée",
                      "do_not_call": "yes"},
            transcription="Contact : ne me rappelez plus.")



class TestPanneApresLancementGardeLIdentifiant(unittest.TestCase):
    """The phone rang: no later failure must be blamed on them.

    FOUND BY THE AUDIT OF 03/09/2026. The code states its intention in full on
    the line following the creation: `THE CALL HAS GONE OUT HERE. Everything
    that fails from this line on will be reclassified "result pending" and will
    keep THAT identifier`. But the `except` only caught PART of the family —
    `EchecDeNotreCote`. A follow-up response that is not JSON (an
    intermediary's error page, a truncated body) raises a BARE `ErreurApi`,
    which went through.

    WHAT THAT COSTS SOMEBODY: the conversation took place and succeeded;
    RingBack counts a failed attempt, arms a follow-up — the phone rings a
    second time for an exchange already concluded — and the CALL-E identifier
    is written nowhere, so `Recover the pending results` can no longer find it.
    The result is lost AND the person is disturbed.
    """

    CLE = "cle-de-test-0123456789"

    def setUp(self):
        etat = {"appels": 0}

        class FauxCoupeApresLancement(BaseHTTPRequestHandler):
            def log_message(self, *_args):
                pass

            def do_POST(self):
                # The creation succeeds: the call GOES OUT, and its identifier
                # exists.
                corps = json.dumps({"id": "appel-parti-1",
                                    "status": "queued"}).encode("utf-8")
                self.send_response(201)
                self.send_header("Content-Type", "application/json")
                self.send_header("Content-Length", str(len(corps)))
                self.end_headers()
                self.wfile.write(corps)

            def do_GET(self):
                # The follow-up returns HTML: that is what a broken gateway
                # returns, and it is not JSON.
                etat["appels"] += 1
                corps = b"<html><body>502 Bad Gateway</body></html>"
                self.send_response(200)
                self.send_header("Content-Type", "text/html")
                self.send_header("Content-Length", str(len(corps)))
                self.end_headers()
                self.wfile.write(corps)

        self.serveur = HTTPServer(("127.0.0.1", 0), FauxCoupeApresLancement)
        threading.Thread(target=self.serveur.serve_forever,
                         daemon=True).start()
        self.addCleanup(self.serveur.server_close)
        self.addCleanup(self.serveur.shutdown)
        self.url = f"http://127.0.0.1:{self.serveur.server_address[1]}"

    def test_la_panne_du_suivi_garde_l_identifiant(self):
        client = calle_client.AppelReel(
            cle_api=self.CLE, url_base=self.url, delai_total=2.0,
            intervalle=0.01, delai_requete=2.0)
        with self.assertRaises(calle_client.ErreurApi) as vu:
            client.appeler("M. Un Contact", "+33 6 39 98 50 42",
                           {"horaire": "2026-09-10T14:30", "motif": "séance"},
                           mission="Bonjour.")
        erreur = vu.exception
        # (1) The call's identifier is kept: it is the only thing that lets us
        # find what the conversation produced.
        self.assertEqual(getattr(erreur, "identifiant", ""), "appel-parti-1")
        # (2) And the failure must NOT read as a call that did not go out.
        self.assertTrue(getattr(erreur, "appel_lance", False),
                        "l'appel est parti : le dire est ce qui empêche de "
                        "compter une tentative et d'armer une relance")



class TestLesProchesConsommentLeurQuota(unittest.TestCase):
    """The `nearest` slots count towards their half-day's quota.

    FOUND BY HIS REAL TEST CALL OF 04/09/2026, on his real database: a move
    campaign with ONE appointment to move out was offered seven slots — **all
    on the same Saturday**, from 8:20 to 14:40. His remark, word for word: `au
    lieu de faire un tirage de plein de dates, il n'en a selectionne qu'une
    seule`.

    THE CAUSE: `PROCHES_DABORD` takes the three nearest slots as they are —
    that is deliberate — but they were NOT recorded in the per-half-day count.
    So the half-day could receive `PAR_DEMI_JOURNEE` MORE, and the first day
    collected 3 + 2 + 2 = seven slots instead of four. With a target of seven
    (one appointment to move), the loop stopped before it had seen the second
    day.

    AND SO THE AGENT HAD NOTHING TO NEGOTIATE: seven times the same Saturday is
    not seven offers, it is one. It is exactly the defect the spread exists to
    avoid.
    """

    def _prefs(self):
        prefs = generation.Preferences()
        for jour in range(5):
            horaires.basculer_periode(prefs, jour, 9 * 60, 12 * 60 + 30,
                                      "ouvrir")
            horaires.basculer_periode(prefs, jour, 14 * 60, 18 * 60 + 30,
                                      "ouvrir")
        return prefs

    LUNDI = datetime.datetime(2026, 8, 17, 8, 0)

    def _par_jour(self, places):
        compte = {}
        for horaire in places:
            compte[horaire[:10]] = compte.get(horaire[:10], 0) + 1
        return compte

    def test_un_seul_rendez_vous_a_deplacer_couvre_plusieurs_jours(self):
        base = db.Base(":memory:")
        self.addCleanup(base.fermer)
        places = horaires.places_negociables(base, self._prefs(),
                                             depuis=self.LUNDI, a_deplacer=1)
        self.assertTrue(places)
        jours = self._par_jour(places)
        self.assertGreater(
            len(jours), 1,
            f"les {len(places)} places tombent toutes le même jour : "
            f"{jours} — l'agent n'a rien à négocier")

    def test_le_stock_s_etale_sur_les_jours_ET_les_demi_journees(self):
        """HIS RULE, word for word: `plein de jours differents et matin et
        apres-midi` (04/09/2026).

        AND NOT A HARD CAP PER HALF-DAY: a first version of this test asserted
        that, and it was wrong. `places_negociables`'s SECOND ROUND is allowed
        to exceed the quota, and it is written in the code: `better two more
        slots on the same morning than seven people without a date`. It only
        kicks in when the target exceeds what the calendar can give while
        respecting the quota — which happens from seven appointments to move
        on. A test that forbade that fallback would forbid the product to serve
        everybody.

        What is guarded is the SPREAD: the more people there are to rebook, the
        more days the offer covers — and never a single one.
        """
        base = db.Base(":memory:")
        self.addCleanup(base.fermer)
        vus = {}
        for a_deplacer, jours_attendus in ((1, 4), (3, 10)):
            with self.subTest(a_deplacer=a_deplacer):
                places = horaires.places_negociables(
                    base, self._prefs(), depuis=self.LUNDI,
                    a_deplacer=a_deplacer)
                jours, demies = set(), set()
                for horaire in places:
                    quand = datetime.datetime.fromisoformat(horaire)
                    jours.add(horaire[:10])
                    demies.add("matin"
                               if quand.hour < horaires.HEURE_BASCULE_MIDI
                               else "apres")
                vus[a_deplacer] = len(jours)
                self.assertGreaterEqual(
                    len(jours), jours_attendus,
                    f"{len(places)} places sur seulement {len(jours)} jour(s)")
                # MORNING **AND** AFTERNOON: half of his rule.
                self.assertEqual(demies, {"matin", "apres"},
                                 f"une seule demi-journée servie : {demies}")
        # AND THE SPREAD FOLLOWS THE LOAD: three people to rebook cover more
        # days than one.
        self.assertGreater(vus[3], vus[1])

    def test_les_plus_proches_restent_les_premieres(self):
        """The non-regression: the `nearest first` order does not move."""
        base = db.Base(":memory:")
        self.addCleanup(base.fermer)
        prefs = self._prefs()
        toutes = [e["horaire"] for e in horaires.creneaux_proposables(
            base, prefs, depuis=self.LUNDI) if not e["occupe"]]
        places = horaires.places_negociables(base, prefs, depuis=self.LUNDI,
                                             a_deplacer=1)
        self.assertEqual(places[:horaires.PROCHES_DABORD],
                         toutes[:horaires.PROCHES_DABORD])



class TestLeJournalDAuditMasqueAuPointDEcriture(unittest.TestCase):
    """The log masks what the provider answered — without relying on the caller.

    REPORTED BY A CALL-E REVIEWER on 04/09/2026 on proposal #297. He was right
    on the substance: every caller did go through `reponse_brute_lisible`, but
    nothing enforced it. The promise written twice — `_auditer`'s docstring,
    the published README — rested on the sole discipline of whoever calls.

    THIS TEST CALLS `_auditer` DIRECTLY, with raw content, because that is
    exactly what a future caller would do without knowing.
    """

    NUMERO = "+33 6 39 98 00 42"
    BRUT = '{"recipients":[{"phones":["+33 6 39 98 00 42"]}]}'

    def test_un_numero_rendu_par_l_api_ne_s_ecrit_pas_en_clair(self):
        dossier = tempfile.mkdtemp(prefix="ringback-audit-")
        self.addCleanup(shutil.rmtree, dossier, ignore_errors=True)
        chemin = os.path.join(dossier, "audit.jsonl")
        client = calle_client.AppelReel(cle_api="cle-de-test-0123456789",
                                        chemin_audit=chemin)
        client._auditer("06 39 •• •• 42", "terminé", reponse_brute=self.BRUT)
        with open(chemin, encoding="utf-8") as fichier:
            ecrit = fichier.read()
        self.assertNotIn(self.NUMERO, ecrit)
        self.assertNotIn("3398004", ecrit.replace(" ", ""))
        # AND THE LINE STAYS USEFUL: it is what serves to understand what
        # RingBack could not read. Masking must not empty.
        self.assertIn("recipients", ecrit)

    def test_masquer_deux_fois_ne_degrade_pas_la_citation(self):
        """The masking is idempotent — otherwise applying it again at the write
        point would spoil the quotations already masked by
        `reponse_brute_lisible`.
        """
        une = calle_client.masquer_numeros_du_texte(self.BRUT)
        deux = calle_client.masquer_numeros_du_texte(une)
        self.assertEqual(une, deux)
        self.assertNotIn(self.NUMERO, une)



class TestLAdresseDuServiceEstControlee(unittest.TestCase):
    """The key only goes to CALL-E, or to a local dummy API.

    REPORTED BY A CALL-E REVIEWER on 04/09/2026 on proposal #297:
    `CALLE_API_URL` was read and used as it was. A shared machine, a forgotten
    variable, a tutorial copied out — and the `Authorization` header along with
    the patients' numbers went elsewhere.
    """

    CLE = "cle-de-test-0123456789"

    def _construire(self, url):
        return calle_client.AppelReel(cle_api=self.CLE, url_base=url)

    def test_le_vrai_service_et_ses_sous_domaines_passent(self):
        for url in ("https://api.heycall-e.com", "https://heycall-e.com",
                    "https://api.heycall-e.com/", "https://eu.heycall-e.com"):
            with self.subTest(url=url):
                self.assertEqual(self._construire(url).url_base,
                                 url.rstrip("/"))

    def test_une_api_factice_locale_passe_car_rien_ne_quitte_la_machine(self):
        for url in ("http://127.0.0.1:8791", "http://localhost:8791",
                    "https://127.0.0.1:8791"):
            with self.subTest(url=url):
                self.assertEqual(self._construire(url).url_base, url)

    def test_toute_autre_adresse_est_refusee_et_le_refus_la_nomme(self):
        refuses = ("http://api.heycall-e.com",         # en clair
                   "https://heycall-e.com.pirate.io",  # domaine voisin
                   "https://api.heycal1-e.com",  # a digit for an l
                   "http://192.168.1.50:8080",  # the local network
                   "ftp://heycall-e.com",
                   "pas-une-adresse")
        for url in refuses:
            with self.subTest(url=url):
                with self.assertRaises(calle_client.AdresseApiRefusee) as pris:
                    self._construire(url)
                # THE REFUSAL NAMES THE ADDRESS IT SAW. Without that it is
                # indistinguishable from a missing key, and the user would look
                # in the wrong place.
                self.assertIn(url, str(pris.exception))

    def test_une_adresse_vide_veut_dire_non_renseignee_pas_mauvaise(self):
        """NUANCE MEASURED BY TRIAL: `url_base=""` or `CALLE_API_URL=""` mean `I
        have set nothing`, and the product must then use the official address —
        not refuse. Only a DIRECT call to the check with an empty value is a
        caller error.
        """
        self.assertEqual(self._construire("").url_base,
                         calle_client.AppelReel.URL_DEFAUT)
        with self.assertRaises(calle_client.AdresseApiRefusee):
            calle_client.valider_adresse_api("")

    def test_le_refus_retombe_en_simulation_sans_toucher_aux_appelants(self):
        """AdresseApiRefusee inherits from CleApiAbsente ON PURPOSE: everything
        that already knew how to fall back to simulation for want of a key
        falls back the same way for want of a valid address. No caller had to
        change.
        """
        self.assertTrue(issubclass(calle_client.AdresseApiRefusee,
                                   calle_client.CleApiAbsente))
        with self.assertRaises(calle_client.CleApiAbsente):
            self._construire("https://exemple.invalide")

    def test_l_adresse_vient_aussi_de_l_environnement(self):
        """The environment variable is the path the reviewer named: it goes
        through the same check as the argument.
        """
        sauve = os.environ.get("CALLE_API_URL")
        os.environ["CALLE_API_URL"] = "http://ailleurs.example.com"
        try:
            with self.assertRaises(calle_client.AdresseApiRefusee):
                calle_client.AppelReel(cle_api=self.CLE)
        finally:
            if sauve is None:
                os.environ.pop("CALLE_API_URL", None)
            else:
                os.environ["CALLE_API_URL"] = sauve


if __name__ == "__main__":
    unittest.main()
